window.WORD_AI_EXAMPLE_LIBRARY = {"source":"DeepSeek one-time offline generation with a separate review pass","model":"deepseek-v4-pro","generatedAt":"2026-08-08T14:01:49.813052+00:00","entries":{"monster":{"examples":[{"sentence":"The legend describes a sea monster that would rise from the depths to swallow entire ships.","translation":"传说描述了一种会从深海升起吞没整艘船只的海怪。"},{"sentence":"Environmentalists argue that the factory has become a monster, polluting the river and harming local communities.","translation":"环保主义者认为这家工厂已变成一个污染河流、危害当地社区的怪物。"},{"sentence":"Although the dictator was once seen as a liberator, history now remembers him as a monster responsible for countless atrocities.","translation":"尽管这位独裁者曾被视为解放者，但历史如今将他铭记为一个犯下无数暴行的恶魔。"},{"sentence":"The ancient fossil reveals a monster that dominated the prehistoric oceans with its enormous jaws.","translation":"这块古老化石揭示了一种以其巨大颌骨统治史前海洋的巨兽。"},{"sentence":"When the project grew into an unmanageable monster, the team had to restructure it completely to avoid failure.","translation":"当项目变成一个难以控制的庞然大物时，团队不得不彻底重组以避免失败。"}]},"gasp":{"examples":[{"sentence":"When the curtain rose to reveal the breathtaking landscape, a collective gasp of wonder echoed through the theater.","translation":"当幕布升起展现出令人叹为观止的风景时，剧院里响起了一片惊叹的抽气声。"},{"sentence":"Although the hiker was exhausted, he managed to gasp out a warning about the approaching storm.","translation":"尽管徒步者筋疲力尽，他还是喘着气发出了关于即将来临的暴风雨的警告。"},{"sentence":"The patient's sudden gasp for air indicated that the respiratory condition was worsening rapidly.","translation":"病人突然喘气表明呼吸状况正在迅速恶化。"},{"sentence":"Because the water was unexpectedly cold, she let out a sharp gasp as she stepped into the pool.","translation":"因为水温出乎意料地冷，她踏入泳池时猛地倒吸了一口气。"},{"sentence":"At the last gasp of the negotiation, both parties finally reached a compromise that satisfied their core interests.","translation":"在谈判的最后关头，双方终于达成了满足各自核心利益的妥协。"}]},"gloomy":{"examples":[{"sentence":"The gloomy economic outlook, which was exacerbated by global trade tensions, forced many companies to downsize.","translation":"因全球贸易紧张局势而加剧的黯淡经济前景，迫使许多公司裁员。"},{"sentence":"Despite the gloomy weather, the volunteers continued to work diligently to restore the damaged ecosystem.","translation":"尽管天气阴沉，志愿者们仍继续勤奋工作以恢复受损的生态系统。"},{"sentence":"Her gloomy demeanor suggested that she had received disappointing news, although she tried to remain composed.","translation":"她忧郁的举止暗示她收到了令人失望的消息，尽管她试图保持镇定。"},{"sentence":"The report paints a gloomy picture of the region's future unless immediate measures are taken to curb pollution.","translation":"报告描绘了该地区未来的黯淡景象，除非立即采取措施遏制污染。"},{"sentence":"Long-term unemployment can lead to a gloomy state of mind, which in turn may hinder one's ability to seek new opportunities.","translation":"长期失业会导致忧郁的心理状态，这反过来可能阻碍一个人寻求新机会的能力。"}]},"miniature":{"examples":[{"sentence":"Although the artist specialized in large murals, she also created a miniature of the landscape that captured every subtle hue.","translation":"尽管这位艺术家专攻大型壁画，她也创作了一幅风景的微型画，捕捉了每一种微妙的色调。"},{"sentence":"The architect presented a miniature of the proposed building, which allowed the committee to visualize the spatial relationships more clearly.","translation":"建筑师展示了拟建建筑的微缩模型，这使委员会能够更清晰地想象空间关系。"},{"sentence":"Because the original fresco had deteriorated over centuries, historians relied on a detailed miniature to study its composition.","translation":"由于原始壁画经过几个世纪已经损坏，历史学家依靠一幅详细的缩图来研究其构图。"},{"sentence":"While the full-scale prototype was still under construction, engineers tested the aerodynamics using a miniature in a wind tunnel.","translation":"当全尺寸原型仍在建造中时，工程师们利用微缩模型在风洞中测试了空气动力学性能。"},{"sentence":"The collector’s prized possession was a miniature of a Victorian house, complete with tiny furniture that reflected the era’s craftsmanship.","translation":"这位收藏家最珍贵的财产是一栋维多利亚式房屋的微缩模型，配有反映那个时代工艺的微小家具。"}]},"fertilizer":{"examples":[{"sentence":"Although chemical fertilizer boosts crop yields in the short term, its overuse can deplete soil organic matter over time.","translation":"尽管化肥在短期内能提高作物产量，但过度使用会随着时间的推移耗尽土壤有机质。"},{"sentence":"Farmers who apply organic fertilizer not only enrich the soil with nutrients but also improve its water-holding capacity.","translation":"施用有机肥料的农民不仅为土壤补充了养分，还提高了其保水能力。"},{"sentence":"Because the cost of synthetic fertilizer is closely tied to natural gas prices, many developing countries face volatile input expenses.","translation":"由于合成肥料的成本与天然气价格密切相关，许多发展中国家面临着投入成本的波动。"},{"sentence":"The agricultural extension program promoted a slow-release fertilizer, which minimizes nutrient runoff and protects nearby waterways.","translation":"农业推广项目推广了一种缓释肥料，它能最大限度地减少养分径流并保护附近的水道。"},{"sentence":"When farmers adopted precision agriculture techniques, they reduced fertilizer usage by 20 percent without sacrificing yields.","translation":"当农民采用精准农业技术时，他们在不牺牲产量的情况下将肥料用量减少了20%。"}]},"train":{"examples":[{"sentence":"Although the high-speed train offers a comfortable journey, many travelers still choose flights for long-distance trips to save time.","translation":"尽管高速列车提供了舒适的旅程，但许多旅客仍然选择航班进行长途旅行以节省时间。"},{"sentence":"The government invested heavily in the train network, which not only reduced commute times but also stimulated economic growth in suburban areas.","translation":"政府大力投资铁路网络，这不仅缩短了通勤时间，还刺激了郊区的经济增长。"},{"sentence":"Because the overnight train was fully booked, we had to take a bus, which added several hours to our journey.","translation":"由于夜间火车票已售罄，我们不得不乘坐公共汽车，这使我们的旅程增加了几个小时。"},{"sentence":"While waiting for the delayed train, passengers gathered in the station hall, where a digital board displayed updated departure times.","translation":"在等待晚点列车时，乘客们聚集在车站大厅，那里的电子显示屏显示了更新的发车时间。"},{"sentence":"The train, which was equipped with advanced safety systems, maintained a steady speed despite the heavy snowfall.","translation":"这列配备了先进安全系统的火车，尽管下着大雪，仍保持了稳定的速度。"}]},"offensive":{"examples":[{"sentence":"Publishing material that is deeply offensive to a particular community can undermine social cohesion.","translation":"发布对特定群体极具冒犯性的材料会破坏社会凝聚力。"},{"sentence":"Although the advertisement was intended to be humorous, many viewers found its portrayal of rural life offensive.","translation":"尽管这则广告本意是幽默的，但许多观众认为其对农村生活的描绘令人反感。"},{"sentence":"The committee decided to remove the statue because its symbolism had become offensive to a large segment of the population.","translation":"委员会决定移除这座雕像，因为其象征意义已令大部分民众感到冒犯。"},{"sentence":"Using offensive language in a professional setting not only damages relationships but also reflects poorly on one's judgment.","translation":"在职业场合使用冒犯性语言不仅损害人际关系，还会让人对你的判断力产生负面印象。"},{"sentence":"The government condemned the offensive remarks made by the foreign official, stating that they violated diplomatic norms.","translation":"政府谴责了该外国官员的冒犯性言论，称其违反了外交准则。"}]},"furious":{"examples":[{"sentence":"Although the manager was furious about the missed deadline, she agreed to extend the project by two days.","translation":"尽管经理对错过截止日期感到愤怒，但她同意将项目延长两天。"},{"sentence":"The community became furious when they learned that the factory had been polluting the river for years.","translation":"当社区得知工厂多年来一直在污染河流时，他们变得怒不可遏。"},{"sentence":"Because the politician made a furious speech against corruption, he gained widespread support from the public.","translation":"因为这位政治家发表了一篇激烈反对腐败的演讲，他获得了公众的广泛支持。"},{"sentence":"The scientist was furious that her research findings were distorted by the media, which misled the public.","translation":"这位科学家对她的研究成果被媒体歪曲感到愤怒，这误导了公众。"},{"sentence":"While the negotiations were underway, a furious argument broke out over the terms of the trade agreement.","translation":"在谈判进行期间，就贸易协定的条款爆发了一场激烈的争论。"}]},"brave":{"examples":[{"sentence":"Although the rescue mission was extremely dangerous, the brave volunteers entered the flood zone to evacuate stranded families.","translation":"尽管救援任务极其危险，勇敢的志愿者们还是进入了洪水区疏散被困家庭。"},{"sentence":"The brave decision to whistleblow on corporate fraud, which initially cost her the job, ultimately led to industry-wide reforms.","translation":"举报公司欺诈的勇敢决定最初让她失去了工作，但最终导致了全行业的改革。"},{"sentence":"Because the brave surgeon performed an experimental procedure, the patient survived what was previously considered an inoperable condition.","translation":"因为那位勇敢的外科医生实施了一项实验性手术，病人从先前被认为无法手术的病情中存活了下来。"},{"sentence":"A brave entrepreneur must often invest in unproven technologies, thereby risking capital to gain a competitive advantage.","translation":"勇敢的企业家必须经常投资于未经证实的技术，从而冒着资本风险以获得竞争优势。"},{"sentence":"The brave stance taken by the human rights lawyer, despite threats to her safety, inspired a global movement for justice.","translation":"那位人权律师不顾人身安全威胁而采取的勇敢立场，激励了一场全球性的正义运动。"}]},"notebook":{"examples":[{"sentence":"Although digital note-taking is popular, many writers still rely on a physical notebook to capture fleeting ideas without distraction.","translation":"尽管数字笔记很流行，许多作家仍依赖纸质笔记本来捕捉稍纵即逝的灵感而不受干扰。"},{"sentence":"Because a well-maintained notebook serves as a reliable record, researchers can trace the evolution of their hypotheses over time.","translation":"因为一本维护良好的笔记本可作为可靠记录，研究人员能够追踪其假设随时间演变的过程。"},{"sentence":"When students use a dedicated notebook for each subject, they not only organize their notes but also reinforce learning through structured review.","translation":"当学生为每门科目使用专用笔记本时，他们不仅能整理笔记，还能通过结构化复习巩固学习。"},{"sentence":"The engineer sketched a rough design in her notebook, which later became the blueprint for an innovative energy-saving device.","translation":"工程师在笔记本上画了一个粗略设计，后来这成为了一个创新节能设备的蓝图。"},{"sentence":"If you keep a dream notebook by your bedside, you can record vivid details that often fade within minutes of waking.","translation":"如果你在床边放一本梦境笔记本，就能记录下醒来后几分钟内常常消失的生动细节。"}]},"custom":{"examples":[{"sentence":"Although the custom of afternoon tea originated in Britain, it has been adapted by many cultures to suit local tastes and social rhythms.","translation":"尽管下午茶的习俗起源于英国，但已被许多文化改造以适应当地口味和社交节奏。"},{"sentence":"Because the custom of bowing conveys respect without physical contact, it remains a preferred greeting in several East Asian societies.","translation":"因为鞠躬的习俗无需身体接触就能表达尊重，它在几个东亚社会中仍是首选的问候方式。"},{"sentence":"When a community preserves a unique wedding custom, it not only honors its ancestors but also strengthens intergenerational bonds.","translation":"当一个社区保留独特的婚礼习俗时，它不仅尊重祖先，还加强了代际纽带。"},{"sentence":"The custom of giving red envelopes during Lunar New Year, which symbolizes good luck and prosperity, is cherished by both children and adults.","translation":"农历新年发红包的习俗象征着好运和繁荣，深受儿童和成人的珍视。"},{"sentence":"If a business custom conflicts with ethical principles, companies must choose between short-term profit and long-term reputation.","translation":"如果一种商业习俗与道德原则冲突，公司必须在短期利润和长期声誉之间做出选择。"}]},"method":{"examples":[{"sentence":"Although the traditional lecture method remains common, active learning strategies often yield deeper understanding and higher retention rates.","translation":"尽管传统的讲授方法仍很普遍，主动学习策略通常能带来更深刻的理解和更高的记忆保持率。"},{"sentence":"Because the new analytical method reduces processing time by half, laboratories can now handle a larger volume of samples daily.","translation":"因为新的分析方法将处理时间缩短了一半，实验室现在每天能处理更多样本。"},{"sentence":"When selecting a research method, scholars must consider not only the nature of their data but also the ethical implications of their approach.","translation":"在选择研究方法时，学者不仅要考虑数据的性质，还要考虑其方法的伦理影响。"},{"sentence":"The Socratic method, which uses probing questions to stimulate critical thinking, has been employed by educators for centuries.","translation":"苏格拉底方法通过探究性问题激发批判性思维，已被教育者使用了几个世纪。"},{"sentence":"If a manufacturing method proves unsustainable, companies should invest in greener alternatives to ensure long-term viability.","translation":"如果一种制造方法被证明不可持续，公司应投资于更环保的替代方案以确保长期生存能力。"}]},"beer":{"examples":[{"sentence":"Although beer is often associated with social gatherings, excessive consumption can lead to serious health problems over time.","translation":"尽管啤酒常与社交聚会联系在一起，但长期过量饮用可能导致严重的健康问题。"},{"sentence":"The craft beer industry has grown rapidly because consumers increasingly value unique flavors and local production.","translation":"精酿啤酒行业发展迅速，因为消费者越来越重视独特的风味和本地生产。"},{"sentence":"Researchers have found that moderate beer consumption may offer some cardiovascular benefits, yet these are outweighed by the risks of heavy drinking.","translation":"研究人员发现，适量饮用啤酒可能对心血管有一定益处，但这些益处被大量饮酒的风险所抵消。"},{"sentence":"In many European countries, beer is deeply embedded in cultural traditions, which helps sustain local breweries despite global competition.","translation":"在许多欧洲国家，啤酒深深植根于文化传统中，这有助于本地啤酒厂在全球竞争中生存。"},{"sentence":"When governments raise taxes on beer, they aim to reduce alcohol-related harm while also generating revenue for public services.","translation":"当政府提高啤酒税时，其目的是减少与酒精相关的危害，同时为公共服务创造收入。"}]},"bottom":{"examples":[{"sentence":"The bottom of the ocean remains largely unexplored, which limits our understanding of marine biodiversity.","translation":"海洋底部在很大程度上仍未被探索，这限制了我们对于海洋生物多样性的理解。"},{"sentence":"Because the company failed to address the root cause, its financial performance eventually hit rock bottom.","translation":"由于公司未能解决根本原因，其财务表现最终跌至谷底。"},{"sentence":"A thorough investigation is needed to get to the bottom of the data breach that compromised millions of accounts.","translation":"需要进行彻底调查，以查明导致数百万账户受损的数据泄露事件的真相。"},{"sentence":"Although the proposal seemed promising at first, a careful analysis revealed that its assumptions were built on a shaky bottom.","translation":"尽管该提案起初看似很有前景，但仔细分析后发现其假设的基础并不稳固。"},{"sentence":"Educational reforms should start from the bottom by improving primary schools, rather than focusing only on elite universities.","translation":"教育改革应从底层开始，改善小学教育，而不是只关注精英大学。"}]},"critical":{"examples":[{"sentence":"Although critical thinking is widely promoted in higher education, many students still struggle to apply it effectively in their research.","translation":"尽管批判性思维在高等教育中被广泛提倡，但许多学生在研究中仍难以有效运用它。"},{"sentence":"The patient's condition became critical after the surgery, which required immediate intervention from the intensive care unit.","translation":"手术后病人的状况变得危急，这需要重症监护室的立即干预。"},{"sentence":"Because the reviewer was overly critical of the manuscript, the authors felt discouraged rather than motivated to improve their work.","translation":"由于审稿人对稿件过于挑剔，作者们感到气馁，而不是有动力去改进他们的工作。"},{"sentence":"Securing sufficient funding is critical for the laboratory, as it ensures that experiments can continue without interruption.","translation":"获得充足的资金对实验室至关重要，因为它能确保实验不间断地进行。"},{"sentence":"The report was critical of the current educational system, arguing that it fails to prepare students for the challenges of the modern workforce.","translation":"该报告批评了当前的教育体系，认为它未能让学生为现代职场的挑战做好准备。"}]},"develop":{"examples":[{"sentence":"When students engage in collaborative research projects, they develop critical thinking skills that benefit their future careers.","translation":"当学生参与合作研究项目时，他们会培养出有益于未来职业发展的批判性思维能力。"},{"sentence":"Governments that invest in renewable energy infrastructure can develop more sustainable economies while reducing carbon emissions.","translation":"投资可再生能源基础设施的政府能够发展更可持续的经济，同时减少碳排放。"},{"sentence":"Although the initial costs are high, companies that develop comprehensive employee training programs often see long-term productivity gains.","translation":"尽管初始成本很高，但制定全面员工培训计划的公司通常能获得长期的生产力提升。"},{"sentence":"To address the housing shortage, urban planners must develop innovative solutions that balance density with quality of life.","translation":"为了解决住房短缺问题，城市规划者必须制定创新方案，在密度与生活质量之间取得平衡。"},{"sentence":"Because early exposure to multiple languages can enhance cognitive flexibility, many educators encourage children to develop bilingual proficiency.","translation":"由于早期接触多种语言能增强认知灵活性，许多教育者鼓励儿童培养双语能力。"}]},"chalk":{"examples":[{"sentence":"Although digital tools are prevalent, many mathematics teachers still prefer chalk for illustrating complex equations on blackboards.","translation":"尽管数字工具很普遍，许多数学老师仍然更喜欢用粉笔在黑板上演示复杂的方程式。"},{"sentence":"The geologist explained that the white cliffs are composed primarily of chalk, a soft limestone formed from ancient marine organisms.","translation":"地质学家解释说，这些白色悬崖主要由白垩构成，这是一种由古代海洋生物形成的软质石灰岩。"},{"sentence":"In art classes, students often use chalk pastels to create vibrant drawings that blend smoothly on textured paper.","translation":"在美术课上，学生经常使用粉彩笔创作鲜艳的画作，这些画作在有纹理的纸上能平滑地融合。"},{"sentence":"Because chalk dust can trigger respiratory issues, many schools have replaced traditional chalkboards with whiteboards and markers.","translation":"由于粉笔灰尘可能引发呼吸问题，许多学校已经用白板和马克笔取代了传统的黑板。"},{"sentence":"The researcher used a piece of chalk to mark the excavation grid, ensuring that each artifact's location was precisely recorded.","translation":"研究人员用一支粉笔标记挖掘网格，确保每件文物的位置都被精确记录。"}]},"advertise":{"examples":[{"sentence":"Although many startups advertise their products through social media influencers, this strategy can backfire if the influencer's audience does not align with the brand.","translation":"尽管许多初创公司通过社交媒体网红宣传其产品，但如果网红的受众与品牌不符，这一策略可能适得其反。"},{"sentence":"Companies that advertise during major sporting events often pay premium rates, yet they gain access to a vast and engaged audience.","translation":"在大型体育赛事期间做广告的公司通常支付高昂费用，但它们能接触到庞大且投入的观众。"},{"sentence":"Because job seekers increasingly rely on online platforms, employers must advertise vacancies on multiple channels to reach a diverse pool of candidates.","translation":"由于求职者越来越依赖在线平台，雇主必须在多个渠道发布职位广告，以接触到多样化的候选人。"},{"sentence":"To ensure compliance with regulations, pharmaceutical companies must carefully advertise the benefits and risks of their medications in all promotional materials.","translation":"为了确保符合法规，制药公司必须在所有宣传材料中谨慎地宣传其药物的益处和风险。"},{"sentence":"While traditional billboards still exist, many businesses now advertise through targeted online campaigns that use data analytics to optimize reach.","translation":"虽然传统广告牌仍然存在，但许多企业现在通过使用数据分析优化覆盖范围的定向在线活动进行广告宣传。"}]},"duty":{"examples":[{"sentence":"Although the new tariff policy imposes a higher duty on imported electronics, it aims to protect domestic manufacturers.","translation":"尽管新的关税政策对进口电子产品征收更高的关税，但其目的是保护国内制造商。"},{"sentence":"Because nurses have a duty to provide compassionate care, they often work long hours under stressful conditions.","translation":"由于护士有责任提供富有同情心的护理，她们经常在压力条件下长时间工作。"},{"sentence":"When citizens fulfill their civic duty by voting, they strengthen the democratic process.","translation":"当公民通过投票履行公民义务时，他们加强了民主进程。"},{"sentence":"The committee emphasized that it is the duty of every scientist to report data accurately, which ensures research integrity.","translation":"委员会强调，准确报告数据是每位科学家的责任，这确保了研究的诚信。"},{"sentence":"While off duty, the police officer still felt a moral duty to intervene in the emergency.","translation":"虽然不当班，这名警察仍然感到有道德义务在紧急情况下进行干预。"}]},"motive":{"examples":[{"sentence":"Although the defendant's motive for the crime was unclear, the evidence pointed to financial desperation.","translation":"尽管被告的犯罪动机尚不清楚，但证据指向了经济上的绝望。"},{"sentence":"Because profit is a powerful motive for corporations, environmental regulations must be strictly enforced.","translation":"由于利润是企业的强大动机，必须严格执行环境法规。"},{"sentence":"The researcher's primary motive for conducting the study was to address a gap in the literature, which she had identified years earlier.","translation":"研究人员进行这项研究的主要动机是填补文献中的一个空白，这是她多年前就发现的。"},{"sentence":"When evaluating a charitable donation, one should consider the donor's motive to ensure it is altruistic.","translation":"在评估慈善捐赠时，人们应该考虑捐赠者的动机，以确保它是利他的。"},{"sentence":"Critics argue that the government's hidden motive for the policy is to gain political support rather than to benefit the public.","translation":"批评者认为，政府推行该政策的隐藏动机是获得政治支持，而不是造福公众。"}]},"marriage":{"examples":[{"sentence":"Although marriage is often portrayed as a romantic ideal, it requires continuous effort and compromise to sustain.","translation":"尽管婚姻常被描绘成浪漫的理想，但它需要持续的努力和妥协来维持。"},{"sentence":"Because marriage laws vary significantly across cultures, international couples must navigate complex legal frameworks.","translation":"由于婚姻法律在不同文化中差异很大，跨国夫妇必须应对复杂的法律框架。"},{"sentence":"The marriage of artificial intelligence and healthcare has led to breakthroughs that were unimaginable a decade ago.","translation":"人工智能与医疗保健的结合带来了十年前难以想象的突破。"},{"sentence":"While marriage can provide emotional and financial stability, it may also restrict personal freedom if not based on equality.","translation":"虽然婚姻能提供情感和经济稳定，但如果不是基于平等，它也可能限制个人自由。"},{"sentence":"Sociologists argue that the decline in marriage rates reflects broader shifts in societal values, rather than a rejection of commitment.","translation":"社会学家认为，结婚率的下降反映了社会价值观的更广泛转变，而不是对承诺的拒绝。"}]},"appointment":{"examples":[{"sentence":"Because the appointment with the specialist was unexpectedly postponed, she had to rearrange her entire work schedule.","translation":"由于与专家的预约意外推迟，她不得不重新安排整个工作日程。"},{"sentence":"The appointment of an independent auditor, which was recommended by the board, helped restore investor confidence.","translation":"董事会建议任命一名独立审计师，这有助于恢复投资者信心。"},{"sentence":"Although he arrived early for the appointment, the manager kept him waiting for over an hour without explanation.","translation":"尽管他提前赴约，经理却让他等了一个多小时而没有解释。"},{"sentence":"Missing a critical appointment can have serious consequences, especially when it involves medical consultations or legal matters.","translation":"错过重要约会可能产生严重后果，尤其是在涉及医疗咨询或法律事务时。"},{"sentence":"The university streamlined its appointment system to ensure that students could easily book meetings with faculty advisors.","translation":"大学简化了预约系统，以确保学生能轻松预约与导师的会面。"}]},"mosaic":{"examples":[{"sentence":"The cultural landscape of modern cities is a mosaic of traditions, languages, and customs that enriches community life.","translation":"现代城市的文化景观是由传统、语言和习俗组成的马赛克，丰富了社区生活。"},{"sentence":"Because a nation's identity is shaped by diverse historical influences, its heritage often resembles a complex mosaic rather than a single narrative.","translation":"由于一个国家的身份由多样的历史影响塑造，其遗产往往像一幅复杂的马赛克，而非单一叙事。"},{"sentence":"Although each individual contribution seems small, the collective effort of volunteers forms a mosaic of social support that strengthens the entire community.","translation":"尽管每个人的贡献看似微小，但志愿者的集体努力形成了一幅社会支持的马赛克，增强了整个社区。"},{"sentence":"In genetic research, the human genome can be understood as a mosaic of inherited traits that interact with environmental factors.","translation":"在基因研究中，人类基因组可被理解为一幅由遗传特征组成的马赛克，这些特征与环境因素相互作用。"},{"sentence":"When educators integrate multiple disciplines into a single project, they create a learning mosaic that helps students see connections between different fields.","translation":"当教育者将多个学科整合到一个项目中时，他们创造了一幅学习马赛克，帮助学生看到不同领域之间的联系。"}]},"exempt":{"examples":[{"sentence":"Nonprofit organizations that focus on public welfare are often exempt from certain taxes to encourage their charitable activities.","translation":"专注于公共福利的非营利组织通常被免除某些税收，以鼓励其慈善活动。"},{"sentence":"Although small businesses may be exempt from some regulations, they still must comply with basic safety standards to protect their employees.","translation":"尽管小企业可能被免除某些法规，但它们仍必须遵守基本安全标准以保护员工。"},{"sentence":"Because the new law aims to reduce administrative burdens, low-income households are exempt from the annual filing fee.","translation":"由于新法律旨在减轻行政负担，低收入家庭被免除了年度申报费。"},{"sentence":"In many countries, diplomatic personnel are exempt from local prosecution under international agreements, which ensures their functional independence.","translation":"在许多国家，外交人员根据国际协议被免除当地起诉，这确保了其职能独立性。"},{"sentence":"While certain medical devices are exempt from rigorous clinical trials, manufacturers must still provide evidence of safety and efficacy.","translation":"尽管某些医疗器械被免除严格的临床试验，但制造商仍必须提供安全性和有效性的证据。"}]},"become":{"examples":[{"sentence":"Although the policy was intended to promote equality, it has become a barrier to social mobility for disadvantaged groups.","translation":"尽管该政策旨在促进平等，但它已成为弱势群体社会流动的障碍。"},{"sentence":"Because digital technology reshapes communication patterns, face-to-face interaction has become a rare and valuable skill in professional settings.","translation":"由于数字技术重塑了沟通模式，面对面交流已成为专业环境中一项罕见而有价值的技能。"},{"sentence":"When a country neglects investment in renewable energy, its economy may become overly dependent on volatile fossil fuel markets.","translation":"当一个国家忽视对可再生能源的投资时，其经济可能变得过度依赖动荡的化石燃料市场。"},{"sentence":"If global temperatures continue to rise, many coastal cities will become uninhabitable within this century, which would trigger massive displacement.","translation":"如果全球气温继续上升，许多沿海城市将在本世纪内变得无法居住，这将引发大规模流离失所。"},{"sentence":"Through consistent practice and feedback, a novice writer can become a persuasive communicator who engages diverse audiences.","translation":"通过持续的练习和反馈，一个新手作家可以成为一个有说服力的沟通者，吸引不同的受众。"}]},"opera":{"examples":[{"sentence":"Although opera is often perceived as an elite art form, its narratives frequently explore universal human emotions.","translation":"尽管歌剧常被视为精英艺术形式，但其叙事经常探索普遍的人类情感。"},{"sentence":"Because opera combines orchestral music with theatrical performance, it offers a uniquely immersive cultural experience.","translation":"由于歌剧将管弦乐与戏剧表演相结合，它提供了一种独特的沉浸式文化体验。"},{"sentence":"When attending an opera, one should familiarize oneself with the libretto to fully appreciate the storyline.","translation":"观看歌剧时，人们应熟悉剧本以充分欣赏故事情节。"},{"sentence":"Many modern opera houses employ advanced acoustics, which ensures that every note reaches the audience with clarity.","translation":"许多现代歌剧院采用先进的声学设计，这确保每个音符都能清晰地传达给观众。"},{"sentence":"Studying opera can enhance one's understanding of historical contexts, thereby enriching the appreciation of classical music.","translation":"学习歌剧可以加深对历史背景的理解，从而丰富对古典音乐的欣赏。"}]},"host":{"examples":[{"sentence":"The host of the seminar introduced each speaker with a brief biography, which helped the audience understand their expertise.","translation":"研讨会的主持人用简短的传记介绍每位演讲者，这有助于听众了解他们的专长。"},{"sentence":"Because a skilled host can facilitate meaningful discussions, conferences often rely on experienced moderators.","translation":"由于熟练的主持人能促进有意义的讨论，会议通常依赖经验丰富的主持人。"},{"sentence":"When a city decides to host an international summit, it must enhance security measures to ensure the safety of all delegates.","translation":"当一个城市决定主办国际峰会时，它必须加强安全措施以确保所有代表的安全。"},{"sentence":"The talk show host asked probing questions, thereby revealing insights that the audience had not previously considered.","translation":"脱口秀主持人提出了尖锐的问题，从而揭示了观众之前未曾考虑过的见解。"},{"sentence":"A generous host not only provides refreshments but also creates an environment where guests feel valued and respected.","translation":"慷慨的主人不仅提供茶点，还营造一个让客人感到被重视和尊重的环境。"}]},"meat":{"examples":[{"sentence":"Although meat is a rich source of protein, excessive consumption has been linked to various health issues.","translation":"尽管肉类是蛋白质的丰富来源，但过量食用与多种健康问题有关。"},{"sentence":"Because the production of meat requires significant resources, reducing intake can contribute to environmental sustainability.","translation":"由于肉类生产需要大量资源，减少摄入有助于环境可持续性。"},{"sentence":"When preparing meat, it is essential to cook it thoroughly to eliminate harmful bacteria that may cause illness.","translation":"准备肉类时，彻底煮熟以消除可能导致疾病的有害细菌是至关重要的。"},{"sentence":"The global demand for meat continues to rise, which places pressure on agricultural systems to adopt more efficient practices.","translation":"全球对肉类的需求持续增长，这给农业系统带来压力，要求其采取更高效的做法。"},{"sentence":"Cultured meat, which is grown in laboratories, offers a potential solution to ethical concerns regarding animal welfare.","translation":"实验室培育的肉类为有关动物福利的伦理问题提供了一个潜在的解决方案。"}]},"satisfactory":{"examples":[{"sentence":"Although the initial results were disappointing, the revised methodology yielded a satisfactory outcome that met all research objectives.","translation":"尽管最初的结果令人失望，但修订后的方法产生了令人满意的结果，达到了所有研究目标。"},{"sentence":"A satisfactory solution to urban congestion must integrate public transit improvements with smart traffic management, which reduces commute times significantly.","translation":"一个令人满意的城市拥堵解决方案必须将公共交通改善与智能交通管理相结合，从而显著减少通勤时间。"},{"sentence":"Because the company implemented rigorous quality controls, customer feedback on the new product was overwhelmingly satisfactory.","translation":"由于公司实施了严格的质量控制，客户对新产品的反馈绝大多数是满意的。"},{"sentence":"To ensure a satisfactory work-life balance, employees are encouraged to set clear boundaries and prioritize tasks effectively.","translation":"为了确保令人满意的工作与生活平衡，鼓励员工设定明确的界限并有效地优先处理任务。"},{"sentence":"The peace negotiations, which lasted for months, finally reached a satisfactory agreement that addressed the core concerns of both parties.","translation":"持续数月的和平谈判最终达成了一项令人满意的协议，解决了双方的核心关切。"}]},"pour":{"examples":[{"sentence":"When the government decided to pour substantial funds into renewable energy research, private investment followed suit, thereby accelerating innovation.","translation":"当政府决定将大量资金投入可再生能源研究时，私人投资也随之跟进，从而加速了创新。"},{"sentence":"Although critics pour scorn on the new policy, its long-term benefits for public health are supported by empirical evidence that cannot be ignored.","translation":"尽管批评者对新政策大加嘲讽，但其对公共健康的长期益处有不可忽视的实证支持。"},{"sentence":"International organizations continue to pour humanitarian aid into the region, yet logistical challenges hinder effective distribution, which exacerbates the crisis.","translation":"国际组织继续向该地区倾注人道主义援助，但后勤挑战阻碍了有效分发，从而加剧了危机。"},{"sentence":"To master a foreign language, learners must pour countless hours into deliberate practice and immersive exposure, rather than relying solely on passive study.","translation":"要掌握一门外语，学习者必须投入无数时间进行刻意练习和沉浸式接触，而不是仅仅依赖被动学习。"},{"sentence":"As the economic crisis deepened, citizens began to pour into the streets, demanding structural reforms that would address systemic inequality.","translation":"随着经济危机加深，市民开始涌上街头，要求进行能够解决系统性不平等的结构性改革。"}]},"the":{"examples":[{"sentence":"Although the initial results were promising, the research team decided to conduct further experiments to ensure the findings were reproducible.","translation":"尽管初步结果令人鼓舞，研究团队决定进行进一步实验，以确保研究结果可重复。"},{"sentence":"The policy, which was implemented last year, has significantly reduced carbon emissions in the industrial sector.","translation":"这项去年实施的政策显著减少了工业部门的碳排放。"},{"sentence":"Because the committee failed to reach a consensus, the decision was postponed until the next meeting.","translation":"由于委员会未能达成共识，决定被推迟到下次会议。"},{"sentence":"The professor emphasized that critical thinking is essential for students to navigate the complexities of the modern world.","translation":"教授强调，批判性思维对于学生应对现代世界的复杂性至关重要。"},{"sentence":"When the new regulations take effect, companies will be required to disclose their environmental impact in annual reports.","translation":"当新规生效时，公司将被要求在年度报告中披露其环境影响。"}]},"circulate":{"examples":[{"sentence":"Although the new policy was intended to remain confidential, details began to circulate among employees within hours.","translation":"尽管新政策本应保密，但细节在几小时内就开始在员工中流传。"},{"sentence":"To ensure that cool air can circulate effectively, the engineer designed a ventilation system that uses strategically placed ducts.","translation":"为了确保冷空气能有效流通，工程师设计了一个使用战略性布置管道的通风系统。"},{"sentence":"When a rumor starts to circulate on social media, it often gains credibility simply through repetition, regardless of its truth.","translation":"当谣言开始在社交媒体上传播时，它往往仅通过重复就获得可信度，无论其真实性如何。"},{"sentence":"The heart functions as a pump that enables blood to circulate throughout the body, thereby delivering oxygen and nutrients to tissues.","translation":"心脏起到泵的作用，使血液在全身循环，从而将氧气和营养物质输送到组织。"},{"sentence":"Because the central bank injected liquidity into the market, more capital began to circulate, which stimulated economic growth.","translation":"由于中央银行向市场注入流动性，更多资本开始流通，这刺激了经济增长。"}]},"piece":{"examples":[{"sentence":"The archaeologist discovered a piece of pottery that dated back to the Han Dynasty, which provided new insights into ancient trade routes.","translation":"考古学家发现了一件可追溯到汉代的陶器，这为古代贸易路线提供了新的见解。"},{"sentence":"When writing a research paper, it is crucial to evaluate each piece of evidence critically to ensure the argument is well-supported.","translation":"在撰写研究论文时，批判性地评估每一条证据以确保论点得到充分支持至关重要。"},{"sentence":"Although the composer is known for his operas, this piece of chamber music reveals a more intimate and experimental side of his talent.","translation":"尽管这位作曲家以歌剧闻名，但这首室内乐作品展现了他更私密和实验性的一面。"},{"sentence":"The legal team reviewed every piece of the contract before signing, because even a minor oversight could lead to significant liabilities.","translation":"法律团队在签署前审查了合同的每一项条款，因为即使是一个小疏忽也可能导致重大责任。"},{"sentence":"To solve the mystery, the detective assembled each piece of the puzzle, which ultimately revealed a pattern that pointed to the culprit.","translation":"为了解开谜团，侦探拼凑起每一块拼图，最终揭示出指向罪犯的模式。"}]},"partial":{"examples":[{"sentence":"The committee reached only a partial consensus because several members remained unconvinced by the evidence presented.","translation":"委员会只达成了部分共识，因为几位成员对所呈证据仍持怀疑态度。"},{"sentence":"Although the reform achieved partial success in urban areas, its impact on rural communities was far less pronounced.","translation":"尽管改革在城市地区取得了部分成功，但其对农村社区的影响远没有那么明显。"},{"sentence":"A partial analysis of the data may lead to misleading conclusions if researchers ignore confounding variables.","translation":"如果研究人员忽略混杂变量，对数据的部分分析可能会导致误导性结论。"},{"sentence":"The historian warned that relying on a partial account of events could distort our understanding of the past.","translation":"历史学家警告说，依赖对事件的部分叙述可能会扭曲我们对过去的理解。"},{"sentence":"Because the funding was only partial, the research team had to scale back the scope of their investigation.","translation":"由于资金只是部分的，研究团队不得不缩减调查范围。"}]},"overturn":{"examples":[{"sentence":"Although the new evidence was compelling, the court refused to overturn the previous conviction because procedural rules limited the scope of review.","translation":"尽管新证据很有说服力，法院仍拒绝推翻先前的定罪，因为程序规则限制了审查范围。"},{"sentence":"The sudden economic downturn threatened to overturn the government's fiscal plan, which had relied on steady growth to fund social programs.","translation":"突如其来的经济衰退有可能推翻政府的财政计划，该计划依赖稳定增长来资助社会项目。"},{"sentence":"If the scientific consensus were to overturn the long-held theory, many textbooks would require immediate revision to reflect the new paradigm.","translation":"如果科学共识要推翻长期持有的理论，许多教科书将需要立即修订以反映新范式。"},{"sentence":"The activist group launched a legal challenge to overturn the restrictive law, arguing that it violated fundamental human rights.","translation":"该活动组织发起法律挑战以推翻这项限制性法律，认为它侵犯了基本人权。"},{"sentence":"Because the new CEO sought to overturn the company's traditional hierarchy, she implemented a flat organizational structure that empowered junior staff.","translation":"由于新任首席执行官试图推翻公司的传统等级制度，她实施了扁平化的组织结构，赋予初级员工权力。"}]},"lion":{"examples":[{"sentence":"Although the lion is often depicted as a solitary hunter, it actually relies on coordinated group tactics to bring down large prey.","translation":"尽管狮子常被描绘成独行猎手，它实际上依赖协调的群体战术来捕获大型猎物。"},{"sentence":"The lion population in West Africa has declined sharply because habitat fragmentation prevents prides from maintaining viable territories.","translation":"西非的狮子数量急剧下降，因为栖息地破碎化使狮群无法维持可生存的领地。"},{"sentence":"While the lion symbolizes courage in many cultures, its representation in literature often reflects deeper themes of power and mortality.","translation":"虽然狮子在许多文化中象征勇气，但它在文学中的表现往往反映了权力和死亡等更深层的主题。"},{"sentence":"Conservationists argue that protecting the lion requires not only anti-poaching measures but also community engagement to reduce human-wildlife conflict.","translation":"保护主义者认为，保护狮子不仅需要反偷猎措施，还需要社区参与以减少人类与野生动物的冲突。"},{"sentence":"The lion, which is an apex predator, plays a crucial role in regulating herbivore populations, thereby maintaining the balance of the ecosystem.","translation":"狮子作为顶级捕食者，在调节食草动物数量方面起着关键作用，从而维持生态系统的平衡。"}]},"vicious":{"examples":[{"sentence":"The politician faced a vicious smear campaign that distorted his record and misled voters.","translation":"那位政治家面临一场恶毒的诽谤运动，歪曲了他的记录并误导了选民。"},{"sentence":"Without intervention, the vicious cycle of poverty and malnutrition will persist for generations.","translation":"如果没有干预，贫困和营养不良的恶性循环将持续数代。"},{"sentence":"The dog, which had been trained for fighting, became vicious and had to be restrained.","translation":"那只被训练来打斗的狗变得凶猛，不得不被约束起来。"},{"sentence":"A vicious rumor, which spread through social media, ruined the company's reputation overnight.","translation":"一个通过社交媒体传播的恶毒谣言一夜之间毁掉了公司的声誉。"},{"sentence":"The vicious hurricane, which struck the coast with little warning, caused catastrophic flooding.","translation":"那场猛烈的飓风在几乎没有预警的情况下袭击了海岸，造成了灾难性的洪水。"}]},"tobacco":{"examples":[{"sentence":"Although tobacco was once considered a symbol of sophistication, it is now widely recognized as a leading cause of preventable death.","translation":"尽管烟草曾被视为成熟的象征，但现在它被广泛认为是可预防死亡的主要原因。"},{"sentence":"Because tobacco cultivation often involves heavy pesticide use, it poses significant environmental and health risks to farming communities.","translation":"由于烟草种植通常涉及大量农药使用，它对农业社区构成了重大的环境和健康风险。"},{"sentence":"Governments that impose high taxes on tobacco products not only reduce smoking rates but also generate revenue for healthcare systems.","translation":"对烟草产品征收高税的政府不仅降低了吸烟率，还为医疗系统创造了收入。"},{"sentence":"While tobacco companies have diversified into alternative products, their core business remains dependent on nicotine addiction.","translation":"尽管烟草公司已向替代产品多元化发展，但其核心业务仍然依赖于尼古丁成瘾。"},{"sentence":"The global decline in tobacco use, which has been driven by public health campaigns, is a major achievement in preventive medicine.","translation":"全球烟草使用的下降，由公共卫生运动推动，是预防医学的一项重大成就。"}]},"swear":{"examples":[{"sentence":"Although witnesses swear to tell the truth, memory distortions can still lead to inaccurate testimony in court.","translation":"尽管证人宣誓说实话，但记忆扭曲仍可能导致法庭上的不实证词。"},{"sentence":"Because public officials swear an oath to uphold the law, any breach of that oath constitutes a serious ethical violation.","translation":"由于公职人员宣誓维护法律，任何违背誓言的行为都构成严重的道德违规。"},{"sentence":"Many athletes swear by high-intensity interval training, which they claim improves both endurance and metabolic health.","translation":"许多运动员极其信赖高强度间歇训练，他们声称这能提高耐力和代谢健康。"},{"sentence":"When researchers swear that a new drug is effective, they must provide robust clinical evidence to support their claims.","translation":"当研究人员坚信一种新药有效时，他们必须提供强有力的临床证据来支持其主张。"},{"sentence":"While some people swear when they are angry, others use humor to defuse tension, thereby maintaining better social relationships.","translation":"虽然有些人生气时会咒骂，但其他人用幽默来化解紧张，从而维持更好的社会关系。"}]},"scandal":{"examples":[{"sentence":"Although the scandal initially seemed minor, it eventually revealed systemic corruption that had persisted for years.","translation":"尽管丑闻起初看似微小，但最终揭露了持续多年的系统性腐败。"},{"sentence":"Because the scandal involved data fabrication, it undermined the credibility of the entire research field and led to stricter oversight.","translation":"由于丑闻涉及数据造假，它损害了整个研究领域的可信度，并导致了更严格的监督。"},{"sentence":"The political scandal, which was exposed by investigative journalists, forced the resignation of several high-ranking officials.","translation":"这起由调查记者曝光的政治丑闻，迫使几名高级官员辞职。"},{"sentence":"When a scandal breaks in the corporate world, companies often hire crisis management firms to mitigate reputational damage.","translation":"当企业界爆发丑闻时，公司通常会聘请危机管理公司来减轻声誉损害。"},{"sentence":"The scandal not only destroyed the politician's career but also eroded public trust in the electoral process itself.","translation":"这起丑闻不仅毁了那位政治家的职业生涯，还削弱了公众对选举过程本身的信任。"}]},"celebrate":{"examples":[{"sentence":"Many universities celebrate their centennial by hosting academic conferences that invite scholars from around the world.","translation":"许多大学通过举办邀请世界各地学者的学术会议来庆祝百年校庆。"},{"sentence":"While some traditions celebrate the harvest with feasts, others emphasize quiet reflection on the year's labor.","translation":"虽然有些传统以盛宴庆祝丰收，但另一些则强调对一年劳作的静思。"},{"sentence":"The community decided to celebrate the restoration of the historic library, which had been damaged by the flood.","translation":"社区决定庆祝那座曾被洪水损坏的历史图书馆的修复。"},{"sentence":"Companies often celebrate major milestones not only to reward employees but also to reinforce a shared sense of purpose.","translation":"公司经常庆祝重大里程碑，不仅为了奖励员工，也为了强化共同的使命感。"},{"sentence":"Rather than celebrate individual achievements in isolation, the research team chose to acknowledge every member's contribution.","translation":"研究团队没有孤立地庆祝个人成就，而是选择认可每位成员的贡献。"}]},"left":{"examples":[{"sentence":"Although the negotiations were promising, the sudden withdrawal of the key investor left the startup without sufficient funding.","translation":"尽管谈判很有希望，但关键投资者的突然退出使这家初创公司失去了足够的资金。"},{"sentence":"The rapid technological shift left many traditional workers unemployed, which forced them to acquire new skills through government programs.","translation":"快速的技术变革使许多传统工人失业，这迫使他们通过政府项目获取新技能。"},{"sentence":"Because the manager left the decision entirely to the inexperienced team, the project suffered from a lack of strategic direction.","translation":"由于经理将决定完全留给缺乏经验的团队，该项目因缺乏战略方向而受损。"},{"sentence":"The devastating earthquake left the coastal city in ruins, thereby necessitating a massive international relief effort.","translation":"毁灭性的地震使这座沿海城市成为废墟，从而需要大规模的国际救援行动。"},{"sentence":"When the lead researcher left the institution, she entrusted her unfinished work to a junior colleague who later made a breakthrough.","translation":"当首席研究员离开该机构时，她将未完成的工作托付给了一位后来取得突破的初级同事。"}]},"report":{"examples":[{"sentence":"The annual sustainability report indicates that the company has reduced its carbon footprint by thirty percent over the past five years.","translation":"年度可持续发展报告显示，该公司在过去五年中将碳足迹减少了百分之三十。"},{"sentence":"Because the journalist failed to verify her sources, the report contained several inaccuracies that damaged the newspaper's credibility.","translation":"由于记者未能核实她的消息来源，该报道包含几处不准确之处，损害了报纸的可信度。"},{"sentence":"According to the latest census report, the urban population has grown significantly, whereas rural areas have experienced a steady decline.","translation":"根据最新的人口普查报告，城市人口显著增长，而农村地区则经历了持续下降。"},{"sentence":"The committee will report its findings directly to the board, which will then decide whether to implement the proposed reforms.","translation":"委员会将直接向董事会报告其调查结果，然后董事会将决定是否实施拟议的改革。"},{"sentence":"Rather than simply report the data, the analyst provided a comprehensive interpretation that highlighted underlying trends and potential risks.","translation":"分析师没有简单地报告数据，而是提供了全面的解读，突出了潜在趋势和可能的风险。"}]},"love":{"examples":[{"sentence":"A genuine love of learning, rather than external rewards, sustains students through the most challenging academic pursuits.","translation":"对学习真正的热爱，而非外在奖励，支撑学生度过最艰难的学术追求。"},{"sentence":"Because parental love provides a secure foundation, children who receive consistent affection tend to develop stronger emotional resilience.","translation":"因为父母的爱提供了安全的基础，得到持续关爱的孩子往往能培养出更强的情绪韧性。"},{"sentence":"Although romantic love often inspires great art, its intensity can also lead to profound personal turmoil when expectations clash with reality.","translation":"尽管浪漫的爱情常常激发伟大的艺术，但当期望与现实冲突时，其强烈程度也可能导致深刻的个人动荡。"},{"sentence":"Cultivating a love for nature in early childhood encourages lifelong environmental stewardship, which benefits society as a whole.","translation":"在幼儿时期培养对自然的热爱，能鼓励终生的环境管理，这有益于整个社会。"},{"sentence":"The love that binds a community together becomes most visible when neighbors voluntarily support one another during a crisis.","translation":"当邻居在危机中自愿互相支持时，将社区凝聚在一起的爱变得最为明显。"}]},"tanker":{"examples":[{"sentence":"Because a single oil tanker can transport millions of barrels, its safe operation is critical to preventing environmental disasters at sea.","translation":"因为一艘油轮可以运输数百万桶石油，其安全运营对于防止海上环境灾难至关重要。"},{"sentence":"The aging tanker, which had served for decades without major incident, was finally retired to comply with stricter international regulations.","translation":"那艘服役数十年未发生重大事故的老旧油轮，最终为遵守更严格的国际法规而退役。"},{"sentence":"When a tanker runs aground near a fragile coastline, the resulting oil spill can devastate marine ecosystems for generations.","translation":"当一艘油轮在脆弱的海岸线附近搁浅时，由此产生的石油泄漏可能对海洋生态系统造成几代人的破坏。"},{"sentence":"Investing in double-hulled tanker designs significantly reduces the risk of cargo leakage, thereby protecting both commerce and the environment.","translation":"投资于双层船体油轮设计可显著降低货物泄漏的风险，从而保护商业和环境。"},{"sentence":"Although modern tanker navigation relies on advanced satellite systems, human oversight remains indispensable for avoiding collisions in busy shipping lanes.","translation":"尽管现代油轮导航依赖先进的卫星系统，但在繁忙的航道上避免碰撞，人工监督仍然不可或缺。"}]},"scientist":{"examples":[{"sentence":"Although the scientist faced widespread skepticism, her rigorous methodology eventually convinced the academic community to reconsider established theories.","translation":"尽管这位科学家面临广泛的质疑，但她严谨的方法论最终说服了学术界重新考虑既有理论。"},{"sentence":"Because a scientist must communicate findings clearly, many universities now require doctoral candidates to take courses in public engagement.","translation":"因为科学家必须清晰地传达研究成果，许多大学现在要求博士生修读公众参与课程。"},{"sentence":"The renowned scientist, whose work on renewable energy transformed the industry, emphasized that collaboration accelerates innovation more than competition does.","translation":"那位在可再生能源领域的工作改变了整个行业的著名科学家强调，合作比竞争更能加速创新。"},{"sentence":"When a young scientist challenges a long-held paradigm, the resulting debate often leads to deeper understanding, even if the original idea is ultimately disproven.","translation":"当一位年轻科学家挑战一个长期存在的范式时，由此引发的辩论通常会带来更深刻的理解，即使最初的想法最终被推翻。"},{"sentence":"A responsible scientist must weigh the potential benefits of genetic engineering against ethical concerns, thereby ensuring that progress does not outpace moral reflection.","translation":"一位负责任的科学家必须权衡基因工程的潜在益处与伦理关切，从而确保进步不会超越道德反思。"}]},"natural":{"examples":[{"sentence":"It is natural for young children to feel anxious when they first enter an unfamiliar environment.","translation":"年幼的孩子初次进入陌生环境时感到焦虑是很自然的。"},{"sentence":"Although natural talent plays a role, sustained effort is often the decisive factor in academic achievement.","translation":"虽然天赋有一定作用，但持续的努力往往是学业成就的决定性因素。"},{"sentence":"Governments should invest in preserving natural habitats, because biodiversity loss has irreversible consequences.","translation":"政府应当投资保护自然栖息地，因为生物多样性的丧失会带来不可逆转的后果。"},{"sentence":"A natural consequence of urbanization is the decline of traditional community ties, which can weaken social support networks.","translation":"城市化的一个自然结果是传统社区纽带的衰退，这可能会削弱社会支持网络。"},{"sentence":"When students are encouraged to ask questions, their natural curiosity becomes a powerful driver of learning.","translation":"当学生被鼓励提问时，他们天生的好奇心就会成为学习的强大动力。"}]},"its":{"examples":[{"sentence":"Every educational system has its own strengths and weaknesses, which reflect the cultural values of the society it serves.","translation":"每一种教育体系都有其自身的优点和缺点，这反映了它所服务社会的文化价值观。"},{"sentence":"A company that neglects its employees' well-being may achieve short-term profits, but it will eventually face high turnover and low morale.","translation":"一家忽视员工福祉的公司可能会获得短期利润，但最终将面临高离职率和低士气。"},{"sentence":"The ancient city is famous for its well-preserved architecture, which attracts scholars and tourists from around the world.","translation":"这座古城以其保存完好的建筑而闻名，吸引了来自世界各地的学者和游客。"},{"sentence":"Although the theory was initially controversial, its core principles have since been validated by numerous empirical studies.","translation":"尽管该理论最初存在争议，但其核心原则后来已被大量实证研究所证实。"},{"sentence":"A language loses its vitality when younger generations no longer use it for daily communication.","translation":"当年轻一代不再在日常交流中使用一种语言时，它便失去了生命力。"}]},"mistake":{"examples":[{"sentence":"Although the researcher double-checked the data, a subtle mistake in the statistical analysis led to an incorrect conclusion.","translation":"尽管研究人员仔细核对了数据，但统计分析中的一个细微错误导致了错误的结论。"},{"sentence":"Because the intern failed to clarify the instructions, she made a mistake that delayed the entire project by two weeks.","translation":"由于实习生没有澄清指示，她犯了一个错误，导致整个项目延误了两周。"},{"sentence":"When a mistake is identified early in the design phase, it can be corrected without significant cost or time overruns.","translation":"当错误在设计阶段早期被发现时，可以在没有重大成本或时间超支的情况下纠正。"},{"sentence":"The manager emphasized that learning from a mistake is more valuable than avoiding all risk, which can stifle innovation.","translation":"经理强调，从错误中学习比避免所有风险更有价值，因为后者会扼杀创新。"},{"sentence":"If the government acknowledges its policy mistake promptly, it can restore public trust through transparent corrective measures.","translation":"如果政府及时承认其政策错误，它可以通过透明的纠正措施恢复公众信任。"}]},"meanwhile":{"examples":[{"sentence":"While the government promotes digital innovation, it must, meanwhile, address the growing digital divide that leaves rural communities behind.","translation":"在政府推动数字创新的同时，它必须解决日益扩大的数字鸿沟，这一鸿沟使农村社区落后。"},{"sentence":"The company expanded its overseas markets; meanwhile, it invested in local talent to ensure cultural adaptability.","translation":"该公司拓展了海外市场；与此同时，它投资于本地人才以确保文化适应性。"},{"sentence":"Although the new policy aims to boost economic growth, it may, meanwhile, exacerbate income inequality if not carefully implemented.","translation":"尽管新政策旨在促进经济增长，但如果实施不慎，它可能同时加剧收入不平等。"},{"sentence":"The researchers analyzed the data using advanced algorithms; meanwhile, they validated the results through independent experiments.","translation":"研究人员使用先进算法分析数据；与此同时，他们通过独立实验验证了结果。"},{"sentence":"Because the project deadline was approaching, the team worked overtime; meanwhile, the manager coordinated with external stakeholders to avoid delays.","translation":"由于项目截止日期临近，团队加班工作；与此同时，经理与外部利益相关者协调以避免延误。"}]},"college":{"examples":[{"sentence":"Although college tuition has risen sharply, many students still pursue higher education because it significantly enhances career prospects.","translation":"尽管大学学费大幅上涨，许多学生仍然追求高等教育，因为它显著提升职业前景。"},{"sentence":"The college recently introduced a mentorship program, which pairs students with industry professionals to bridge the gap between theory and practice.","translation":"该学院最近推出了一个导师计划，将学生与行业专业人士配对，以弥合理论与实践之间的差距。"},{"sentence":"While some argue that college is not for everyone, statistics show that graduates earn substantially more over their lifetimes.","translation":"虽然有人认为大学并不适合所有人，但统计数据显示，毕业生一生中的收入要高得多。"},{"sentence":"Because the college emphasizes interdisciplinary research, students are encouraged to collaborate across departments to solve complex problems.","translation":"由于该学院强调跨学科研究，鼓励学生跨部门合作以解决复杂问题。"},{"sentence":"The college's decision to expand online courses has made education more accessible, thereby attracting a diverse student body from around the world.","translation":"该学院扩大在线课程的决定使教育更容易获得，从而吸引了来自世界各地的多元化学生群体。"}]},"costly":{"examples":[{"sentence":"Although renewable energy infrastructure is costly to build, it reduces long-term operational expenses and environmental impact.","translation":"尽管可再生能源基础设施的建设成本高昂，但它减少了长期的运营费用和环境影响。"},{"sentence":"The company's failure to update its cybersecurity systems proved costly when a data breach compromised millions of user records.","translation":"该公司未能更新其网络安全系统，当一次数据泄露危及数百万用户记录时，这被证明代价高昂。"},{"sentence":"Because medical treatments for advanced diseases are often more costly than preventive care, health policies should prioritize early intervention.","translation":"由于晚期疾病的医疗往往比预防性护理更昂贵，卫生政策应优先考虑早期干预。"},{"sentence":"While organic farming is more costly due to labor-intensive practices, it yields products that are free from synthetic pesticides.","translation":"虽然有机农业因劳动密集型做法而成本更高，但它生产出不含合成农药的产品。"},{"sentence":"A poorly designed software system can lead to costly maintenance and frequent downtime, which ultimately affects user satisfaction.","translation":"一个设计不佳的软件系统可能导致昂贵的维护和频繁的停机，最终影响用户满意度。"}]},"reservoir":{"examples":[{"sentence":"The new reservoir will not only supply drinking water to the city but also generate hydroelectric power, thereby reducing reliance on fossil fuels.","translation":"新水库不仅将为城市提供饮用水，还将产生水力发电，从而减少对化石燃料的依赖。"},{"sentence":"Because the reservoir was built without adequate environmental assessment, it disrupted the migration routes of several endangered fish species.","translation":"由于水库在建设时没有进行充分的环境评估，它扰乱了几种濒危鱼类的迁徙路线。"},{"sentence":"Wetlands act as a natural reservoir for floodwaters, which helps to protect downstream communities from catastrophic inundation during heavy rains.","translation":"湿地作为洪水的天然蓄水池，有助于保护下游社区在暴雨期间免受灾难性淹没。"},{"sentence":"The human gut microbiome is a vast reservoir of genetic diversity, which plays a crucial role in digestion and immune function.","translation":"人类肠道微生物组是遗传多样性的巨大储存库，在消化和免疫功能中起着至关重要的作用。"},{"sentence":"Although the reservoir was intended to boost agricultural productivity, its construction led to the displacement of thousands of rural families.","translation":"尽管该水库旨在提高农业生产力，但其建设导致数千农村家庭流离失所。"}]},"badly":{"examples":[{"sentence":"Although the company badly needs to innovate, its rigid culture stifles creative thinking.","translation":"尽管公司迫切需要创新，但其僵化的文化扼杀了创造性思维。"},{"sentence":"Because the instructions were badly written, many users could not assemble the product correctly.","translation":"由于说明书编写得很糟糕，许多用户无法正确组装产品。"},{"sentence":"The economy was so badly affected by the pandemic that recovery took several years.","translation":"经济受到疫情的严重影响，以至于复苏花了好几年时间。"},{"sentence":"When a leader behaves badly, it undermines trust throughout the entire organization.","translation":"当领导者行为不当时，它会破坏整个组织的信任。"},{"sentence":"The building was badly damaged in the earthquake, which made it unsafe for occupancy.","translation":"该建筑在地震中严重受损，这使得它不适合居住。"}]},"turnover":{"examples":[{"sentence":"Although the company's turnover increased by 20 percent, rising operational costs eroded its net profit margin.","translation":"尽管公司营业额增长了20%，但不断上升的运营成本侵蚀了其净利润率。"},{"sentence":"High employee turnover can disrupt team cohesion, which is why many firms invest in retention strategies.","translation":"高员工流失率会破坏团队凝聚力，这就是许多公司投资于留任策略的原因。"},{"sentence":"Efficient inventory turnover ensures that perishable goods are sold before they expire, thereby reducing waste.","translation":"高效的库存周转确保易腐商品在过期前售出，从而减少浪费。"},{"sentence":"Because the restaurant experiences rapid table turnover during peak hours, waitstaff must work with exceptional speed.","translation":"由于餐厅在高峰时段翻台率很高，服务员必须以极快的速度工作。"},{"sentence":"A low asset turnover ratio may indicate that a company is not using its resources effectively to generate sales.","translation":"较低的资产周转率可能表明公司未能有效利用其资源来创造销售额。"}]},"mere":{"examples":[{"sentence":"Although the task seemed a mere formality, it required careful attention to detail.","translation":"虽然这项任务看似仅仅是个形式，但它需要仔细关注细节。"},{"sentence":"Because the evidence was a mere circumstantial link, the jury remained unconvinced of his guilt.","translation":"因为证据仅仅是一个间接的关联，陪审团仍然不相信他有罪。"},{"sentence":"While a mere apology cannot undo the harm, it is an essential first step toward reconciliation.","translation":"虽然仅仅道歉不能消除伤害，但它是走向和解的关键第一步。"},{"sentence":"The mere mention of the controversial topic, which had divided the community for years, reignited heated debates.","translation":"仅仅提到这个多年来分裂社区的有争议话题，就重新引发了激烈的辩论。"},{"sentence":"If we rely on a mere increase in surveillance without addressing root causes, crime rates will not decline.","translation":"如果我们仅仅依靠增加监控而不解决根本原因，犯罪率不会下降。"}]},"crystal":{"examples":[{"sentence":"When the solution cooled slowly, a perfect crystal formed at the bottom of the flask.","translation":"当溶液缓慢冷却时，烧瓶底部形成了一颗完美的晶体。"},{"sentence":"The crystal chandelier, which had been imported from Venice, became the centerpiece of the grand ballroom.","translation":"那盏从威尼斯进口的水晶吊灯，成为了大舞厅的中心装饰。"},{"sentence":"Because the crystal structure of the mineral was highly symmetrical, it exhibited unique optical properties.","translation":"因为这种矿物的晶体结构高度对称，它展现出独特的光学性质。"},{"sentence":"Although the crystal vase appeared delicate, it was surprisingly resistant to thermal shock.","translation":"虽然这个水晶花瓶看起来很精致，但它对热冲击的抵抗力却出奇地强。"},{"sentence":"The scientist used X-ray diffraction to analyze the crystal lattice, thereby determining the atomic arrangement.","translation":"科学家使用X射线衍射分析晶格，从而确定了原子排列。"}]},"mixture":{"examples":[{"sentence":"Because the concrete was a precise mixture of cement, sand, and gravel, it achieved exceptional strength.","translation":"因为混凝土是水泥、沙子和砾石的精确混合物，它达到了非凡的强度。"},{"sentence":"The novel is a compelling mixture of historical fact and imaginative fiction, which appeals to a wide audience.","translation":"这部小说是历史事实与想象虚构的引人入胜的混合物，吸引了广泛的读者。"},{"sentence":"When the chemist combined the two solutions, a cloudy mixture formed, indicating a chemical reaction.","translation":"当化学家混合两种溶液时，形成了浑浊的混合物，表明发生了化学反应。"},{"sentence":"Although the team was a mixture of experienced veterans and new recruits, they collaborated effectively.","translation":"虽然这个团队是经验丰富的老手和新人的混合体，但他们合作得很有效。"},{"sentence":"The policy resulted in a mixture of economic growth and environmental degradation, thereby sparking public debate.","translation":"该政策导致了经济增长和环境退化的混合，从而引发了公众辩论。"}]},"liner":{"examples":[{"sentence":"The ocean liner, which was once a symbol of luxury travel, has been largely replaced by faster air routes for transatlantic journeys.","translation":"远洋班轮曾是奢华旅行的象征，如今已被更快的跨大西洋航线所取代。"},{"sentence":"Engineers installed a protective liner inside the pipeline to prevent corrosion, thereby extending the infrastructure's lifespan significantly.","translation":"工程师在管道内部安装了保护衬里以防止腐蚀，从而显著延长了基础设施的使用寿命。"},{"sentence":"Because the cargo liner operates on a fixed schedule, businesses rely on it for predictable delivery of raw materials.","translation":"由于定期货轮按固定时间表运营，企业依赖它来确保原材料的可预测交付。"},{"sentence":"The pond liner, made of durable synthetic material, effectively prevents water from seeping into the surrounding soil, which is essential for maintaining water levels.","translation":"池塘衬垫由耐用的合成材料制成，能有效防止水渗入周围的土壤，这对维持水位至关重要。"},{"sentence":"As air travel became more affordable, the passenger liner industry declined, leaving only a few nostalgic cruise routes that cater to tourists.","translation":"随着航空旅行变得更加实惠，客运班轮行业逐渐衰落，只留下少数迎合游客的怀旧邮轮航线。"}]},"capital":{"examples":[{"sentence":"Beijing, which is the capital of China, has a history that spans over three millennia.","translation":"北京是中国的首都，拥有超过三千年的历史。"},{"sentence":"Because the startup lacked sufficient capital, it could not expand its operations to new markets.","translation":"由于这家初创公司缺乏足够的资本，它无法将业务扩展到新市场。"},{"sentence":"The government allocated substantial capital to infrastructure projects, thereby stimulating economic growth.","translation":"政府将大量资本分配给基础设施项目，从而刺激了经济增长。"},{"sentence":"Although London is not the geographical center of England, it remains the political and financial capital.","translation":"尽管伦敦不是英格兰的地理中心，但它仍然是政治和金融首都。"},{"sentence":"Venture capital firms often invest in high-risk startups that have the potential for rapid growth.","translation":"风险资本公司经常投资于具有快速增长潜力的高风险初创企业。"}]},"wheel":{"examples":[{"sentence":"The invention of the wheel, which occurred around 3500 BC, revolutionized transportation and trade.","translation":"轮子的发明大约在公元前3500年，彻底改变了运输和贸易。"},{"sentence":"Because the steering wheel malfunctioned, the driver lost control of the vehicle and veered off the road.","translation":"由于方向盘发生故障，驾驶员失去了对车辆的控制，偏离了道路。"},{"sentence":"A Ferris wheel offers passengers a panoramic view of the city, thereby attracting many tourists.","translation":"摩天轮为乘客提供城市的全景视野，从而吸引了许多游客。"},{"sentence":"Although the wheel appears to be a simple device, its design requires precise engineering to bear heavy loads.","translation":"尽管轮子看似简单的装置，但其设计需要精密工程来承受重载。"},{"sentence":"The potter shaped the clay on a spinning wheel, which allowed her to create symmetrical vessels.","translation":"陶工在旋转的轮子上塑造黏土，这使她能够制作对称的容器。"}]},"drawer":{"examples":[{"sentence":"Although the drawer was labeled as containing office supplies, it actually held a collection of rare coins.","translation":"尽管抽屉上标着装有办公用品，但实际上里面收藏着稀有硬币。"},{"sentence":"Because the drawer was stuck due to humidity, the librarian had to use a special tool to open it.","translation":"由于抽屉因潮湿卡住了，图书管理员不得不使用特殊工具来打开它。"},{"sentence":"When the detective examined the bottom drawer, he found a hidden compartment that contained crucial evidence.","translation":"当侦探检查最底层的抽屉时，他发现了一个隐藏的隔层，里面装有关键证据。"},{"sentence":"To ensure that the drawer would not accidentally open during transport, the movers secured it with strong tape.","translation":"为了确保抽屉在运输过程中不会意外打开，搬运工用强力胶带将其固定。"},{"sentence":"The antique desk, which had a secret drawer, was sold at auction for a surprisingly high price.","translation":"那张有一个秘密抽屉的古董书桌在拍卖会上以惊人的高价售出。"}]},"midst":{"examples":[{"sentence":"Although the negotiations were in the midst of a deadlock, the mediator proposed a creative compromise that eventually broke the impasse.","translation":"尽管谈判正处于僵局之中，调解人提出了一个创造性的妥协方案，最终打破了僵局。"},{"sentence":"In the midst of a severe drought, the government implemented water rationing to ensure that essential services could continue operating.","translation":"在严重干旱之中，政府实施了用水配给，以确保基本服务能够继续运行。"},{"sentence":"The discovery of ancient ruins in the midst of the construction site forced the developers to halt the project while archaeologists conducted a thorough excavation.","translation":"在建筑工地中间发现古代遗址，迫使开发商暂停项目，同时考古学家进行了彻底挖掘。"},{"sentence":"Because the company was in the midst of a digital transformation, it invested heavily in upskilling its workforce to avoid widespread job displacement.","translation":"因为公司正处于数字化转型之中，它大力投资于提升员工技能，以避免大规模的工作岗位流失。"},{"sentence":"In the midst of a heated election campaign, the candidate maintained a calm demeanor, which helped to reassure undecided voters.","translation":"在激烈的竞选活动之中，候选人保持冷静的举止，这有助于安抚犹豫不决的选民。"}]},"probable":{"examples":[{"sentence":"Given the steady decline in birth rates, it is highly probable that the population will shrink over the next two decades.","translation":"鉴于出生率持续下降，未来二十年人口很可能会减少。"},{"sentence":"Although the experiment is still in progress, the most probable outcome aligns with the initial hypothesis.","translation":"尽管实验仍在进行，最可能的结果与最初的假设一致。"},{"sentence":"If current emission trends continue, a rise in global temperatures of more than two degrees becomes increasingly probable.","translation":"如果当前的排放趋势持续下去，全球气温上升超过两度就变得越来越可能。"},{"sentence":"The committee concluded that a compromise was the only probable path to securing bipartisan support.","translation":"委员会得出结论，妥协是获得两党支持唯一可能的途径。"},{"sentence":"Because the patient exhibited all the classic symptoms, the physician considered a viral infection the most probable diagnosis.","translation":"由于患者表现出所有典型症状，医生认为病毒感染是最可能的诊断。"}]},"cupboard":{"examples":[{"sentence":"Although the cupboard was antique, its shelves were reinforced to hold heavy ceramic dishes safely.","translation":"尽管这个橱柜是古董，但它的搁板被加固了，以便安全地放置沉重的陶瓷盘子。"},{"sentence":"The laboratory cupboard, which stores hazardous chemicals, must be inspected regularly to ensure compliance with safety regulations.","translation":"存放危险化学品的实验室橱柜必须定期检查，以确保符合安全规定。"},{"sentence":"Because the kitchen cupboard was poorly organized, finding a specific spice often took several frustrating minutes.","translation":"由于厨房的碗柜整理不善，找到一种特定的香料常常要花好几分钟，令人沮丧。"},{"sentence":"When the floodwaters receded, the wooden cupboard had warped beyond repair, forcing the family to replace it.","translation":"当洪水退去后，木制的食橱已经变形得无法修复，迫使这家人更换它。"},{"sentence":"The school cupboard, filled with art supplies, was relocated to a brighter corner, thereby encouraging more creative activities.","translation":"学校放满美术用品的柜子被移到了一个更明亮的角落，从而鼓励了更多的创意活动。"}]},"driver":{"examples":[{"sentence":"A primary driver of economic inequality is the uneven distribution of educational resources, which perpetuates social stratification.","translation":"经济不平等的一个主要驱动因素是教育资源分布不均，这使社会分层长期持续。"},{"sentence":"Although the bus driver faced heavy traffic, she maintained a calm demeanor, thereby ensuring passenger safety.","translation":"尽管公交车司机遇到了严重的交通堵塞，但她保持冷静的态度，从而确保了乘客的安全。"},{"sentence":"Because the device driver was incompatible with the updated operating system, the printer ceased to function properly.","translation":"由于设备驱动程序与更新的操作系统不兼容，打印机无法正常工作。"},{"sentence":"The taxi driver, who knew every shortcut in the city, chose a route that avoided the morning rush hour entirely.","translation":"那位熟悉城市每条捷径的出租车司机选择了一条完全避开早高峰的路线。"},{"sentence":"Technological innovation is often cited as the key driver behind long-term productivity growth, rather than mere capital accumulation.","translation":"技术创新常被认为是长期生产力增长背后的关键驱动力，而非单纯的资本积累。"}]},"dominant":{"examples":[{"sentence":"Although the company holds a dominant market share, it continues to invest heavily in innovation to maintain its lead.","translation":"尽管该公司占据市场支配地位，但它仍大力投资创新以保持领先。"},{"sentence":"In many ecosystems, a single dominant species can shape the entire community structure, which affects biodiversity.","translation":"在许多生态系统中，单一的优势物种可以塑造整个群落结构，从而影响生物多样性。"},{"sentence":"Because the dominant narrative in the media often overlooks marginalized perspectives, alternative voices are gaining traction online.","translation":"由于媒体中的主流叙事常常忽视边缘视角，替代声音在网上正获得关注。"},{"sentence":"A dominant allele will express its trait even when paired with a recessive one, thereby determining the organism's phenotype.","translation":"显性等位基因即使与隐性等位基因配对也会表达其性状，从而决定生物体的表型。"},{"sentence":"While renewable energy is expanding, fossil fuels remain the dominant source of global power generation, which poses environmental challenges.","translation":"尽管可再生能源在扩张，化石燃料仍然是全球发电的主要来源，这带来了环境挑战。"}]},"percentage":{"examples":[{"sentence":"Although a large percentage of the budget is allocated to research, the returns on investment remain uncertain.","translation":"尽管预算的很大一部分被分配给研究，但投资回报仍不确定。"},{"sentence":"The percentage of students who pass the exam on their first attempt has increased because the school introduced intensive preparatory courses.","translation":"因为学校引入了强化预备课程，首次尝试就通过考试的学生比例有所增加。"},{"sentence":"While the percentage of renewable energy usage grows, fossil fuels still dominate the global energy mix.","translation":"虽然可再生能源使用的比例在增长，但化石燃料仍主导着全球能源结构。"},{"sentence":"A significant percentage of employees report higher job satisfaction when they are given flexible working hours, which enhances overall productivity.","translation":"当员工获得灵活工作时间时，有相当比例的人报告更高的工作满意度，这提高了整体生产力。"},{"sentence":"The percentage of elderly citizens in the population is rising, thereby increasing the demand for healthcare services.","translation":"人口中老年公民的比例正在上升，从而增加了对医疗服务的需求。"}]},"lure":{"examples":[{"sentence":"Despite the lure of high salaries in the private sector, many graduates choose public service to contribute to society.","translation":"尽管私营部门高薪的诱惑，许多毕业生仍选择公共服务以贡献社会。"},{"sentence":"The lure of quick profits often leads investors to overlook long-term risks, which can result in significant losses.","translation":"快速获利的诱惑常常使投资者忽视长期风险，这可能导致重大损失。"},{"sentence":"Because the lure of social media is so strong, students must develop self-discipline to maintain their academic focus.","translation":"因为社交媒体的诱惑如此强烈，学生必须培养自律以保持学业专注。"},{"sentence":"While the lure of urban life attracts many young people, the high cost of living can offset the benefits of higher wages.","translation":"虽然城市生活的诱惑吸引了许多年轻人，但高昂的生活成本可能抵消较高工资的好处。"},{"sentence":"The lure of fame and fortune drives some individuals to take unethical shortcuts, thereby damaging their long-term reputation.","translation":"名利的诱惑驱使一些人采取不道德的捷径，从而损害他们的长期声誉。"}]},"specialist":{"examples":[{"sentence":"Although the general practitioner suspected a common allergy, she referred the patient to a specialist to ensure an accurate diagnosis.","translation":"尽管全科医生怀疑是常见的过敏，她还是将患者转诊给专科医生以确保准确诊断。"},{"sentence":"Because the legal dispute involved complex international regulations, the firm hired a specialist who had decades of experience in cross-border litigation.","translation":"由于法律纠纷涉及复杂的国际法规，公司聘请了一位在跨境诉讼方面有数十年经验的专家。"},{"sentence":"The university invited a specialist in renewable energy to deliver a lecture, which inspired many students to pursue careers in sustainable technology.","translation":"大学邀请了一位可再生能源专家来做讲座，这激发了许多学生投身于可持续技术事业。"},{"sentence":"When the software system crashed repeatedly, the IT department called in a specialist rather than attempting further repairs themselves.","translation":"当软件系统反复崩溃时，IT部门请来了一位专家，而不是自己尝试进一步维修。"},{"sentence":"A specialist in ancient manuscripts can decipher texts that have remained unreadable for centuries, thereby unlocking lost knowledge.","translation":"古代手稿专家能够破译几个世纪以来一直无法阅读的文本，从而解锁失落的知识。"}]},"miserable":{"examples":[{"sentence":"Although she achieved professional success, she felt miserable because her personal relationships had deteriorated over time.","translation":"尽管她在事业上取得了成功，但由于人际关系逐渐恶化，她感到痛苦不堪。"},{"sentence":"The prolonged economic recession made life miserable for many families, which forced them to cut back on essential expenses.","translation":"长期的经济衰退使许多家庭生活悲惨，这迫使他们削减基本开支。"},{"sentence":"When the project failed due to poor planning, the team leader was miserable, knowing that his oversight had cost the company dearly.","translation":"当项目因计划不周而失败时，团队领导感到痛苦，因为他知道自己的疏忽让公司付出了沉重代价。"},{"sentence":"Because the prisoners were confined in cramped cells without adequate sanitation, their existence was utterly miserable.","translation":"由于囚犯被关押在狭窄且卫生条件不足的牢房里，他们的生活极其悲惨。"},{"sentence":"Students who are bullied often feel miserable at school, which can lead to a decline in their academic performance and mental health.","translation":"遭受欺凌的学生在学校经常感到痛苦，这可能导致他们的学业成绩和心理健康下降。"}]},"punch":{"examples":[{"sentence":"The new industrial punch can process metal sheets with remarkable speed, thereby increasing the factory's overall productivity.","translation":"这台新的工业冲床能以惊人的速度加工金属板，从而提高了工厂的整体生产力。"},{"sentence":"Although he was provoked, he refrained from throwing a punch, because he knew that violence would only escalate the conflict.","translation":"尽管被激怒了，他还是忍住没有出拳，因为他知道暴力只会使冲突升级。"},{"sentence":"The speech lacked a strong punch at the end, which left the audience feeling uninspired rather than motivated to take action.","translation":"演讲结尾缺乏有力的冲击力，这让听众感到平淡无奇，而不是受到激励去采取行动。"},{"sentence":"To ensure precise hole placement, the technician used a center punch before drilling into the metal component.","translation":"为了确保孔位精确，技术员在钻入金属部件之前使用了中心冲。"},{"sentence":"When the boxer delivered a powerful punch to his opponent's jaw, the referee immediately stopped the match to check for injury.","translation":"当拳击手向对手的下巴猛击一拳时，裁判立即暂停比赛以检查是否受伤。"}]},"sway":{"examples":[{"sentence":"The sway of public opinion can shape government policy, especially when citizens actively engage in democratic processes.","translation":"公众舆论的影响力可以左右政府政策，尤其是当公民积极参与民主进程时。"},{"sentence":"Although traditional media still holds considerable sway, social media platforms are increasingly influencing how people perceive current events.","translation":"尽管传统媒体仍具有相当大的影响力，但社交媒体平台正日益影响人们对时事的看法。"},{"sentence":"The sway of peer pressure during adolescence can lead young people to make decisions that conflict with their long-term interests.","translation":"青春期同伴压力的影响力可能导致年轻人做出与自身长远利益相悖的决定。"},{"sentence":"To reduce the sway of cognitive biases, researchers should design experiments that incorporate double-blind procedures and random assignment.","translation":"为减少认知偏差的影响，研究人员应设计包含双盲程序和随机分配的实验。"},{"sentence":"Because charismatic leaders can exert great sway over their followers, it is essential to foster critical thinking within organizations.","translation":"由于魅力型领导者能对其追随者施加巨大影响，在组织内部培养批判性思维至关重要。"}]},"extreme":{"examples":[{"sentence":"Although some argue that extreme measures are necessary during crises, such actions can erode public trust in institutions.","translation":"尽管有人认为在危机期间极端措施是必要的，但此类行为会侵蚀公众对机构的信任。"},{"sentence":"Because the extreme of wealth inequality can destabilize societies, progressive taxation is often proposed as a remedy.","translation":"由于财富不平等的极端可能破坏社会稳定，累进税制常被提议作为补救措施。"},{"sentence":"When policymakers ignore the extreme of climate change, they risk catastrophic consequences for future generations.","translation":"当政策制定者忽视气候变化的极端时，他们会使后代面临灾难性后果的风险。"},{"sentence":"The extreme of nationalism, if left unchecked, can lead to xenophobia and international conflict.","translation":"民族主义的极端，如果不加遏制，会导致仇外心理和国际冲突。"},{"sentence":"To avoid the extreme of burnout, employees should maintain a healthy work-life balance through regular breaks and exercise.","translation":"为避免过度劳累的极端，员工应通过定期休息和锻炼来保持健康的工作与生活平衡。"}]},"vigorous":{"examples":[{"sentence":"A vigorous exercise routine, which includes both aerobic and strength training, can significantly improve cardiovascular health.","translation":"一套包括有氧和力量训练的充满活力的锻炼计划，可以显著改善心血管健康。"},{"sentence":"Because vigorous competition in the tech industry drives innovation, consumers benefit from better products and lower prices.","translation":"由于科技行业激烈的竞争推动创新，消费者受益于更好的产品和更低的价格。"},{"sentence":"Although the plant appeared delicate, its vigorous growth in harsh conditions surprised the botanists.","translation":"尽管这株植物看起来娇弱，但它在恶劣条件下旺盛的生长令植物学家惊讶。"},{"sentence":"The government's vigorous promotion of renewable energy has reduced carbon emissions, thereby mitigating climate change.","translation":"政府对可再生能源的大力推广减少了碳排放，从而缓解了气候变化。"},{"sentence":"To ensure a vigorous democracy, citizens must engage in informed debate and hold their leaders accountable.","translation":"为确保一个充满活力的民主，公民必须参与知情的辩论并追究领导人的责任。"}]},"easter":{"examples":[{"sentence":"Although Easter is primarily a Christian holiday, many non-religious families enjoy traditions such as egg hunts and festive meals.","translation":"尽管复活节主要是基督教节日，但许多非宗教家庭也享受寻蛋和节日大餐等传统。"},{"sentence":"Because Easter falls on the first Sunday after the first full moon following the spring equinox, its date varies each year.","translation":"因为复活节在春分后第一个满月后的第一个星期日，所以其日期每年都不同。"},{"sentence":"The company launched a marketing campaign that tied its new product to Easter themes, thereby increasing seasonal sales.","translation":"该公司发起了一场营销活动，将其新产品与复活节主题联系起来，从而提高了季节性销售额。"},{"sentence":"While Easter symbolizes rebirth and hope in Western cultures, it also coincides with spring festivals in many other traditions.","translation":"虽然复活节在西方文化中象征重生和希望，但它也与许多其他传统中的春节同时发生。"},{"sentence":"Schools often schedule a break around Easter, which allows families to travel together during the pleasant spring weather.","translation":"学校通常在复活节前后安排假期，这使得家庭可以在宜人的春季天气中一起旅行。"}]},"permanent":{"examples":[{"sentence":"Although the job started as a temporary position, her exceptional performance led to a permanent contract.","translation":"尽管这份工作最初是临时职位，但她出色的表现使她获得了永久合同。"},{"sentence":"The government decided to establish a permanent committee to address climate change, rather than relying on ad hoc task forces.","translation":"政府决定成立一个常设委员会来应对气候变化，而不是依赖临时工作组。"},{"sentence":"Because the sculpture is a permanent installation in the park, it must withstand all weather conditions.","translation":"因为这座雕塑是公园里的永久装置，所以它必须能承受各种天气条件。"},{"sentence":"While some effects of the medication are temporary, others may cause permanent changes to brain chemistry.","translation":"虽然药物的某些作用是暂时的，但其他作用可能会对大脑化学产生永久性改变。"},{"sentence":"The treaty aimed to create a permanent peace between the two nations, thereby ending decades of conflict.","translation":"该条约旨在两国之间建立永久和平，从而结束数十年的冲突。"}]},"rough":{"examples":[{"sentence":"Although the sea was rough, the experienced sailors navigated the vessel safely to the harbor.","translation":"尽管海面波涛汹涌，经验丰富的水手们还是将船安全驶入港口。"},{"sentence":"The architect presented a rough sketch of the building, which will be refined after client feedback.","translation":"建筑师展示了建筑的草图，将在客户反馈后进一步完善。"},{"sentence":"Because the terrain was rough and uneven, the construction team had to use specialized equipment to lay the foundation.","translation":"由于地形崎岖不平，施工队不得不使用专用设备来打地基。"},{"sentence":"A rough estimate suggests that the project will cost around two million dollars, but a detailed budget is still needed.","translation":"粗略估计表明该项目将花费约两百万美元，但仍需要详细的预算。"},{"sentence":"While the initial draft was rough, it provided a solid framework that the team could develop into a polished report.","translation":"虽然初稿很粗糙，但它提供了一个坚实的框架，团队可以将其发展成一份精炼的报告。"}]},"vertical":{"examples":[{"sentence":"Because the cliff face is nearly vertical, climbers must use specialized equipment to ascend safely.","translation":"因为悬崖面几乎是垂直的，登山者必须使用专业设备才能安全攀登。"},{"sentence":"The vertical integration of the supply chain, which reduces costs and improves efficiency, is a key strategy for the company.","translation":"供应链的垂直整合降低了成本并提高了效率，是公司的一项关键战略。"},{"sentence":"Although horizontal collaboration is common, vertical partnerships between firms can foster innovation in niche markets.","translation":"尽管横向合作很常见，但公司间的垂直合作可以在利基市场促进创新。"},{"sentence":"The architect incorporated a vertical atrium that allows natural light to penetrate all floors of the building.","translation":"建筑师设计了一个垂直中庭，使自然光能够穿透建筑物的所有楼层。"},{"sentence":"When analyzing social hierarchies, researchers often examine vertical mobility to understand changes in status over time.","translation":"在分析社会等级时，研究人员经常考察垂直流动性，以了解地位随时间的变化。"}]},"flexible":{"examples":[{"sentence":"A flexible curriculum allows students to pursue interdisciplinary interests while still meeting core requirements.","translation":"灵活的课程设置使学生能够追求跨学科兴趣，同时仍满足核心要求。"},{"sentence":"Because remote work offers flexible hours, many employees report higher job satisfaction and better work-life balance.","translation":"由于远程工作提供灵活的工作时间，许多员工表示工作满意度更高，工作与生活的平衡也更好。"},{"sentence":"Governments that adopt flexible policies can respond more effectively to rapid economic changes than those with rigid regulations.","translation":"采取灵活政策的政府比那些法规僵化的政府能更有效地应对快速的经济变化。"},{"sentence":"Although the material is highly flexible, it retains sufficient strength to be used in lightweight construction.","translation":"尽管这种材料非常柔韧，但它仍保持足够的强度，可用于轻质建筑。"},{"sentence":"To foster innovation, organizations should cultivate a flexible culture that encourages experimentation and tolerates failure.","translation":"为了促进创新，组织应培养一种灵活的文化，鼓励实验并容忍失败。"}]},"goodby":{"examples":[{"sentence":"Although the word goodby is simple, it often carries a weight of unspoken emotions when parting from close friends.","translation":"虽然再见这个词很简单，但与密友分别时，它往往承载着未言明的情感重量。"},{"sentence":"Because a sincere goodby can ease the pain of separation, many cultures have developed elaborate farewell rituals.","translation":"因为真诚的再见能减轻分离的痛苦，许多文化发展出了精心设计的告别仪式。"},{"sentence":"When the exchange students said their final goodby, they promised to maintain their cross-cultural friendships through regular video calls.","translation":"当交换生们最后说再见时，他们承诺通过定期视频通话来维持跨文化友谊。"},{"sentence":"The retiring CEO's goodby speech, which emphasized gratitude and future hopes, left a lasting impression on all employees.","translation":"退休CEO的告别演说强调了感激和未来希望，给所有员工留下了持久印象。"},{"sentence":"Without a proper goodby, unresolved conflicts can linger, making it harder to achieve emotional closure after a long-term relationship ends.","translation":"没有恰当的再见，未解决的冲突会持续存在，使得长期关系结束后更难实现情感上的了结。"}]},"brow":{"examples":[{"sentence":"Although she maintained a calm expression, the slight furrow of her brow revealed her deep concern about the project's outcome.","translation":"尽管她保持平静的表情，但眉头微蹙显露出她对项目结果的深切担忧。"},{"sentence":"Because the intense sunlight caused him to constantly wipe his brow, he decided to wear a wide-brimmed hat during fieldwork.","translation":"因为强烈的阳光使他不断擦拭额头，他决定在野外工作时戴一顶宽边帽。"},{"sentence":"When the professor raised a skeptical brow, the student realized that her argument needed more substantial evidence to be convincing.","translation":"当教授扬起怀疑的眉毛时，学生意识到她的论点需要更实质性的证据才能令人信服。"},{"sentence":"The ancient statue's smooth brow, which symbolized wisdom and serenity, inspired the artist to incorporate similar features into his modern sculptures.","translation":"古代雕像光滑的额头象征着智慧和宁静，启发艺术家将类似特征融入他的现代雕塑中。"},{"sentence":"Despite the stress of the negotiation, he kept his brow unfurrowed, thereby projecting an image of confidence and control.","translation":"尽管谈判压力很大，他保持眉头舒展，从而展现出自信和掌控的形象。"}]},"purple":{"examples":[{"sentence":"Although purple is often linked to royalty, it can also evoke feelings of creativity and calm in modern design.","translation":"尽管紫色常与皇室联系在一起，但在现代设计中它也能唤起创造力和平静的感觉。"},{"sentence":"Because the dye was historically expensive, purple garments were reserved for emperors and high-ranking officials.","translation":"由于这种染料历史上非常昂贵，紫色服装仅供皇帝和高级官员使用。"},{"sentence":"When mixed with blue, purple creates a sense of depth that is frequently used in abstract paintings.","translation":"当与蓝色混合时，紫色创造出一种深度感，这种手法常用于抽象绘画中。"},{"sentence":"The sunset painted the sky in shades of purple, which reminded the poet of a velvet curtain slowly descending.","translation":"落日将天空染成紫色，这让诗人想起缓缓降下的天鹅绒幕布。"},{"sentence":"If you want to convey luxury and wisdom in your brand, purple is an excellent choice for the logo.","translation":"如果你想在品牌中传达奢华与智慧，紫色是标志的绝佳选择。"}]},"quarterly":{"examples":[{"sentence":"The company issues a quarterly earnings report, which allows investors to track its financial health over time.","translation":"公司发布季度收益报告，这使投资者能够长期跟踪其财务健康状况。"},{"sentence":"Because the journal is published quarterly, it can include comprehensive research articles that require extensive peer review.","translation":"由于该期刊每季度出版一次，它可以收录需要广泛同行评审的综合性研究文章。"},{"sentence":"Government agencies release quarterly GDP data, which often influence monetary policy decisions.","translation":"政府机构发布季度GDP数据，这常常影响货币政策决策。"},{"sentence":"While monthly meetings address immediate issues, quarterly reviews allow the team to assess long-term progress.","translation":"虽然月度会议处理眼前的问题，但季度审查使团队能够评估长期进展。"},{"sentence":"Subscribing to a quarterly magazine can provide curated insights, thereby saving readers time in filtering information.","translation":"订阅季刊可以提供精选的见解，从而节省读者筛选信息的时间。"}]},"stability":{"examples":[{"sentence":"A well-designed constitution provides the stability that allows democratic institutions to mature over time.","translation":"一部精心设计的宪法提供了稳定性，使民主制度能够随着时间的推移而成熟。"},{"sentence":"Because emotional stability is essential for effective leadership, many organizations now invest in resilience training for managers.","translation":"由于情绪稳定性对于有效领导至关重要，许多组织现在为管理者投资韧性培训。"},{"sentence":"Although short-term volatility attracts speculators, long-term investors consistently prioritize the stability of returns over rapid gains.","translation":"尽管短期波动吸引投机者，但长期投资者始终将回报的稳定性置于快速收益之上。"},{"sentence":"The central bank's primary mandate is to maintain price stability, which in turn fosters consumer confidence and sustainable growth.","translation":"中央银行的主要职责是维持物价稳定，这反过来又促进了消费者信心和可持续增长。"},{"sentence":"Researchers found that the stability of a child's home environment significantly predicts academic achievement later in life.","translation":"研究人员发现，儿童家庭环境的稳定性显著预示了日后的学业成就。"}]},"verdict":{"examples":[{"sentence":"Although the jury reached a guilty verdict, the defense attorney immediately announced plans to appeal the decision.","translation":"尽管陪审团作出了有罪裁决，但辩护律师立即宣布计划对判决提出上诉。"},{"sentence":"The court's verdict, which was delivered after a six-month trial, set a new legal precedent for corporate liability cases.","translation":"法院在为期六个月的审判后作出的判决，为公司责任案件树立了新的法律先例。"},{"sentence":"Because the verdict hinged on a single piece of DNA evidence, the prosecution faced intense scrutiny from legal experts.","translation":"由于裁决取决于一项DNA证据，检方面临着法律专家的严格审查。"},{"sentence":"When the final verdict was read aloud, the defendant showed no visible emotion, thereby surprising the courtroom observers.","translation":"当最终判决被大声宣读时，被告没有表现出明显的情绪，从而使法庭观察者感到惊讶。"},{"sentence":"The public's verdict on the new education policy was overwhelmingly negative, which prompted the government to reconsider its approach.","translation":"公众对新教育政策的评判绝大多数是负面的，这促使政府重新考虑其做法。"}]},"medicine":{"examples":[{"sentence":"Although modern medicine has made remarkable progress, many rural areas still lack access to basic healthcare services.","translation":"尽管现代医学取得了显著进步，许多农村地区仍然缺乏基本医疗服务。"},{"sentence":"Traditional Chinese medicine, which relies on natural herbs and holistic diagnosis, is gaining recognition worldwide.","translation":"依赖天然草药和整体诊断的中医正在全球获得认可。"},{"sentence":"Because the new medicine targets the virus directly, it has proven more effective than previous treatments.","translation":"因为这种新药直接针对病毒，它被证明比以前的治疗方法更有效。"},{"sentence":"Studying medicine requires not only a strong academic foundation but also a genuine desire to help others.","translation":"学医不仅需要扎实的学术基础，还需要真诚帮助他人的愿望。"},{"sentence":"The government increased funding for preventive medicine, thereby reducing the long-term burden on hospitals.","translation":"政府增加了对预防医学的资助，从而减轻了医院的长期负担。"}]},"vessel":{"examples":[{"sentence":"Although the fishing vessel encountered a severe storm, its reinforced hull prevented any structural damage.","translation":"尽管这艘渔船遭遇了猛烈的风暴，但其加固的船体防止了任何结构损坏。"},{"sentence":"The laboratory uses a sealed glass vessel to contain volatile chemicals, thereby ensuring the safety of the researchers.","translation":"实验室使用密封的玻璃容器来盛装挥发性化学物质，从而确保研究人员的安全。"},{"sentence":"Because the blood vessel was constricted, the patient experienced numbness in his extremities until the medication took effect.","translation":"由于血管收缩，患者四肢感到麻木，直到药物生效后才缓解。"},{"sentence":"The ancient clay vessel, which was unearthed during the excavation, provided crucial evidence of early trade networks.","translation":"在挖掘过程中出土的古代陶器，为早期贸易网络提供了关键证据。"},{"sentence":"When designing a pressure vessel for deep-sea exploration, engineers must account for immense external forces to ensure structural integrity.","translation":"在设计用于深海探索的压力容器时，工程师必须考虑巨大的外部力量以确保结构完整性。"}]},"conservation":{"examples":[{"sentence":"Because conservation of the wetlands is critical for migratory birds, the government has designated the area a protected reserve.","translation":"由于湿地保护对候鸟至关重要，政府已将该地区划为保护区。"},{"sentence":"The conservation of ancient manuscripts requires controlled temperature and humidity, which prevents further deterioration of the fragile paper.","translation":"古代手稿的保护需要控制温度和湿度，这可以防止脆弱纸张的进一步恶化。"},{"sentence":"Although conservation efforts have increased the panda population, habitat fragmentation remains a serious threat to their long-term survival.","translation":"尽管保护工作增加了大熊猫的数量，但栖息地破碎化仍对其长期生存构成严重威胁。"},{"sentence":"Effective energy conservation in buildings can be achieved through better insulation, which reduces the need for heating and cooling.","translation":"通过更好的隔热可以实现建筑的有效节能，从而减少供暖和制冷的需求。"},{"sentence":"The conservation of marine biodiversity depends not only on reducing pollution but also on establishing sustainable fishing practices.","translation":"海洋生物多样性的保护不仅取决于减少污染，还取决于建立可持续的捕捞方式。"}]},"rug":{"examples":[{"sentence":"Although the rug was handwoven from natural fibers, it proved remarkably resistant to stains and fading.","translation":"尽管这块地毯是用天然纤维手工编织的，但它却非常耐污和不易褪色。"},{"sentence":"Because the antique rug contained delicate silk threads, it required professional cleaning to preserve its luster.","translation":"由于这块古董地毯含有精致的丝线，因此需要专业清洗以保持其光泽。"},{"sentence":"The interior designer placed a vibrant rug beneath the dining table, which instantly warmed the minimalist space.","translation":"室内设计师在餐桌下放置了一块鲜艳的地毯，这立刻让极简风格的空间变得温馨起来。"},{"sentence":"When the company tried to sweep the safety violations under the rug, a whistleblower exposed the cover-up to the media.","translation":"当公司试图掩盖安全违规行为时，一名举报人向媒体揭露了这一掩盖行为。"},{"sentence":"A well-chosen rug can define a seating area in an open-plan room, thereby creating a sense of intimacy without walls.","translation":"一块精心挑选的地毯可以在开放式房间中界定出座位区，从而在没有墙壁的情况下营造出亲密感。"}]},"roundabout":{"examples":[{"sentence":"Although the roundabout explanation seemed inefficient, it ultimately preserved the team's morale during the restructuring.","translation":"尽管这种委婉的解释看似效率低下，但它最终在重组期间维护了团队的士气。"},{"sentence":"The negotiator used a roundabout strategy to address the sensitive topic, which prevented an immediate breakdown in talks.","translation":"谈判者采用迂回策略来处理敏感话题，从而避免了谈判的立即破裂。"},{"sentence":"Because the direct question might have caused embarrassment, she chose a roundabout way to inquire about his plans.","translation":"因为直接提问可能会造成尴尬，她选择了一种委婉的方式来询问他的计划。"},{"sentence":"The roundabout route through the countryside, while longer, offered a scenic alternative to the congested highway.","translation":"这条穿越乡村的迂回路线虽然更长，却为拥堵的高速公路提供了一条风景优美的替代路线。"},{"sentence":"His roundabout reasoning, which initially frustrated the committee, eventually revealed a critical flaw in the proposal.","translation":"他迂回的推理起初让委员会感到沮丧，但最终揭示了提案中的一个关键缺陷。"}]},"cord":{"examples":[{"sentence":"The electrician replaced the worn extension cord to ensure the workshop met safety regulations.","translation":"电工更换了磨损的延长线，以确保车间符合安全规定。"},{"sentence":"Because the spinal cord is essential for transmitting neural signals, any injury can have severe consequences.","translation":"因为脊髓对于传递神经信号至关重要，任何损伤都可能带来严重后果。"},{"sentence":"The mountaineer used a durable nylon cord to secure the tent, which withstood the strong winds overnight.","translation":"登山者用一根耐用的尼龙绳固定帐篷，这使帐篷经受住了整夜的强风。"},{"sentence":"In traditional bookbinding, artisans rely on a waxed cord to stitch the pages together, thereby creating a durable spine.","translation":"在传统书籍装订中，工匠依靠蜡线将书页缝合在一起，从而形成耐用的书脊。"},{"sentence":"The umbilical cord provides vital nutrients and oxygen to the fetus, while also removing waste products.","translation":"脐带为胎儿提供重要的营养物质和氧气，同时清除废物。"}]},"film":{"examples":[{"sentence":"The documentary film, which examines the effects of urbanization on wildlife, has been screened at international festivals.","translation":"这部探讨城市化对野生动物影响的纪录片已在国际电影节上展映。"},{"sentence":"A thin film of oil on the water surface can block sunlight, thereby disrupting the photosynthesis of aquatic plants.","translation":"水面上的一层薄油膜会阻挡阳光，从而干扰水生植物的光合作用。"},{"sentence":"To protect the delicate surface, the technician applied a transparent film that resists scratches and UV radiation.","translation":"为了保护脆弱的表面，技术人员涂上了一层能抵抗划痕和紫外线的透明薄膜。"},{"sentence":"Although the film received mixed reviews, its innovative cinematography set a new standard for the genre.","translation":"尽管这部电影评价褒贬不一，但其创新的摄影技术为该类型树立了新标准。"},{"sentence":"When the photographic film is exposed to light, it captures a latent image that requires chemical development.","translation":"当摄影胶卷暴露在光线下时，它会捕捉到一个需要化学显影的潜像。"}]},"practically":{"examples":[{"sentence":"In the digital age, practically every aspect of our lives is influenced by algorithms that shape our choices.","translation":"在数字时代，我们生活的几乎每个方面都受到塑造我们选择的算法的影响。"},{"sentence":"The two theories are so similar that they are practically indistinguishable to anyone without specialized training.","translation":"这两种理论如此相似，以至于对于没有受过专门训练的人来说，它们几乎无法区分。"},{"sentence":"Because the new policy streamlined procedures, the approval process became practically effortless for small businesses.","translation":"由于新政策简化了程序，审批过程对小企业来说几乎毫不费力。"},{"sentence":"Although the task seemed daunting at first, with proper planning it proved practically manageable.","translation":"尽管这项任务起初看起来令人生畏，但通过适当的规划，它被证明几乎是可管理的。"},{"sentence":"In some remote regions, access to clean water is practically nonexistent, which exacerbates health crises.","translation":"在一些偏远地区，清洁用水的获取几乎不存在，这加剧了健康危机。"}]},"home":{"examples":[{"sentence":"Although she traveled the world, she always felt a deep connection to her childhood home.","translation":"尽管她周游世界，但她始终对童年的家有着深深的眷恋。"},{"sentence":"Because remote work is now common, many people have transformed their home into a productive office space.","translation":"由于远程工作现在很普遍，许多人已将自己的家改造成了高效的办公空间。"},{"sentence":"The government launched a program to ensure that every low-income family has a safe and affordable home.","translation":"政府启动了一项计划，以确保每个低收入家庭都有一个安全且负担得起的家。"},{"sentence":"While urban apartments offer convenience, they often lack the warmth that makes a house feel like a home.","translation":"虽然城市公寓提供了便利，但它们往往缺乏让房子有家的感觉的温暖。"},{"sentence":"The concept of home extends beyond physical walls, which is why refugees often carry their cultural identity with them.","translation":"家的概念超越了物理的墙壁，这就是为什么难民常常随身携带着他们的文化身份。"}]},"sad":{"examples":[{"sentence":"It is sad that many students abandon their artistic passions because of pressure to pursue practical careers.","translation":"令人悲哀的是，许多学生因为追求实用职业的压力而放弃了他们的艺术热情。"},{"sentence":"While technological progress brings convenience, it is sad that it often leads to social isolation.","translation":"虽然技术进步带来了便利，但令人悲哀的是，它常常导致社会孤立。"},{"sentence":"The sad reality is that climate change disproportionately affects vulnerable communities, which lack resources to adapt.","translation":"悲哀的现实是，气候变化对缺乏适应资源的脆弱社区造成了不成比例的影响。"},{"sentence":"A sad consequence of urbanization is the loss of green spaces, which are essential for mental well-being.","translation":"城市化的一个悲哀后果是绿地的丧失，而绿地对心理健康至关重要。"},{"sentence":"Although the film had a happy ending, it portrayed the sad truth about the struggles of immigrant families.","translation":"尽管这部电影有一个幸福的结局，但它描绘了关于移民家庭挣扎的悲哀真相。"}]},"low":{"examples":[{"sentence":"Although the company's profits hit a new low, the CEO remained optimistic about the upcoming product launch.","translation":"尽管公司利润创下新低，首席执行官对即将推出的产品仍持乐观态度。"},{"sentence":"Because the region experiences a low annual rainfall, farmers rely heavily on irrigation systems.","translation":"由于该地区年降雨量低，农民严重依赖灌溉系统。"},{"sentence":"When consumer confidence reaches a low, governments often introduce stimulus packages to boost spending.","translation":"当消费者信心降至低点时，政府通常会推出刺激计划以促进消费。"},{"sentence":"The study found that a diet low in saturated fats can significantly reduce the risk of heart disease.","translation":"研究发现，低饱和脂肪的饮食可以显著降低患心脏病的风险。"},{"sentence":"Despite the low unemployment rate, many workers still struggle with stagnant wages and rising living costs.","translation":"尽管失业率低，许多工人仍因工资停滞和生活成本上升而挣扎。"}]},"start":{"examples":[{"sentence":"Although the initial investment is substantial, the company decided to start the renewable energy project to ensure long-term sustainability.","translation":"尽管初期投资巨大，公司还是决定启动可再生能源项目，以确保长期可持续性。"},{"sentence":"Because the evidence was inconclusive, the committee chose to start a thorough investigation rather than rush to judgment.","translation":"由于证据不确凿，委员会选择开始彻底调查，而不是仓促下结论。"},{"sentence":"When the new semester begins, students should start by reviewing the syllabus to understand the course requirements.","translation":"当新学期开始时，学生应从查看教学大纲开始，以了解课程要求。"},{"sentence":"If the government fails to start addressing climate change now, future generations will face irreversible consequences.","translation":"如果政府现在不开始应对气候变化，后代将面临不可逆转的后果。"},{"sentence":"The research team will start collecting data only after the ethical approval has been granted, which ensures compliance with regulations.","translation":"研究团队只有在获得伦理批准后才会开始收集数据，这确保了符合规定。"}]},"prevent":{"examples":[{"sentence":"Although the new policy aims to prevent corruption, its effectiveness depends on rigorous enforcement and public oversight.","translation":"尽管新政策旨在防止腐败，但其有效性取决于严格的执行和公众监督。"},{"sentence":"Because early detection is crucial, regular screenings can prevent many cancers from progressing to advanced stages.","translation":"由于早期发现至关重要，定期筛查可以防止许多癌症发展到晚期。"},{"sentence":"While vaccines prevent infectious diseases, herd immunity requires a high percentage of the population to be immunized.","translation":"虽然疫苗可以预防传染病，但群体免疫需要高比例的人口接种疫苗。"},{"sentence":"To prevent data breaches, companies must implement robust cybersecurity measures, thereby protecting sensitive information.","translation":"为了防止数据泄露，公司必须实施强大的网络安全措施，从而保护敏感信息。"},{"sentence":"Strict building codes prevent structural failures during earthquakes, which saves countless lives in seismic zones.","translation":"严格的建筑规范防止了地震期间的结构倒塌，这在地震带拯救了无数生命。"}]},"emphasis":{"examples":[{"sentence":"Although the course covers many topics, the primary emphasis is on critical thinking, which is essential for academic success.","translation":"尽管课程涵盖许多主题，但主要重点是批判性思维，这对学术成功至关重要。"},{"sentence":"Because the previous curriculum lacked practical skills, the new program places greater emphasis on hands-on training.","translation":"由于之前的课程缺乏实践技能，新项目更加重视动手培训。"},{"sentence":"While some educators emphasize rote memorization, others argue that the emphasis should shift to creative problem-solving.","translation":"虽然一些教育者强调死记硬背，但其他人认为重点应转向创造性解决问题。"},{"sentence":"The government's emphasis on renewable energy has led to significant investments in solar and wind power, thereby reducing carbon emissions.","translation":"政府对可再生能源的重视导致了对太阳能和风能的大量投资，从而减少了碳排放。"},{"sentence":"In her speech, the director placed special emphasis on the need for interdisciplinary collaboration, which fosters innovation.","translation":"在她的演讲中，主任特别强调了跨学科合作的必要性，这促进了创新。"}]},"plausible":{"examples":[{"sentence":"Although his alibi seemed plausible at first, the detective found contradictions in his story.","translation":"尽管他的不在场证明起初似乎合理，但侦探在他的叙述中发现了矛盾。"},{"sentence":"The scientist offered a plausible explanation for the anomaly, which was later confirmed by experiments.","translation":"科学家为这一异常现象提供了一个看似合理的解释，后来被实验证实。"},{"sentence":"Because the candidate's promises were not plausible, the voters turned to a more realistic alternative.","translation":"因为候选人的承诺并不合理，选民转向了更现实的选择。"},{"sentence":"A plausible scenario for the extinction involves a massive asteroid impact, which would have blocked sunlight.","translation":"一个看似合理的灭绝情景涉及一次巨大的小行星撞击，这会阻挡阳光。"},{"sentence":"While the forgery was plausible enough to fool many experts, a detailed analysis revealed subtle flaws.","translation":"虽然赝品足以骗过许多专家，但详细分析揭示了细微的缺陷。"}]},"stranger":{"examples":[{"sentence":"Although he was a stranger to the city, he navigated the complex subway system by using a detailed map.","translation":"尽管他对这个城市很陌生，但他通过使用详细的地图成功乘坐了复杂的地铁系统。"},{"sentence":"Because she was a stranger to the local language, she enrolled in an intensive course to communicate effectively.","translation":"由于她对当地语言一窍不通，她报名参加了一个强化课程以便有效沟通。"},{"sentence":"The kindness of a stranger, who offered directions when she was lost, restored her faith in humanity.","translation":"一个陌生人的善意，在她迷路时为她指路，恢复了她对人性的信心。"},{"sentence":"While a stranger may seem intimidating at first, engaging in conversation often reveals shared interests and perspectives.","translation":"尽管陌生人起初可能令人生畏，但进行交谈往往会揭示共同的兴趣和观点。"},{"sentence":"To ensure that no stranger feels excluded, the community center organizes weekly social events for newcomers.","translation":"为了确保没有陌生人感到被排斥，社区中心每周为新来者组织社交活动。"}]},"bowl":{"examples":[{"sentence":"Although the ceramic bowl was expensive, its intricate hand-painted design made it a worthwhile investment for the collector.","translation":"尽管这只陶瓷碗价格昂贵，但其复杂的手绘设计使其成为收藏家值得的投资。"},{"sentence":"Because the soup was served in a chilled bowl, it remained refreshingly cool even on the hot summer afternoon.","translation":"因为汤是用冰镇碗盛放的，即使在炎热的夏日午后，它依然保持着清爽的凉意。"},{"sentence":"The wooden bowl, which had been passed down through generations, held not only fruit but also cherished family memories.","translation":"那只代代相传的木碗，不仅盛着水果，还承载着珍贵的家庭回忆。"},{"sentence":"While the chef prepared the salad, he carefully selected a wide, shallow bowl to ensure the dressing coated every leaf evenly.","translation":"厨师在准备沙拉时，精心挑选了一个宽而浅的碗，以确保调料均匀地包裹每一片叶子。"},{"sentence":"If you use a microwave-safe bowl, you can reheat the leftovers without worrying about harmful chemicals leaching into your food.","translation":"如果你使用微波炉安全碗，就可以重新加热剩菜，而不必担心有害化学物质渗入食物中。"}]},"frontier":{"examples":[{"sentence":"Although the digital frontier offers immense opportunities, it also presents significant challenges related to privacy and security.","translation":"尽管数字前沿提供了巨大的机遇，但它也带来了与隐私和安全相关的重大挑战。"},{"sentence":"Because the frontier region lacked clear legal jurisdiction, disputes over land ownership frequently escalated into violent conflicts.","translation":"由于边境地区缺乏明确的法律管辖权，土地所有权纠纷经常升级为暴力冲突。"},{"sentence":"The scientific frontier of gene editing, which holds promise for curing genetic diseases, also raises profound ethical questions.","translation":"基因编辑的科学前沿有望治愈遗传疾病，但也引发了深刻的伦理问题。"},{"sentence":"While the government invested in frontier infrastructure, it aimed to promote economic integration and cultural exchange with neighboring countries.","translation":"政府在投资边境基础设施的同时，旨在促进与邻国的经济一体化和文化交流。"},{"sentence":"If explorers had not ventured beyond the known frontier, many of today's geographical and scientific discoveries would remain unknown.","translation":"如果探险家们没有冒险超越已知的边界，今天的许多地理和科学发现将仍然不为人知。"}]},"temporary":{"examples":[{"sentence":"Although the ceasefire was only temporary, it allowed humanitarian aid to reach the war-torn region without further casualties.","translation":"尽管停火只是暂时的，但它使人道主义援助能够到达饱受战争蹂躏的地区，而没有造成更多伤亡。"},{"sentence":"Because the company faced a sudden surge in demand, it hired temporary workers to ensure that production targets were met on time.","translation":"由于公司面临需求的突然激增，它雇佣了临时工以确保按时完成生产目标。"},{"sentence":"The temporary bridge, which was constructed after the flood, served as a vital link until a permanent structure could be built.","translation":"洪水后修建的临时桥梁，在永久性结构建成之前，起到了至关重要的连接作用。"},{"sentence":"While the medication provides temporary relief from pain, it does not address the underlying cause of the chronic condition.","translation":"虽然这种药物能暂时缓解疼痛，但它并不能解决慢性病的根本原因。"},{"sentence":"If the government imposes temporary trade restrictions, domestic industries may benefit in the short term, but consumers could face higher prices.","translation":"如果政府实施临时贸易限制，国内产业可能在短期内受益，但消费者可能面临更高的价格。"}]},"fall":{"examples":[{"sentence":"The fall of the Roman Empire, which resulted from a combination of internal decay and external invasions, remains a pivotal event in world history.","translation":"罗马帝国的衰落源于内部腐朽和外部入侵的结合，至今仍是世界历史上的关键事件。"},{"sentence":"A sudden fall in consumer confidence can trigger a chain reaction that slows down the entire economy.","translation":"消费者信心的突然下降可能引发连锁反应，导致整个经济放缓。"},{"sentence":"Because the fall in birth rates has been persistent, many countries are now facing the challenge of an aging population.","translation":"由于出生率的持续下降，许多国家现在正面临人口老龄化的挑战。"},{"sentence":"The rapid fall of the company's stock price, which followed the scandal, wiped out billions in market value within days.","translation":"丑闻之后公司股价的迅速下跌在几天内抹去了数十亿的市值。"},{"sentence":"The fall of the Berlin Wall in 1989 symbolized not only the end of the Cold War but also the triumph of democratic aspirations.","translation":"1989年柏林墙的倒塌不仅象征着冷战的结束，也象征着民主愿望的胜利。"}]},"cocaine":{"examples":[{"sentence":"Because cocaine trafficking networks often exploit weak governance structures, international cooperation is vital to disrupt their operations.","translation":"由于可卡因贩运网络经常利用薄弱的治理结构，国际合作对于瓦解其运作至关重要。"},{"sentence":"The surge in cocaine production in the Andean region, which is linked to poverty and lack of alternative livelihoods, requires a multifaceted solution.","translation":"安第斯地区可卡因产量的激增与贫困和缺乏替代生计有关，这需要多方面的解决方案。"},{"sentence":"Although cocaine is sometimes glamorized in popular culture, its devastating effects on mental health and family stability are well-documented.","translation":"尽管可卡因有时在流行文化中被美化，但它对心理健康和家庭稳定的破坏性影响是有据可查的。"},{"sentence":"Lawmakers have proposed stricter penalties for cocaine possession, yet critics argue that such measures fail to address the root causes of addiction.","translation":"立法者提议对持有可卡因实施更严厉的处罚，但批评者认为这些措施未能解决成瘾的根本原因。"},{"sentence":"The chemical runoff from clandestine cocaine labs contaminates water sources, thereby endangering both aquatic life and the health of downstream communities.","translation":"秘密可卡因实验室的化学径流污染了水源，从而危及水生生物和下游社区的健康。"}]},"cabbage":{"examples":[{"sentence":"Because cabbage is rich in vitamins and affordable, it has become a staple in many school lunch programs.","translation":"由于卷心菜富含维生素且价格实惠，它已成为许多学校午餐计划中的主食。"},{"sentence":"Although cabbage is often underestimated, it can be transformed into a delicious dish when braised with a few simple seasonings.","translation":"尽管卷心菜常常被低估，但用几种简单的调料炖煮后，它就能变成一道美味的菜肴。"},{"sentence":"Farmers in the region have started to cultivate cabbage as a winter crop, which has significantly increased their annual income.","translation":"该地区的农民开始种植卷心菜作为冬季作物，这大大增加了他们的年收入。"},{"sentence":"Nutritionists recommend including cabbage in one's diet because its high fiber content aids digestion and promotes gut health.","translation":"营养学家建议在饮食中加入卷心菜，因为其高纤维含量有助于消化并促进肠道健康。"},{"sentence":"In many cultures, fermented cabbage is a traditional food that not only preserves the vegetable but also enhances its nutritional value.","translation":"在许多文化中，发酵卷心菜是一种传统食品，它不仅保存了蔬菜，还提高了其营养价值。"}]},"assemble":{"examples":[{"sentence":"Although the instructions were written in a foreign language, the engineer managed to assemble the complex machinery by relying on the detailed diagrams.","translation":"尽管说明书是用外语写的，但工程师依靠详细的图表成功组装了这台复杂的机器。"},{"sentence":"Because the conference attracted scholars from various disciplines, the organizer had to assemble a diverse range of presentation materials to cater to all interests.","translation":"由于会议吸引了来自不同学科的学者，组织者不得不收集各种演示材料以满足所有兴趣。"},{"sentence":"When the volunteers assemble at the community center every Saturday, they sort and pack donations for families in need.","translation":"当志愿者们每周六在社区中心集合时，他们会分类和打包捐赠物品给有需要的家庭。"},{"sentence":"The research team will assemble the data from multiple surveys into a comprehensive report, which will be published in a leading journal.","translation":"研究团队将把来自多项调查的数据汇编成一份综合报告，该报告将发表在一家顶级期刊上。"},{"sentence":"To ensure the project's success, the manager decided to assemble a task force of experienced professionals who could address the technical challenges.","translation":"为了确保项目的成功，经理决定组建一个由经验丰富的专业人员组成的特别工作组，以应对技术挑战。"}]},"shift":{"examples":[{"sentence":"Because the company introduced a new shift system, employees can now choose flexible working hours that better suit their personal lives.","translation":"由于公司引入了新的轮班制度，员工现在可以选择更适合个人生活的弹性工作时间。"},{"sentence":"Although the shift in government policy was unexpected, it provided a much-needed boost to the renewable energy sector.","translation":"尽管政府政策的转变出乎意料，但它为可再生能源行业提供了急需的推动力。"},{"sentence":"When the factory operates on a three-shift schedule, it can maximize production output while maintaining equipment efficiency.","translation":"当工厂实行三班倒时，它可以最大化产量，同时保持设备效率。"},{"sentence":"A gradual shift in public opinion, which has been documented by recent polls, indicates growing support for environmental protection measures.","translation":"最近的民意调查显示，公众舆论的逐渐转变表明对环境保护措施的支持日益增长。"},{"sentence":"The manager decided to shift the team's focus from short-term profits to long-term sustainability, thereby ensuring the company's future growth.","translation":"经理决定将团队的重点从短期利润转移到长期可持续性上，从而确保公司的未来发展。"}]},"firm":{"examples":[{"sentence":"The firm, which specializes in renewable energy, has expanded its operations to three continents.","translation":"这家专门从事可再生能源的公司已将业务扩展到三大洲。"},{"sentence":"Because the firm adopted a flexible work policy, employee satisfaction and productivity both increased.","translation":"由于公司采取了灵活的工作政策，员工满意度和生产力都提高了。"},{"sentence":"Although the firm faced intense competition, its commitment to quality ensured long-term customer loyalty.","translation":"尽管公司面临激烈竞争，但其对质量的承诺确保了长期的客户忠诚度。"},{"sentence":"The consulting firm provided strategic advice that helped the startup secure a significant round of funding.","translation":"这家咨询公司提供了战略建议，帮助这家初创公司获得了一轮重要的融资。"},{"sentence":"When the firm merged with a larger corporation, it gained access to advanced technology and broader markets.","translation":"当公司与一家更大的企业合并时，它获得了先进技术和更广阔的市场。"}]},"paradox":{"examples":[{"sentence":"The paradox of thrift suggests that when everyone saves more during a recession, aggregate demand falls and the economy worsens.","translation":"节俭悖论表明，当经济衰退时每个人都增加储蓄，总需求就会下降，经济状况反而恶化。"},{"sentence":"A well-known paradox in environmental policy is that technological efficiency gains often lead to higher overall resource consumption.","translation":"环境政策中一个众所周知的悖论是，技术效率的提高往往导致总体资源消耗增加。"},{"sentence":"The fact that social media connects people globally while simultaneously increasing feelings of isolation presents a modern paradox.","translation":"社交媒体在全球范围内连接人们的同时却加剧了孤独感，这一事实构成了一个现代悖论。"},{"sentence":"It is a paradox that strict regulations intended to protect workers can sometimes reduce employment opportunities for the very people they aim to help.","translation":"旨在保护工人的严格法规有时反而减少了他们本应帮助的人的就业机会，这是一个悖论。"},{"sentence":"The paradox of tolerance argues that a society that is completely tolerant of intolerant views risks being undermined by those views.","translation":"宽容悖论认为，一个完全容忍不宽容观点的社会有被这些观点颠覆的风险。"}]},"fridge":{"examples":[{"sentence":"To ensure food safety, it is essential to store raw meat on the bottom shelf of the fridge, which prevents juices from dripping onto other items.","translation":"为了确保食品安全，必须将生肉存放在冰箱的底层搁架上，这可以防止汁液滴到其他物品上。"},{"sentence":"Because a fridge consumes a significant amount of electricity, selecting an energy-efficient model can lead to substantial long-term savings.","translation":"由于冰箱消耗大量电力，选择节能型号可以带来可观的长期节省。"},{"sentence":"When preparing for a dinner party, it is wise to clear out the fridge beforehand, thereby creating ample space for prepared dishes and beverages.","translation":"在准备晚宴时，事先清理冰箱是明智的，从而为准备好的菜肴和饮料创造充足的空间。"},{"sentence":"Although a fridge is designed to preserve food, it cannot prevent spoilage indefinitely, so regular checks are necessary.","translation":"尽管冰箱旨在保存食物，但它不能无限期地防止变质，因此定期检查是必要的。"},{"sentence":"In shared living situations, labeling your items in the fridge helps avoid confusion, which reduces the likelihood of accidental consumption.","translation":"在合住的情况下，在冰箱里的物品上贴上标签有助于避免混淆，这减少了意外食用的可能性。"}]},"hit":{"examples":[{"sentence":"The sudden economic downturn dealt a severe hit to small businesses, many of which were forced to close permanently.","translation":"突如其来的经济衰退对小企业造成了严重打击，许多企业被迫永久关闭。"},{"sentence":"Her latest novel became an instant hit, largely because it addressed universal themes with profound insight.","translation":"她的最新小说立即成为畅销书，很大程度上是因为它以深刻的洞察力探讨了普遍的主题。"},{"sentence":"When the company's reputation took a hit after the scandal, management implemented rigorous reforms to restore public trust.","translation":"丑闻发生后，公司声誉受损，管理层实施了严格的改革以恢复公众信任。"},{"sentence":"The boxer delivered a decisive hit that ended the match in the third round, demonstrating superior strategy.","translation":"拳击手打出了决定性的一击，在第三回合结束了比赛，展示了卓越的策略。"},{"sentence":"Although the website experienced a massive hit in traffic, the upgraded server infrastructure prevented any downtime.","translation":"尽管网站流量激增，但升级后的服务器基础设施避免了任何停机时间。"}]},"pitch":{"examples":[{"sentence":"Although the team lost the match, the coach praised their effort on the pitch because they never gave up.","translation":"尽管球队输掉了比赛，教练还是赞扬了他们在球场上的努力，因为他们从未放弃。"},{"sentence":"The entrepreneur's pitch was so persuasive that the investors agreed to fund the project without hesitation.","translation":"这位企业家的推销非常有说服力，投资者毫不犹豫地同意资助这个项目。"},{"sentence":"Because the roof had a steep pitch, snow slid off easily, which prevented structural damage during winter.","translation":"由于屋顶坡度很陡，雪很容易滑落，从而防止了冬季的结构损坏。"},{"sentence":"The singer's perfect pitch allowed her to identify any note instantly, a skill that impressed the entire orchestra.","translation":"这位歌手拥有完美的音高辨别力，能立即识别任何音符，这一技能给整个管弦乐队留下了深刻印象。"},{"sentence":"When the debate reached its highest pitch, the moderator intervened to ensure a respectful exchange of ideas.","translation":"当辩论达到最激烈的程度时，主持人介入以确保尊重的思想交流。"}]},"tank":{"examples":[{"sentence":"Although the water tank was installed on the roof, it still required regular maintenance to prevent leaks.","translation":"尽管水箱安装在屋顶上，但仍需定期维护以防止泄漏。"},{"sentence":"The factory uses a large storage tank, which holds chemicals that must be kept at a constant temperature.","translation":"工厂使用一个大型储罐，其中容纳必须保持恒温的化学品。"},{"sentence":"Because the fuel tank was damaged during the collision, the vehicle could not continue its journey.","translation":"由于油箱在碰撞中损坏，车辆无法继续行驶。"},{"sentence":"The fish tank in the laboratory requires careful monitoring, thereby ensuring the health of the aquatic specimens.","translation":"实验室里的鱼缸需要仔细监测，从而确保水生标本的健康。"},{"sentence":"When the industrial tank was inspected, engineers discovered corrosion that could lead to a hazardous leak.","translation":"当检查工业罐体时，工程师发现了可能导致危险泄漏的腐蚀。"}]},"relation":{"examples":[{"sentence":"The study examines the relation between sleep quality and academic performance, which has significant implications for student well-being.","translation":"这项研究探讨了睡眠质量与学业表现之间的关系，这对学生福祉有重要影响。"},{"sentence":"In relation to climate change, governments must adopt more ambitious policies, thereby reducing carbon emissions.","translation":"关于气候变化，各国政府必须采取更雄心勃勃的政策，从而减少碳排放。"},{"sentence":"A positive relation between employee satisfaction and productivity has been widely documented, although the causal direction remains debated.","translation":"员工满意度与生产力之间的正相关关系已被广泛记录，尽管因果方向仍有争议。"},{"sentence":"Her research focuses on the relation of language to cultural identity, which is a topic of growing interest in sociolinguistics.","translation":"她的研究侧重于语言与文化认同的关系，这是社会语言学中日益受关注的话题。"},{"sentence":"The company's success has no direct relation to its advertising budget, rather than being driven by product quality.","translation":"该公司的成功与其广告预算没有直接关系，而是由产品质量驱动。"}]},"stain":{"examples":[{"sentence":"A coffee stain on the document made several words illegible, which caused delays in processing the application.","translation":"文件上的咖啡渍使几个字难以辨认，这导致申请处理延迟。"},{"sentence":"The wooden table acquired a dark stain from years of use, although it was regularly polished.","translation":"木桌因多年使用而留下了深色污迹，尽管它定期上光。"},{"sentence":"Although the fabric was treated with a protective coating, a faint stain remained after washing.","translation":"尽管布料经过保护涂层处理，洗涤后仍留有淡淡的污渍。"},{"sentence":"The scandal left a permanent stain on his political career, thereby ending his chances of re-election.","translation":"丑闻给他的政治生涯留下了永久的污点，从而终结了他连任的机会。"},{"sentence":"Using a special solvent, she removed the oil stain from the concrete floor, which had been there for weeks.","translation":"她用一种特殊的溶剂清除了水泥地上的油渍，这油渍已存在数周。"}]},"divine":{"examples":[{"sentence":"Although the ancient temple was built to honor a divine being, its design also reflects human ingenuity.","translation":"尽管这座古庙是为敬奉一位神灵而建，但其设计也反映了人类的智慧。"},{"sentence":"The philosopher argued that divine revelation, rather than empirical evidence, provides the ultimate source of moral truth.","translation":"这位哲学家认为，神圣启示而非经验证据，提供了道德真理的最终来源。"},{"sentence":"Because the choir's performance achieved a divine perfection, the audience sat in stunned silence for several moments.","translation":"因为合唱团的表演达到了神圣的完美境界，观众在震惊的沉默中坐了好一会儿。"},{"sentence":"The poet used divine imagery to convey a sense of transcendence, which resonated deeply with readers seeking spiritual meaning.","translation":"诗人运用神圣意象来传达一种超越感，这深深引起了寻求精神意义的读者的共鸣。"},{"sentence":"While some view natural beauty as a divine gift, others see it as a product of evolutionary processes.","translation":"虽然有些人将自然之美视为神圣的恩赐，但其他人则将其视为进化过程的产物。"}]},"swell":{"examples":[{"sentence":"A sudden swell of public outrage, which was amplified by social media, forced the government to withdraw the controversial policy.","translation":"公众愤怒的突然高涨，在社交媒体上被放大，迫使政府撤回了这项有争议的政策。"},{"sentence":"Because the river began to swell after days of torrential rain, the authorities issued an evacuation order for low-lying areas.","translation":"因为连日暴雨后河水开始上涨，当局对低洼地区发布了疏散令。"},{"sentence":"The orchestra allowed the final chord to swell gradually, thereby creating a powerful emotional climax that left the audience breathless.","translation":"管弦乐队让最后的和弦逐渐增强，从而创造了一个让观众屏息的强烈情感高潮。"},{"sentence":"Despite the swell in demand for electric vehicles, manufacturers still face significant challenges in battery production.","translation":"尽管电动汽车需求激增，制造商在电池生产方面仍面临重大挑战。"},{"sentence":"The experienced sailor navigated the boat through the heavy swell, which had been caused by a distant storm.","translation":"这位经验丰富的水手驾驶船只穿过了由远处风暴引起的巨浪。"}]},"production":{"examples":[{"sentence":"Because the factory adopted automated assembly lines, its production efficiency improved significantly.","translation":"由于工厂采用了自动化装配线，其生产效率显著提高。"},{"sentence":"Although the initial investment was substantial, the long-term benefits of sustainable production methods justify the cost.","translation":"尽管初始投资巨大，但可持续生产方法的长期效益证明了成本的合理性。"},{"sentence":"The government implemented stricter regulations to ensure that industrial production does not compromise environmental quality.","translation":"政府实施了更严格的法规，以确保工业生产不会损害环境质量。"},{"sentence":"By diversifying its energy sources, the region managed to stabilize electricity production despite fluctuating fuel prices.","translation":"通过能源多样化，该地区在燃料价格波动的情况下仍稳定了电力生产。"},{"sentence":"Researchers argue that the production of knowledge in universities should balance theoretical inquiry with practical application.","translation":"研究人员认为，大学的知识生产应平衡理论探索与实际应用。"}]},"tuck":{"examples":[{"sentence":"Although the tailor added a small tuck to the dress, the overall silhouette remained elegant and flowing.","translation":"尽管裁缝在裙子上加了一个小缝褶，但整体轮廓依然优雅飘逸。"},{"sentence":"The gymnast performed with remarkable tuck, which impressed the judges during the final routine.","translation":"这位体操运动员在最后的成套动作中展现出非凡的活力，给裁判留下了深刻印象。"},{"sentence":"Because the drummer gave a sharp tuck on the snare, the marching band started the parade with perfect timing.","translation":"由于鼓手在小鼓上敲出一声清脆的鼓声，行进乐队以完美的时机开始了游行。"},{"sentence":"The ship's tuck, which extended beyond the stern, provided extra buoyancy in rough seas.","translation":"船尾突出部延伸至船尾之外，在波涛汹涌的海面上提供了额外的浮力。"},{"sentence":"While preparing for the long voyage, the crew stored extra tuck in the galley to ensure they had enough food.","translation":"在为长途航行做准备时，船员们在厨房里储藏了额外的食品，以确保有足够的食物。"}]},"hardware":{"examples":[{"sentence":"Because the company invested in advanced hardware, its data processing speed increased dramatically.","translation":"由于公司投资了先进的硬件，其数据处理速度大幅提升。"},{"sentence":"Although software updates are frequent, the underlying hardware must remain compatible to ensure system stability.","translation":"尽管软件更新频繁，但底层硬件必须保持兼容，以确保系统稳定。"},{"sentence":"The local hardware store, which has been family-owned for decades, supplies everything from plumbing fixtures to electrical components.","translation":"这家当地的五金店已经家族经营了几十年，供应从管道装置到电气元件的各种商品。"},{"sentence":"Engineers tested the new hardware under extreme conditions, thereby confirming its durability for military applications.","translation":"工程师在极端条件下测试了新硬件，从而确认了其在军事应用中的耐用性。"},{"sentence":"When designing a smart home system, one must integrate both hardware and software seamlessly to ensure user satisfaction.","translation":"在设计智能家居系统时，必须无缝集成硬件和软件，以确保用户满意度。"}]},"awkward":{"examples":[{"sentence":"When the interviewer asked a question he could not answer, the candidate fell into an awkward silence that lasted several seconds.","translation":"当面试官问了一个他无法回答的问题时，这位求职者陷入了持续数秒的尴尬沉默。"},{"sentence":"Because the new software interface is awkward to navigate, employees require additional training to complete routine tasks efficiently.","translation":"由于新软件界面操作不便，员工需要额外培训才能高效完成常规任务。"},{"sentence":"Although the proposal was well researched, its awkward structure made it difficult for the committee to follow the main argument.","translation":"尽管该提案研究充分，但其笨拙的结构使委员会难以理解主要论点。"},{"sentence":"The manager handled the awkward situation with such diplomacy that neither party felt offended by the final decision.","translation":"经理以如此圆通的手腕处理了这个棘手局面，以至于双方都对最终决定没有感到被冒犯。"},{"sentence":"An awkward pause in negotiations often signals that one side is reconsidering its position, which can be used strategically.","translation":"谈判中尴尬的停顿往往表明一方正在重新考虑其立场，这可以被策略性地利用。"}]},"office":{"examples":[{"sentence":"The new policy, which was drafted after extensive consultation, will be implemented across every government office by the end of the year.","translation":"这项经过广泛磋商后起草的新政策，将在年底前在所有政府办公室实施。"},{"sentence":"Although she holds a senior office in the organization, she remains approachable and regularly seeks input from junior staff.","translation":"尽管她在组织中担任高级职务，但她仍然平易近人，并定期征求初级员工的意见。"},{"sentence":"The office of the president issued a statement clarifying that the rumors about budget cuts were entirely unfounded.","translation":"总统办公室发表声明澄清，关于预算削减的传言完全没有根据。"},{"sentence":"Modern office design increasingly emphasizes open spaces and natural light, because such environments have been shown to boost productivity.","translation":"现代办公室设计越来越强调开放空间和自然光，因为这样的环境已被证明能提高生产力。"},{"sentence":"He was elected to the office of mayor on a platform of transparency and fiscal responsibility, which resonated with voters.","translation":"他以透明和财政责任的政纲当选市长一职，这引起了选民的共鸣。"}]},"liberate":{"examples":[{"sentence":"Although the new policy aims to liberate small businesses from excessive regulation, its long-term effects remain uncertain.","translation":"尽管新政策旨在将小企业从过度监管中解放出来，但其长期效果仍不确定。"},{"sentence":"The scholarship program helped liberate her from financial constraints, which allowed her to pursue a doctoral degree without part-time work.","translation":"该奖学金项目帮助她摆脱了经济束缚，这使她能够攻读博士学位而无需兼职工作。"},{"sentence":"Because the therapy aims to liberate patients from chronic pain, it has significantly improved their quality of life.","translation":"由于该疗法旨在将患者从慢性疼痛中解放出来，它显著提高了他们的生活质量。"},{"sentence":"The invention of the washing machine helped liberate women from hours of manual labor, thereby enabling greater workforce participation.","translation":"洗衣机的发明帮助女性从数小时的手工劳动中解放出来，从而促进了更多的劳动力参与。"},{"sentence":"While the movement sought to liberate the nation from colonial rule, it also sparked a cultural renaissance that reshaped national identity.","translation":"尽管该运动旨在将国家从殖民统治中解放出来，但它也引发了一场文化复兴，重塑了民族认同。"}]},"police":{"examples":[{"sentence":"Although the police increased patrols in the area, residents still felt that more community engagement was necessary to address the root causes of crime.","translation":"尽管警方在该地区增加了巡逻，居民们仍然认为需要更多的社区参与来解决犯罪的根本原因。"},{"sentence":"The police department, which had recently adopted body cameras, reported a significant decrease in complaints about officer conduct.","translation":"最近采用了随身摄像头的警察局报告称，关于警员行为的投诉显著减少。"},{"sentence":"Because the police relied on forensic evidence rather than eyewitness testimony, they were able to build a stronger case against the suspect.","translation":"由于警方依赖法医证据而非目击者证词，他们得以对嫌疑人构建更有力的案件。"},{"sentence":"When the police collaborated with social workers to respond to mental health crises, the number of violent confrontations dropped dramatically.","translation":"当警方与社会工作者合作应对心理健康危机时，暴力冲突的数量急剧下降。"},{"sentence":"The police chief implemented a new training program to ensure that officers could de-escalate tense situations without resorting to force.","translation":"警察局长实施了一项新的培训计划，以确保警员能够在不诉诸武力的情况下缓和紧张局势。"}]},"brilliant":{"examples":[{"sentence":"Although the young mathematician was brilliant, she struggled to communicate her complex ideas to those without a similar background.","translation":"尽管这位年轻的数学家才华横溢，她却难以向没有类似背景的人传达她复杂的想法。"},{"sentence":"The brilliant marketing campaign, which utilized social media influencers, resulted in a 40% increase in sales within the first quarter.","translation":"这场利用社交媒体影响者的出色营销活动，使第一季度销售额增长了40%。"},{"sentence":"Because the scientist's brilliant discovery challenged established theories, it initially faced skepticism from the academic community.","translation":"由于这位科学家的杰出发现挑战了既有理论，它最初遭到了学术界的怀疑。"},{"sentence":"The artist's brilliant use of light and shadow not only created a sense of depth but also evoked a profound emotional response from viewers.","translation":"艺术家对光影的出色运用不仅营造了深度感，还引发了观众深刻的情感共鸣。"},{"sentence":"While the strategy was brilliant in its simplicity, its success depended on precise timing and flawless execution by the entire team.","translation":"尽管该策略因其简洁而十分高明，但其成功取决于整个团队的精确时机和完美执行。"}]},"bush":{"examples":[{"sentence":"Because the bush had been cleared for agriculture, the soil became vulnerable to erosion during the heavy rains that followed.","translation":"由于灌木丛被清除用于农业，土壤在随后的暴雨中变得容易受到侵蚀。"},{"sentence":"The ecologist explained that the thorny bush, which is often considered a nuisance, actually provides essential shelter for small mammals.","translation":"生态学家解释说，这种常被视为讨厌之物的带刺灌木，实际上为小型哺乳动物提供了必要的庇护。"},{"sentence":"Although the bush appeared dry and lifeless, it was merely dormant and would regenerate with the first signs of spring.","translation":"尽管灌木丛看起来干枯无生气，但它只是处于休眠状态，并会随着春天的第一丝迹象而再生。"},{"sentence":"The hikers lost their way when the trail became overgrown with dense bush, forcing them to rely on a compass to navigate.","translation":"当小径被茂密的灌木丛覆盖时，徒步旅行者迷了路，迫使他们依靠指南针导航。"},{"sentence":"The conservationists planted native bush species along the riverbank to ensure that the habitat would be restored for local wildlife.","translation":"环保主义者在河岸种植了本地灌木物种，以确保为当地野生动物恢复栖息地。"}]},"further":{"examples":[{"sentence":"To further the development of renewable energy, the government has implemented tax incentives that encourage private investment in solar and wind projects.","translation":"为了促进可再生能源的发展，政府实施了税收激励措施，鼓励私人投资太阳能和风能项目。"},{"sentence":"Although the initial study provided valuable insights, further research is necessary to determine whether these findings apply to other populations.","translation":"尽管初步研究提供了宝贵的见解，但需要进一步的研究来确定这些发现是否适用于其他人群。"},{"sentence":"The organization launched a mentorship program to further the professional growth of its junior employees, thereby enhancing overall productivity.","translation":"该组织启动了一项导师计划，以促进初级员工的专业成长，从而提高整体生产力。"},{"sentence":"Because the evidence was inconclusive, the committee requested further analysis before reaching a final decision on the policy change.","translation":"由于证据尚无定论，委员会要求进行进一步分析，然后再就政策变更做出最终决定。"},{"sentence":"International cooperation can further the cause of peace by fostering mutual understanding, which reduces the likelihood of conflict between nations.","translation":"国际合作可以通过促进相互理解来推进和平事业，从而减少国家间冲突的可能性。"}]},"handwriting":{"examples":[{"sentence":"The expert confirmed that the signature was genuine after comparing it with samples of his known handwriting.","translation":"专家在将其与已知的笔迹样本进行比对后，确认签名是真实的。"},{"sentence":"Teachers often emphasize the importance of legible handwriting because it directly affects how exam answers are evaluated.","translation":"老师们经常强调字迹清晰的重要性，因为它直接影响试卷答案的评判。"},{"sentence":"Researchers have found that taking notes by hand improves retention, as the slower process of handwriting forces students to paraphrase information.","translation":"研究人员发现，手写笔记能提高记忆效果，因为较慢的书写过程迫使学生转述信息。"},{"sentence":"The forgery was detected when the suspect's handwriting exhibited consistent pressure patterns that differed from the original document.","translation":"当嫌疑人的笔迹显示出与原文件不同的持续压力模式时，伪造行为被发现了。"},{"sentence":"Graphologists claim that certain features of handwriting, such as slant and spacing, can reveal personality traits.","translation":"笔迹学家声称，笔迹的某些特征，如倾斜度和间距，可以揭示个性特征。"}]},"accommodation":{"examples":[{"sentence":"Although the hotel offered luxurious accommodation, many guests complained about the noise from the nearby construction site.","translation":"尽管酒店提供了豪华的住宿，许多客人还是抱怨附近建筑工地的噪音。"},{"sentence":"The university provides affordable accommodation for international students, which helps them adjust to campus life more easily.","translation":"该大学为国际学生提供负担得起的住宿，这有助于他们更轻松地适应校园生活。"},{"sentence":"Because the eye's accommodation ability declines with age, older adults often need reading glasses to focus on close objects.","translation":"由于眼睛的调节能力随年龄增长而下降，老年人通常需要老花镜来聚焦近处物体。"},{"sentence":"The negotiation succeeded through mutual accommodation, with both sides making concessions to reach a compromise.","translation":"谈判通过相互调和取得了成功，双方都做出了让步以达成妥协。"},{"sentence":"When traveling on a budget, finding cheap accommodation is essential, as it allows you to allocate more funds to experiences.","translation":"在预算有限的情况下旅行时，找到便宜的住宿至关重要，因为这能让你将更多资金分配给体验活动。"}]},"disc":{"examples":[{"sentence":"Because the compact disc offered superior durability, it became the preferred medium for data storage in the 1990s.","translation":"由于光盘提供了卓越的耐用性，它在20世纪90年代成为数据存储的首选介质。"},{"sentence":"The archaeologist carefully cleaned the ancient stone disc, which was carved with mysterious symbols.","translation":"考古学家小心地清理了那块刻有神秘符号的古代石盘。"},{"sentence":"Although streaming is popular, many collectors still value the tactile experience of handling a vinyl disc.","translation":"尽管流媒体很流行，许多收藏家仍然珍视处理黑胶唱片的触觉体验。"},{"sentence":"The technician inserted the installation disc into the drive, thereby initiating the software setup process.","translation":"技术人员将安装光盘插入驱动器，从而启动了软件安装过程。"},{"sentence":"When the hard disc fails, critical data can be lost unless a backup has been made.","translation":"当硬盘发生故障时，除非已进行备份，否则关键数据可能会丢失。"}]},"engage":{"examples":[{"sentence":"To engage students in the lesson, the teacher used interactive simulations that illustrated complex scientific concepts.","translation":"为了让学生参与课堂，老师使用了互动模拟来说明复杂的科学概念。"},{"sentence":"The company decided to engage a renowned architect, thereby ensuring that the new building would be both functional and iconic.","translation":"公司决定聘请一位著名建筑师，从而确保新建筑既实用又具有标志性。"},{"sentence":"When citizens engage in volunteer work, they not only help their communities but also develop valuable skills.","translation":"当公民参与志愿工作时，他们不仅帮助了社区，还培养了宝贵的技能。"},{"sentence":"Although the two countries have political differences, they continue to engage in trade negotiations to boost their economies.","translation":"尽管两国存在政治分歧，它们仍继续进行贸易谈判以促进经济。"},{"sentence":"Modern museums use virtual reality to engage visitors, which transforms a simple tour into an immersive journey through history.","translation":"现代博物馆利用虚拟现实来吸引参观者，这将简单的参观转变为穿越历史的沉浸式旅程。"}]},"trademark":{"examples":[{"sentence":"Although a trademark is a legal tool, it also serves as a powerful marketing asset that shapes consumer perception.","translation":"虽然商标是一种法律工具，但它也是一种强大的营销资产，能够塑造消费者的认知。"},{"sentence":"Because trademark infringement can lead to costly litigation, companies must conduct thorough searches before launching new brands.","translation":"由于商标侵权可能导致昂贵的诉讼，公司在推出新品牌之前必须进行彻底的检索。"},{"sentence":"A trademark that becomes too closely associated with a product category may lose its distinctiveness, thereby weakening legal protection.","translation":"一个与产品类别联系过于紧密的商标可能会失去其显著性，从而削弱法律保护。"},{"sentence":"When a startup secures a trademark early, it can deter competitors from using confusingly similar names.","translation":"当一家初创公司尽早获得商标时，它可以阻止竞争对手使用容易混淆的相似名称。"},{"sentence":"The value of a trademark often increases over time as the brand gains recognition, which makes it a critical intangible asset.","translation":"随着品牌获得认可，商标的价值通常会随着时间的推移而增加，这使其成为一项关键的无形资产。"}]},"jewelry":{"examples":[{"sentence":"Although jewelry is often seen as a luxury item, it can also hold deep cultural and sentimental significance.","translation":"虽然珠宝通常被视为奢侈品，但它也可以具有深厚的文化和情感意义。"},{"sentence":"Because the jewelry industry relies on precious metals and gems, it faces scrutiny over ethical sourcing and environmental impact.","translation":"由于珠宝行业依赖贵金属和宝石，它在道德采购和环境影响方面面临审查。"},{"sentence":"When consumers purchase jewelry as an investment, they should consider factors such as craftsmanship and rarity rather than just aesthetic appeal.","translation":"当消费者购买珠宝作为投资时，他们应考虑工艺和稀有性等因素，而不仅仅是审美吸引力。"},{"sentence":"The exhibition displayed jewelry from various historical periods, which illustrated the evolution of design techniques and cultural influences.","translation":"展览展示了各个历史时期的珠宝，这说明了设计技术和文化影响的演变。"},{"sentence":"Despite the rise of minimalist fashion, ornate jewelry continues to attract buyers who appreciate intricate artistry.","translation":"尽管极简主义时尚兴起，华丽的珠宝仍然吸引着欣赏复杂工艺的买家。"}]},"arm":{"examples":[{"sentence":"Because the patient sustained a severe fracture in her right arm, the surgeon recommended an immediate operation to prevent permanent nerve damage.","translation":"由于患者右臂严重骨折，外科医生建议立即手术以防止永久性神经损伤。"},{"sentence":"Although the robotic arm can perform delicate assembly tasks with remarkable precision, it still requires human oversight to handle unexpected variations on the production line.","translation":"尽管机械臂能够以惊人的精度执行精细的装配任务，但它仍然需要人工监督来处理生产线上的意外变化。"},{"sentence":"The government decided to arm the newly established coast guard with advanced surveillance equipment so that it could respond more effectively to maritime threats.","translation":"政府决定用先进的监视设备武装新成立的海岸警卫队，以便更有效地应对海上威胁。"},{"sentence":"When researchers examined the narrow arm of the bay, they discovered a unique ecosystem that had been isolated from the open ocean for centuries.","translation":"当研究人员考察那个狭长的海湾时，他们发现了一个与开阔海洋隔绝了几个世纪的独特生态系统。"},{"sentence":"To protect the community from escalating violence, the local council voted to arm the neighborhood patrol with non-lethal deterrents rather than firearms.","translation":"为了保护社区免受不断升级的暴力的影响，地方议会投票决定为邻里巡逻队配备非致命威慑装备，而不是枪支。"}]},"digest":{"examples":[{"sentence":"Because the research paper was dense with technical jargon, the professor prepared a concise digest that highlighted the key findings for a broader audience.","translation":"由于这篇研究论文充满了技术术语，教授准备了一份简明的摘要，为更广泛的读者突出了关键发现。"},{"sentence":"Although the weekly digest of industry news saves professionals considerable time, it cannot replace the depth of analysis found in full-length reports.","translation":"尽管每周的行业新闻文摘为专业人士节省了大量时间，但它无法取代完整报告中分析的深度。"},{"sentence":"To help students digest the complex theories of quantum mechanics, the textbook includes a digest of each chapter that summarizes the essential principles.","translation":"为了帮助学生理解复杂的量子力学理论，教科书每章都包含一个摘要，总结基本原理。"},{"sentence":"The human digestive system requires several hours to fully digest a meal rich in fiber, which is why nutritionists recommend eating slowly and mindfully.","translation":"人体消化系统需要几个小时才能完全消化富含纤维的一餐，这就是营养学家建议细嚼慢咽、专心进食的原因。"},{"sentence":"After attending the intensive workshop, participants were given a digest of the main strategies so that they could apply the concepts in their own workplaces.","translation":"参加完密集研讨会后，与会者收到了一份主要策略的摘要，以便他们能在自己的工作场所应用这些概念。"}]},"leg":{"examples":[{"sentence":"Because the athlete tore a ligament in her left leg during the final sprint, she had to withdraw from the championship and undergo months of rehabilitation.","translation":"由于运动员在最后冲刺时左腿韧带撕裂，她不得不退出锦标赛，并接受数月的康复治疗。"},{"sentence":"Although the final leg of the journey through the mountainous terrain was exhausting, the research team remained determined to reach the remote village before nightfall.","translation":"尽管穿越山区的最后一段路程令人筋疲力尽，但研究小组仍决心在夜幕降临前抵达那个偏远的村庄。"},{"sentence":"To improve stability and prevent falls among the elderly, the community center offers exercise classes that specifically strengthen the muscles in the lower leg.","translation":"为了提高老年人的稳定性并防止跌倒，社区中心提供专门增强小腿肌肉的锻炼课程。"},{"sentence":"When the company expanded its logistics network, it added a new leg to the delivery route that connected the warehouse directly to the regional distribution hub.","translation":"当公司扩展其物流网络时，它在配送路线上增加了一段新路程，将仓库与区域配送中心直接连接起来。"},{"sentence":"The engineer designed a prosthetic leg with advanced sensors that enable the user to walk on uneven surfaces with greater confidence and less fatigue.","translation":"工程师设计了一款带有先进传感器的假腿，使用户能够更有信心地在不平坦的路面上行走，且不易疲劳。"}]},"salary":{"examples":[{"sentence":"Although a high salary can be motivating, it does not guarantee long-term job satisfaction.","translation":"尽管高薪能激励人，但它并不能保证长期的职业满足感。"},{"sentence":"Many graduates prioritize salary over professional development, which may limit their career growth.","translation":"许多毕业生优先考虑薪水而非职业发展，这可能会限制他们的职业成长。"},{"sentence":"Because the cost of living has risen sharply, a fixed salary often fails to cover basic expenses.","translation":"由于生活成本急剧上升，固定薪水往往无法覆盖基本开支。"},{"sentence":"Negotiating a starting salary is a crucial skill that every job seeker should develop.","translation":"谈判起薪是每个求职者都应培养的一项关键技能。"},{"sentence":"While salary transparency can promote fairness, it may also lead to workplace tension.","translation":"虽然薪资透明能促进公平，但也可能导致职场关系紧张。"}]},"drawback":{"examples":[{"sentence":"Although the new software offers advanced features, its main drawback is the steep learning curve for beginners.","translation":"尽管新软件提供了先进的功能，但其主要缺点是初学者学习曲线陡峭。"},{"sentence":"A significant drawback of relying solely on tourism is that it makes the local economy vulnerable to seasonal fluctuations.","translation":"完全依赖旅游业的一个显著缺点是它使当地经济容易受到季节性波动的影响。"},{"sentence":"While electric cars reduce emissions, a notable drawback is the limited availability of charging stations in rural areas.","translation":"虽然电动汽车减少了排放，但一个明显的缺点是农村地区充电站有限。"},{"sentence":"The primary drawback of using social media for news is the rapid spread of misinformation, which can mislead the public.","translation":"使用社交媒体获取新闻的主要缺点是错误信息迅速传播，这可能误导公众。"},{"sentence":"Despite its convenience, online shopping has a serious drawback: it often leads to excessive packaging waste.","translation":"尽管网上购物很方便，但它有一个严重的缺点：往往导致过多的包装浪费。"}]},"jog":{"examples":[{"sentence":"Because a morning jog can boost metabolism, many health experts recommend it as part of a daily routine.","translation":"由于晨跑能促进新陈代谢，许多健康专家推荐将其作为日常生活的一部分。"},{"sentence":"Although a brisk jog is beneficial for cardiovascular health, it may strain the joints if proper shoes are not worn.","translation":"尽管快跑有益于心血管健康，但如果鞋子不合适，可能会损伤关节。"},{"sentence":"Taking a short jog during lunch breaks not only refreshes the mind but also improves afternoon productivity.","translation":"午休时进行短跑不仅能提神，还能提高下午的工作效率。"},{"sentence":"A gentle jog along the beach at sunset provides a serene experience that helps reduce stress levels.","translation":"日落时分沿着海滩慢跑能带来宁静的体验，有助于减轻压力。"},{"sentence":"While some people prefer intense workouts, a light jog remains a sustainable exercise that suits all fitness levels.","translation":"虽然有些人喜欢高强度锻炼，但轻松慢跑仍是一种适合所有体能水平的可持续运动。"}]},"combat":{"examples":[{"sentence":"Although modern combat relies heavily on technology, the psychological resilience of soldiers remains crucial.","translation":"尽管现代战斗严重依赖技术，但士兵的心理韧性仍然至关重要。"},{"sentence":"The government launched a new initiative to combat air pollution, which has reached hazardous levels in urban areas.","translation":"政府发起了一项新举措来对抗空气污染，因为城市地区的污染已达到危险水平。"},{"sentence":"Because combat experience can lead to post-traumatic stress, veterans require comprehensive mental health support.","translation":"由于战斗经历可能导致创伤后应激障碍，退伍军人需要全面的心理健康支持。"},{"sentence":"International organizations must collaborate to combat human trafficking, a crime that exploits vulnerable populations.","translation":"国际组织必须合作打击人口贩运，这是一种剥削弱势群体的犯罪。"},{"sentence":"While hand-to-hand combat is rare in modern warfare, it is still taught to enhance soldiers' confidence and agility.","translation":"尽管徒手格斗在现代战争中很少见，但仍被教授以增强士兵的信心和敏捷性。"}]},"christmas":{"examples":[{"sentence":"Christmas, which is celebrated worldwide, has evolved to incorporate diverse cultural traditions beyond its religious origins.","translation":"圣诞节在全球范围内庆祝，已演变为融合了超越其宗教起源的多元文化传统。"},{"sentence":"Because Christmas is a peak season for consumer spending, businesses often rely on holiday sales to meet annual targets.","translation":"由于圣诞节是消费支出的高峰期，企业通常依赖假日销售来实现年度目标。"},{"sentence":"Although Christmas is traditionally a time for family reunions, many people now choose to travel abroad during the holiday.","translation":"尽管圣诞节传统上是家庭团聚的时刻，但现在许多人选择在假期出国旅行。"},{"sentence":"The spirit of Christmas, which emphasizes generosity and compassion, inspires charitable activities throughout December.","translation":"圣诞节的精神强调慷慨和同情，在整个十二月激发慈善活动。"},{"sentence":"While Christmas decorations create a festive atmosphere, their environmental impact has raised concerns among sustainability advocates.","translation":"虽然圣诞装饰营造了节日气氛，但其对环境的影响引起了可持续发展倡导者的担忧。"}]},"wise":{"examples":[{"sentence":"A wise investor diversifies their portfolio to mitigate risk, rather than chasing short-term gains.","translation":"明智的投资者会分散投资组合以降低风险，而不是追逐短期收益。"},{"sentence":"It is wise to seek multiple perspectives before making a decision that will affect the entire community.","translation":"在做出影响整个社区的决定之前，征求多方意见是明智的。"},{"sentence":"While technology offers unprecedented convenience, it is wise to remain mindful of its potential to erode privacy.","translation":"尽管技术提供了前所未有的便利，但明智的做法是始终警惕其侵蚀隐私的潜力。"},{"sentence":"A wise leader cultivates a culture of open dialogue, recognizing that diverse viewpoints strengthen organizational resilience.","translation":"明智的领导者培养开放对话的文化，认识到多元观点能增强组织的韧性。"},{"sentence":"Because resources are finite, it is wise to prioritize investments that yield long-term social and environmental benefits.","translation":"由于资源有限，优先考虑能产生长期社会和环境效益的投资是明智的。"}]},"ourselves":{"examples":[{"sentence":"Although we often seek validation from others, true confidence comes from believing in ourselves.","translation":"尽管我们经常寻求他人的认可，但真正的自信来自于相信自己。"},{"sentence":"When we take time to reflect on our actions, we give ourselves the opportunity to learn from past mistakes.","translation":"当我们花时间反思自己的行为时，我们给了自己从过去的错误中学习的机会。"},{"sentence":"Because we are our own harshest critics, we must learn to treat ourselves with the same compassion we offer others.","translation":"因为我们是自己最严厉的批评者，所以我们必须学会以对待他人的同情心来对待自己。"},{"sentence":"To ensure continuous improvement, we should challenge ourselves to step outside our comfort zones on a regular basis.","translation":"为了确保持续进步，我们应该定期挑战自己走出舒适区。"},{"sentence":"While it is natural to compare ourselves to others, such comparisons often lead to unnecessary dissatisfaction.","translation":"虽然将自己与他人比较是很自然的，但这种比较往往会导致不必要的不满。"}]},"housing":{"examples":[{"sentence":"Because affordable housing is essential for social stability, governments must implement policies that prevent speculative bubbles.","translation":"由于经济适用住房对社会稳定至关重要，政府必须实施防止投机泡沫的政策。"},{"sentence":"Although urban housing shortages are often attributed to population growth, inefficient land use is a more significant factor.","translation":"尽管城市住房短缺常被归因于人口增长，但低效的土地利用是一个更重要的因素。"},{"sentence":"When designing public housing projects, architects should prioritize natural light and ventilation to enhance residents' well-being.","translation":"在设计公共住房项目时，建筑师应优先考虑自然采光和通风，以提升居民的福祉。"},{"sentence":"The government introduced a new housing subsidy, which aims to assist low-income families in securing decent accommodation.","translation":"政府推出了一项新的住房补贴，旨在帮助低收入家庭获得体面的住所。"},{"sentence":"Rather than focusing solely on quantity, housing policies should emphasize quality to create sustainable communities.","translation":"住房政策不应只关注数量，而应强调质量，以创建可持续的社区。"}]},"elementary":{"examples":[{"sentence":"Although the concept is elementary, its application in real-world scenarios requires careful consideration.","translation":"尽管这个概念是基本的，但它在现实场景中的应用需要仔细考虑。"},{"sentence":"The textbook provides an elementary overview of quantum mechanics, which serves as a foundation for more advanced study.","translation":"这本教科书提供了量子力学的基本概述，为更深入的学习奠定了基础。"},{"sentence":"Because elementary errors in the data entry process were overlooked, the entire analysis had to be repeated.","translation":"由于数据输入过程中的基本错误被忽视，整个分析不得不重做。"},{"sentence":"An elementary understanding of grammar is necessary to ensure that your writing is clear and effective.","translation":"对语法的基本理解是必要的，以确保你的写作清晰有效。"},{"sentence":"While the problem may seem elementary, solving it efficiently requires a deep understanding of the underlying principles.","translation":"虽然这个问题看似基本，但高效解决它需要对基本原理有深刻的理解。"}]},"mild":{"examples":[{"sentence":"The region's mild climate, which is characterized by warm summers and cool winters, attracts many retirees.","translation":"该地区温和的气候，以温暖的夏季和凉爽的冬季为特征，吸引了许多退休人员。"},{"sentence":"Although the criticism was mild, it still prompted the team to reexamine their research methodology.","translation":"尽管批评是温和的，但它仍然促使团队重新审视他们的研究方法。"},{"sentence":"A mild detergent is recommended for cleaning delicate fabrics, because harsh chemicals can damage the fibers.","translation":"建议使用温和的洗涤剂清洁精细织物，因为刺激性化学物质会损坏纤维。"},{"sentence":"The patient experienced only mild side effects from the medication, which subsided after a few days without requiring further treatment.","translation":"患者仅经历了药物的轻微副作用，几天后就消退了，无需进一步治疗。"},{"sentence":"His mild manner often led colleagues to underestimate his determination, whereas his actions revealed a fierce resolve.","translation":"他温和的举止常常让同事们低估了他的决心，而他的行动却显示出坚定的意志。"}]},"span":{"examples":[{"sentence":"Although the bridge's central span measures 200 meters, engineers reinforced it to withstand strong winds.","translation":"尽管这座桥的中央跨距为200米，工程师们对其进行了加固以抵御强风。"},{"sentence":"Over a span of two decades, the city transformed into a bustling metropolis, which attracted global investors.","translation":"在二十年的时间里，这座城市转变为繁华的大都市，这吸引了全球投资者。"},{"sentence":"Because the project's time span was extended, the team could refine every detail to ensure high quality.","translation":"由于项目的时间跨度延长了，团队得以完善每一个细节以确保高质量。"},{"sentence":"The life span of certain deep-sea organisms far exceeds that of most land animals, thereby challenging our understanding of aging.","translation":"某些深海生物的寿命远超大多数陆地动物，从而挑战了我们对衰老的理解。"},{"sentence":"When the attention span of young learners is limited, interactive methods can sustain their focus rather than relying on passive lectures.","translation":"当年轻学习者的注意力持续时间有限时，互动式方法可以维持他们的专注，而不是依赖被动讲座。"}]},"designate":{"examples":[{"sentence":"The committee decided to designate a portion of the budget for renewable energy research, which will accelerate the transition to clean power.","translation":"委员会决定指定一部分预算用于可再生能源研究，这将加速向清洁能源的过渡。"},{"sentence":"In many countries, laws designate certain areas as protected zones to preserve biodiversity, thereby safeguarding endangered species.","translation":"在许多国家，法律将某些区域指定为保护区以维护生物多样性，从而保护濒危物种。"},{"sentence":"The professor asked the students to designate one group member to present their findings, because effective collaboration requires clear roles.","translation":"教授要求学生们指定一名小组成员来展示他们的研究结果，因为有效的合作需要明确的角色。"},{"sentence":"Although the CEO will designate a successor next month, the transition plan remains confidential to ensure stability.","translation":"尽管首席执行官将于下个月指定一位继任者，但过渡计划仍属机密以确保稳定。"},{"sentence":"The new policy will designate English as the primary language for all official documents, which may improve international communication.","translation":"新政策将指定英语为所有官方文件的主要语言，这可能会改善国际交流。"}]},"precious":{"examples":[{"sentence":"Because water is a precious resource in arid regions, communities have developed innovative conservation techniques.","translation":"因为水在干旱地区是一种宝贵的资源，社区开发了创新的保护技术。"},{"sentence":"Although the necklace was made of precious stones, its true value lay in the sentimental memories it held.","translation":"尽管这条项链由珍贵的宝石制成，但其真正价值在于它所承载的情感记忆。"},{"sentence":"When we consider the rapid loss of biodiversity, every remaining species becomes a precious part of our natural heritage.","translation":"当我们考虑到生物多样性的迅速丧失时，每一个幸存的物种都成为我们自然遗产中宝贵的一部分。"},{"sentence":"The historian argued that precious historical documents must be preserved, not only for research but also for future generations.","translation":"历史学家认为，珍贵的历史文献必须被保存，不仅为了研究，也为了后代。"},{"sentence":"While modern life offers many distractions, the precious moments of solitude allow us to reflect and recharge.","translation":"虽然现代生活提供了许多干扰，但宝贵的独处时刻让我们得以反思和充电。"}]},"elastic":{"examples":[{"sentence":"Because the waistband is made of elastic, the trousers can accommodate a range of sizes comfortably.","translation":"因为腰带是由松紧带制成的，这条裤子可以舒适地适应各种尺寸。"},{"sentence":"Although the schedule appears fixed, it is actually elastic enough to allow for unexpected delays.","translation":"尽管日程表看似固定，但实际上它足够有弹性，可以应对意外的延误。"},{"sentence":"The concept of justice is often elastic, which means its interpretation can vary across different legal systems.","translation":"正义的概念常常是有弹性的，这意味着其解释在不同的法律体系中可能有所不同。"},{"sentence":"When designing the new sportswear, the team chose an elastic fabric that stretches without losing its shape.","translation":"在设计新款运动服时，团队选择了一种弹性面料，这种面料可以拉伸而不变形。"},{"sentence":"The government's fiscal policy must remain elastic, so that it can respond swiftly to economic downturns.","translation":"政府的财政政策必须保持弹性，以便能够迅速应对经济衰退。"}]},"fire":{"examples":[{"sentence":"Although the fire spread rapidly through the warehouse, the sprinkler system activated in time to prevent a total loss.","translation":"尽管大火在仓库中迅速蔓延，但自动喷水灭火系统及时启动，避免了全部损失。"},{"sentence":"The fire that started in the kitchen was caused by faulty wiring, which the landlord had neglected to repair for months.","translation":"那场始于厨房的火灾是由故障电线引起的，而房东已数月未进行维修。"},{"sentence":"Because the campers failed to extinguish their fire completely, a forest blaze ignited and threatened nearby homes.","translation":"由于露营者未能完全扑灭他们的火，一场森林大火燃起并威胁到附近的房屋。"},{"sentence":"In many traditional ceremonies, fire symbolizes purification and renewal, which explains its central role in rituals worldwide.","translation":"在许多传统仪式中，火象征着净化和更新，这解释了它在世界各地仪式中的核心作用。"},{"sentence":"The ancient scrolls were destroyed by fire, thereby erasing invaluable knowledge that scholars had yet to decipher.","translation":"古代卷轴被火烧毁，从而抹去了学者尚未破译的宝贵知识。"}]},"reel":{"examples":[{"sentence":"The fishing reel, which had been carefully maintained for decades, allowed the angler to land a surprisingly large catch.","translation":"那个被精心保养了几十年的渔轮，让垂钓者成功钓上了一条大得惊人的鱼。"},{"sentence":"Because the documentary footage arrived on a single film reel, the archivist had to digitize it before the material deteriorated.","translation":"由于纪录片素材是以单卷电影胶片的形式送达的，档案管理员必须在材料变质前将其数字化。"},{"sentence":"After the sudden policy shift, the entire industry was left to reel from the uncertainty that followed.","translation":"在政策突然转向之后，整个行业都因随之而来的不确定性而陷入混乱。"},{"sentence":"Although the technician carefully threaded the reel through the projector, a minor misalignment still caused the image to flicker.","translation":"尽管技术人员小心翼翼地将片卷穿过放映机，但微小的错位仍然导致画面闪烁。"},{"sentence":"When communities reel from the effects of rapid urbanization, planners must balance development with the preservation of green spaces.","translation":"当社区因快速城市化的影响而步履蹒跚时，规划者必须在发展与保护绿地之间取得平衡。"}]},"woman":{"examples":[{"sentence":"Although the woman had no formal business training, she built a multinational company through sheer determination and innovative thinking.","translation":"尽管这位女性没有受过正规的商业培训，但她凭借坚定的决心和创新思维建立了一家跨国公司。"},{"sentence":"Because the first woman to lead the department implemented inclusive policies, employee satisfaction and productivity improved significantly.","translation":"由于首位领导该部门的女性实施了包容性政策，员工满意度和生产力显著提高。"},{"sentence":"When a woman in a leadership position advocates for flexible work arrangements, the entire organization benefits from reduced turnover.","translation":"当一位担任领导职务的女性倡导灵活的工作安排时，整个组织都会因人员流失减少而受益。"},{"sentence":"The woman who discovered the breakthrough technique, which revolutionized medical diagnostics, received international acclaim for her contribution.","translation":"那位发现了突破性技术的女性，该技术彻底改变了医疗诊断，因其贡献而获得了国际赞誉。"},{"sentence":"While many doubted her ability, the young woman persisted in her research, thereby proving that gender does not determine scientific aptitude.","translation":"尽管许多人怀疑她的能力，这位年轻女性仍坚持研究，从而证明了性别并不决定科学才能。"}]},"mould":{"examples":[{"sentence":"Because the laboratory maintained strict humidity controls, no mould grew on the sensitive biological samples during storage.","translation":"由于实验室保持了严格的湿度控制，敏感的生物学样本在储存期间没有发霉。"},{"sentence":"The engineer designed a precision mould that enabled the mass production of lightweight components for the aerospace industry.","translation":"工程师设计了一个精密模具，使得航空航天工业的轻质部件得以大规模生产。"},{"sentence":"Although the artist broke the mould of traditional sculpture, her work still conveyed a profound sense of human emotion.","translation":"尽管这位艺术家打破了传统雕塑的模式，她的作品仍然传达了深刻的人类情感。"},{"sentence":"When educators break the mould of conventional teaching, students often develop critical thinking skills that serve them throughout life.","translation":"当教育者打破传统教学的模式时，学生往往会培养出终身受用的批判性思维能力。"},{"sentence":"The chef used a silicone mould to shape the dessert, which ensured a consistent presentation for the high-profile event.","translation":"厨师使用硅胶模具来塑造甜点，这确保了在重要活动中的一致呈现。"}]},"produce":{"examples":[{"sentence":"Although the farm's fresh produce is highly sought after, limited storage facilities prevent wider distribution.","translation":"尽管该农场的新鲜农产品备受追捧，但有限的储存设施阻碍了更广泛的销售。"},{"sentence":"Because the market emphasizes organic produce, many local growers have adopted sustainable farming practices.","translation":"由于市场重视有机农产品，许多当地种植者已采用可持续的耕作方式。"},{"sentence":"When consumers choose seasonal produce, they not only support local agriculture but also reduce carbon footprints.","translation":"当消费者选择时令农产品时，他们不仅支持了本地农业，还减少了碳足迹。"},{"sentence":"The grocery store's produce section, which sources from regional farms, ensures freshness and quality for customers.","translation":"该杂货店的农产品区从区域农场采购，从而确保为顾客提供新鲜和优质的产品。"},{"sentence":"Despite the drought, the cooperative managed to supply ample produce through innovative irrigation techniques.","translation":"尽管遭遇干旱，该合作社通过创新的灌溉技术成功供应了充足的农产品。"}]},"intermittent":{"examples":[{"sentence":"Although the region experiences intermittent rainfall, farmers have developed effective water conservation methods to sustain crops.","translation":"尽管该地区降雨时断时续，但农民们已开发出有效的节水方法来维持作物生长。"},{"sentence":"Because intermittent network failures disrupted remote work, the company invested in a more reliable infrastructure.","translation":"由于间歇性的网络故障扰乱了远程工作，该公司投资建设了更可靠的基础设施。"},{"sentence":"When patients report intermittent symptoms, doctors often recommend keeping a detailed diary to identify patterns.","translation":"当患者报告间歇性症状时，医生通常建议记详细的日记以识别规律。"},{"sentence":"Intermittent fasting, which alternates between eating and fasting periods, has been studied for its potential metabolic benefits.","translation":"间歇性禁食在进食和禁食时段之间交替，因其潜在的代谢益处而受到研究。"},{"sentence":"Despite intermittent setbacks, the research team persisted, ultimately achieving a breakthrough in renewable energy storage.","translation":"尽管遭遇间歇性的挫折，研究团队坚持不懈，最终在可再生能源存储方面取得了突破。"}]},"payment":{"examples":[{"sentence":"Although the initial payment was made on time, subsequent installments were delayed due to administrative errors.","translation":"尽管首付款按时支付，但由于行政错误，后续分期付款被延迟了。"},{"sentence":"Because the company adopted a digital payment system, transaction efficiency improved significantly while costs decreased.","translation":"因为公司采用了数字支付系统，交易效率显著提高，同时成本下降。"},{"sentence":"When a payment is processed through a secure gateway, sensitive financial data is encrypted to prevent fraud.","translation":"当付款通过安全网关处理时，敏感的财务数据会被加密以防止欺诈。"},{"sentence":"If the payment is not received by the due date, a late fee will be applied, which may affect the client's credit rating.","translation":"如果在到期日之前未收到付款，将收取滞纳金，这可能会影响客户的信用评级。"},{"sentence":"The government provides direct payment to farmers, thereby stabilizing their income despite market fluctuations.","translation":"政府向农民提供直接付款，从而在市场波动的情况下稳定他们的收入。"}]},"via":{"examples":[{"sentence":"Although the message was sent via encrypted email, the recipient failed to notice the attachment due to a spam filter.","translation":"尽管消息是通过加密电子邮件发送的，但由于垃圾邮件过滤器，收件人未能注意到附件。"},{"sentence":"Because the research team communicated via video conferencing, they saved considerable time and travel expenses.","translation":"因为研究团队通过视频会议进行沟通，他们节省了大量时间和差旅费用。"},{"sentence":"When data is transmitted via fiber-optic cables, the speed and reliability of the connection are greatly enhanced.","translation":"当数据通过光纤电缆传输时，连接的速度和可靠性大大提高。"},{"sentence":"If you apply for the visa via the official website, the processing time is typically shorter than using a paper form.","translation":"如果你通过官方网站申请签证，处理时间通常比使用纸质表格短。"},{"sentence":"The medication is administered via intravenous injection, which allows for rapid absorption into the bloodstream.","translation":"药物通过静脉注射给药，这使其能迅速被血液吸收。"}]},"invariably":{"examples":[{"sentence":"When researchers rely on a single data source, their conclusions invariably suffer from limited generalizability.","translation":"当研究人员依赖单一数据来源时，其结论的普适性总是会受到限制。"},{"sentence":"In competitive markets, firms that fail to innovate invariably lose their advantage over time.","translation":"在竞争性市场中，未能创新的企业随着时间的推移总是会失去优势。"},{"sentence":"Public policies designed without stakeholder input invariably encounter resistance during implementation.","translation":"在设计时未征求利益相关者意见的公共政策，在实施过程中总是会遇到阻力。"},{"sentence":"Although technology can streamline many tasks, complex decision-making invariably requires human judgment.","translation":"尽管技术可以简化许多任务，但复杂的决策始终需要人类的判断。"},{"sentence":"Students who postpone their assignments until the last minute invariably produce work that falls short of their potential.","translation":"将作业拖到最后一刻的学生，其成果总是未能充分发挥他们的潜力。"}]},"quarrel":{"examples":[{"sentence":"Although the quarrel began over a trivial misunderstanding, it eventually damaged their professional relationship beyond repair.","translation":"尽管这场争吵始于一个微不足道的误会，但最终却无可挽回地损害了他们的职业关系。"},{"sentence":"The board members engaged in a heated quarrel over the proposed merger, which delayed the final vote by several hours.","translation":"董事会成员就拟议的合并展开了激烈争吵，这使得最终投票推迟了数小时。"},{"sentence":"Because the quarrel between the two lead researchers was never resolved, the collaborative project lost its funding.","translation":"由于两位主要研究员之间的争吵从未得到解决，该合作项目失去了资金支持。"},{"sentence":"When a quarrel arises in a multicultural team, it often stems from differing communication styles rather than genuine disagreement.","translation":"当多元文化团队中出现争吵时，它往往源于不同的沟通风格，而非真正的分歧。"},{"sentence":"The long-standing quarrel between the neighboring countries was finally settled through diplomatic mediation, thereby averting a larger conflict.","translation":"邻国之间长期的争吵最终通过外交调解得以解决，从而避免了一场更大的冲突。"}]},"mostly":{"examples":[{"sentence":"Although the conference attracted a diverse audience, the attendees were mostly academics from the field of environmental science.","translation":"尽管会议吸引了多元化的听众，但与会者大多是环境科学领域的学者。"},{"sentence":"The success of the startup was mostly due to its innovative marketing strategy, which targeted a niche audience effectively.","translation":"这家初创公司的成功主要归功于其创新的营销策略，该策略有效地瞄准了小众受众。"},{"sentence":"Because the region's economy is mostly dependent on agriculture, climate change poses a significant threat to its stability.","translation":"由于该地区的经济主要依赖农业，气候变化对其稳定构成了重大威胁。"},{"sentence":"While the course includes some theoretical concepts, the assessments are mostly based on practical applications and case studies.","translation":"虽然这门课程包含一些理论概念，但评估大多基于实际应用和案例研究。"},{"sentence":"The research findings were mostly consistent with previous studies, except for a few anomalies that require further investigation.","translation":"研究结果与先前的研究大体一致，除了一些需要进一步调查的异常情况。"}]},"auto":{"examples":[{"sentence":"The auto industry is shifting toward electric vehicles, which promise to reduce urban air pollution.","translation":"汽车工业正转向电动汽车，这有望减少城市空气污染。"},{"sentence":"Because the auto repair shop diagnosed the engine fault early, we avoided a much costlier breakdown later.","translation":"由于汽车修理厂及早诊断出发动机故障，我们避免了后来代价更高的抛锚。"},{"sentence":"Although auto loans make car ownership more accessible, they can also lead to long-term financial strain.","translation":"尽管汽车贷款使购车变得更容易，但也可能导致长期的财务压力。"},{"sentence":"The researcher developed an auto-calibration system that adjusts the sensors without human intervention.","translation":"这位研究人员开发了一种自动校准系统，无需人工干预即可调整传感器。"},{"sentence":"Modern factories rely on auto-guided vehicles to transport materials, thereby improving efficiency and safety.","translation":"现代工厂依靠自动导引车来运输物料，从而提高了效率和安全性。"}]},"pound":{"examples":[{"sentence":"Although the parcel weighed only a pound, the shipping cost was surprisingly high due to the remote destination.","translation":"尽管包裹只有一磅重，但由于目的地偏远，运费高得惊人。"},{"sentence":"Because the recipe requires a pound of butter, which is quite rich, you may want to reduce the amount for a lighter dish.","translation":"因为食谱需要一磅黄油，这相当油腻，你可能想减少用量以做出更清淡的菜肴。"},{"sentence":"The fisherman used a heavy mallet to pound the octopus, thereby tenderizing the meat before cooking.","translation":"渔夫用重木槌敲打章鱼，从而在烹饪前使肉质变嫩。"},{"sentence":"When the blacksmith began to pound the hot iron, sparks flew in all directions, creating a dramatic scene.","translation":"当铁匠开始锤打炽热的铁块时，火花四溅，场面十分壮观。"},{"sentence":"If you pound the spices into a fine powder, their flavors will be more evenly distributed throughout the dish.","translation":"如果你把香料捣成细粉，它们的味道会更均匀地分布在菜肴中。"}]},"twenty":{"examples":[{"sentence":"Although the company has only twenty employees, it has managed to secure several international patents.","translation":"尽管这家公司只有二十名员工，但它已成功获得多项国际专利。"},{"sentence":"Because the experiment required a sample size of at least twenty participants, the researchers had to extend the recruitment period.","translation":"由于实验需要至少二十名参与者，研究人员不得不延长招募期。"},{"sentence":"When the city implemented a twenty-mile-per-hour speed limit in residential areas, traffic accidents decreased significantly.","translation":"当该市在居民区实施每小时二十英里的限速时，交通事故显著减少。"},{"sentence":"The scholarship program, which awards twenty students each year, aims to support underprivileged youth in pursuing higher education.","translation":"该奖学金项目每年奖励二十名学生，旨在支持贫困青年接受高等教育。"},{"sentence":"If the temperature drops below twenty degrees Fahrenheit, the pipes are likely to freeze, thereby causing extensive damage.","translation":"如果温度降至华氏二十度以下，管道很可能会冻结，从而造成大面积损坏。"}]},"opportunity":{"examples":[{"sentence":"Although the internship is unpaid, it provides a unique opportunity to gain hands-on experience in a competitive industry.","translation":"尽管这份实习没有薪水，但它提供了一个在竞争激烈的行业中获得实践经验的独特机会。"},{"sentence":"Because the conference brings together leading scholars, it offers an ideal opportunity for young researchers to present their work.","translation":"由于这次会议汇集了顶尖学者，它为年轻研究人员展示自己的工作提供了理想的机会。"},{"sentence":"When the government introduced tax incentives for green energy, many entrepreneurs seized the opportunity to launch sustainable startups.","translation":"当政府推出绿色能源税收优惠政策时，许多企业家抓住机会创办了可持续发展的初创企业。"},{"sentence":"The exchange program, which allows students to study abroad for a semester, is a valuable opportunity to broaden their cultural horizons.","translation":"这个交换项目允许学生出国学习一个学期，是拓宽他们文化视野的宝贵机会。"},{"sentence":"If we fail to address climate change now, we may miss the last opportunity to prevent irreversible environmental damage.","translation":"如果我们现在不应对气候变化，我们可能会错过防止不可逆转的环境破坏的最后机会。"}]},"deer":{"examples":[{"sentence":"Although deer are often seen as gentle creatures, their overpopulation can lead to severe ecological imbalances.","translation":"尽管鹿通常被视为温顺的动物，但它们的数量过多会导致严重的生态失衡。"},{"sentence":"Because deer lack natural predators in the area, their population has grown rapidly, which threatens local vegetation.","translation":"由于该地区鹿缺乏天敌，它们的数量迅速增长，这威胁到当地的植被。"},{"sentence":"When the highway was built through the forest, it disrupted the migratory routes of deer, thereby increasing the risk of collisions.","translation":"当高速公路穿过森林修建时，它扰乱了鹿的迁徙路线，从而增加了碰撞的风险。"},{"sentence":"The conservation program, which focuses on restoring native habitats, has helped stabilize the deer population in the region.","translation":"该保护计划专注于恢复原生栖息地，帮助稳定了该地区的鹿群数量。"},{"sentence":"If hunting regulations are not enforced, the deer population may decline to a level that disrupts the entire food chain.","translation":"如果不执行狩猎法规，鹿的数量可能会下降到破坏整个食物链的水平。"}]},"orchard":{"examples":[{"sentence":"Although the orchard was small, it produced enough apples to supply the local market throughout the autumn season.","translation":"尽管果园很小，但它生产的苹果足以在整个秋季供应本地市场。"},{"sentence":"The farmers planted a windbreak of tall trees around the orchard, which protected the fruit trees from strong gusts and reduced soil erosion.","translation":"农民们在果园周围种植了高大的防风林，这保护了果树免受强风侵袭并减少了水土流失。"},{"sentence":"Because the orchard had been neglected for years, the new owners had to prune the overgrown branches and replenish the depleted soil.","translation":"由于果园多年无人照料，新主人不得不修剪过度生长的枝条并补充贫瘠的土壤。"},{"sentence":"The agricultural cooperative invested in a modern irrigation system, thereby ensuring that every tree in the orchard received adequate water during the drought.","translation":"农业合作社投资了一套现代灌溉系统，从而确保果园里的每棵树在干旱期间都能获得充足的水分。"},{"sentence":"While the cherry orchard attracted tourists with its breathtaking blossoms in spring, the real profit came from the summer fruit harvest.","translation":"虽然樱桃园在春天以其令人叹为观止的花朵吸引了游客，但真正的利润来自夏季的水果收获。"}]},"different":{"examples":[{"sentence":"Although the two theories appear similar, they are based on fundamentally different assumptions about human motivation.","translation":"尽管这两种理论看起来相似，但它们基于对人类动机根本不同的假设。"},{"sentence":"The survey revealed that consumers from different age groups have distinct preferences, which marketers must consider when designing campaigns.","translation":"调查显示，不同年龄段的消费者有不同的偏好，营销人员在设计活动时必须考虑这一点。"},{"sentence":"Because the twins were raised in different environments, their personalities diverged significantly despite their identical genetic makeup.","translation":"由于双胞胎在不同的环境中长大，尽管基因构成相同，他们的性格却大相径庭。"},{"sentence":"The new curriculum introduces students to different cultural perspectives, thereby fostering a more inclusive and global mindset.","translation":"新课程向学生介绍不同的文化视角，从而培养更具包容性和全球性的思维模式。"},{"sentence":"While both methods achieve the same goal, they employ different strategies, with one focusing on efficiency and the other on sustainability.","translation":"虽然两种方法达到相同的目标，但它们采用不同的策略，一种注重效率，另一种注重可持续性。"}]},"highway":{"examples":[{"sentence":"Although the highway was designed to alleviate urban congestion, it inadvertently encouraged more car usage.","translation":"尽管这条公路旨在缓解城市拥堵，但它无意中鼓励了更多汽车使用。"},{"sentence":"The government invested in a coastal highway, which not only boosted tourism but also improved access to remote villages.","translation":"政府投资了一条沿海公路，这不仅促进了旅游业，还改善了通往偏远村庄的交通。"},{"sentence":"Because the highway lacked proper lighting, accidents were frequent during nighttime travel.","translation":"由于这条公路缺乏适当的照明，夜间行驶时事故频发。"},{"sentence":"The construction of the transcontinental highway, while costly, has strengthened economic ties between the two regions.","translation":"这条横贯大陆的公路建设虽然成本高昂，但加强了两地区之间的经济联系。"},{"sentence":"To ensure the safety of wildlife, the new highway includes several underpasses that allow animals to cross without risk.","translation":"为了确保野生动物的安全，新公路包括几个地下通道，让动物可以无风险地穿越。"}]},"attention":{"examples":[{"sentence":"Because the issue of mental health has gained more attention, schools are now implementing counseling services for students.","translation":"由于心理健康问题获得了更多关注，学校现在正在为学生实施咨询服务。"},{"sentence":"The documentary, which highlights the plight of endangered species, has drawn global attention to conservation efforts.","translation":"这部纪录片突出了濒危物种的困境，引起了全球对保护工作的关注。"},{"sentence":"Although the company paid close attention to customer feedback, it failed to address the underlying product flaws.","translation":"尽管公司密切关注客户反馈，但未能解决根本的产品缺陷。"},{"sentence":"To ensure a successful event, the organizers must pay meticulous attention to logistical details such as seating and catering.","translation":"为了确保活动成功，组织者必须对座位和餐饮等后勤细节给予细致关注。"},{"sentence":"The sudden shift in market trends demands that investors redirect their attention from traditional sectors to emerging technologies.","translation":"市场趋势的突然转变要求投资者将注意力从传统行业转向新兴技术。"}]},"forward":{"examples":[{"sentence":"Although the initial proposal was rejected, the team decided to move forward with a revised plan that addressed the committee's concerns.","translation":"尽管最初的提案被否决，团队决定继续推进一项修订后的计划，以解决委员会的顾虑。"},{"sentence":"The company's forward-looking strategy, which emphasizes sustainable development, has attracted considerable investment from environmentally conscious funds.","translation":"该公司强调可持续发展的前瞻性战略，吸引了大量来自环保基金的投资。"},{"sentence":"Because the conference was postponed, we look forward to welcoming you at the rescheduled event in September.","translation":"由于会议延期，我们期待在九月的重新安排活动中欢迎您。"},{"sentence":"When researchers put forward a groundbreaking theory, they must provide robust evidence to support their claims.","translation":"当研究人员提出开创性理论时，他们必须提供有力证据来支持其主张。"},{"sentence":"The government is pushing forward with infrastructure reforms, thereby creating new opportunities for private sector participation.","translation":"政府正在推进基础设施改革，从而为私营部门参与创造新机会。"}]},"ash":{"examples":[{"sentence":"Because the volcanic ash contained fine particulate matter, it posed a serious health risk to residents, which prompted a mass evacuation.","translation":"由于火山灰含有细颗粒物，它对居民构成了严重的健康风险，这促使了大规模疏散。"},{"sentence":"The ancient scrolls were reduced to ash in the fire, thereby erasing a unique record of the civilization's legal system.","translation":"古代卷轴在火灾中化为灰烬，从而抹去了该文明法律体系的独特记录。"},{"sentence":"Although the factory claimed to filter its emissions, a layer of ash still accumulated on nearby homes, which indicated inadequate pollution control.","translation":"尽管工厂声称过滤了排放物，但附近房屋上仍积聚了一层灰烬，这表明污染控制不足。"},{"sentence":"By mixing wood ash with water, the settlers created a mild alkali solution that they used to make soap.","translation":"通过将木灰与水混合，定居者制造了一种温和的碱溶液，他们用它来制作肥皂。"},{"sentence":"The cremation process reduces the body to ash, which is then placed in an urn for the family to keep or scatter.","translation":"火化过程将遗体化为灰烬，然后将其放入骨灰盒中，供家人保存或撒放。"}]},"abdomen":{"examples":[{"sentence":"Because the patient experienced sharp pain in the lower abdomen, the physician ordered a CT scan to rule out appendicitis.","translation":"由于患者下腹部剧痛，医生要求进行CT扫描以排除阑尾炎。"},{"sentence":"The yoga instructor emphasized that engaging the abdomen during poses not only improves balance but also protects the spine.","translation":"瑜伽教练强调，在体式中收紧腹部不仅能改善平衡，还能保护脊柱。"},{"sentence":"In spiders, the silk-producing glands are located in the abdomen, which allows them to spin webs with remarkable precision.","translation":"在蜘蛛体内，产丝腺位于腹部，这使它们能够以惊人的精度织网。"},{"sentence":"After the surgery, the patient was advised to avoid heavy lifting to prevent strain on the abdomen, thereby reducing the risk of hernia.","translation":"手术后，患者被建议避免提重物以防止腹部受力，从而降低疝气的风险。"},{"sentence":"Although the insect's thorax is rigid, its abdomen remains flexible, which facilitates movement and respiration.","translation":"尽管昆虫的胸部是坚硬的，但其腹部保持灵活，这有利于运动和呼吸。"}]},"horizontal":{"examples":[{"sentence":"Although vertical integration offers control, horizontal expansion allows companies to diversify their product lines and reduce risk.","translation":"尽管纵向一体化提供控制力，但横向扩张使公司能够多样化其产品线并降低风险。"},{"sentence":"Because the graph's horizontal axis represents time, we can easily track changes in temperature over the past century.","translation":"因为图表的横轴代表时间，我们可以轻松追踪过去一个世纪温度的变化。"},{"sentence":"While the painting features strong vertical elements, the subtle horizontal lines create a sense of calm and stability.","translation":"虽然这幅画以强烈的垂直元素为特色，但微妙的水平线条营造出一种平静和稳定的感觉。"},{"sentence":"The organization adopted a horizontal management structure, which encourages collaboration rather than top-down directives.","translation":"该组织采用了横向管理结构，这鼓励协作而非自上而下的指令。"},{"sentence":"When designing the interface, we prioritized horizontal navigation to ensure that users can access all features without scrolling.","translation":"在设计界面时，我们优先考虑横向导航，以确保用户无需滚动即可访问所有功能。"}]},"symmetry":{"examples":[{"sentence":"Although perfect symmetry is often considered beautiful, slight asymmetry can make a design more dynamic and interesting.","translation":"尽管完美的对称常被认为是美的，但轻微的不对称可以使设计更具动感和趣味。"},{"sentence":"Because the two sides of the equation exhibit symmetry, we can simplify the problem by focusing on just one half.","translation":"因为方程的两边表现出对称性，我们可以通过只关注一半来简化问题。"},{"sentence":"While the human face has approximate bilateral symmetry, minor differences between the left and right sides are normal.","translation":"虽然人脸具有近似的两侧对称，但左右两侧的微小差异是正常的。"},{"sentence":"The architect incorporated symmetry into the building's facade, which conveys a sense of order and formality.","translation":"建筑师将对称性融入建筑的正面，这传达出一种秩序和庄重的感觉。"},{"sentence":"If a crystal lacks internal symmetry, its physical properties may vary depending on the direction of measurement.","translation":"如果晶体缺乏内部对称性，其物理性质可能因测量方向而异。"}]},"finally":{"examples":[{"sentence":"After decades of incremental progress, the research team finally achieved a breakthrough that could transform renewable energy storage.","translation":"经过数十年的逐步进展，研究团队终于取得了一项可能改变可再生能源储存方式的突破。"},{"sentence":"Although the negotiations were protracted and difficult, the two parties finally reached a consensus on the core trade provisions.","translation":"尽管谈判旷日持久且困难重重，双方最终就核心贸易条款达成了共识。"},{"sentence":"When the long-awaited reform was finally enacted, it brought immediate relief to small businesses across the region.","translation":"当期待已久的改革最终颁布时，它立即为该地区的小企业带来了缓解。"},{"sentence":"By integrating feedback from multiple stakeholders, the design team finally produced a blueprint that balanced functionality with aesthetic appeal.","translation":"通过整合多方利益相关者的反馈，设计团队最终制作出了一份兼顾功能与美感的蓝图。"},{"sentence":"Having examined all the evidence, the committee finally concluded that the environmental impact would be minimal if proper safeguards were in place.","translation":"在审查了所有证据后，委员会最终得出结论，如果适当的保障措施到位，环境影响将是最小的。"}]},"helicopter":{"examples":[{"sentence":"Although the helicopter was designed for military use, it now serves civilian purposes such as medical evacuation.","translation":"尽管这架直升机最初是为军事用途设计的，但它现在服务于医疗后送等民用目的。"},{"sentence":"Because the helicopter can land in confined spaces, it is ideal for urban rescue operations.","translation":"由于直升机能在狭小空间着陆，它非常适合城市救援行动。"},{"sentence":"The helicopter, which was equipped with advanced navigation systems, flew safely through the storm.","translation":"那架配备了先进导航系统的直升机安全地穿越了暴风雨。"},{"sentence":"When the helicopter arrived at the scene, the crew immediately began hoisting survivors to safety.","translation":"当直升机抵达现场时，机组人员立即开始将幸存者吊运至安全地带。"},{"sentence":"The company uses a helicopter to transport executives between offices, thereby saving valuable time.","translation":"公司使用直升机在办公室之间运送高管，从而节省宝贵时间。"}]},"predominant":{"examples":[{"sentence":"Although digital media have expanded rapidly, television remains the predominant source of news for older generations.","translation":"尽管数字媒体迅速扩张，电视仍然是老一辈人获取新闻的主要来源。"},{"sentence":"In many developing countries, agriculture is the predominant sector of employment, which makes rural development policies essential for poverty reduction.","translation":"在许多发展中国家，农业是主要的就业部门，这使得农村发展政策对于减贫至关重要。"},{"sentence":"The predominant reason for the project's failure was a lack of clear communication among team members, rather than technical difficulties.","translation":"项目失败的主要原因在于团队成员之间缺乏清晰的沟通，而非技术困难。"},{"sentence":"While economic factors are important, the predominant influence on educational attainment is often the family environment in which a child grows up.","translation":"虽然经济因素很重要，但对教育成就的主要影响往往是孩子成长的家庭环境。"},{"sentence":"The survey revealed that the predominant concern among urban residents is air pollution, which has prompted the government to implement stricter emission standards.","translation":"调查显示，城市居民最主要的担忧是空气污染，这促使政府实施了更严格的排放标准。"}]},"liable":{"examples":[{"sentence":"Although the contract was signed under duress, the company is still liable for the damages caused by the breach.","translation":"尽管合同是在胁迫下签署的，但公司仍需对违约造成的损害负责。"},{"sentence":"Because the manufacturer failed to issue a timely recall, it is liable for any injuries resulting from the defective product.","translation":"由于制造商未能及时召回，它要对缺陷产品造成的任何伤害负责。"},{"sentence":"While all drivers are liable for traffic violations, those who cause accidents face more severe penalties.","translation":"虽然所有司机都要对交通违规负责，但造成事故的司机会面临更严厉的处罚。"},{"sentence":"The new policy states that employers are liable for workplace harassment, which encourages them to enforce stricter codes of conduct.","translation":"新政策规定雇主应对工作场所骚扰负责，这鼓励他们执行更严格的行为准则。"},{"sentence":"If a tenant damages the property beyond normal wear and tear, they are liable for the repair costs, according to the lease agreement.","translation":"根据租赁协议，如果租户对房屋的损坏超出正常磨损，他们应承担维修费用。"}]},"piston":{"examples":[{"sentence":"Although modern engines use advanced materials, the piston remains a critical component that must withstand extreme temperatures and pressures.","translation":"尽管现代发动机使用先进材料，活塞仍然是必须承受极端温度和压力的关键部件。"},{"sentence":"Because the piston was not properly lubricated, excessive friction caused the engine to overheat and eventually seize.","translation":"由于活塞没有得到适当润滑，过度摩擦导致发动机过热并最终卡死。"},{"sentence":"The hydraulic system uses a piston to convert fluid pressure into mechanical force, which is essential for operating heavy machinery.","translation":"液压系统利用活塞将流体压力转化为机械力，这对于操作重型机械至关重要。"},{"sentence":"When the piston moves downward during the intake stroke, a mixture of air and fuel is drawn into the cylinder.","translation":"当活塞在进气冲程中向下移动时，空气和燃料的混合物被吸入气缸。"},{"sentence":"The innovative design features a hollow piston, thereby reducing weight without compromising structural integrity.","translation":"创新设计采用空心活塞，从而在不影响结构完整性的情况下减轻了重量。"}]},"hate":{"examples":[{"sentence":"Although hate is a powerful emotion, it often harms the person who harbors it more than the intended target.","translation":"尽管仇恨是一种强烈的情感，但它往往对怀有仇恨的人造成的伤害比对目标更大。"},{"sentence":"When hate is allowed to fester within a society, it can erode the trust that is essential for democratic governance.","translation":"当仇恨在社会中滋生时，它会侵蚀民主治理所必需的信任。"},{"sentence":"The hate that divided the two families was eventually overcome through a series of sincere reconciliatory gestures.","translation":"分裂两个家庭的仇恨最终通过一系列真诚的和解姿态得以克服。"},{"sentence":"Because hate crimes target individuals based on their identity, they send a message of fear to entire communities.","translation":"由于仇恨犯罪基于身份针对个人，它们向整个社区传递了恐惧的信息。"},{"sentence":"Psychologists argue that hate is not an innate emotion but rather a learned response that can be unlearned through education.","translation":"心理学家认为仇恨不是一种天生的情感，而是一种可以通过教育消除的习得反应。"}]},"circle":{"examples":[{"sentence":"Although the children sat in a circle around the teacher, some still struggled to focus on the story.","translation":"尽管孩子们围着老师坐成一圈，有些人仍然难以集中注意力听故事。"},{"sentence":"Expanding your professional circle through networking events can open doors to unexpected career opportunities, which is why many graduates attend them regularly.","translation":"通过社交活动拓展职业圈子可以带来意想不到的职业机会，这就是为什么许多毕业生经常参加这些活动。"},{"sentence":"The artist drew a perfect circle freehand, demonstrating years of disciplined practice that impressed the entire audience.","translation":"这位艺术家徒手画了一个完美的圆，展示了多年自律练习的成果，令全场观众印象深刻。"},{"sentence":"Because a vicious circle of poverty and poor education traps many families for generations, targeted interventions are essential to break the cycle.","translation":"由于贫困与教育落后之间的恶性循环使许多家庭世代受困，有针对性的干预措施对于打破这一循环至关重要。"},{"sentence":"The discussion eventually came full circle, returning to the original proposal after hours of debate, thereby highlighting the complexity of the issue.","translation":"讨论最终绕了一圈，在数小时的辩论后又回到了最初的提议，从而凸显了问题的复杂性。"}]},"sugar":{"examples":[{"sentence":"Excessive consumption of sugar has been linked to a higher risk of obesity and diabetes, which has prompted many governments to introduce health campaigns.","translation":"过量摄入糖分与肥胖和糖尿病的较高风险有关，这促使许多政府推出了健康宣传活动。"},{"sentence":"The chef added a pinch of sugar to the tomato sauce to balance the acidity, thereby enhancing the overall flavor of the dish.","translation":"厨师在番茄酱中加入少许糖以平衡酸度，从而提升了菜肴的整体风味。"},{"sentence":"Many processed foods contain hidden sugar, which makes it difficult for consumers to control their intake unless they carefully read nutrition labels.","translation":"许多加工食品含有隐藏的糖分，这使得消费者难以控制摄入量，除非他们仔细阅读营养标签。"},{"sentence":"Plants produce sugar through photosynthesis, converting sunlight into chemical energy that sustains nearly all life on Earth.","translation":"植物通过光合作用产生糖分，将阳光转化为化学能，维持了地球上几乎所有的生命。"},{"sentence":"The government imposed a tax on sugary drinks to discourage excessive sugar consumption, a policy that has proven effective in several countries.","translation":"政府对含糖饮料征税，以抑制过量糖分摄入，这一政策已在多个国家被证明有效。"}]},"wife":{"examples":[{"sentence":"His wife, a renowned scientist, has published several influential papers on climate change, which have shaped international environmental policies.","translation":"他的妻子是一位著名科学家，发表了几篇关于气候变化的有影响力的论文，这些论文影响了国际环境政策。"},{"sentence":"The couple decided that the wife would pursue her career abroad while the husband managed the household, a choice that challenged traditional gender roles.","translation":"这对夫妇决定妻子去国外发展事业，而丈夫则负责料理家务，这一选择挑战了传统的性别角色。"},{"sentence":"In many traditional societies, a wife was expected to devote herself entirely to domestic duties, which limited her opportunities for personal growth.","translation":"在许多传统社会中，妻子被期望全身心投入家务劳动，这限制了她个人成长的机会。"},{"sentence":"The novel explores the inner conflict of a wife who struggles to balance family obligations and personal ambitions, a theme that resonates with many modern readers.","translation":"这部小说探讨了一位妻子在家庭责任与个人抱负之间挣扎的内心冲突，这一主题引起了许多现代读者的共鸣。"},{"sentence":"After his wife passed away, he found solace in continuing the charitable work they had started together, which helped him cope with his grief.","translation":"妻子去世后，他通过继续他们共同发起的慈善工作找到了慰藉，这帮助他应对了悲痛。"}]},"cock":{"examples":[{"sentence":"Although the cock crowed at dawn, the villagers had already begun their daily chores.","translation":"尽管公鸡在黎明时啼叫，村民们早已开始了日常劳作。"},{"sentence":"Because the old water cock was leaking, the plumber installed a new one to prevent water waste.","translation":"因为旧水龙头漏水，水管工安装了一个新的以防止浪费水。"},{"sentence":"The farmer relied on the cock, which served as a natural alarm clock for the entire household.","translation":"农夫依赖那只公鸡，它充当了全家人的天然闹钟。"},{"sentence":"When the cock strutted across the barnyard, the hens followed him in a neat line.","translation":"当公鸡在谷仓空地上大摇大摆地走过时，母鸡们排成整齐的一行跟着他。"},{"sentence":"The engineer adjusted the safety cock carefully, thereby ensuring that the pressure remained stable.","translation":"工程师仔细调整了安全旋塞，从而确保压力保持稳定。"}]},"lid":{"examples":[{"sentence":"When the lid of the pressure cooker is not secured properly, steam can escape and cause serious burns.","translation":"当高压锅的盖子没有正确盖好时，蒸汽会逸出并导致严重烫伤。"},{"sentence":"The company placed a tight lid on expenditure to ensure that the project remained within budget.","translation":"公司严格控制开支，以确保项目保持在预算之内。"},{"sentence":"Although the jar's lid was stuck, applying hot water loosened it enough to open without damage.","translation":"尽管罐子的盖子卡住了，但用热水浇淋使其松动，足以无损打开。"},{"sentence":"By keeping a lid on sensitive negotiations, the diplomats prevented premature leaks that could have derailed the peace talks.","translation":"通过保密敏感的谈判，外交官们防止了可能破坏和平谈判的过早泄密。"},{"sentence":"The new regulation puts a lid on carbon emissions, which will force industries to adopt cleaner technologies.","translation":"新规定限制了碳排放，这将迫使工业采用更清洁的技术。"}]},"drama":{"examples":[{"sentence":"Although she studied drama at university, she now works as a corporate trainer, using theatrical techniques to improve communication skills.","translation":"尽管她在大学学习戏剧，但她现在担任企业培训师，运用戏剧技巧来提高沟通能力。"},{"sentence":"The drama of the courtroom, which captivated the public, highlighted significant flaws in the legal system.","translation":"法庭上的戏剧性事件吸引了公众，凸显了法律体系的重大缺陷。"},{"sentence":"Because television drama often reflects societal values, it serves as a valuable subject for cultural analysis.","translation":"由于电视剧往往反映社会价值观，它成为文化分析的重要课题。"},{"sentence":"The drama club's production of Hamlet received widespread acclaim, thereby encouraging more students to participate in the arts.","translation":"戏剧俱乐部制作的《哈姆雷特》广受好评，从而鼓励了更多学生参与艺术活动。"},{"sentence":"When the novel was adapted into a drama, the screenwriter added new scenes to enhance the emotional impact.","translation":"当这部小说被改编成戏剧时，编剧增加了新场景以增强情感冲击力。"}]},"organism":{"examples":[{"sentence":"A single-celled organism can exhibit remarkably complex behaviors when it responds to environmental changes.","translation":"单细胞生物在应对环境变化时，能够表现出极其复杂的行为。"},{"sentence":"Because the organism reproduces rapidly, it is widely used in genetic research to study inheritance patterns.","translation":"由于这种生物繁殖迅速，它被广泛用于遗传学研究，以探究遗传模式。"},{"sentence":"The organism's ability to adapt to extreme temperatures, which provides insights into evolutionary biology, has fascinated scientists for decades.","translation":"这种生物适应极端温度的能力为进化生物学提供了见解，几十年来一直令科学家着迷。"},{"sentence":"A healthy organism maintains internal stability through a process known as homeostasis, thereby ensuring optimal functioning.","translation":"健康的生物体通过称为稳态的过程维持内部稳定，从而确保最佳功能。"},{"sentence":"The introduction of a non-native organism can disrupt an entire ecosystem, as seen in many invasive species cases that threaten biodiversity.","translation":"引入非本地生物可能破坏整个生态系统，正如许多威胁生物多样性的入侵物种案例所示。"}]},"distance":{"examples":[{"sentence":"Although the distance between the two cities is considerable, the new high-speed rail line has effectively reduced travel time.","translation":"尽管两座城市之间的距离遥远，但新的高铁线路有效缩短了旅行时间。"},{"sentence":"Maintaining a critical distance from one's own work, which is essential for objective self-assessment, allows researchers to identify flaws more easily.","translation":"与自己的作品保持批判性距离对于客观的自我评估至关重要，这使研究人员更容易发现缺陷。"},{"sentence":"Because the perceived distance between social classes can hinder effective communication, policymakers must address this issue to promote social cohesion.","translation":"由于社会阶层之间感知到的距离会阻碍有效沟通，政策制定者必须解决这一问题以促进社会凝聚力。"},{"sentence":"From a distance, the mountain appeared serene, yet its slopes concealed treacherous terrain that challenged even experienced climbers.","translation":"从远处看，这座山显得宁静，但其山坡隐藏着危险的地形，甚至对经验丰富的登山者也是挑战。"},{"sentence":"The researchers collaborated seamlessly via video conferencing, despite the distance that separated their laboratories on different continents.","translation":"尽管距离将位于不同大陆的实验室隔开，研究人员通过视频会议实现了无缝协作。"}]},"nothing":{"examples":[{"sentence":"Despite the committee's lengthy deliberations, nothing of substance emerged to address the budget shortfall.","translation":"尽管委员会进行了漫长的审议，但未能提出任何实质性内容来解决预算缺口。"},{"sentence":"When researchers examined the correlation, they found nothing to support the claim that screen time impairs cognitive development.","translation":"当研究人员检验相关性时，他们未发现任何证据支持屏幕时间损害认知发展的说法。"},{"sentence":"Because the policy lacked enforcement mechanisms, it accomplished nothing beyond symbolic recognition of the problem.","translation":"由于该政策缺乏执行机制，除了象征性地承认问题之外，它一无所成。"},{"sentence":"If a hypothesis cannot be tested empirically, it contributes nothing to scientific progress.","translation":"如果一个假设无法被实证检验，它对科学进步毫无贡献。"},{"sentence":"Although the new software promised efficiency gains, it offered nothing that justified its high implementation cost.","translation":"尽管新软件承诺提高效率，但它并未提供任何足以证明其高昂实施成本的功能。"}]},"monitor":{"examples":[{"sentence":"Although the monitor displayed normal readings, the engineer suspected a calibration error and ran a diagnostic test.","translation":"尽管监视器显示正常读数，但工程师怀疑存在校准错误，于是运行了诊断测试。"},{"sentence":"Because the class monitor organized study groups effectively, the overall performance of the students improved significantly.","translation":"由于班长有效地组织了学习小组，学生的整体表现显著提高。"},{"sentence":"When the air quality monitor detected elevated pollutant levels, the authorities issued a health advisory for vulnerable populations.","translation":"当空气质量监测器检测到污染物水平升高时，当局向脆弱人群发布了健康建议。"},{"sentence":"The network monitor, which analyzes traffic in real time, helps prevent cyberattacks by identifying suspicious patterns.","translation":"网络监视器实时分析流量，通过识别可疑模式帮助防止网络攻击。"},{"sentence":"To ensure patient safety, the nurse attached a heart rate monitor that would alert the staff if any irregularities occurred.","translation":"为确保患者安全，护士连接了一个心率监测器，一旦出现任何异常就会提醒医护人员。"}]},"legend":{"examples":[{"sentence":"Although the legend of the dragon persists in local folklore, archaeologists have found no evidence of such a creature.","translation":"尽管龙的传说在当地民间传说中流传，但考古学家没有发现这种生物的证据。"},{"sentence":"Because the map's legend was unclear, hikers misinterpreted the symbols and took a dangerous route.","translation":"由于地图的图例不清晰，徒步旅行者误解了符号，走上了一条危险的路线。"},{"sentence":"When scholars examined the legend of Robin Hood, they discovered that it evolved from earlier ballads about outlaws.","translation":"当学者们研究罗宾汉的传说时，他们发现它是由早期关于亡命之徒的歌谣演变而来的。"},{"sentence":"The musician became a legend in the jazz world, which still celebrates his innovative improvisational style.","translation":"这位音乐家成为爵士乐界的传奇人物，至今人们仍在颂扬他创新的即兴演奏风格。"},{"sentence":"If a legend lacks historical corroboration, it is often classified as mythology rather than factual history.","translation":"如果一个传说缺乏历史佐证，它通常被归类为神话而非真实历史。"}]},"maneuver":{"examples":[{"sentence":"The general's brilliant maneuver, which involved a feigned retreat, completely deceived the enemy and led to a swift victory.","translation":"将军的巧妙策略，包括一次佯装撤退，完全欺骗了敌人并带来了迅速的胜利。"},{"sentence":"In a competitive market, companies must maneuver strategically to gain an advantage, rather than relying solely on traditional methods.","translation":"在竞争激烈的市场中，公司必须战略性地运筹帷幄以获得优势，而不是仅仅依赖传统方法。"},{"sentence":"Although the driver attempted a risky maneuver to overtake the truck, he lost control and caused a serious accident.","translation":"尽管司机试图进行一次危险的机动以超越卡车，但他失去了控制并造成了严重事故。"},{"sentence":"The spacecraft performed a complex maneuver to enter the planet's orbit, which allowed scientists to study its atmosphere.","translation":"航天器执行了一次复杂的机动以进入行星轨道，这使得科学家能够研究其大气层。"},{"sentence":"When negotiating a contract, a skilled lawyer can maneuver through legal loopholes to protect their client's interests.","translation":"在谈判合同时，一位熟练的律师能巧妙地利用法律漏洞来保护客户的利益。"}]},"sponge":{"examples":[{"sentence":"Although a natural sponge appears simple, its intricate canal system efficiently filters bacteria from seawater.","translation":"尽管天然海绵看似简单，但其复杂的管道系统能高效地从海水中过滤细菌。"},{"sentence":"Because the sponge's porous structure provides an ideal habitat, many small marine organisms seek shelter within it.","translation":"由于海绵的多孔结构提供了理想的栖息地，许多小型海洋生物在其中寻求庇护。"},{"sentence":"When scientists studied the deep-sea sponge, they discovered compounds that may lead to new antibiotics.","translation":"当科学家研究深海海绵时，他们发现了可能带来新型抗生素的化合物。"},{"sentence":"The synthetic sponge, which mimics the absorbency of natural species, is used to clean up industrial chemical spills.","translation":"这种模仿天然物种吸收能力的合成海绵，被用于清理工业化学品泄漏。"},{"sentence":"While a sponge lacks true tissues, its specialized cells coordinate to pump water and capture food particles.","translation":"尽管海绵缺乏真正的组织，但其特化细胞协同工作以泵水和捕获食物颗粒。"}]},"solve":{"examples":[{"sentence":"Although the housing crisis is multifaceted, the government can solve it through a combination of subsidies and zoning reforms.","translation":"尽管住房危机是多方面的，但政府可以通过补贴和分区改革的结合来解决它。"},{"sentence":"Because the algorithm processes data in parallel, it can solve complex optimization problems much faster than traditional methods.","translation":"由于该算法并行处理数据，它能比传统方法更快地解决复杂的优化问题。"},{"sentence":"To solve the issue of antibiotic resistance, researchers are exploring phage therapy, which uses viruses to target bacteria.","translation":"为了解决抗生素耐药性问题，研究人员正在探索噬菌体疗法，即利用病毒来靶向细菌。"},{"sentence":"When engineers encountered the bridge's unexpected vibration, they had to solve the problem by installing tuned mass dampers.","translation":"当工程师遇到桥梁的意外振动时，他们不得不通过安装调谐质量阻尼器来解决问题。"},{"sentence":"Rather than applying quick fixes, we must solve the root causes of urban congestion, such as inadequate public transport.","translation":"我们不应采用权宜之计，而必须解决城市拥堵的根本原因，例如公共交通不足。"}]},"ideal":{"examples":[{"sentence":"Although Plato's ideal republic seems utopian, its emphasis on justice continues to inspire modern political theory.","translation":"尽管柏拉图的理想国看似乌托邦，但它对正义的强调继续启发着现代政治理论。"},{"sentence":"Because the ideal of complete equality is unattainable, policymakers should focus on reducing extreme disparities.","translation":"由于完全平等的理想无法实现，政策制定者应专注于减少极端差距。"},{"sentence":"While the ideal work-life balance varies by individual, setting clear boundaries is essential for long-term well-being.","translation":"尽管理想的工作与生活平衡因人而异，但设定明确的界限对长期健康至关重要。"},{"sentence":"The ideal educational system, which fosters creativity and critical thinking, remains a goal for reformers worldwide.","translation":"培养创造力和批判性思维的理想教育体系，仍然是全球改革者的目标。"},{"sentence":"When experimental results fall short of the theoretical ideal, scientists gain insights that drive further innovation.","translation":"当实验结果达不到理论理想值时，科学家会获得推动进一步创新的见解。"}]},"cognitive":{"examples":[{"sentence":"Although cognitive biases can distort our judgment, we can mitigate their effects through deliberate reflection and evidence-based reasoning.","translation":"尽管认知偏差可能扭曲我们的判断，但我们可以通过深思熟虑和基于证据的推理来减轻其影响。"},{"sentence":"Because cognitive development in early childhood lays the foundation for future learning, educators emphasize play-based activities that stimulate curiosity.","translation":"由于儿童早期的认知发展为未来的学习奠定基础，教育工作者强调能够激发好奇心的游戏活动。"},{"sentence":"The study revealed that regular aerobic exercise improves cognitive function, which is particularly beneficial for older adults at risk of dementia.","translation":"研究表明，定期进行有氧运动可以改善认知功能，这对有痴呆风险的老年人尤其有益。"},{"sentence":"While cognitive psychology focuses on internal mental processes, behavioral psychology examines observable actions and their environmental triggers.","translation":"认知心理学关注内部心理过程，而行为心理学则研究可观察的行为及其环境触发因素。"},{"sentence":"To ensure accurate diagnosis, clinicians must assess cognitive impairment using standardized tests rather than relying solely on subjective reports.","translation":"为了确保准确诊断，临床医生必须使用标准化测试评估认知障碍，而不是仅仅依赖主观报告。"}]},"knife":{"examples":[{"sentence":"Although a sharp knife is essential for precise cutting, it requires careful handling to prevent accidents.","translation":"尽管锋利的刀对精确切割至关重要，但需要小心操作以防止事故。"},{"sentence":"The surgeon used a scalpel, which is a specialized knife, to make an incision that would minimize scarring.","translation":"外科医生使用手术刀，这是一种专用刀，以做出能最小化疤痕的切口。"},{"sentence":"Because the chef's knife was dull, he had to apply more pressure, thereby increasing the risk of slipping.","translation":"由于厨师的刀钝了，他不得不施加更大的压力，从而增加了滑刀的风险。"},{"sentence":"When camping, a multi-purpose knife can serve not only as a cutting tool but also as a can opener and screwdriver.","translation":"露营时，一把多功能刀不仅可以作为切割工具，还可以用作开罐器和螺丝刀。"},{"sentence":"The artisan crafted a decorative knife with an intricately carved handle, which reflected the cultural heritage of the region.","translation":"工匠制作了一把装饰刀，手柄雕刻精美，反映了该地区的文化遗产。"}]},"document":{"examples":[{"sentence":"Although the document was marked confidential, it was accidentally circulated to all staff members.","translation":"尽管这份文件被标记为机密，但它意外地被传阅给了所有员工。"},{"sentence":"The lawyer insisted that every clause in the document be reviewed before the signing, which prevented a costly oversight.","translation":"律师坚持在签署前审查文件中的每一项条款，这避免了一个代价高昂的疏忽。"},{"sentence":"Because the historical document was fragile, the archivist used special gloves to handle it.","translation":"由于这份历史文件很脆弱，档案管理员戴了特殊手套来处理它。"},{"sentence":"The team collaborated on the document through a shared platform, thereby reducing version conflicts.","translation":"团队通过共享平台协作处理这份文件，从而减少了版本冲突。"},{"sentence":"If the document is not properly formatted, the automated system will reject it without further review.","translation":"如果文件格式不正确，自动化系统将直接拒绝，不再进一步审查。"}]},"bow":{"examples":[{"sentence":"In Japanese business culture, a slight bow is expected when exchanging business cards, which demonstrates mutual respect.","translation":"在日本商务文化中，交换名片时微微鞠躬是预期的，这体现了相互尊重。"},{"sentence":"Although the bow was made of fiberglass, it performed as well as traditional wooden bows in accuracy tests.","translation":"尽管这把弓是由玻璃纤维制成的，但在精度测试中它的表现与传统木弓一样好。"},{"sentence":"The cellist's bow technique improved dramatically after she practiced slow scales every day, thereby enhancing her overall performance.","translation":"这位大提琴手的运弓技巧在她每天练习慢速音阶后显著提高，从而提升了她的整体演奏水平。"},{"sentence":"When the archer drew the bow, her steady hand and focused gaze ensured a perfect shot.","translation":"当弓箭手拉弓时，她稳定的手和专注的目光确保了一次完美的射击。"},{"sentence":"The performer took a deep bow after the final curtain call, which expressed sincere gratitude to the audience.","translation":"在最后一次谢幕后，表演者深深鞠了一躬，这表达了对观众的诚挚感谢。"}]},"booth":{"examples":[{"sentence":"At the technology expo, the startup's booth attracted a large crowd because it featured an interactive virtual reality demonstration.","translation":"在科技博览会上，这家初创公司的展台吸引了一大群人，因为它展示了互动式虚拟现实演示。"},{"sentence":"The voting booth is designed to ensure privacy, which is essential for maintaining the integrity of the electoral process.","translation":"投票亭旨在确保隐私，这对于维护选举过程的完整性至关重要。"},{"sentence":"Although the library's study booth was small, it provided a quiet space where students could focus without interruptions.","translation":"尽管图书馆的学习间很小，但它提供了一个安静的空间，让学生可以不受干扰地集中注意力。"},{"sentence":"The restaurant's corner booth, with its plush seating and soft lighting, created an intimate atmosphere that was perfect for romantic dinners.","translation":"餐厅角落的卡座配有舒适的座椅和柔和的灯光，营造出私密的氛围，非常适合浪漫晚餐。"},{"sentence":"Travelers can use the self-service check-in booth to print boarding passes, thereby saving time and avoiding long queues at the counter.","translation":"旅客可以使用自助值机亭打印登机牌，从而节省时间并避免在柜台前排长队。"}]},"feeling":{"examples":[{"sentence":"After months of rigorous training, the athlete developed a keen feeling for the rhythm of the race, which allowed her to pace herself perfectly.","translation":"经过数月的严格训练，这位运动员对比赛节奏产生了敏锐的感觉，这使她能够完美地控制自己的速度。"},{"sentence":"The survey results indicated a pervasive feeling of optimism among consumers, which prompted companies to increase their investment in new products.","translation":"调查结果显示消费者普遍存在乐观情绪，这促使企业增加对新产品的投资。"},{"sentence":"Although the evidence seemed conclusive, a lingering feeling of uncertainty led the scientist to conduct additional experiments.","translation":"尽管证据似乎确凿，但一种挥之不去的不确定感促使这位科学家进行了额外的实验。"},{"sentence":"The interior designer used warm colors and soft textures to evoke a feeling of comfort, thereby making the living space more inviting.","translation":"室内设计师使用暖色调和柔软的材料来唤起舒适感，从而使居住空间更加温馨。"},{"sentence":"When she revisited her childhood home, a profound feeling of nostalgia washed over her, reminding her of the simple joys of her youth.","translation":"当她重访童年故居时，一种深刻的怀旧感涌上心头，让她想起了年轻时的简单快乐。"}]},"bacterium":{"examples":[{"sentence":"The bacterium Helicobacter pylori, which can survive in the acidic environment of the stomach, is a major cause of ulcers.","translation":"幽门螺杆菌这种细菌能在胃的酸性环境中生存，是溃疡的主要病因。"},{"sentence":"Because this bacterium is resistant to multiple antibiotics, treating the infection requires a combination of drugs.","translation":"由于这种细菌对多种抗生素耐药，治疗感染需要联合用药。"},{"sentence":"Although the bacterium is typically harmless, it can cause severe illness in individuals with compromised immune systems.","translation":"尽管这种细菌通常无害，但它可能在免疫系统受损的个体中引起严重疾病。"},{"sentence":"Researchers engineered a bacterium to produce insulin, thereby revolutionizing the treatment of diabetes.","translation":"研究人员改造了一种细菌来生产胰岛素，从而彻底改变了糖尿病的治疗方法。"},{"sentence":"When the bacterium enters the bloodstream through a wound, it can lead to a life-threatening condition known as sepsis.","translation":"当这种细菌通过伤口进入血液时，可能导致一种称为脓毒症的危及生命的状况。"}]},"concession":{"examples":[{"sentence":"Although the government made a significant concession by reducing carbon emissions, environmental groups argued that the measures were still insufficient.","translation":"尽管政府通过减少碳排放做出了重大让步，环保组织仍认为这些措施不够充分。"},{"sentence":"The company offered a concession on overtime pay, which helped to avert a prolonged strike that would have disrupted production.","translation":"公司提供了加班费方面的让步，这有助于避免一场会扰乱生产的长期罢工。"},{"sentence":"Because a well-timed concession can build trust during negotiations, diplomats often use it as a strategic tool to reach agreements.","translation":"因为适时的让步能在谈判中建立信任，外交官们常将其作为达成协议的战略工具。"},{"sentence":"The university lowered tuition fees for low-income students, a concession that was necessary to promote educational equity across the campus.","translation":"大学降低了低收入学生的学费，这一让步对于促进校园内的教育公平是必要的。"},{"sentence":"As a concession to local residents, the construction company limited working hours, thereby reducing noise pollution in the neighborhood.","translation":"作为对当地居民的让步，建筑公司限制了工作时间，从而减少了社区的噪音污染。"}]},"refund":{"examples":[{"sentence":"Customers who are dissatisfied with the product can request a full refund within 30 days, which ensures consumer protection.","translation":"对产品不满意的顾客可以在30天内要求全额退款，这确保了消费者保护。"},{"sentence":"The university issued a partial refund to students because campus facilities were closed due to unexpected maintenance work.","translation":"大学向学生发放了部分退款，因为校园设施因意外维修工作而关闭。"},{"sentence":"To maintain consumer trust, the company promised a prompt refund for any defective items, provided that they are returned with a receipt.","translation":"为了维护消费者信任，该公司承诺对任何有缺陷的商品迅速退款，前提是凭收据退回。"},{"sentence":"Although the conference was canceled at the last minute, the organizers provided a full refund to all registered participants, which mitigated their disappointment.","translation":"尽管会议在最后一刻被取消，组织者仍向所有注册参与者提供了全额退款，这减轻了他们的失望。"},{"sentence":"The tax refund system is designed to reimburse individuals who have overpaid their income taxes, thereby correcting fiscal imbalances.","translation":"退税制度旨在偿还那些多缴个人所得税的个人，从而纠正财政失衡。"}]},"chase":{"examples":[{"sentence":"Although the chase for material wealth can bring temporary satisfaction, it often fails to provide lasting happiness.","translation":"虽然对物质财富的追求能带来暂时的满足，但它往往无法提供持久的幸福。"},{"sentence":"The documentary highlights the dramatic chase between predator and prey, which illustrates the harsh realities of nature.","translation":"这部纪录片突出了捕食者与猎物之间的戏剧性追逐，这说明了自然的残酷现实。"},{"sentence":"Because the police chase endangered public safety, the officers decided to call it off after a brief pursuit.","translation":"因为警方的追逐危及公共安全，警官们在短暂追捕后决定取消行动。"},{"sentence":"His relentless chase of perfection in every project, while admirable, sometimes leads to unnecessary delays.","translation":"他对每个项目完美的不懈追求虽然令人钦佩，但有时会导致不必要的延误。"},{"sentence":"When the chase for innovation becomes the sole focus, companies may overlook the importance of ethical considerations.","translation":"当对创新的追求成为唯一焦点时，公司可能会忽视道德考量的重要性。"}]},"eve":{"examples":[{"sentence":"On the eve of the examination, students often review key concepts to ensure they are well-prepared for the test.","translation":"考试前夕，学生们经常复习关键概念，以确保他们为考试做好充分准备。"},{"sentence":"Because the eve of the festival is a time for family reunions, many people travel long distances to be with their loved ones.","translation":"因为节日前夕是家庭团聚的时刻，许多人长途跋涉与亲人相聚。"},{"sentence":"The eve of the conference was marked by intense preparation, which included finalizing the agenda and setting up the venue.","translation":"会议前夕的特点是紧张的准备工作，其中包括敲定议程和布置场地。"},{"sentence":"While the eve of a new policy often brings uncertainty, it also offers an opportunity for stakeholders to voice their concerns.","translation":"虽然新政策前夕常常带来不确定性，但它也为利益相关者提供了表达关切的机会。"},{"sentence":"On the eve of the launch, the team worked tirelessly to ensure that all systems were functioning correctly.","translation":"发布前夕，团队不知疲倦地工作，以确保所有系统正常运行。"}]},"lately":{"examples":[{"sentence":"Although the company has launched several new products lately, its market share has not increased as expected.","translation":"尽管该公司近来推出了几款新产品，但其市场份额并未如预期增长。"},{"sentence":"Because the research team has focused on artificial intelligence lately, they have made breakthroughs in natural language processing.","translation":"由于研究团队近来专注于人工智能，他们在自然语言处理方面取得了突破。"},{"sentence":"Lately, many governments have implemented stricter environmental regulations, which aim to reduce carbon emissions significantly.","translation":"近来，许多政府实施了更严格的环境法规，旨在显著减少碳排放。"},{"sentence":"While the economy has shown signs of recovery lately, unemployment rates remain stubbornly high in certain sectors.","translation":"尽管近来经济显示出复苏迹象，但某些行业的失业率仍然居高不下。"},{"sentence":"The professor has been emphasizing the importance of critical thinking lately, which encourages students to question established theories.","translation":"教授近来一直强调批判性思维的重要性，这鼓励学生质疑既有理论。"}]},"trousers":{"examples":[{"sentence":"Because the company's dress code requires formal attire, employees must wear tailored trousers rather than casual jeans.","translation":"由于公司的着装要求正式服装，员工必须穿着剪裁合体的长裤，而不是休闲牛仔裤。"},{"sentence":"Although the traditional uniform included a skirt, the school now allows female students to wear trousers, which promotes greater comfort and equality.","translation":"尽管传统校服包括裙子，但学校现在允许女生穿长裤，这促进了更大的舒适性和平等。"},{"sentence":"When hiking in rough terrain, it is advisable to wear durable trousers that can withstand abrasion and protect against insects.","translation":"在崎岖地形徒步时，建议穿着耐用的长裤，能够承受磨损并防止昆虫叮咬。"},{"sentence":"The fashion industry has recently seen a resurgence of wide-legged trousers, which offer a stylish alternative to skinny fits.","translation":"时尚界近来见证了阔腿裤的复兴，这为紧身款式提供了时尚的替代选择。"},{"sentence":"In many cultures, wearing trousers is a symbol of modernity, whereas traditional garments like robes are reserved for ceremonies.","translation":"在许多文化中，穿长裤是现代性的象征，而长袍等传统服装则保留用于仪式。"}]},"heavy":{"examples":[{"sentence":"Because of the heavy traffic during rush hour, commuters often spend twice as long on the road, which leads to increased stress and reduced productivity.","translation":"由于高峰时段的交通拥堵，通勤者通常在路上花费两倍的时间，这导致压力增加和生产力下降。"},{"sentence":"Although the heavy workload seemed overwhelming at first, the team managed to complete the project on time by delegating tasks effectively.","translation":"尽管起初繁重的工作量似乎难以承受，但团队通过有效分配任务，按时完成了项目。"},{"sentence":"The heavy reliance on fossil fuels has contributed to climate change, which is why many countries are investing in renewable energy sources.","translation":"对化石燃料的严重依赖导致了气候变化，这就是为什么许多国家正在投资可再生能源。"},{"sentence":"When lifting heavy objects, it is crucial to use proper technique to avoid back injuries, which can have long-term consequences.","translation":"提起重物时，使用正确技巧以避免背部受伤至关重要，这可能会产生长期后果。"},{"sentence":"The heavy rainfall over the weekend caused widespread flooding, which disrupted transportation and damaged crops in the region.","translation":"周末的强降雨导致大面积洪水，扰乱了交通并损害了该地区的农作物。"}]},"session":{"examples":[{"sentence":"Although the morning session was devoted to lectures, the afternoon session allowed participants to engage in hands-on workshops.","translation":"尽管上午的会议专门用于讲座，但下午的会议让参与者能够参与实践工作坊。"},{"sentence":"The training session, which focused on conflict resolution, equipped managers with practical strategies to handle workplace disputes.","translation":"这次专注于冲突解决的培训课程为管理者提供了处理职场纠纷的实用策略。"},{"sentence":"Because the court session involved sensitive testimony, the judge ordered the courtroom to be cleared of all spectators.","translation":"由于开庭涉及敏感证词，法官命令清空法庭内的所有旁听者。"},{"sentence":"The professor scheduled an extra review session before the final exam to ensure that students could clarify any remaining doubts.","translation":"教授在期末考试前安排了一次额外的复习课，以确保学生能够澄清任何遗留的疑问。"},{"sentence":"While the negotiation session was initially deadlocked, a breakthrough came when both sides agreed to a temporary ceasefire.","translation":"尽管谈判会议最初陷入僵局，但当双方同意临时停火时，出现了突破。"}]},"sole":{"examples":[{"sentence":"Although she was the sole candidate with international experience, the selection committee prioritized local expertise.","translation":"尽管她是唯一拥有国际经验的候选人，但选拔委员会优先考虑了本地专业知识。"},{"sentence":"The sole purpose of this policy is to reduce carbon emissions, thereby mitigating the effects of climate change.","translation":"这项政策的唯一目的是减少碳排放，从而缓解气候变化的影响。"},{"sentence":"Because he was the sole heir to the family business, he felt a strong obligation to preserve its legacy.","translation":"因为他是家族企业的唯一继承人，他感到有强烈的义务去维护其遗产。"},{"sentence":"The researcher argued that poverty is not the sole determinant of educational outcomes, as parental involvement also plays a crucial role.","translation":"研究人员认为，贫困并不是教育成果的唯一决定因素，因为父母的参与也起着关键作用。"},{"sentence":"When the sole of the hiking boot wore out, the experienced mountaineer replaced it rather than buying a new pair.","translation":"当登山靴的鞋底磨损时，这位经验丰富的登山者更换了鞋底，而不是买一双新的。"}]},"exam":{"examples":[{"sentence":"Because the final exam accounts for a significant portion of the grade, students must review consistently throughout the term.","translation":"由于期末考试占成绩的很大一部分，学生必须在整个学期中持续复习。"},{"sentence":"Although standardized exam scores are often used for university admission, they do not fully reflect a student's creativity.","translation":"尽管标准化考试成绩常被用于大学录取，但它们并不能完全反映学生的创造力。"},{"sentence":"The teacher designed the exam to assess not only factual recall but also the ability to apply concepts to new situations.","translation":"老师设计这场考试不仅是为了考查事实记忆，也是为了评估将概念应用于新情境的能力。"},{"sentence":"After failing the entrance exam, she adopted a more structured study plan, which ultimately led to her success the following year.","translation":"入学考试失败后，她采用了更有条理的学习计划，这最终使她在第二年取得了成功。"},{"sentence":"The national college entrance exam, which is known as Gaokao, is widely regarded as a turning point in a Chinese student's life.","translation":"全国大学入学考试，即高考，被普遍视为中国学生人生的转折点。"}]},"grasp":{"examples":[{"sentence":"A firm grasp of statistical methods is essential for conducting rigorous research, which can lead to more reliable conclusions.","translation":"扎实掌握统计方法对于开展严谨的研究至关重要，这可以得出更可靠的结论。"},{"sentence":"Although the concept is abstract, students can develop a solid grasp of it through hands-on experiments and case studies.","translation":"尽管这个概念很抽象，但学生通过动手实验和案例研究可以扎实掌握它。"},{"sentence":"Her exceptional grasp of cross-cultural communication enabled her to negotiate effectively, thereby securing a lucrative deal.","translation":"她对跨文化沟通的出色把握使她能够有效谈判，从而获得了一笔利润丰厚的交易。"},{"sentence":"The report demonstrates a thorough grasp of the economic factors that influence urban development, which is crucial for policymakers.","translation":"该报告显示出对影响城市发展的经济因素的透彻理解，这对政策制定者至关重要。"},{"sentence":"To succeed in the digital age, professionals must have a comprehensive grasp of emerging technologies, rather than relying solely on traditional skills.","translation":"要在数字时代取得成功，专业人士必须全面掌握新兴技术，而不是仅仅依赖传统技能。"}]},"growth":{"examples":[{"sentence":"Although economic growth is essential for national prosperity, it must be balanced with environmental sustainability to ensure long-term well-being.","translation":"尽管经济增长对国家繁荣至关重要，但必须与环境可持续性相平衡，以确保长期福祉。"},{"sentence":"The rapid growth of online education, which accelerated during the pandemic, has transformed traditional learning paradigms.","translation":"在线教育的快速增长在疫情期间加速，已经改变了传统的学习模式。"},{"sentence":"Because population growth in urban areas strains infrastructure, governments must invest in smart city technologies.","translation":"由于城市地区的人口增长给基础设施带来压力，政府必须投资于智慧城市技术。"},{"sentence":"Personal growth often occurs when individuals step outside their comfort zones, thereby developing resilience and new skills.","translation":"个人成长往往发生在个体走出舒适区时，从而培养韧性和新技能。"},{"sentence":"While the company's growth strategy focuses on emerging markets, it also prioritizes sustainable practices to maintain its reputation.","translation":"虽然公司的增长战略侧重于新兴市场，但它也优先考虑可持续实践以维护其声誉。"}]},"thermometer":{"examples":[{"sentence":"Because the thermometer recorded a sudden drop in temperature, the researchers halted the experiment to prevent equipment damage.","translation":"由于温度计记录到温度突然下降，研究人员停止了实验以防止设备损坏。"},{"sentence":"A digital thermometer, which provides instant readings, is more convenient than a traditional mercury thermometer for home use.","translation":"数字温度计能提供即时读数，比传统水银温度计更适合家庭使用。"},{"sentence":"When the nurse used a thermometer to check the patient's fever, she discovered that the temperature was dangerously high.","translation":"当护士用体温计检查病人的发烧情况时，她发现体温高得危险。"},{"sentence":"In food safety, a calibrated thermometer is indispensable to ensure that meat reaches the required internal temperature.","translation":"在食品安全中，校准过的温度计对于确保肉类达到所需的内部温度是不可或缺的。"},{"sentence":"Although the thermometer is a simple device, its invention revolutionized medicine by enabling accurate diagnosis of fevers.","translation":"尽管温度计是一个简单的设备，但它的发明通过实现发烧的准确诊断而彻底改变了医学。"}]},"neither":{"examples":[{"sentence":"Although neither candidate fully addressed the economic concerns, the debate still clarified their policy differences.","translation":"尽管两位候选人都没有完全解决经济问题，但辩论仍然澄清了他们的政策差异。"},{"sentence":"Because neither the original plan nor the alternative proposal was feasible, the committee decided to postpone the project.","translation":"由于原计划和替代方案都不可行，委员会决定推迟该项目。"},{"sentence":"Neither the rapid advancement of technology nor the increase in funding has eliminated educational inequality, which remains a persistent issue.","translation":"技术的快速进步和资金的增加都没有消除教育不平等，这仍然是一个持续存在的问题。"},{"sentence":"When neither party is willing to accept responsibility, conflicts tend to escalate rather than resolve.","translation":"当双方都不愿意承担责任时，冲突往往会升级而不是解决。"},{"sentence":"The research indicates that neither diet nor exercise alone can guarantee long-term health, thereby emphasizing the need for a holistic approach.","translation":"研究表明，单靠饮食或运动都不能保证长期健康，从而强调了整体方法的必要性。"}]},"inland":{"examples":[{"sentence":"Inland cities, which often lack direct access to seaports, must rely on efficient rail and road networks to facilitate trade.","translation":"内陆城市通常缺乏直达海港的通道，必须依赖高效的铁路和公路网络来促进贸易。"},{"sentence":"Because inland areas are more susceptible to extreme temperature fluctuations, farmers there need to adopt climate-resilient crops.","translation":"由于内陆地区更容易受到极端温度波动的影响，那里的农民需要采用适应气候的作物。"},{"sentence":"The government is promoting inland tourism to diversify the economy, rather than relying solely on coastal attractions.","translation":"政府正在推广内陆旅游以实现经济多元化，而不是仅仅依赖沿海景点。"},{"sentence":"While inland waterways offer a cost-effective transport option, their development requires substantial investment in dredging and locks.","translation":"虽然内陆水道提供了一种经济高效的运输选择，但其发展需要对疏浚和船闸进行大量投资。"},{"sentence":"Inland regions, despite their rich natural resources, often struggle with depopulation as young people migrate to coastal cities for better opportunities.","translation":"内陆地区尽管拥有丰富的自然资源，但由于年轻人为了更好的机会迁移到沿海城市，往往面临人口减少的问题。"}]},"colonial":{"examples":[{"sentence":"Although the colonial era ended decades ago, its economic legacy continues to shape trade patterns in many developing nations.","translation":"尽管殖民时代几十年前就结束了，但其经济遗产仍在影响许多发展中国家的贸易模式。"},{"sentence":"Because colonial powers often suppressed local industries, newly independent countries faced significant challenges when building self-sufficient economies.","translation":"由于殖民列强经常压制当地工业，新独立的国家在建立自给自足的经济时面临重大挑战。"},{"sentence":"While colonial architecture attracts tourists, it also serves as a reminder of a painful history that many communities prefer not to revisit.","translation":"虽然殖民建筑吸引游客，但它也提醒着许多社区不愿重温的痛苦历史。"},{"sentence":"If historians fail to examine colonial narratives critically, they risk perpetuating biased perspectives that obscure the experiences of indigenous peoples.","translation":"如果历史学家未能批判性地审视殖民叙事，他们就有可能延续掩盖原住民经历的偏见观点。"},{"sentence":"The colonial administration implemented policies that prioritized resource extraction, thereby hindering long-term sustainable development in the region.","translation":"殖民政府实施了优先资源开采的政策，从而阻碍了该地区的长期可持续发展。"}]},"roar":{"examples":[{"sentence":"Although the lion's roar is often associated with aggression, it primarily serves to communicate territorial boundaries to other prides.","translation":"尽管狮子的吼声常与攻击性联系在一起，但它主要用于向其他狮群传达领地边界。"},{"sentence":"Because the roar of the waterfall was so deafening, the researchers had to use hand signals to coordinate their data collection efforts.","translation":"由于瀑布的轰鸣声震耳欲聋，研究人员不得不使用手势来协调数据收集工作。"},{"sentence":"When the crowd's roar erupted after the final whistle, it was clear that the underdog team had achieved an unexpected victory.","translation":"当终场哨响后人群爆发出欢呼声时，很明显这支不被看好的队伍取得了意外的胜利。"},{"sentence":"The stock market's roar during the tech boom was driven by speculative investments, which ultimately led to a severe economic downturn.","translation":"科技繁荣时期股市的喧嚣是由投机性投资推动的，这最终导致了严重的经济衰退。"},{"sentence":"Without the constant roar of traffic, residents of the newly pedestrianized zone reported significantly lower stress levels and better sleep quality.","translation":"没有了持续不断的交通轰鸣声，新步行区的居民报告称压力水平显著降低，睡眠质量更好。"}]},"good":{"examples":[{"sentence":"Although individual success is often celebrated, the greater good of society depends on collective efforts to address systemic inequalities.","translation":"尽管个人成功常被颂扬，但社会的更大利益取决于解决系统性不平等的集体努力。"},{"sentence":"Because the new policy prioritizes the common good over corporate profits, it has garnered widespread support from environmental groups.","translation":"由于新政策将公共利益置于企业利润之上，它获得了环保团体的广泛支持。"},{"sentence":"While donating to charity is an act of personal good, it cannot replace the need for structural changes that ensure equitable resource distribution.","translation":"虽然慈善捐赠是一种个人善行，但它不能取代确保资源公平分配的结构性变革的需要。"},{"sentence":"If leaders fail to consider the long-term good of their decisions, they may achieve short-term gains at the expense of future generations.","translation":"如果领导者未能考虑其决策的长期利益，他们可能会以牺牲后代为代价来获取短期收益。"},{"sentence":"The organization's mission is to harness technology for the good of humanity, thereby addressing challenges such as climate change and healthcare access.","translation":"该组织的使命是利用技术为人类谋福利，从而应对气候变化和医疗保健可及性等挑战。"}]},"helmet":{"examples":[{"sentence":"Because the construction site was full of hazards, every worker was required to wear a helmet at all times.","translation":"因为建筑工地充满危险，所以每位工人都被要求始终佩戴安全帽。"},{"sentence":"Although the helmet appeared undamaged after the crash, the cyclist replaced it to ensure continued protection.","translation":"尽管头盔在碰撞后看起来没有损坏，但骑车人还是更换了它，以确保持续的保护。"},{"sentence":"The new law mandates that all motorcyclists wear a helmet, which has significantly reduced fatalities.","translation":"新法律规定所有摩托车手必须佩戴头盔，这已显著降低了死亡人数。"},{"sentence":"When participating in contact sports, athletes should wear a helmet that meets international safety standards.","translation":"参加接触性运动时，运动员应佩戴符合国际安全标准的头盔。"},{"sentence":"Research shows that wearing a helmet can prevent severe head injuries, thereby saving lives in accidents.","translation":"研究表明，佩戴头盔可以防止严重的头部受伤，从而在事故中挽救生命。"}]},"please":{"examples":[{"sentence":"To ensure your application is processed promptly, please submit all required documents by the specified deadline.","translation":"为确保您的申请得到及时处理，请在指定截止日期前提交所有必需文件。"},{"sentence":"If you encounter any technical issues during the online exam, please contact the support team immediately.","translation":"如果您在在线考试中遇到任何技术问题，请立即联系支持团队。"},{"sentence":"Please note that the library will be closed for renovation, which means all borrowed books must be returned beforehand.","translation":"请注意，图书馆将因翻修而关闭，这意味着所有借出的书籍必须提前归还。"},{"sentence":"Because the conference room has limited capacity, please register early to secure your seat.","translation":"因为会议室容量有限，请尽早注册以确保您的座位。"},{"sentence":"While we appreciate your feedback, please direct all formal complaints through the official channel.","translation":"虽然我们感谢您的反馈，但请通过官方渠道提出所有正式投诉。"}]},"sharp":{"examples":[{"sentence":"Although the knife was sharp, it required careful handling to avoid accidents.","translation":"尽管这把刀很锋利，但需要小心使用以避免事故。"},{"sentence":"The sharp decline in stock prices caused widespread panic among investors, which led to a market crash.","translation":"股票价格的急剧下跌引起了投资者的普遍恐慌，进而导致市场崩盘。"},{"sentence":"Because her sharp mind allowed her to solve complex problems quickly, she was promoted to lead the research team.","translation":"因为她敏锐的头脑能快速解决复杂问题，她被提升为研究团队的负责人。"},{"sentence":"The teacher's sharp tone when correcting the student's mistake made the entire class uneasy.","translation":"老师纠正学生错误时的尖刻语气让全班都感到不安。"},{"sentence":"If you arrive at 8 sharp, you will have enough time to prepare for the meeting.","translation":"如果你八点整到达，你将有足够的时间为会议做准备。"}]},"token":{"examples":[{"sentence":"Although the scholarship was only a token amount, it symbolized the foundation's belief in her potential.","translation":"虽然奖学金只是象征性的金额，但它象征着基金会对她潜力的信任。"},{"sentence":"The company offered a token discount to loyal customers, which did little to offset the recent price increases.","translation":"公司为忠实客户提供了象征性的折扣，但这几乎无法抵消近期的价格上涨。"},{"sentence":"As a token of gratitude, the community planted a tree in the park, thereby creating a lasting memorial.","translation":"作为感谢的象征，社区在公园里种了一棵树，从而创造了一个持久的纪念。"},{"sentence":"The government's token gesture of reducing a minor tax, while ignoring systemic issues, was criticized as inadequate.","translation":"政府象征性地减少了一项小额税收，却忽视了系统性问题，因此被批评为不够充分。"},{"sentence":"He gave her a locket as a token of his affection, which she treasured despite their eventual separation.","translation":"他送给她一个挂坠盒作为爱意的象征，尽管他们最终分开了，她仍珍藏着它。"}]},"freeze":{"examples":[{"sentence":"When the temperature drops below zero, the water in the pipes can freeze, causing them to burst.","translation":"当温度降到零度以下时，管道中的水会结冰，导致管道爆裂。"},{"sentence":"Although the company planned to expand, the board decided to freeze all new hiring until the economic outlook improves.","translation":"尽管公司计划扩张，董事会决定冻结所有新招聘，直到经济前景好转。"},{"sentence":"Because the computer system crashed, the technician had to freeze the server to prevent data loss.","translation":"由于计算机系统崩溃，技术人员不得不冻结服务器以防止数据丢失。"},{"sentence":"If you want to preserve fresh vegetables for a longer period, you should freeze them immediately after harvesting.","translation":"如果你想更长时间地保存新鲜蔬菜，你应该在收获后立即将其冷冻。"},{"sentence":"While hiking in the mountains, we encountered a sudden blizzard that made us freeze in our tracks.","translation":"在山上徒步旅行时，我们遇到了一场突如其来的暴风雪，让我们呆立原地。"}]},"worldwide":{"examples":[{"sentence":"Although the pandemic caused severe disruptions, it also accelerated the worldwide adoption of remote work technologies.","translation":"尽管疫情造成了严重破坏，但它也加速了全球范围内远程工作技术的采用。"},{"sentence":"Because the internet enables instant communication, businesses can now reach a worldwide audience with minimal cost.","translation":"由于互联网实现了即时通信，企业现在可以以最低的成本接触到全球受众。"},{"sentence":"The worldwide decline in biodiversity is a pressing issue that requires immediate international cooperation.","translation":"全球生物多样性的下降是一个紧迫的问题，需要立即开展国际合作。"},{"sentence":"When the film was released, it achieved worldwide acclaim, breaking box office records in multiple countries.","translation":"当这部电影上映时，它获得了全球赞誉，在多个国家打破了票房纪录。"},{"sentence":"Despite cultural differences, the Olympic Games promote worldwide unity through the spirit of friendly competition.","translation":"尽管存在文化差异，奥运会通过友好竞争的精神促进了全球团结。"}]},"function":{"examples":[{"sentence":"Although the primary function of education is to impart knowledge, it also plays a crucial role in shaping character.","translation":"虽然教育的首要功能是传授知识，但它在塑造品格方面也起着至关重要的作用。"},{"sentence":"The human brain cannot function properly without adequate sleep, which impairs cognitive abilities and decision-making.","translation":"没有充足的睡眠，人脑无法正常运作，这会损害认知能力和决策。"},{"sentence":"Because the new software can function on multiple platforms, it has gained widespread popularity among users.","translation":"由于新软件可以在多个平台上运行，它在用户中获得了广泛的欢迎。"},{"sentence":"The function of this committee is to oversee the implementation of policies, thereby ensuring accountability and transparency.","translation":"该委员会的职能是监督政策的执行，从而确保问责制和透明度。"},{"sentence":"When a government fails to perform its basic function of maintaining public order, social unrest often ensues.","translation":"当政府未能履行其维持公共秩序的基本职能时，社会动荡往往随之而来。"}]},"amid":{"examples":[{"sentence":"Although the negotiations were tense, the diplomats reached a consensus amid growing international pressure.","translation":"尽管谈判紧张，但在日益增长的国际压力下，外交官们达成了共识。"},{"sentence":"The startup secured funding amid a recession, because its innovative model promised long-term growth.","translation":"这家初创公司在经济衰退期间获得了资金，因为其创新模式承诺了长期增长。"},{"sentence":"While the city was in chaos, the hospital continued to operate efficiently amid the power outage.","translation":"当城市陷入混乱时，医院在停电期间继续高效运作。"},{"sentence":"The researcher maintained her composure amid harsh criticism, which ultimately strengthened her argument.","translation":"这位研究人员在严厉批评中保持冷静，这最终加强了她的论点。"},{"sentence":"Amid the rapid digital transformation, companies that fail to adapt risk losing their competitive edge.","translation":"在快速数字化转型中，未能适应的公司有失去竞争优势的风险。"}]},"nervous":{"examples":[{"sentence":"Although she had rehearsed the speech multiple times, she still felt nervous when she saw the large audience.","translation":"尽管她多次排练了演讲，但看到众多观众时她仍然感到紧张。"},{"sentence":"Because the exam results would determine his scholarship, he grew increasingly nervous as the release date approached.","translation":"由于考试成绩将决定他的奖学金，随着公布日期临近，他变得越来越紧张。"},{"sentence":"The candidate, who was nervous about the panel interview, prepared thoroughly to ensure she could answer every question confidently.","translation":"这位对小组面试感到紧张的候选人做了充分准备，以确保能自信地回答每个问题。"},{"sentence":"While waiting for the medical test results, the patient became nervous, which is a common reaction to uncertainty.","translation":"在等待医学检查结果时，病人变得紧张，这是对不确定性的常见反应。"},{"sentence":"If you are nervous about networking events, you can start by attending smaller gatherings to build your confidence gradually.","translation":"如果你对社交活动感到紧张，可以从小型聚会开始，逐步建立自信。"}]},"porcelain":{"examples":[{"sentence":"Because porcelain is fired at extremely high temperatures, it becomes non-porous and resistant to stains, which makes it ideal for tableware.","translation":"由于瓷器在极高温度下烧制，它变得无孔且耐污，这使其成为餐具的理想选择。"},{"sentence":"The antique porcelain vase, which was crafted during the Qing dynasty, fetched a record price at the auction due to its rarity.","translation":"这件清代制作的古董瓷瓶因其稀有性在拍卖会上拍出了创纪录的价格。"},{"sentence":"Although porcelain is often associated with delicate art, it is also used in industrial applications such as electrical insulators.","translation":"尽管瓷器常与精美艺术联系在一起，但它也用于工业应用，如电绝缘体。"},{"sentence":"The restoration expert carefully repaired the cracked porcelain figurine, ensuring that the original glaze was matched perfectly.","translation":"修复专家小心地修复了破裂的瓷俑，确保与原釉完美匹配。"},{"sentence":"When selecting porcelain tiles for the kitchen, homeowners should consider both durability and aesthetic appeal to ensure long-term satisfaction.","translation":"在为厨房选择瓷砖时，房主应考虑耐用性和美观性，以确保长期满意。"}]},"nasty":{"examples":[{"sentence":"Because the nasty weather delayed all flights, the passengers had to spend the night at the airport, which caused widespread frustration.","translation":"由于恶劣的天气延误了所有航班，乘客不得不在机场过夜，这引起了普遍的不满。"},{"sentence":"The journalist exposed the company's nasty practices, which included exploiting workers and polluting the environment.","translation":"记者揭露了该公司的恶劣行径，包括剥削工人和污染环境。"},{"sentence":"Although the medicine had a nasty taste, the child took it without complaint because she understood it would help her recover.","translation":"尽管药味难闻，孩子还是毫无怨言地服用了，因为她明白这有助于康复。"},{"sentence":"The nasty cut on his hand required stitches, but the doctor assured him that it would heal completely within two weeks.","translation":"他手上严重的割伤需要缝合，但医生向他保证两周内会完全愈合。"},{"sentence":"When the negotiation turned nasty, the mediator intervened to ensure that both parties could reach a fair agreement.","translation":"当谈判变得激烈时，调解人介入以确保双方能达成公平协议。"}]},"roll":{"examples":[{"sentence":"Although the teacher called the roll every morning, some students still managed to arrive late without being noticed.","translation":"尽管老师每天早上点名，但有些学生仍然设法迟到而不被发现。"},{"sentence":"The ancient roll of parchment, which was discovered in a hidden cave, contained detailed records of early trade routes.","translation":"在隐蔽洞穴中发现的那卷古老羊皮纸，详细记载了早期贸易路线。"},{"sentence":"Because the slow roll of the waves created a soothing rhythm, she often sat by the shore to clear her mind.","translation":"因为海浪缓慢的滚动形成了一种舒缓的节奏，她经常坐在岸边理清思绪。"},{"sentence":"The company maintained a detailed roll of all employees, thereby ensuring that work histories could be verified quickly.","translation":"公司保存了所有员工的详细名册，从而确保工作经历能够迅速核实。"},{"sentence":"When the baker prepared a fresh roll of dough each morning, the bread remained soft and flavorful throughout the day.","translation":"当面包师每天早上准备一卷新鲜面团时，面包全天都保持柔软可口。"}]},"permit":{"examples":[{"sentence":"The construction company obtained a building permit before starting work, which ensured compliance with local regulations.","translation":"建筑公司在开工前获得了建筑许可证，这确保了符合当地法规。"},{"sentence":"Without a valid work permit, international students are often restricted in the number of hours they can be employed.","translation":"没有有效的工作许可证，国际学生通常在工作时间上受到限制。"},{"sentence":"The environmental agency issued a permit that allowed the factory to discharge treated water, provided that strict conditions were met.","translation":"环保机构签发了一份许可证，允许工厂排放处理过的水，前提是满足严格条件。"},{"sentence":"Because researchers must apply for a special permit to conduct experiments in the reserve, the application process is highly competitive.","translation":"由于研究人员必须申请特别许可证才能在保护区进行实验，申请过程竞争非常激烈。"},{"sentence":"The city council decided to revoke the vendor's permit after repeated violations, thereby setting a precedent for future cases.","translation":"市议会决定在多次违规后吊销该商贩的许可证，从而为未来案例树立了先例。"}]},"loyalty":{"examples":[{"sentence":"Employee loyalty often increases when companies invest in professional development, which in turn reduces turnover rates.","translation":"当公司投资于职业发展时，员工忠诚度通常会提高，这反过来又降低了离职率。"},{"sentence":"The long-standing loyalty between the two nations was strengthened by decades of cultural exchange, thereby fostering mutual trust.","translation":"两国之间长期的忠诚通过数十年的文化交流得到加强，从而增进了相互信任。"},{"sentence":"Although the organization faced severe criticism, the loyalty of its core members never wavered, which helped it survive the crisis.","translation":"尽管该组织面临严厉批评，但其核心成员的忠诚从未动摇，这帮助它度过了危机。"},{"sentence":"In academic collaborations, loyalty to shared research goals can be more important than individual recognition, because it ensures long-term progress.","translation":"在学术合作中，对共同研究目标的忠诚可能比个人认可更为重要，因为它确保了长期进展。"},{"sentence":"Customer loyalty programs are designed to reward repeat purchases, but they also provide valuable data that can improve marketing strategies.","translation":"客户忠诚度计划旨在奖励重复购买，但它们也提供了可以改进营销策略的宝贵数据。"}]},"finding":{"examples":[{"sentence":"The committee's finding that the policy had exacerbated inequality prompted a thorough review of its implementation.","translation":"委员会发现该政策加剧了不平等，这促使对其执行情况进行了彻底审查。"},{"sentence":"Although the initial finding was promising, subsequent experiments failed to replicate the same results.","translation":"尽管最初的发现很有希望，但随后的实验未能复现相同的结果。"},{"sentence":"Researchers published their finding that regular exercise significantly improves cognitive function in older adults.","translation":"研究人员发表了他们的发现，即定期锻炼能显著改善老年人的认知功能。"},{"sentence":"The court's finding that the company had violated environmental regulations led to substantial fines.","translation":"法院裁定该公司违反了环境法规，导致其被处以巨额罚款。"},{"sentence":"Because the finding was based on a small sample size, the authors called for further investigation to confirm its validity.","translation":"由于该发现基于小样本量，作者呼吁进一步研究以确认其有效性。"}]},"giggle":{"examples":[{"sentence":"When the professor made an unintentional pun, a few students began to giggle quietly in the back row.","translation":"当教授无意中说了一个双关语时，后排有几个学生开始轻声咯咯地笑。"},{"sentence":"Although the situation was serious, she could not help but giggle at the absurdity of the argument.","translation":"尽管情况很严重，但她还是忍不住对这场争论的荒谬之处咯咯地笑。"},{"sentence":"The children would often giggle during the science demonstration, which distracted the presenter.","translation":"孩子们经常在科学演示时咯咯地笑，这分散了演示者的注意力。"},{"sentence":"Because the joke was so unexpected, the entire audience started to giggle in unison.","translation":"因为笑话太出乎意料，整个观众都齐声咯咯地笑起来。"},{"sentence":"She tried to suppress a giggle when she noticed the typo in the official document.","translation":"当她注意到官方文件中的错字时，她试图忍住咯咯的笑。"}]},"till":{"examples":[{"sentence":"Although the deadline was extended, we continued working till midnight to ensure the project's quality.","translation":"尽管截止日期延长了，但我们还是继续工作到午夜，以确保项目的质量。"},{"sentence":"The new regulation will not be enforced till the beginning of next year, which gives companies time to adapt.","translation":"新规定要到明年年初才会执行，这给了公司适应的时间。"},{"sentence":"Because the experiment required continuous monitoring, the researchers stayed in the lab till dawn.","translation":"由于实验需要持续监测，研究人员在实验室里一直待到天亮。"},{"sentence":"She postponed her decision till she had gathered sufficient evidence, thereby avoiding a hasty conclusion.","translation":"她推迟决定，直到收集到足够的证据，从而避免了草率的结论。"},{"sentence":"The scholarship application remains open till the end of March, when all submissions will be reviewed.","translation":"奖学金申请一直开放到三月底，届时所有提交的材料都将被审核。"}]},"ability":{"examples":[{"sentence":"Although she has a natural ability for languages, she still practices every day to maintain fluency.","translation":"尽管她天生具有语言能力，但她仍然每天练习以保持流利度。"},{"sentence":"Because the ability to think critically is essential in academia, universities emphasize it in their curricula.","translation":"因为批判性思考的能力在学术界至关重要，所以大学在课程中强调这一点。"},{"sentence":"When students develop the ability to manage their time effectively, they often achieve better academic results.","translation":"当学生培养出有效管理时间的能力时，他们通常会取得更好的学业成绩。"},{"sentence":"The scholarship is awarded to those who demonstrate exceptional ability, which includes both academic and leadership skills.","translation":"奖学金授予那些表现出卓越能力的人，这包括学术和领导技能。"},{"sentence":"A leader's true ability is revealed not only during crises but also in daily decision-making.","translation":"领导者的真正能力不仅在危机期间显现，在日常决策中也会显露。"}]},"plus":{"examples":[{"sentence":"Although the base salary is modest, the benefits package plus bonuses make the job attractive.","translation":"虽然基本工资不高，但福利待遇加上奖金使这份工作很有吸引力。"},{"sentence":"Because the project requires technical expertise plus creative thinking, we need a diverse team.","translation":"因为这个项目需要技术专长加上创造性思维，我们需要一个多元化的团队。"},{"sentence":"When you consider the cost of tuition plus living expenses, studying abroad can be expensive.","translation":"当你考虑到学费加上生活费用时，出国留学可能很昂贵。"},{"sentence":"The new policy offers tax breaks for small businesses, plus grants for innovation, which should stimulate the economy.","translation":"新政策为小企业提供税收减免，加上创新拨款，这应该能刺激经济。"},{"sentence":"Effective communication requires not only clarity but also empathy, plus the ability to listen actively.","translation":"有效沟通不仅需要清晰，还需要同理心，加上积极倾听的能力。"}]},"building":{"examples":[{"sentence":"The university decided to renovate the old library building rather than construct a new one, because preserving historical architecture strengthens campus identity.","translation":"大学决定翻新旧的图书馆建筑而不是新建一座，因为保护历史建筑能增强校园认同感。"},{"sentence":"Although the building was designed by a renowned architect, its maintenance costs have exceeded initial projections, forcing the owners to seek additional funding.","translation":"尽管这栋建筑由一位著名建筑师设计，但其维护成本已超出最初预测，迫使业主寻求额外资金。"},{"sentence":"Effective building insulation can significantly reduce energy consumption, which is why many governments now enforce stricter thermal regulations.","translation":"有效的建筑隔热可以显著降低能耗，这就是许多政府现在执行更严格的热工法规的原因。"},{"sentence":"The research team analyzed how building orientation affects natural ventilation, concluding that south-facing facades yield optimal airflow in temperate climates.","translation":"研究团队分析了建筑朝向如何影响自然通风，得出结论：在温带气候下，朝南的立面能产生最佳气流。"},{"sentence":"Investing in green building technologies not only lowers operational expenses but also enhances occupant well-being, a dual benefit that appeals to forward-thinking developers.","translation":"投资绿色建筑技术不仅降低运营成本，还能提升居住者的福祉，这种双重好处吸引了有远见的开发商。"}]},"plumber":{"examples":[{"sentence":"When the plumber inspected the old pipes, he found that mineral buildup had reduced water pressure, which explained the persistent low flow.","translation":"当水管工检查旧管道时，他发现矿物质堆积降低了水压，这解释了持续的低水流问题。"},{"sentence":"Although the plumber was expensive, his thorough work prevented a major leak that could have damaged the entire basement.","translation":"尽管水管工收费昂贵，但他彻底的工作防止了一次可能损坏整个地下室的大泄漏。"},{"sentence":"The plumber installed a new filtration system, thereby improving water quality and reducing the household's reliance on bottled water.","translation":"水管工安装了一个新的过滤系统，从而改善了水质并减少了家庭对瓶装水的依赖。"},{"sentence":"Because the plumber arrived promptly, the burst pipe was fixed before it caused extensive water damage to the office.","translation":"因为水管工及时到达，破裂的管道在造成办公室大面积水损之前就被修好了。"},{"sentence":"A skilled plumber must understand complex blueprints, which is why vocational training now includes courses on digital design tools.","translation":"一个熟练的水管工必须理解复杂的蓝图，这就是为什么职业培训现在包括数字设计工具课程的原因。"}]},"fearful":{"examples":[{"sentence":"Although the surgery was routine, the patient remained fearful of complications that could prolong her recovery.","translation":"尽管手术是常规的，病人仍然担心可能出现并发症，从而延长康复时间。"},{"sentence":"Investors grew fearful when the central bank hinted at tighter monetary policy, causing a sharp decline in stock prices.","translation":"当央行暗示将收紧货币政策时，投资者变得担忧，导致股价急剧下跌。"},{"sentence":"Many communities are fearful that the new industrial project will contaminate local water sources and harm public health.","translation":"许多社区担心新的工业项目会污染当地水源，危害公众健康。"},{"sentence":"The researcher was fearful that the small sample size would undermine the statistical significance of her findings.","translation":"研究人员担心样本量过小会削弱其研究结果的统计显著性。"},{"sentence":"Because the region is prone to earthquakes, residents remain fearful of another major tremor striking without warning.","translation":"由于该地区地震多发，居民一直担心又一次大地震会在毫无预警的情况下发生。"}]},"perish":{"examples":[{"sentence":"Although modern medicine has advanced, many still perish from preventable diseases due to lack of access to healthcare.","translation":"尽管现代医学已经进步，许多人仍然因缺乏医疗资源而死于可预防的疾病。"},{"sentence":"Because the ancient texts were not properly preserved, they began to perish, resulting in the loss of invaluable knowledge.","translation":"由于古代文献没有得到妥善保存，它们开始腐烂，导致宝贵知识的丧失。"},{"sentence":"If we do not take immediate action against pollution, entire ecosystems may perish, which would disrupt the balance of nature.","translation":"如果我们不立即采取行动对抗污染，整个生态系统可能会毁灭，这将破坏自然平衡。"},{"sentence":"While some species adapt to changing climates, others perish because they cannot cope with the rapid environmental shifts.","translation":"虽然一些物种能适应气候变化，但其他物种因无法应对快速的环境变化而灭绝。"},{"sentence":"The flowers will perish unless they are watered regularly, a fact that every gardener must remember.","translation":"除非定期浇水，否则这些花会凋谢，这是每个园丁都必须记住的事实。"}]},"inform":{"examples":[{"sentence":"Although the deadline was approaching, the manager failed to inform the team, which led to unnecessary stress.","translation":"尽管截止日期临近，经理却没有通知团队，这导致了不必要的压力。"},{"sentence":"Because the policy change affects all employees, the HR department must inform everyone through an official announcement.","translation":"由于政策变化影响所有员工，人力资源部必须通过官方公告通知每个人。"},{"sentence":"When conducting research, it is essential to inform participants about the purpose of the study to ensure ethical compliance.","translation":"在进行研究时，必须告知参与者研究目的，以确保符合伦理规范。"},{"sentence":"The survey results will inform the development of new strategies, which aim to improve customer satisfaction.","translation":"调查结果将为新策略的制定提供依据，这些策略旨在提高客户满意度。"},{"sentence":"If you notice any irregularities, you should inform the authorities immediately, thereby preventing further damage.","translation":"如果你发现任何违规行为，应立即通知当局，从而防止进一步的损害。"}]},"tragedy":{"examples":[{"sentence":"The sudden collapse of the historic bridge was not merely an engineering failure but a profound human tragedy that claimed dozens of lives.","translation":"那座历史悠久的桥梁突然倒塌不仅是一次工程失败，更是一场夺走数十条生命的深重人间悲剧。"},{"sentence":"When a society neglects mental health support, the resulting suicide rates can escalate into a public health tragedy that demands urgent policy intervention.","translation":"当一个社会忽视心理健康支持时，由此导致的自杀率可能升级为一场需要紧急政策干预的公共卫生悲剧。"},{"sentence":"Although the playwright intended to highlight social injustice, the audience was most moved by the personal tragedy of the protagonist's unfulfilled aspirations.","translation":"尽管剧作家意在凸显社会不公，但观众最为动容的是主人公壮志未酬的个人悲剧。"},{"sentence":"Environmental degradation, if left unchecked, will transform the gradual loss of biodiversity into an irreversible ecological tragedy for future generations.","translation":"如果放任不管，环境退化将使生物多样性的逐渐丧失演变成后代无法逆转的生态悲剧。"},{"sentence":"Historians argue that the famine was not a natural disaster but a man-made tragedy caused by flawed agricultural policies and bureaucratic indifference.","translation":"历史学家认为，那场饥荒并非天灾，而是由错误的农业政策和官僚冷漠造成的人为悲剧。"}]},"rid":{"examples":[{"sentence":"Although the company invested heavily in cybersecurity, it still struggled to rid its network of persistent malware.","translation":"尽管公司在网络安全上投入巨资，但仍难以清除网络中顽固的恶意软件。"},{"sentence":"Because the new policy streamlined bureaucratic procedures, citizens were finally able to rid themselves of tedious paperwork.","translation":"由于新政策简化了官僚程序，市民终于能够摆脱繁琐的文书工作。"},{"sentence":"When the community organized a cleanup campaign, they managed to rid the park of litter that had accumulated for years.","translation":"当社区组织清理活动时，他们成功清除了公园里积存多年的垃圾。"},{"sentence":"To ensure a fair trial, the judge sought to rid the jury of any preconceived biases through careful selection.","translation":"为确保公正审判，法官通过仔细筛选，力求使陪审团摆脱任何先入为主的偏见。"},{"sentence":"While the therapy was demanding, it helped the patient rid himself of deep-rooted anxieties that had hindered his daily life.","translation":"尽管治疗要求很高，但它帮助患者摆脱了阻碍日常生活的根深蒂固的焦虑。"}]},"concern":{"examples":[{"sentence":"Although the company's profits have increased, there is growing concern about its environmental impact.","translation":"尽管公司利润有所增长，但人们对其环境影响的担忧日益增加。"},{"sentence":"The primary concern of the new policy is to ensure that all students have access to quality education.","translation":"新政策的主要关切是确保所有学生都能获得优质教育。"},{"sentence":"Because public health is a major concern, the government has invested heavily in medical research.","translation":"由于公共卫生是一个重大关切问题，政府已在医学研究上投入巨资。"},{"sentence":"Her deep concern for social justice led her to volunteer at a legal aid clinic, which helps low-income families.","translation":"她对社会正义的深切关心促使她在一家为低收入家庭提供帮助的法律援助诊所做志愿者。"},{"sentence":"While economic growth is important, we must not ignore the concern that inequality is widening.","translation":"虽然经济增长很重要，但我们绝不能忽视不平等正在扩大的担忧。"}]},"drop":{"examples":[{"sentence":"A single drop of polluted water can contain harmful bacteria, which poses a serious health risk to the community.","translation":"一滴受污染的水可能含有有害细菌，这对社区构成严重的健康风险。"},{"sentence":"The recent drop in the unemployment rate suggests that the economy is recovering, although challenges remain.","translation":"近期失业率的下降表明经济正在复苏，尽管挑战依然存在。"},{"sentence":"Because of the severe drought, every drop of water is precious, and residents are urged to conserve it.","translation":"由于严重干旱，每一滴水都很宝贵，居民们被敦促节约用水。"},{"sentence":"A sudden drop in temperature during the growing season can damage crops, thereby reducing the harvest.","translation":"生长季节气温骤降会损害作物，从而减少收成。"},{"sentence":"The charity emphasizes that even a small drop of kindness can make a big difference in someone's life.","translation":"该慈善机构强调，即使是一滴小小的善意也能对某人的生活产生重大影响。"}]},"hurry":{"examples":[{"sentence":"Because the report was due by noon, the team worked in a hurry and overlooked several critical errors.","translation":"由于报告必须在中午前提交，团队匆忙赶工，忽略了几处关键错误。"},{"sentence":"Although she was in a hurry to catch the train, she paused to help the elderly man who had dropped his groceries.","translation":"尽管她急着赶火车，还是停下来帮助那位掉了东西的老人。"},{"sentence":"The manager's constant hurry to launch the product without adequate testing ultimately damaged the company's reputation.","translation":"经理不断催促产品上市而未充分测试，最终损害了公司声誉。"},{"sentence":"Students who complete assignments in a hurry often fail to grasp the underlying concepts, which affects their long-term academic performance.","translation":"匆忙完成作业的学生往往未能掌握基本概念，从而影响长期学业表现。"},{"sentence":"In a hurry to meet the deadline, the researchers published preliminary findings that later proved to be inaccurate.","translation":"为了赶在截止日期前完成，研究人员发表了初步结果，后来却被证明不准确。"}]},"both":{"examples":[{"sentence":"Although both candidates presented compelling arguments, the committee ultimately favored the one with more practical experience.","translation":"尽管两位候选人都提出了令人信服的论点，委员会最终倾向于那位实践经验更丰富的人。"},{"sentence":"Because the new software offers both enhanced security and a user-friendly interface, it has been widely adopted by financial institutions.","translation":"由于新软件既提供增强的安全性又具有用户友好的界面，它已被金融机构广泛采用。"},{"sentence":"The research indicates that both genetic and environmental factors play a crucial role in shaping an individual's personality.","translation":"研究表明，遗传和环境因素在塑造个人性格方面都起着至关重要的作用。"},{"sentence":"While both approaches have their merits, the experimental method yields more reliable data when applied correctly.","translation":"虽然两种方法各有优点，但实验方法在正确应用时能产生更可靠的数据。"},{"sentence":"Effective communication requires both clarity of expression and the ability to listen actively, which are skills that can be developed through practice.","translation":"有效的沟通既需要清晰的表达，也需要积极倾听的能力，这些技能可以通过练习来培养。"}]},"distribute":{"examples":[{"sentence":"To ensure equitable access, the organization decided to distribute the educational materials through local libraries and community centers.","translation":"为了确保公平获取，该组织决定通过当地图书馆和社区中心分发教育材料。"},{"sentence":"Although the company plans to distribute its new product globally, it will first test the market in a few key regions.","translation":"尽管公司计划在全球分销其新产品，但它将首先在几个关键地区测试市场。"},{"sentence":"Because the charity failed to distribute the donations efficiently, many families in need did not receive the promised aid.","translation":"由于慈善机构未能有效分发捐赠物资，许多有需要的家庭没有收到承诺的援助。"},{"sentence":"The professor asked the students to distribute the survey questionnaires to a diverse sample of participants, thereby ensuring representative results.","translation":"教授要求学生将调查问卷分发给多样化的参与者样本，从而确保结果具有代表性。"},{"sentence":"When governments distribute resources based on transparent criteria, public trust in the system tends to increase significantly.","translation":"当政府根据透明的标准分配资源时，公众对该系统的信任往往会显著增加。"}]},"heel":{"examples":[{"sentence":"Because she wore high heels for extended periods, she developed a painful spur on her heel that required medical attention.","translation":"由于长时间穿高跟鞋，她的脚后跟长了疼痛的骨刺，需要就医。"},{"sentence":"The new running shoes, which feature extra cushioning in the heel, are designed to reduce impact on the joints.","translation":"这款新跑鞋在脚后跟处有额外的缓冲，旨在减少对关节的冲击。"},{"sentence":"When the dancer pivoted on her heel, she lost balance and stumbled, but quickly recovered her poise.","translation":"当舞者以脚后跟为轴旋转时，她失去平衡踉跄了一下，但很快恢复了镇定。"},{"sentence":"Although the heel of the shoe was worn down, the cobbler managed to repair it with a sturdy new piece of leather.","translation":"尽管鞋后跟磨损了，鞋匠还是用一块结实的新皮革修好了它。"},{"sentence":"The dog, trained to heel, walked obediently beside its owner without pulling on the leash.","translation":"那只经过训练的狗紧跟在主人脚边，顺从地走着，没有拉扯狗绳。"}]},"wire":{"examples":[{"sentence":"Although the wire was thin, it was strong enough to support the weight of the hanging sculpture.","translation":"尽管这根金属丝很细，但它足够坚固，能够支撑悬挂雕塑的重量。"},{"sentence":"The electrician replaced the old wire with a new one, thereby reducing the risk of a short circuit.","translation":"电工用新电线替换了旧电线，从而降低了短路的风险。"},{"sentence":"Because the telegraph wire was damaged during the storm, communication with the remote village was temporarily lost.","translation":"由于电报线在暴风雨中受损，与偏远村庄的通讯暂时中断了。"},{"sentence":"The farmer installed a wire fence around the pasture, which effectively kept the livestock from wandering off.","translation":"农民在牧场周围安装了铁丝网围栏，这有效地防止了牲畜走失。"},{"sentence":"When the wire is heated, its resistance increases, a principle that is used in many electrical devices.","translation":"当金属丝被加热时，其电阻会增加，这一原理被用于许多电气设备中。"}]},"hose":{"examples":[{"sentence":"Because the garden hose was too short to reach the flower beds, we had to connect an extension.","translation":"由于花园水管太短，无法够到花坛，我们不得不接上一段延长管。"},{"sentence":"The firefighter unrolled the hose with practiced speed, ensuring that water could be directed at the flames immediately.","translation":"消防员熟练地迅速展开水龙带，确保水能立即喷向火焰。"},{"sentence":"Although the rubber hose appeared durable, it cracked under the high pressure of the industrial pump.","translation":"尽管橡胶软管看起来很耐用，但在工业泵的高压下它还是破裂了。"},{"sentence":"After washing the car, he carefully coiled the hose and hung it on the rack, which prevented kinks and extended its life.","translation":"洗完车后，他小心地卷起水管并挂在架子上，这防止了打结并延长了其使用寿命。"},{"sentence":"In the laboratory, a flexible hose is used to transfer liquids safely, thereby minimizing the risk of spills.","translation":"在实验室中，使用柔性软管安全地输送液体，从而最大限度地减少了溢出的风险。"}]},"week":{"examples":[{"sentence":"Although the project deadline is only a week away, the team remains confident that they can complete it on time.","translation":"尽管项目截止日期只剩一周，团队仍然有信心按时完成。"},{"sentence":"The new policy, which was announced last week, has already sparked considerable debate among educators.","translation":"上周宣布的新政策已经在教育工作者中引发了相当大的争论。"},{"sentence":"Because the conference was postponed by a week, we had extra time to refine our presentation.","translation":"由于会议推迟了一周，我们有额外的时间来完善我们的演示文稿。"},{"sentence":"If you practice the piano for an hour each day, you will notice significant improvement within a week.","translation":"如果你每天练习钢琴一小时，一周内你就会注意到显著的进步。"},{"sentence":"The construction crew worked overtime throughout the week, thereby ensuring that the bridge was completed ahead of schedule.","translation":"施工队整个星期都在加班，从而确保了大桥提前完工。"}]},"patent":{"examples":[{"sentence":"Although the patent system is designed to reward inventors, it can sometimes hinder innovation when overly broad claims are granted.","translation":"尽管专利制度旨在奖励发明者，但当授予过于宽泛的权利要求时，它有时会阻碍创新。"},{"sentence":"Because the company failed to patent its core algorithm, competitors quickly replicated the technology and eroded its market share.","translation":"由于该公司未能为其核心算法申请专利，竞争对手迅速复制了该技术并侵蚀了其市场份额。"},{"sentence":"A well-drafted patent application not only protects an invention but also signals a firm's commitment to research and development.","translation":"一份精心撰写的专利申请不仅保护发明，还表明公司对研发的承诺。"},{"sentence":"While the patent granted the startup a temporary monopoly, it also attracted venture capital that was essential for scaling production.","translation":"虽然该专利赋予了初创公司暂时的垄断地位，但它也吸引了对于扩大生产至关重要的风险投资。"},{"sentence":"Universities often patent discoveries that arise from publicly funded research, thereby generating revenue to support further scientific inquiry.","translation":"大学通常为公共资助研究中产生的发现申请专利，从而产生收入以支持进一步的科学研究。"}]},"myself":{"examples":[{"sentence":"Although I consider myself a diligent student, I sometimes struggle to maintain focus when studying complex theoretical concepts.","translation":"尽管我认为自己是一个勤奋的学生，但在学习复杂的理论概念时，我有时难以保持专注。"},{"sentence":"By challenging myself to learn a new programming language every year, I have developed a versatile skill set that enhances my career prospects.","translation":"通过每年挑战自己学习一门新的编程语言，我培养了多方面的技能，从而提升了我的职业前景。"},{"sentence":"I often remind myself that constructive criticism, rather than praise, is the catalyst for genuine personal growth.","translation":"我经常提醒自己，建设性的批评而非赞美，才是真正个人成长的催化剂。"},{"sentence":"When I found myself overwhelmed by the workload, I adopted a strict time-management system to ensure that each task received adequate attention.","translation":"当我发现自己被工作压得喘不过气时，我采用了一套严格的时间管理系统，以确保每项任务都得到充分关注。"},{"sentence":"Because I pride myself on being an independent thinker, I always scrutinize popular opinions before accepting them as truth.","translation":"因为我以独立思考者为荣，所以在接受流行观点为真理之前，我总是仔细审视它们。"}]},"speak":{"examples":[{"sentence":"Although many leaders speak eloquently about corporate values, their actions often fail to align with their rhetoric.","translation":"尽管许多领导者就企业价值观侃侃而谈，但他们的行动往往与言辞不符。"},{"sentence":"Because she could speak three languages fluently, she was chosen to represent the company at the international trade fair.","translation":"因为她能流利地说三种语言，她被选为代表公司参加国际贸易博览会。"},{"sentence":"When experts speak on matters of public policy, they have a responsibility to present evidence-based arguments rather than personal opinions.","translation":"当专家就公共政策问题发言时，他们有责任提出基于证据的论点，而不是个人意见。"},{"sentence":"The statistics speak to a troubling trend of declining mental health among university students, which demands immediate intervention.","translation":"统计数据表明大学生心理健康状况下降的令人担忧的趋势，这需要立即干预。"},{"sentence":"While it is important to speak up against injustice, doing so through constructive dialogue is more effective than through aggressive confrontation.","translation":"虽然大声反对不公正很重要，但通过建设性对话这样做比通过激烈对抗更有效。"}]},"damp":{"examples":[{"sentence":"Although the damp in the basement was initially ignored, it eventually caused structural damage that required extensive repairs.","translation":"尽管地下室的湿气最初被忽视，但它最终导致了结构损坏，需要大规模维修。"},{"sentence":"Because the damp from the leaking pipe had spread to the walls, the landlord hired a contractor to fix the issue promptly.","translation":"由于漏水管道产生的湿气蔓延到了墙壁，房东立即聘请了承包商来解决问题。"},{"sentence":"The damp that accumulated in the poorly ventilated bathroom not only fostered mold growth but also emitted an unpleasant odor.","translation":"通风不良的浴室里积聚的湿气不仅滋生了霉菌，还散发出难闻的气味。"},{"sentence":"When the damp in the storage room reached critical levels, the manager installed a dehumidifier to protect the inventory.","translation":"当储藏室的湿气达到临界水平时，经理安装了除湿机以保护库存。"},{"sentence":"The persistent damp in the old library, which had damaged many rare books, prompted the board to invest in climate control systems.","translation":"旧图书馆里持续的湿气损坏了许多珍本书籍，这促使董事会投资了气候控制系统。"}]},"kingdom":{"examples":[{"sentence":"Although the kingdom was prosperous, its reliance on a single trade route made it vulnerable to economic disruptions.","translation":"尽管这个王国繁荣昌盛，但它对单一贸易路线的依赖使其容易受到经济中断的影响。"},{"sentence":"Because the kingdom invested in advanced irrigation systems, its agricultural output doubled within a decade.","translation":"由于该王国投资了先进的灌溉系统，其农业产量在十年内翻了一番。"},{"sentence":"The ancient kingdom, which was known for its architectural marvels, attracted scholars from distant lands.","translation":"这个以建筑奇迹闻名的古王国吸引了来自遥远国度的学者。"},{"sentence":"When the kingdom fell to invaders, its cultural legacy was preserved through the manuscripts that were hidden in monasteries.","translation":"当王国被入侵者攻陷时，其文化遗产通过藏在修道院中的手稿得以保存。"},{"sentence":"In the animal kingdom, social structures often determine access to resources, which can affect survival rates.","translation":"在动物界中，社会结构通常决定资源的获取，这会影响生存率。"}]},"first":{"examples":[{"sentence":"Although first impressions are often inaccurate, they can significantly influence hiring decisions.","translation":"尽管第一印象往往不准确，但它们能显著影响招聘决策。"},{"sentence":"Because the first phase of the project was completed ahead of schedule, the team received additional funding.","translation":"由于项目的第一阶段提前完成，团队获得了额外资金。"},{"sentence":"When first introduced to the market, the product faced skepticism, which later turned into widespread acceptance.","translation":"当首次引入市场时，该产品面临质疑，后来转变为广泛接受。"},{"sentence":"If the first attempt fails, researchers must analyze the data carefully before proceeding.","translation":"如果第一次尝试失败，研究人员必须仔细分析数据后再继续。"},{"sentence":"The first chapter of the thesis establishes a theoretical framework that guides the entire study.","translation":"论文的第一章建立了一个指导整个研究的理论框架。"}]},"link":{"examples":[{"sentence":"Although the link between diet and disease is well-established, many people still ignore nutritional advice.","translation":"尽管饮食与疾病之间的联系已得到充分证实，但许多人仍然忽视营养建议。"},{"sentence":"Because the new bridge provides a direct link between the two cities, travel time has been reduced by half.","translation":"由于新桥提供了两座城市之间的直接连接，旅行时间减少了一半。"},{"sentence":"When researchers discovered a genetic link to the disorder, they were able to develop targeted therapies.","translation":"当研究人员发现该疾病的遗传联系时，他们得以开发靶向疗法。"},{"sentence":"The study found a strong link between employee satisfaction and productivity, which suggests that investing in well-being is beneficial.","translation":"研究发现员工满意度与生产力之间存在密切联系，这表明投资于福祉是有益的。"},{"sentence":"If the communication link fails, the entire network may become unstable, thereby disrupting critical services.","translation":"如果通信链路出现故障，整个网络可能变得不稳定，从而中断关键服务。"}]},"homework":{"examples":[{"sentence":"Although homework is often seen as a burden, it reinforces classroom learning and builds essential study habits.","translation":"尽管家庭作业常被视为负担，但它能巩固课堂所学并培养必要的学习习惯。"},{"sentence":"Because homework provides an opportunity for independent practice, students can identify areas where they need further clarification.","translation":"由于家庭作业提供了独立练习的机会，学生可以发现需要进一步澄清的知识点。"},{"sentence":"When teachers assign homework that requires critical thinking, they encourage deeper engagement with the subject matter.","translation":"当教师布置需要批判性思维的家庭作业时，他们会鼓励学生对学科内容进行更深入的思考。"},{"sentence":"Effective homework policies, which balance quantity with quality, can prevent student burnout while promoting academic growth.","translation":"有效的家庭作业政策在数量与质量之间取得平衡，既能防止学生倦怠，又能促进学业进步。"},{"sentence":"Rather than simply repeating textbook exercises, meaningful homework tasks connect theoretical concepts to real-world applications.","translation":"有意义的家庭作业任务不是简单地重复课本练习，而是将理论概念与现实应用联系起来。"}]},"his":{"examples":[{"sentence":"Although his initial proposal was rejected, he refined it and eventually secured funding.","translation":"尽管他最初的提案被拒绝了，但他对其进行了完善并最终获得了资金。"},{"sentence":"A leader who listens to his team members fosters a collaborative environment that drives innovation.","translation":"一个倾听团队成员意见的领导者会营造一种推动创新的协作环境。"},{"sentence":"Because his research challenged established theories, it sparked considerable debate among scholars.","translation":"因为他的研究挑战了既有理论，所以在学者中引发了大量争论。"},{"sentence":"The artist expressed his vision through a series of paintings that captured the essence of urban life.","translation":"这位艺术家通过一系列捕捉城市生活本质的画作表达了他的愿景。"},{"sentence":"When a student takes ownership of his learning, he develops critical thinking skills that benefit him lifelong.","translation":"当学生对自己的学习负责时，他会培养出终身受益的批判性思维能力。"}]},"evaporate":{"examples":[{"sentence":"When the temperature exceeds 100 degrees Celsius, water will evaporate rapidly, turning into steam.","translation":"当温度超过100摄氏度时，水会迅速蒸发，变成水蒸气。"},{"sentence":"Because the solvent can evaporate at room temperature, it is widely used in the production of quick-drying adhesives.","translation":"由于这种溶剂在室温下就能蒸发，它被广泛用于生产快干胶粘剂。"},{"sentence":"If the reservoir is not covered, a significant amount of water will evaporate during the hot summer months.","translation":"如果水库不加盖，在炎热的夏季月份会有大量的水蒸发掉。"},{"sentence":"Although the initial excitement was palpable, it began to evaporate once the team encountered unforeseen obstacles.","translation":"尽管最初的兴奋之情溢于言表，但一旦团队遇到意外障碍，这种热情就开始消失。"},{"sentence":"The scientist demonstrated that alcohol can evaporate more quickly than water due to its lower boiling point.","translation":"科学家证明，由于酒精的沸点较低，它比水蒸发得更快。"}]},"road":{"examples":[{"sentence":"Because the road was covered in black ice, several vehicles skidded off the highway that morning.","translation":"因为路面覆盖着黑冰，那天早上有几辆车滑出了公路。"},{"sentence":"The government allocated funds to widen the road, which had become a bottleneck during rush hour.","translation":"政府拨款拓宽那条道路，它在高峰时段已成为交通瓶颈。"},{"sentence":"Although the road to success is often paved with setbacks, perseverance ultimately leads to achievement.","translation":"尽管成功之路常常布满挫折，但坚持不懈最终会带来成就。"},{"sentence":"To ensure the safety of pedestrians, the city installed speed bumps along the road near the school.","translation":"为了确保行人安全，该市在学校附近的道路上安装了减速带。"},{"sentence":"When the main road was closed for repairs, commuters had to take a detour through narrow side streets.","translation":"当主干道因维修而封闭时，通勤者不得不绕行狭窄的小街。"}]},"weak":{"examples":[{"sentence":"Although the company's market position appears strong, its weak cash flow could lead to liquidity problems if not addressed promptly.","translation":"尽管该公司的市场地位看似稳固，但其疲软的现金流若不及时解决，可能导致流动性问题。"},{"sentence":"Because the argument relies on weak analogies rather than solid evidence, it fails to convince the academic committee.","translation":"由于该论证依赖不充分的类比而非确凿证据，因此未能说服学术委员会。"},{"sentence":"A weak institutional framework often allows corruption to flourish, which in turn undermines economic development.","translation":"薄弱的制度框架往往纵容腐败滋生，进而破坏经济发展。"},{"sentence":"While the novel's plot is engaging, its weak character development prevents readers from forming emotional connections.","translation":"尽管小说情节引人入胜，但其薄弱的人物塑造使读者难以形成情感共鸣。"},{"sentence":"The bridge was closed after engineers discovered weak joints that could compromise its structural integrity during heavy winds.","translation":"工程师发现桥梁存在不牢固的接点，可能在大风中损害其结构完整性，因此该桥被关闭。"}]},"pink":{"examples":[{"sentence":"The pink ribbon has become an internationally recognized symbol for breast cancer awareness campaigns, which mobilize millions of people each year.","translation":"粉红丝带已成为国际公认的乳腺癌宣传活动的标志，每年动员数百万人参与。"},{"sentence":"Because pink noise contains equal energy per octave, it is often used in audio engineering to test loudspeaker performance.","translation":"由于粉红噪音每倍频程能量相等，它常被用于音频工程中测试扬声器性能。"},{"sentence":"Although pink is traditionally associated with femininity in Western cultures, it was considered a masculine color in the early 20th century.","translation":"尽管在西方文化中粉红色传统上与女性气质相关联，但在20世纪初它曾被视为男性色彩。"},{"sentence":"The artist used a delicate pink hue to convey a sense of tranquility, thereby creating a calming atmosphere in the gallery.","translation":"艺术家使用柔和的粉红色调来传达宁静感，从而在画廊中营造出平和的氛围。"},{"sentence":"When the company redesigned its logo with a vibrant pink, it successfully attracted a younger demographic, which boosted sales significantly.","translation":"当公司用充满活力的粉红色重新设计标志时，成功吸引了更年轻的群体，从而显著提升了销售额。"}]},"beautiful":{"examples":[{"sentence":"A beautiful campus environment can significantly enhance students' well-being, which in turn improves their academic performance.","translation":"美丽的校园环境可以显著提升学生的幸福感，进而提高他们的学业表现。"},{"sentence":"Although the building's design is beautiful, its lack of accessibility features has drawn criticism from disability advocates.","translation":"尽管该建筑的设计很美丽，但其缺乏无障碍设施引发了残障人士权益倡导者的批评。"},{"sentence":"The mathematician described the proof as beautiful because of its elegant simplicity and the unexpected connections it revealed.","translation":"这位数学家称该证明是美丽的，因为它具有优雅的简洁性，并揭示了意想不到的联系。"},{"sentence":"Preserving beautiful natural landscapes is essential not only for tourism but also for maintaining biodiversity, which benefits future generations.","translation":"保护美丽的自然景观不仅对旅游业至关重要，而且对维持生物多样性至关重要，从而造福后代。"},{"sentence":"Her beautiful articulation of complex ideas made the lecture accessible to a diverse audience, thereby fostering greater understanding.","translation":"她对复杂思想的美丽阐述使讲座易于被不同的听众理解，从而促进了更深入的认识。"}]},"software":{"examples":[{"sentence":"Open-source software, which allows users to modify and share code freely, has accelerated technological innovation across industries.","translation":"开源软件允许用户自由修改和共享代码，加速了各行业的技术创新。"},{"sentence":"Because modern businesses rely heavily on specialized software, investing in employee training can significantly boost productivity.","translation":"由于现代企业严重依赖专业软件，投资于员工培训可以显著提高生产力。"},{"sentence":"Educational software that adapts to individual learning paces has proven effective in improving student outcomes in diverse classrooms.","translation":"能够适应个人学习节奏的教育软件已被证明能有效提高多样化课堂中的学生成绩。"},{"sentence":"Although software piracy remains a concern, the rise of affordable subscription models has reduced its prevalence in many regions.","translation":"尽管软件盗版仍然令人担忧，但可负担的订阅模式的兴起已减少了许多地区的盗版现象。"},{"sentence":"Engineers use simulation software to test designs under extreme conditions, thereby minimizing the risk of costly physical failures.","translation":"工程师使用仿真软件在极端条件下测试设计，从而将代价高昂的物理故障风险降至最低。"}]},"cycle":{"examples":[{"sentence":"Although the economic cycle is inherently unpredictable, policymakers use leading indicators to anticipate downturns and adjust fiscal measures accordingly.","translation":"尽管经济周期本质上难以预测，但政策制定者利用先行指标来预测衰退并相应调整财政措施。"},{"sentence":"Because the carbon cycle regulates Earth's climate over millennia, disrupting it through deforestation accelerates global warming.","translation":"由于碳循环在数千年间调节着地球气候，通过森林砍伐破坏它会加速全球变暖。"},{"sentence":"The product development cycle, which now integrates customer feedback at every stage, enables companies to launch innovations that better meet market needs.","translation":"产品开发周期现在在每个阶段都整合了客户反馈，使公司能够推出更好地满足市场需求的创新产品。"},{"sentence":"When the sleep-wake cycle is disrupted by shift work, individuals often experience impaired cognitive function, thereby reducing workplace safety.","translation":"当睡眠-觉醒周期被轮班工作打乱时，个体常会出现认知功能受损，从而降低工作场所安全性。"},{"sentence":"Expanding urban cycle networks not only reduces traffic congestion but also promotes public health, which in turn lowers healthcare costs.","translation":"扩建城市自行车网络不仅减少了交通拥堵，还促进了公共健康，进而降低了医疗成本。"}]},"realistic":{"examples":[{"sentence":"Although the initial proposal was ambitious, the committee eventually adopted a more realistic plan that balanced innovation with feasibility.","translation":"尽管最初的提案雄心勃勃，委员会最终还是采纳了一个更现实的计划，在创新与可行性之间取得了平衡。"},{"sentence":"Because the training simulator offers a realistic environment, pilots can practice emergency procedures without risking actual lives.","translation":"由于训练模拟器提供了逼真的环境，飞行员可以在不危及实际生命的情况下练习应急程序。"},{"sentence":"When setting career objectives, it is crucial to maintain a realistic perspective, which helps avoid unnecessary frustration and burnout.","translation":"在设定职业目标时，保持现实的视角至关重要，这有助于避免不必要的挫折和倦怠。"},{"sentence":"The architect created a realistic 3D model of the building, thereby allowing clients to visualize the final structure before construction began.","translation":"建筑师创建了建筑的逼真三维模型，从而使客户在施工开始前就能直观看到最终结构。"},{"sentence":"A realistic assessment of market demand is essential, unless a company is willing to risk overproduction and financial loss.","translation":"对市场需求的现实评估至关重要，除非公司愿意冒生产过剩和财务损失的风险。"}]},"deduct":{"examples":[{"sentence":"Because the tax code allows you to deduct mortgage interest, many homeowners find that itemizing deductions reduces their overall tax liability.","translation":"由于税法允许扣除抵押贷款利息，许多房主发现逐项列出扣除额能减少他们的总体税负。"},{"sentence":"If you fail to submit the expense report on time, the finance department will deduct the unverified costs from your next reimbursement.","translation":"如果你未能按时提交费用报告，财务部门将从你的下一次报销中扣除未经核实的费用。"},{"sentence":"The software can automatically deduct bank fees when reconciling accounts, which saves accountants considerable time each month.","translation":"该软件在对账时可以自动扣除银行手续费，这每月为会计师节省了大量时间。"},{"sentence":"Although the contract stipulates a penalty for late delivery, the client may choose to deduct a smaller amount as a gesture of goodwill.","translation":"尽管合同规定了延迟交货的罚金，客户可能选择扣除较小金额以示善意。"},{"sentence":"When calculating net profit, it is standard practice to deduct all operating expenses, including depreciation and amortization.","translation":"在计算净利润时，标准做法是扣除所有运营费用，包括折旧和摊销。"}]},"metric":{"examples":[{"sentence":"Because the metric system is based on powers of ten, unit conversions are far simpler than in imperial systems.","translation":"由于公制以十的幂次为基础，单位换算比英制简单得多。"},{"sentence":"International scientific journals require authors to report measurements in metric units to ensure consistency across studies.","translation":"国际科学期刊要求作者以公制单位报告测量数据，以确保各项研究之间的一致性。"},{"sentence":"Although the United States still uses customary units, many industries have adopted metric standards to facilitate global trade.","translation":"尽管美国仍使用惯用单位，但许多行业已采用公制标准以促进全球贸易。"},{"sentence":"Engineers designed the bridge to withstand a load of fifty metric tons, which exceeds the expected traffic weight.","translation":"工程师将这座桥设计为可承受五十公吨的荷载，这超过了预期的交通重量。"},{"sentence":"When comparing national health systems, policymakers often use life expectancy as a key metric of overall performance.","translation":"在比较各国医疗体系时，政策制定者常将预期寿命作为衡量整体表现的关键指标。"}]},"skull":{"examples":[{"sentence":"Although the skull is remarkably strong, a direct blow can cause a fracture that requires immediate medical attention.","translation":"尽管头骨非常坚固，但直接打击可能导致骨折，需要立即就医。"},{"sentence":"Because the skull encases the brain, any damage to it can have serious neurological consequences.","translation":"由于头骨包裹着大脑，任何对其的损伤都可能产生严重的神经学后果。"},{"sentence":"Forensic scientists used the skull to reconstruct the victim's facial features, which helped identify the remains.","translation":"法医科学家利用头骨重建了受害者的面部特征，这有助于确认遗骸身份。"},{"sentence":"When examining the fossilized skull, researchers noted a prominent brow ridge that indicated a robust early human ancestor.","translation":"在检查这块化石头骨时，研究人员注意到突出的眉脊，这表明是一种强壮的早期人类祖先。"},{"sentence":"The surgeon carefully removed a portion of the skull to relieve pressure on the brain, thereby preventing further damage.","translation":"外科医生小心地移除了一部分头骨以减轻大脑压力，从而防止了进一步损伤。"}]},"unload":{"examples":[{"sentence":"Because the shipment contained fragile items, the workers had to unload the truck with extreme caution to avoid breakage.","translation":"由于货物包含易碎物品，工人们必须极其小心地卸货以避免破损。"},{"sentence":"Although the port was busy, the crew managed to unload the cargo within the scheduled time, which pleased the shipping company.","translation":"尽管港口繁忙，船员们还是设法在预定时间内卸完了货物，这让航运公司很满意。"},{"sentence":"When you unload your emotional burdens onto a trusted friend, you often gain a fresh perspective on your problems.","translation":"当你向一位信赖的朋友倾诉情感负担时，你常常会对自己的问题获得新的视角。"},{"sentence":"The company decided to unload its non-core assets, thereby streamlining operations and focusing on its main business.","translation":"公司决定剥离非核心资产，从而精简运营并专注于主营业务。"},{"sentence":"If you unload the dishwasher promptly, you can avoid a pile-up of dirty dishes in the sink.","translation":"如果你及时清空洗碗机，就能避免水槽里堆积脏盘子。"}]},"thrust":{"examples":[{"sentence":"Although the main thrust of the argument was compelling, the lack of empirical evidence weakened its overall impact.","translation":"尽管该论点的主要要旨令人信服，但缺乏实证证据削弱了其整体影响力。"},{"sentence":"The engine generates sufficient thrust to propel the aircraft forward, thereby overcoming air resistance during takeoff.","translation":"发动机产生足够的推力推动飞机前进，从而在起飞时克服空气阻力。"},{"sentence":"Because the critic's verbal thrust targeted the core of the policy, it prompted a thorough review by the committee.","translation":"因为评论家的口头攻击直指政策核心，这促使委员会进行了彻底审查。"},{"sentence":"With a sudden thrust of the spear, the warrior pierced the shield, which demonstrated his exceptional strength.","translation":"随着长矛的猛然一刺，战士刺穿了盾牌，这显示了他非凡的力量。"},{"sentence":"The economic thrust of the report emphasizes sustainable growth, rather than short-term profit maximization.","translation":"报告的经济要旨强调可持续增长，而不是短期利润最大化。"}]},"conductor":{"examples":[{"sentence":"The orchestra's conductor used precise gestures to unify the musicians, thereby creating a harmonious performance.","translation":"乐团的指挥用精准的手势统一了乐手，从而创造了一场和谐的演出。"},{"sentence":"Because copper is an excellent conductor of electricity, it is widely used in power transmission lines.","translation":"因为铜是优良的电导体，它被广泛用于输电线路。"},{"sentence":"The bus conductor patiently assisted passengers with their luggage, which ensured a smooth boarding process.","translation":"公交车售票员耐心地帮助乘客搬运行李，这确保了顺畅的上车过程。"},{"sentence":"As a conductor of social change, the organization bridges gaps between communities, rather than imposing top-down solutions.","translation":"作为社会变革的引导者，该组织在社区之间架起桥梁，而不是强加自上而下的解决方案。"},{"sentence":"The train conductor announced the delay, which was caused by unexpected track maintenance, to keep passengers informed.","translation":"列车长宣布了由意外轨道维护造成的延误，以便让乘客了解情况。"}]},"gay":{"examples":[{"sentence":"The garden was filled with gay flowers, which attracted numerous butterflies and delighted the visitors.","translation":"花园里开满了艳丽的花朵，这吸引了无数蝴蝶，令游客欣喜。"},{"sentence":"Despite the somber occasion, her gay laughter unexpectedly lightened the atmosphere, which surprised everyone.","translation":"尽管场合庄重，她欢快的笑声出人意料地缓和了气氛，这让所有人惊讶。"},{"sentence":"The artist used gay colors in the mural, thereby transforming the dull wall into a vibrant community landmark.","translation":"艺术家在壁画中运用艳丽的色彩，从而将单调的墙壁变成了充满活力的社区地标。"},{"sentence":"Because the festival retained a gay spirit, it continued to attract participants even during economic hardships.","translation":"因为节日保持了欢快的精神，即使在经济困难时期，它仍继续吸引参与者。"},{"sentence":"In Victorian novels, a gay disposition was often depicted as a sign of moral purity, rather than mere frivolity.","translation":"在维多利亚小说中，快乐的性情常被描绘成道德纯洁的标志，而不仅仅是轻浮。"}]},"huge":{"examples":[{"sentence":"The new infrastructure project required a huge investment, which the government justified by citing long-term economic benefits.","translation":"新的基础设施项目需要巨额投资，政府以长期经济效益为由证明了其合理性。"},{"sentence":"Although the company faced huge financial losses last quarter, its leadership remains confident about a recovery.","translation":"尽管公司上个季度遭受了巨大的财务损失，其领导层仍对复苏充满信心。"},{"sentence":"Renewable energy offers a huge opportunity to reduce carbon emissions, provided that governments implement supportive policies.","translation":"可再生能源为减少碳排放提供了巨大的机会，前提是政府实施支持性政策。"},{"sentence":"The research team made a huge breakthrough by identifying a gene linked to the disease, which could lead to new treatments.","translation":"研究团队通过识别与该疾病相关的基因取得了巨大突破，这可能带来新的治疗方法。"},{"sentence":"Urbanization creates a huge demand for housing, which in turn drives up property prices in major cities.","translation":"城市化创造了对住房的巨大需求，进而推高了大城市的房价。"}]},"lung":{"examples":[{"sentence":"Although lung cancer remains a leading cause of death worldwide, early detection through screening can significantly improve survival rates.","translation":"尽管肺癌仍然是全球主要的死亡原因，但通过筛查进行早期发现可以显著提高生存率。"},{"sentence":"Because air pollution contains fine particulate matter that penetrates deep into the lung, it poses a serious threat to respiratory health.","translation":"由于空气污染含有能深入肺部的细颗粒物，它对呼吸系统健康构成了严重威胁。"},{"sentence":"The surgeon successfully removed the tumor from the patient's left lung, which had been causing persistent breathing difficulties.","translation":"外科医生成功地从患者的左肺切除了肿瘤，该肿瘤一直导致持续的呼吸困难。"},{"sentence":"While regular exercise strengthens the heart and muscles, it also enhances lung capacity, thereby improving overall endurance.","translation":"虽然定期锻炼能增强心脏和肌肉，但它也能提高肺活量，从而改善整体耐力。"},{"sentence":"Researchers are developing artificial lung devices that can temporarily support patients with severe respiratory failure, offering a bridge to recovery.","translation":"研究人员正在开发能够暂时支持严重呼吸衰竭患者的人工肺装置，为康复提供过渡。"}]},"ice-cream":{"examples":[{"sentence":"The ice-cream industry has responded to health concerns by developing low-sugar alternatives that still taste indulgent.","translation":"冰淇淋行业通过开发低糖替代品来应对健康问题，这些替代品仍然口感醇厚。"},{"sentence":"Because the ice-cream contained stabilizers, it maintained a smooth texture even after being partially thawed.","translation":"因为冰淇淋含有稳定剂，所以即使部分融化后仍能保持细腻的质地。"},{"sentence":"The ice-cream parlor, which sources ingredients from local farms, has become a popular community gathering spot.","translation":"这家冰淇淋店从当地农场采购原料，已成为受欢迎的社区聚集地。"},{"sentence":"Researchers found that ice-cream consumption rises significantly during heatwaves, posing challenges for supply chains.","translation":"研究人员发现，热浪期间冰淇淋消费量显著上升，给供应链带来了挑战。"},{"sentence":"Although the ice-cream was marketed as a premium product, its artificial flavorings disappointed discerning consumers.","translation":"尽管这款冰淇淋被宣传为高端产品，但其人工香料令挑剔的消费者感到失望。"}]},"imagine":{"examples":[{"sentence":"It is difficult to imagine how modern medicine would function without the contributions of early anatomists.","translation":"很难想象没有早期解剖学家的贡献，现代医学将如何运作。"},{"sentence":"While policymakers imagine that automation will boost productivity, many workers fear it will exacerbate inequality.","translation":"尽管政策制定者设想自动化将提高生产力，但许多工人担心它会加剧不平等。"},{"sentence":"To fully grasp the scale of the universe, one must imagine distances that defy everyday experience.","translation":"要完全理解宇宙的尺度，就必须想象那些超越日常经验的距离。"},{"sentence":"The architect encouraged the community to imagine a public space that fosters both recreation and cultural exchange.","translation":"建筑师鼓励社区去想象一个既能促进休闲又能促进文化交流的公共空间。"},{"sentence":"Because we cannot directly observe black holes, scientists must imagine their properties based on indirect evidence.","translation":"因为我们无法直接观测黑洞，科学家必须根据间接证据来设想它们的特性。"}]},"voyage":{"examples":[{"sentence":"Although the voyage was originally scheduled for two weeks, unexpected storms extended it by several days.","translation":"尽管航行原定两周，但意外的风暴将其延长了几天。"},{"sentence":"The captain decided to delay the voyage because the weather forecast predicted dangerous conditions at sea.","translation":"船长决定推迟航行，因为天气预报预测海上会有危险状况。"},{"sentence":"While the voyage offered breathtaking views of the coastline, it also tested the crew's endurance.","translation":"虽然这次航行提供了令人叹为观止的海岸线景色，但也考验了船员的耐力。"},{"sentence":"The voyage, which was funded by a scientific institution, aimed to study marine biodiversity in remote areas.","translation":"这次由一家科学机构资助的航行，旨在研究偏远地区的海洋生物多样性。"},{"sentence":"If the voyage succeeds, it will mark the first time a solar-powered vessel has circumnavigated the globe.","translation":"如果这次航行成功，它将标志着太阳能船只首次环球航行。"}]},"central":{"examples":[{"sentence":"Although the central government implemented new policies, local authorities struggled to enforce them effectively.","translation":"尽管中央政府实施了新政策，但地方当局难以有效执行。"},{"sentence":"The central theme of the novel, which explores the conflict between tradition and modernity, resonates with many readers.","translation":"这部小说的中心主题探讨了传统与现代之间的冲突，引起了许多读者的共鸣。"},{"sentence":"Because the central heating system malfunctioned, the entire building experienced a significant drop in temperature.","translation":"由于中央供暖系统发生故障，整栋楼的温度大幅下降。"},{"sentence":"The central bank's decision to lower interest rates, which was unexpected, stimulated economic growth in the short term.","translation":"中央银行出人意料地决定降低利率，在短期内刺激了经济增长。"},{"sentence":"While the central location of the hotel offers convenience, the noise from the street can be disruptive at night.","translation":"虽然酒店的中心位置提供了便利，但街上的噪音在夜间可能会造成干扰。"}]},"comment":{"examples":[{"sentence":"The professor's comment on my essay, which pointed out several logical fallacies, helped me improve my argumentation skills.","translation":"教授对我论文的评论指出了几个逻辑谬误，帮助我提高了论证能力。"},{"sentence":"Because the politician's comment was taken out of context, it sparked unnecessary controversy among the public.","translation":"由于这位政治家的评论被断章取义，它在公众中引发了不必要的争议。"},{"sentence":"A constructive comment from a peer reviewer can significantly enhance the quality of a research paper, thereby increasing its chances of acceptance.","translation":"同行评审人建设性的评论可以显著提高研究论文的质量，从而增加其被接受的机会。"},{"sentence":"Although the manager's comment was brief, it provided clear guidance on the project's next steps.","translation":"尽管经理的评论很简短，但它为项目的下一步提供了明确的指导。"},{"sentence":"Her insightful comment during the meeting, which drew on recent data, convinced the team to adopt a new strategy.","translation":"她在会议上的深刻评论引用了最新数据，说服团队采用了新策略。"}]},"help":{"examples":[{"sentence":"Although many students seek help from tutors, self-study remains essential for deep understanding.","translation":"尽管许多学生向导师寻求帮助，但自学对于深入理解仍然至关重要。"},{"sentence":"The help that experienced mentors provide can accelerate career development, which benefits both individuals and organizations.","translation":"经验丰富的导师提供的帮助可以加速职业发展，这对个人和组织都有益。"},{"sentence":"Without timely help from international organizations, the region would have faced a severe food crisis.","translation":"如果没有国际组织的及时帮助，该地区将面临严重的粮食危机。"},{"sentence":"Governments often offer financial help to small businesses, thereby stimulating local economic growth.","translation":"政府经常向小企业提供财政帮助，从而刺激当地经济增长。"},{"sentence":"Because the help of volunteers is invaluable during emergencies, communities should invest in training programs.","translation":"因为志愿者的帮助在紧急情况下非常宝贵，社区应该投资于培训项目。"}]},"shampoo":{"examples":[{"sentence":"Dermatologists recommend using a sulfate-free shampoo, which cleanses the scalp gently without stripping away natural oils.","translation":"皮肤科医生建议使用无硫酸盐的洗发水，它能温和清洁头皮而不洗去天然油脂。"},{"sentence":"Because the new shampoo contains argan oil, it effectively moisturizes dry hair and reduces frizz throughout the day.","translation":"由于这款新洗发水含有摩洛哥坚果油，它能有效滋润干燥的头发，并在一整天内减少毛躁。"},{"sentence":"When traveling, it is convenient to carry a solid shampoo bar, which saves space and complies with airline liquid restrictions.","translation":"旅行时，携带固体洗发皂很方便，它节省空间并符合航空公司的液体限制。"},{"sentence":"The company reformulated its best-selling shampoo to exclude parabens, thereby addressing growing consumer concerns about chemical additives.","translation":"该公司重新配制了其最畅销的洗发水，去除了对羟基苯甲酸酯，从而回应了消费者对化学添加剂日益增长的担忧。"},{"sentence":"Although the shampoo was marketed as hypoallergenic, some users still experienced scalp irritation due to individual sensitivities.","translation":"尽管这款洗发水被宣传为低过敏性，但由于个体敏感性，一些用户仍然经历了头皮刺激。"}]},"raid":{"examples":[{"sentence":"Although the police raid was conducted at dawn, the suspects managed to destroy crucial evidence before being apprehended.","translation":"尽管警方的突袭在黎明时进行，但嫌疑人在被捕前还是设法销毁了关键证据。"},{"sentence":"The company suffered a significant data breach because a cyber raid exploited a vulnerability that had not been patched.","translation":"该公司遭受了严重的数据泄露，因为一次网络攻击利用了一个未修补的漏洞。"},{"sentence":"While the Viking raid on the monastery was brutal, it ultimately led to cultural exchanges that reshaped the region.","translation":"虽然维京人对修道院的袭击很残酷，但它最终导致了重塑该地区的文化交流。"},{"sentence":"The regulatory raid uncovered numerous violations, thereby forcing the factory to implement stricter safety protocols.","translation":"监管突袭发现了许多违规行为，从而迫使工厂实施更严格的安全规程。"},{"sentence":"If the task force had not executed the raid with precision, the hostages might have been harmed during the operation.","translation":"如果特遣队没有精准地执行突袭，人质可能在行动中受到伤害。"}]},"reed":{"examples":[{"sentence":"Because the reed beds act as a natural filtration system, the river water remains remarkably clean despite industrial runoff.","translation":"由于芦苇丛充当了天然过滤系统，尽管有工业径流，河水仍然非常干净。"},{"sentence":"The musician replaced the reed on her oboe, which had become warped from humidity, to ensure a clear tone for the performance.","translation":"这位音乐家更换了双簧管上因潮湿而变形的簧片，以确保演奏时音色清晰。"},{"sentence":"Although the reed appears delicate, its flexible structure allows it to bend in strong winds without breaking.","translation":"尽管芦苇看起来很脆弱，但其柔韧的结构使其能在强风中弯曲而不会折断。"},{"sentence":"Ancient civilizations used papyrus reed not only for writing materials but also for constructing boats, thereby facilitating trade.","translation":"古代文明不仅用纸莎草制作书写材料，还用来造船，从而促进了贸易。"},{"sentence":"When the artist painted the reed in the foreground, she used swift brushstrokes to capture the essence of the marshland.","translation":"当画家在前景中画芦苇时，她用快速的笔触捕捉了沼泽地的神韵。"}]},"next":{"examples":[{"sentence":"The research team will analyze the current data before designing the next experiment, which aims to test the new hypothesis.","translation":"研究团队将先分析当前数据，然后设计下一个实验，该实验旨在检验新假设。"},{"sentence":"If the next administration fails to invest in renewable energy, the country may not meet its climate targets by 2030.","translation":"如果下一届政府未能投资可再生能源，该国可能无法在2030年前实现其气候目标。"},{"sentence":"Because the next phase of the project requires extensive fieldwork, the committee has allocated additional funding for travel.","translation":"由于项目的下一阶段需要大量实地工作，委员会已拨出额外资金用于差旅。"},{"sentence":"The software update will be deployed next month, after which the development team will focus on the next version's features.","translation":"软件更新将于下个月部署，之后开发团队将专注于下一个版本的功能。"},{"sentence":"While the current generation faces economic uncertainty, the next generation may benefit from technological advancements that create new opportunities.","translation":"虽然当前一代面临经济不确定性，但下一代可能会受益于创造新机遇的技术进步。"}]},"necklace":{"examples":[{"sentence":"The antique necklace, which had been passed down through four generations, was carefully restored by a master jeweler.","translation":"那条历经四代传承的古董项链，由一位珠宝大师精心修复。"},{"sentence":"Because the necklace was crafted from ethically sourced materials, it appealed to environmentally conscious consumers.","translation":"由于这条项链采用符合道德标准采购的材料制成，它吸引了具有环保意识的消费者。"},{"sentence":"Although the necklace appeared delicate, its innovative clasp ensured that it remained secure during vigorous activity.","translation":"尽管这条项链看似精致，但其创新的搭扣确保它在剧烈活动中依然牢固。"},{"sentence":"The museum displayed a necklace from the Ming dynasty so that visitors could appreciate the artistry of ancient metalwork.","translation":"博物馆展出了一条明代项链，以便参观者欣赏古代金属工艺的精湛技艺。"},{"sentence":"If a necklace is stored in a dry, dark place, its luster can be preserved for decades.","translation":"如果将项链存放在干燥、避光的地方，其光泽可以保持数十年。"}]},"toxic":{"examples":[{"sentence":"Because the factory released toxic waste into the river, the local ecosystem suffered irreversible damage.","translation":"由于工厂向河流排放有毒废物，当地生态系统遭受了不可逆转的破坏。"},{"sentence":"Although the plant has toxic properties, it can be used to develop life-saving drugs when handled by experts.","translation":"尽管这种植物具有毒性，但由专家处理时，它可以用来开发挽救生命的药物。"},{"sentence":"The report, which analyzed air quality in major cities, found that toxic pollutants often exceed safe levels during rush hour.","translation":"这份报告分析了主要城市的空气质量，发现有毒污染物在交通高峰时段经常超过安全水平。"},{"sentence":"To ensure a healthy work environment, companies must address toxic behaviors such as bullying and harassment promptly.","translation":"为了确保健康的工作环境，公司必须及时处理欺凌和骚扰等有害行为。"},{"sentence":"While social media can foster connection, it can also become a toxic space when users engage in personal attacks and misinformation.","translation":"尽管社交媒体可以促进联系，但当用户进行人身攻击和传播错误信息时，它也可能变成一个有害的空间。"}]},"thorn":{"examples":[{"sentence":"Although the rose is beautiful, its thorn can cause a painful wound if not handled carefully.","translation":"尽管玫瑰很美，但如果不小心处理，它的刺会造成疼痛的伤口。"},{"sentence":"The gardener removed the thorn from her finger with tweezers, which she had sterilized beforehand.","translation":"园丁用事先消毒过的镊子拔出了手指上的刺。"},{"sentence":"Because a thorn can introduce bacteria deep into the skin, it is essential to clean the area thoroughly.","translation":"因为刺可能将细菌带入皮肤深处，所以彻底清洁该区域至关重要。"},{"sentence":"While hiking through the dense forest, he felt a sharp thorn pierce his ankle, causing him to limp.","translation":"在穿越茂密森林时，他感到一根锋利的刺扎入脚踝，使他跛行。"},{"sentence":"The thorn on the stem of the plant serves as a defense mechanism, thereby deterring herbivores from eating it.","translation":"植物茎上的刺是一种防御机制，从而阻止食草动物啃食它。"}]},"vulnerable":{"examples":[{"sentence":"Because the coastal city lacks adequate flood defenses, it is highly vulnerable to storm surges during hurricanes.","translation":"由于这座沿海城市缺乏足够的防洪设施，它在飓风期间极易受到风暴潮的侵袭。"},{"sentence":"The elderly are often more vulnerable to scams, which is why they need to be educated about online fraud.","translation":"老年人往往更容易受到诈骗，这就是为什么他们需要接受有关网络欺诈的教育。"},{"sentence":"Without regular software updates, your computer becomes vulnerable to malware and other security threats.","translation":"如果没有定期的软件更新，你的电脑就容易受到恶意软件和其他安全威胁的攻击。"},{"sentence":"The species is vulnerable to extinction due to habitat loss, which has accelerated in recent decades.","translation":"由于栖息地丧失，该物种容易灭绝，而近几十年来栖息地丧失的速度加快了。"},{"sentence":"Although the fortress was considered impregnable, its eastern wall was vulnerable to artillery fire.","translation":"尽管这座堡垒被认为是坚不可摧的，但其东墙容易受到炮火攻击。"}]},"cable":{"examples":[{"sentence":"Although the cable was buried deep underground, a construction accident severed it and disrupted the entire network.","translation":"尽管电缆深埋地下，但一次施工事故将其切断，导致整个网络中断。"},{"sentence":"The bridge's main cable, which consists of thousands of steel wires, must be inspected regularly to ensure structural integrity.","translation":"大桥的主缆由数千根钢丝组成，必须定期检查以确保结构完整性。"},{"sentence":"Because the undersea cable transmits data at high speeds, it has become a critical component of global communications.","translation":"由于海底电缆能高速传输数据，它已成为全球通信的关键组成部分。"},{"sentence":"Engineers used a durable synthetic cable to replace the worn steel one, thereby extending the elevator's service life.","translation":"工程师用耐用的合成缆绳替换了磨损的钢缆，从而延长了电梯的使用寿命。"},{"sentence":"When the power cable failed during the storm, emergency generators activated to maintain essential services.","translation":"当电力电缆在暴风雨中发生故障时，应急发电机启动以维持基本服务。"}]},"replace":{"examples":[{"sentence":"To improve efficiency, the company decided to replace manual processes with automated systems that reduce human error.","translation":"为了提高效率，公司决定用减少人为错误的自动化系统取代手动流程。"},{"sentence":"Although electric vehicles are gaining popularity, they cannot yet fully replace traditional cars due to charging infrastructure limitations.","translation":"尽管电动汽车越来越受欢迎，但由于充电基础设施的限制，它们还不能完全取代传统汽车。"},{"sentence":"The manager chose to replace the outdated software with a cloud-based platform, which allows for seamless collaboration.","translation":"经理选择用基于云的平台替换过时的软件，该平台可实现无缝协作。"},{"sentence":"If we replace fossil fuels with renewable energy sources, we can significantly reduce greenhouse gas emissions.","translation":"如果我们用可再生能源替代化石燃料，就能显著减少温室气体排放。"},{"sentence":"Rather than replace the entire machine, the technician repaired the faulty component, thereby saving time and resources.","translation":"技术人员没有更换整台机器，而是修理了故障部件，从而节省了时间和资源。"}]},"glimpse":{"examples":[{"sentence":"Although the fog obscured most of the landscape, we caught a brief glimpse of the ancient castle on the hill.","translation":"尽管大雾遮蔽了大部分景色，我们还是瞥见了山上的古堡。"},{"sentence":"The leaked document offers a rare glimpse into the company's long-term strategy, which has been kept secret for years.","translation":"这份泄露的文件让人难得一窥公司隐藏多年的长期战略。"},{"sentence":"While analyzing the data, the researcher caught a glimpse of a pattern that could revolutionize the field of medicine.","translation":"在分析数据时，研究者瞥见了一种可能彻底改变医学领域的模式。"},{"sentence":"Through a gap in the curtains, I caught a glimpse of the bustling street life that contrasted sharply with the quiet room.","translation":"透过窗帘的缝隙，我瞥见了熙熙攘攘的街景，与安静的房间形成鲜明对比。"},{"sentence":"The biography provides an intimate glimpse into the artist's struggles, thereby deepening our appreciation of his work.","translation":"这本传记让我们得以一窥艺术家的内心挣扎，从而加深了对其作品的理解。"}]},"common":{"examples":[{"sentence":"A common mistake among novice writers is to neglect the importance of a clear thesis statement, which weakens the entire essay.","translation":"新手作家常犯的一个错误是忽视清晰论点的重要性，这会削弱整篇文章。"},{"sentence":"Although the two theories appear distinct, they share a common foundation in the principles of quantum mechanics.","translation":"尽管这两种理论看似不同，但它们在量子力学原理上有着共同的基础。"},{"sentence":"It is common for international students to experience culture shock when they first arrive, but most adapt within a few months.","translation":"国际学生初到时普遍会经历文化冲击，但大多数在几个月内就能适应。"},{"sentence":"The researchers found a common genetic marker among patients, which may lead to earlier diagnosis of the disease.","translation":"研究人员在患者中发现了一种共同的遗传标记，这可能有助于更早诊断该疾病。"},{"sentence":"Because the two communities have a common interest in preserving the local environment, they decided to collaborate on a conservation project.","translation":"由于两个社区在保护当地环境方面有共同利益，他们决定合作开展一个保护项目。"}]},"murmur":{"examples":[{"sentence":"A murmur of discontent spread through the audience when the speaker refused to address their concerns.","translation":"当演讲者拒绝回应他们的关切时，一阵不满的低语在观众中蔓延开来。"},{"sentence":"The soft murmur of the wind through the pines created an atmosphere of profound tranquility in the mountain retreat.","translation":"风穿过松林时发出的轻柔低语，为山间静修地营造出一种深邃的宁静氛围。"},{"sentence":"Although the official report was optimistic, a murmur of doubt persisted among the researchers who had reviewed the raw data.","translation":"尽管官方报告持乐观态度，但审查过原始数据的研究人员中仍持续存在怀疑的低语。"},{"sentence":"The steady murmur of the city at night, punctuated by distant sirens, reminded him that he was never truly alone.","translation":"夜晚城市持续不断的低语，偶尔被远处的警笛声打断，提醒他从未真正独处过。"},{"sentence":"During the negotiation, a murmur of approval arose when the mediator proposed a compromise that protected both parties' core interests.","translation":"谈判期间，当调解人提出一项保护双方核心利益的妥协方案时，响起了一阵赞同的低语。"}]},"fragrant":{"examples":[{"sentence":"The fragrant steam rising from the jasmine tea filled the study with a sense of calm that sharpened her focus.","translation":"茉莉花茶升起的芬芳蒸汽充满了书房，带来一种宁静感，使她的注意力更加集中。"},{"sentence":"Because the garden was planted with fragrant herbs like rosemary and lavender, it attracted both pollinators and visitors seeking relaxation.","translation":"由于花园里种植了迷迭香和薰衣草等芬芳草本植物，它吸引了传粉昆虫和寻求放松的游客。"},{"sentence":"The fragrant blossoms of the orange trees, which lined the courtyard, served as a natural air purifier and a symbol of the region's agricultural heritage.","translation":"庭院旁成排的橙树盛开的芬芳花朵，充当了天然的空气净化器，也是该地区农业遗产的象征。"},{"sentence":"Although the dish was simple, the fragrant combination of garlic and fresh basil elevated it to a memorable culinary experience.","translation":"虽然这道菜很简单，但大蒜和新鲜罗勒的芬芳组合将其提升为一次难忘的美食体验。"},{"sentence":"The fragrant wood of the cedar chest, which had protected her grandmother's quilts for decades, evoked a powerful sense of family continuity.","translation":"雪松木箱的芬芳木材保护了她祖母的被子数十年，唤起了一种强烈的家族延续感。"}]},"bribe":{"examples":[{"sentence":"Although the mayor denied any wrongdoing, the leaked emails suggested that he had solicited a bribe from the developer.","translation":"尽管市长否认有任何不当行为，但泄露的电子邮件表明他曾向开发商索贿。"},{"sentence":"Because the customs officer refused to accept a bribe, the smuggler's illegal shipment was seized and destroyed.","translation":"由于海关官员拒绝接受贿赂，走私者的非法货物被扣押并销毁。"},{"sentence":"The bribe, which was offered in a discreet envelope, was immediately reported to the anti-corruption agency.","translation":"那笔用隐蔽信封递送的贿赂，被立即报告给了反腐败机构。"},{"sentence":"When the multinational corporation was caught paying a bribe to secure the mining rights, its stock price plummeted.","translation":"当这家跨国公司被发现为获取采矿权而行贿时，其股价暴跌。"},{"sentence":"The whistleblower provided evidence that a bribe had been used to influence the judge's ruling, thereby undermining public trust in the judiciary.","translation":"举报人提供了证据，表明有人用贿赂影响法官的裁决，从而破坏了公众对司法系统的信任。"}]},"stay":{"examples":[{"sentence":"The extended stay of international experts facilitated knowledge transfer, which accelerated the project's progress.","translation":"国际专家的长期停留促进了知识转移，从而加快了项目的进展。"},{"sentence":"Although a brief stay in a foreign country may seem insufficient, it can still provide valuable cultural insights.","translation":"虽然在国外短暂停留似乎不够，但它仍能提供宝贵的文化见解。"},{"sentence":"The policy requires a minimum stay of six months to ensure that researchers fully engage with the local community.","translation":"该政策要求至少停留六个月，以确保研究人员充分融入当地社区。"},{"sentence":"Because her stay was funded by a prestigious grant, she could focus entirely on her fieldwork without financial worries.","translation":"由于她的停留由一项著名资助支持，她可以完全专注于实地工作而无经济之忧。"},{"sentence":"A prolonged stay in a high-pressure environment often leads to burnout, which undermines long-term productivity.","translation":"在高压环境中的长期停留往往导致倦怠，从而损害长期生产力。"}]},"sausage":{"examples":[{"sentence":"Although sausage is a staple in many diets, its high sodium content poses health risks if consumed excessively.","translation":"虽然香肠是许多饮食中的主食，但如果过量食用，其高钠含量会带来健康风险。"},{"sentence":"The traditional sausage recipe, which has been passed down for generations, is now protected as cultural heritage.","translation":"这种世代相传的传统香肠配方如今被作为文化遗产加以保护。"},{"sentence":"Because the sausage market is highly competitive, producers must innovate to differentiate their products.","translation":"由于香肠市场竞争激烈，生产商必须创新以使产品差异化。"},{"sentence":"Researchers developed a plant-based sausage that mimics the texture of meat, thereby appealing to flexitarian consumers.","translation":"研究人员开发了一种模仿肉质口感的植物基香肠，从而吸引了弹性素食消费者。"},{"sentence":"When sausage is fermented under controlled conditions, it develops a distinct flavor that enhances culinary diversity.","translation":"当香肠在受控条件下发酵时，它会形成独特的风味，从而丰富烹饪多样性。"}]},"spade":{"examples":[{"sentence":"Although the soil was compacted, the gardener used a spade to turn it over before planting the vegetables.","translation":"尽管土壤板结，园丁还是用铲子翻土，然后种植蔬菜。"},{"sentence":"Because the trench needed to be precisely dug, the workers relied on a spade rather than a mechanical excavator.","translation":"因为沟渠需要精确挖掘，工人们依靠铲子而不是机械挖掘机。"},{"sentence":"When the archaeologist uncovered the artifact, she carefully wielded a spade to avoid damaging the surrounding area.","translation":"当考古学家发现文物时，她小心地使用铲子，以免损坏周围区域。"},{"sentence":"The farmer sharpened the spade before digging the irrigation channel, which ensured a clean cut through the roots.","translation":"农民在挖掘灌溉渠之前磨快了铲子，这确保了干净地切断根系。"},{"sentence":"Despite the availability of modern tools, the traditional spade remains essential for tasks that require manual precision.","translation":"尽管有现代工具可用，传统的铲子对于需要手工精确度的任务仍然必不可少。"}]},"fresh":{"examples":[{"sentence":"The research team proposed a fresh approach to data analysis, which yielded more accurate results than previous methods.","translation":"研究团队提出了一种新的数据分析方法，这比之前的方法得出了更准确的结果。"},{"sentence":"After a short break, the students returned to their studies with fresh energy, thereby improving their concentration.","translation":"短暂休息后，学生们带着充沛的精力重新投入到学习中，从而提高了注意力。"},{"sentence":"Consuming fresh vegetables daily is essential for maintaining a balanced diet, because they provide vital nutrients.","translation":"每天食用新鲜蔬菜对于保持均衡饮食至关重要，因为它们提供重要的营养素。"},{"sentence":"The company hired a fresh graduate who brought innovative ideas to the marketing department, which revitalized the team.","translation":"公司雇佣了一名应届毕业生，他为市场部带来了创新的想法，这使团队重新焕发了活力。"},{"sentence":"To preserve the environment, many communities are investing in technologies that convert seawater into fresh water.","translation":"为了保护环境，许多社区正在投资将海水转化为淡水的技术。"}]},"confer":{"examples":[{"sentence":"Although the award may confer prestige, it does not guarantee long-term career success.","translation":"尽管这个奖项可能带来声望，但它并不能保证长期的职业成功。"},{"sentence":"The committee will confer with external experts before making a final decision, thereby ensuring a well-informed outcome.","translation":"委员会将在做出最终决定之前与外部专家协商，从而确保结果充分知情。"},{"sentence":"Because the new policy could confer significant advantages on small businesses, it has received widespread support.","translation":"由于新政策可能给小企业带来显著优势，它得到了广泛支持。"},{"sentence":"Universities confer degrees upon students who have fulfilled all academic requirements, which serves as a formal recognition of their achievement.","translation":"大学授予满足所有学术要求的学生学位，这是对他们成就的正式认可。"},{"sentence":"When leaders confer with stakeholders, they can identify potential risks that might otherwise be overlooked.","translation":"当领导者与利益相关者协商时，他们能够识别出可能被忽视的潜在风险。"}]},"empirical":{"examples":[{"sentence":"Empirical research, which relies on observable data, is fundamental to the advancement of science.","translation":"依赖可观察数据的实证研究是科学进步的基础。"},{"sentence":"Although the hypothesis was plausible, it lacked empirical support and was therefore rejected.","translation":"尽管这个假设看似合理，但缺乏实证支持，因此被拒绝了。"},{"sentence":"Policy decisions should be based on empirical evidence rather than on intuition, because this leads to more effective outcomes.","translation":"政策决策应基于实证证据而非直觉，因为这会带来更有效的结果。"},{"sentence":"When conducting empirical studies, researchers must control for confounding variables to ensure valid conclusions.","translation":"在进行实证研究时，研究者必须控制混杂变量，以确保结论有效。"},{"sentence":"The empirical data, which was collected over a decade, revealed a significant correlation between diet and health.","translation":"这些收集了十年的实证数据揭示了饮食与健康之间的显著相关性。"}]},"province":{"examples":[{"sentence":"Sichuan province, which is famous for its spicy cuisine and giant pandas, attracts millions of tourists each year.","translation":"四川省以其辛辣美食和大熊猫而闻名，每年吸引数百万游客。"},{"sentence":"Although the province has a relatively small population, its economic output rivals that of many larger regions due to its thriving tech industry.","translation":"尽管该省人口相对较少，但由于其蓬勃发展的科技产业，其经济产出可与许多更大的地区相媲美。"},{"sentence":"Because the province implemented strict environmental regulations, air quality has improved significantly over the past five years.","translation":"由于该省实施了严格的环境法规，过去五年空气质量显著改善。"},{"sentence":"The cultural traditions of this province, which include unique folk dances and festivals, have been preserved for centuries.","translation":"该省的文化传统，包括独特的民间舞蹈和节日，已经保存了几个世纪。"},{"sentence":"While the central government oversees national defense, each province is responsible for managing its own education and healthcare systems.","translation":"虽然中央政府负责国防，但每个省负责管理自己的教育和医疗系统。"}]},"direction":{"examples":[{"sentence":"Although she had no formal training, her innate sense of direction guided her through the unfamiliar city.","translation":"尽管她没有受过正式训练，但她天生的方向感引导她穿过了这座陌生的城市。"},{"sentence":"The committee decided to change the research direction because the initial approach yielded no significant results.","translation":"委员会决定改变研究方向，因为最初的方法没有产生显著成果。"},{"sentence":"Under the direction of a renowned conductor, the orchestra delivered a performance that moved the entire audience.","translation":"在一位著名指挥家的指导下，管弦乐队进行了一场感动全体观众的演出。"},{"sentence":"While the company expanded rapidly, it lacked a clear strategic direction, which eventually led to its decline.","translation":"虽然公司迅速扩张，但缺乏明确的战略方向，这最终导致了它的衰落。"},{"sentence":"The new policy steered the economy in a direction that favored sustainable development over short-term gains.","translation":"新政策将经济引向了一个有利于可持续发展而非短期收益的方向。"}]},"volcano":{"examples":[{"sentence":"Because the volcano is located near a densely populated area, authorities have developed a comprehensive evacuation plan to ensure public safety.","translation":"由于这座火山位于人口稠密地区附近，当局已制定全面的疏散计划以确保公共安全。"},{"sentence":"The volcano, which last erupted over a century ago, is now a popular tourist attraction that draws thousands of visitors annually.","translation":"这座火山上一次喷发是在一个多世纪前，现在是一个受欢迎的旅游景点，每年吸引成千上万的游客。"},{"sentence":"When a volcano erupts, it releases not only lava and ash but also gases that can affect the global climate for years.","translation":"火山喷发时，不仅会释放熔岩和火山灰，还会释放出可能影响全球气候多年的气体。"},{"sentence":"Studying the geological history of a volcano helps scientists predict future eruptions, thereby reducing potential damage to surrounding communities.","translation":"研究火山的地质历史有助于科学家预测未来的喷发，从而减少对周边社区的潜在损害。"},{"sentence":"Although the volcano is currently dormant, continuous monitoring is essential because seismic activity could resume at any time.","translation":"尽管这座火山目前处于休眠状态，但持续监测至关重要，因为地震活动可能随时恢复。"}]},"jazz":{"examples":[{"sentence":"Jazz, which emerged from a fusion of African and European musical traditions, has evolved into a globally celebrated art form.","translation":"爵士乐源于非洲和欧洲音乐传统的融合，已发展成为一种全球赞誉的艺术形式。"},{"sentence":"Because jazz emphasizes improvisation, it allows musicians to express their individuality while collaborating with others in real time.","translation":"由于爵士乐强调即兴创作，它允许音乐家在实时合作中表达个性。"},{"sentence":"The jazz concert not only showcased the talents of veteran performers but also introduced promising young artists to the audience.","translation":"这场爵士音乐会不仅展示了资深表演者的才华，还向观众介绍了有前途的年轻艺术家。"},{"sentence":"Although jazz was once considered controversial, it is now studied in academic institutions for its complex harmonic structures and cultural significance.","translation":"尽管爵士乐曾被认为有争议，但现在因其复杂的和声结构和文化意义而在学术机构中被研究。"},{"sentence":"Listening to jazz can enhance cognitive flexibility, which is why some educators incorporate it into learning environments to stimulate creative thinking.","translation":"听爵士乐可以增强认知灵活性，这就是为什么一些教育工作者将其融入学习环境以激发创造性思维。"}]},"stab":{"examples":[{"sentence":"Although he had no formal training, he decided to take a stab at writing a novel during his summer break.","translation":"尽管他没有受过正规训练，他还是决定在暑假期间尝试写一部小说。"},{"sentence":"When the startup failed, the investors felt a sharp stab of disappointment, which prompted them to reassess their strategy.","translation":"当创业公司失败时，投资者们感到一阵强烈的失望，这促使他们重新评估自己的策略。"},{"sentence":"She made a stab at explaining the complex theory to the audience, using simple analogies to ensure clarity.","translation":"她尝试向观众解释这个复杂的理论，用简单的类比来确保清晰。"},{"sentence":"The sudden stab of pain in his chest made him realize that he had been neglecting his health for too long.","translation":"胸口突然的刺痛使他意识到自己忽视健康太久了。"},{"sentence":"Because the deadline was approaching, the team took a stab at completing the project, even though resources were limited.","translation":"由于截止日期临近，团队尝试完成项目，尽管资源有限。"}]},"curl":{"examples":[{"sentence":"Although the metal sheet was initially flat, exposure to intense heat caused it to curl at the edges.","translation":"尽管金属板最初是平的，但暴露在高温下导致其边缘卷曲。"},{"sentence":"The calligrapher added a delicate curl to the final stroke, which gave the character a sense of graceful movement.","translation":"书法家在最后一笔上添加了一个精致的卷曲，这赋予了字体一种优雅的动感。"},{"sentence":"Because the wooden frame absorbed moisture from the air, a noticeable curl developed along the bottom of the canvas.","translation":"由于木框吸收了空气中的水分，画布底部出现了明显的翘曲。"},{"sentence":"The architect designed the roof with a gentle curl that channels rainwater into a collection system, thereby reducing water waste.","translation":"建筑师将屋顶设计成一道柔和的曲线，以便将雨水导入收集系统，从而减少水资源浪费。"},{"sentence":"When the dancer performed, a single curl of her hair escaped from the bun and swayed with every turn.","translation":"当舞者表演时，一缕卷发从发髻中散落出来，随着每一个转身而摇曳。"}]},"exterior":{"examples":[{"sentence":"Although the building's exterior appears modern, its interior retains many traditional elements that reflect local culture.","translation":"尽管建筑的外部看起来很现代，但其内部保留了许多反映当地文化的传统元素。"},{"sentence":"The committee decided to restore only the exterior of the historic theater, which had suffered significant weather damage over the decades.","translation":"委员会决定仅修复这座历史剧院的外部，因为它在几十年间遭受了严重的风雨侵蚀。"},{"sentence":"Because the device has a rugged exterior, it can withstand harsh environmental conditions without compromising internal components.","translation":"由于该设备有着坚固的外壳，它能承受恶劣的环境条件而不损害内部组件。"},{"sentence":"Underneath her calm exterior, she was meticulously planning every stage of the negotiation, which ultimately led to a favorable outcome.","translation":"在她平静的外表之下，她正周密地规划着谈判的每一个阶段，这最终带来了有利的结果。"},{"sentence":"The minimalist exterior of the museum, clad in local stone, helps it blend harmoniously with the surrounding landscape while providing a striking visual contrast.","translation":"博物馆极简的外立面采用本地石材，使其与周边景观和谐相融，同时形成鲜明的视觉对比。"}]},"considerable":{"examples":[{"sentence":"Although the initial investment is considerable, the long-term savings from energy efficiency will offset the cost.","translation":"尽管初期投资相当大，但能源效率带来的长期节省将抵消成本。"},{"sentence":"The research team devoted considerable effort to verifying the data, which ensured the accuracy of their published findings.","translation":"研究团队投入了相当大的精力来核实数据，这确保了他们发表的研究结果的准确性。"},{"sentence":"Because the new policy imposes considerable costs on small businesses, lawmakers are debating a phased implementation to ease the burden.","translation":"由于新政策给小型企业带来了可观的成本，立法者正在讨论分阶段实施以减轻负担。"},{"sentence":"Her considerable experience in cross-cultural communication made her an ideal candidate for the international project, which required frequent travel.","translation":"她在跨文化交流方面的丰富经验，使她成为该国际项目的理想人选，该项目需要频繁出差。"},{"sentence":"The city has allocated considerable resources to expanding public transportation, thereby reducing traffic congestion and improving air quality.","translation":"该市已拨出大量资源用于扩建公共交通，从而缓解交通拥堵并改善空气质量。"}]},"operational":{"examples":[{"sentence":"Although the new factory is fully automated, it requires skilled technicians to keep the machinery operational.","translation":"尽管新工厂是全自动化的，但它需要熟练的技术人员来保持机器正常运转。"},{"sentence":"The charity will expand its services only if it secures enough operational funds to cover daily expenses.","translation":"该慈善机构只有在获得足够的运营资金来支付日常开支时，才会扩大其服务。"},{"sentence":"Because the airport's radar system became non-operational during the storm, all flights were delayed.","translation":"由于机场的雷达系统在暴风雨中失灵，所有航班都被延误了。"},{"sentence":"Managers must ensure that the backup generators are operational, which is critical for maintaining data center uptime.","translation":"管理人员必须确保备用发电机正常运行，这对于维持数据中心的正常运行时间至关重要。"},{"sentence":"The new policy will become operational next month, thereby standardizing procedures across all departments.","translation":"新政策将于下个月生效，从而使所有部门的程序标准化。"}]},"affiliate":{"examples":[{"sentence":"Many small hospitals choose to affiliate with larger networks, which allows them to share resources and reduce costs.","translation":"许多小型医院选择附属于更大的网络，这使它们能够共享资源并降低成本。"},{"sentence":"Although the research center is independent, it decided to affiliate with the university to access federal grants.","translation":"尽管该研究中心是独立的，但它决定附属于这所大学以获得联邦资助。"},{"sentence":"The local sports club will affiliate with the national association, thereby gaining eligibility for official competitions.","translation":"当地体育俱乐部将加入全国协会，从而获得参加官方比赛的资格。"},{"sentence":"Because the company wanted to expand into new markets, it chose to affiliate with a well-established foreign partner.","translation":"由于该公司想拓展新市场，它选择与一家成熟的外国合作伙伴建立联系。"},{"sentence":"Professionals who affiliate with accredited organizations often enhance their credibility, which can lead to career advancement.","translation":"加入经认可组织的专业人士通常会提高他们的可信度，这可能会带来职业发展。"}]},"hole":{"examples":[{"sentence":"The unexpected resignation of the CEO left a hole in the company's leadership, which the board struggled to fill quickly.","translation":"首席执行官的意外辞职给公司领导层留下了一个空缺，董事会难以迅速填补。"},{"sentence":"Because the budget had a significant hole, the project manager had to cut several non-essential activities.","translation":"由于预算存在巨大缺口，项目经理不得不削减几项非必要活动。"},{"sentence":"The new evidence revealed a hole in the defendant's alibi, thereby casting doubt on his innocence.","translation":"新证据揭示了被告不在场证明中的一个漏洞，从而对他的清白产生了怀疑。"},{"sentence":"Although the software was thoroughly tested, a security hole allowed hackers to access sensitive data.","translation":"尽管该软件经过了全面测试，但一个安全漏洞使黑客能够访问敏感数据。"},{"sentence":"The drought created a hole in the region's water supply, which forced authorities to impose strict rationing.","translation":"干旱给该地区的供水造成了一个缺口，迫使当局实施严格的配给。"}]},"context":{"examples":[{"sentence":"Although the statement seems controversial, understanding its historical context reveals a more nuanced perspective.","translation":"尽管这一说法看似有争议，但了解其历史背景会揭示出更微妙的视角。"},{"sentence":"Because the cultural context influences interpretation, researchers must adapt their methods when studying different societies.","translation":"由于文化背景影响解读，研究人员在研究不同社会时必须调整方法。"},{"sentence":"While the data appears inconsistent, placing it within the broader economic context clarifies the underlying trends.","translation":"虽然数据看似不一致，但将其置于更广泛的经济背景中就能阐明潜在趋势。"},{"sentence":"The policy, which was criticized initially, gained acceptance when its social context was fully explained.","translation":"这项最初受到批评的政策，在其社会背景得到充分解释后获得了认可。"},{"sentence":"To ensure accurate translation, one must consider the linguistic context rather than relying solely on dictionary definitions.","translation":"为确保翻译准确，必须考虑语言上下文，而不是仅仅依赖字典定义。"}]},"classic":{"examples":[{"sentence":"Although written centuries ago, this novel remains a classic because it explores timeless human dilemmas.","translation":"尽管写于几个世纪前，这部小说仍是经典，因为它探讨了永恒的人类困境。"},{"sentence":"The study, which introduced groundbreaking methodology, has become a classic in the field of psychology.","translation":"这项引入了开创性方法的研究，已成为心理学领域的经典。"},{"sentence":"While many films fade into obscurity, this one endures as a classic due to its innovative storytelling.","translation":"虽然许多电影逐渐被人遗忘，但这部因其创新的叙事手法而成为经典。"},{"sentence":"Because it captures the essence of an era, the documentary is now regarded as a classic of historical filmmaking.","translation":"由于它捕捉了一个时代的精髓，这部纪录片现在被视为历史电影制作的经典。"},{"sentence":"The theory, despite its age, remains a classic that continues to influence contemporary scientific thought.","translation":"尽管年代久远，这一理论仍是经典，持续影响着当代科学思想。"}]},"therapy":{"examples":[{"sentence":"Although medication is common, cognitive behavioral therapy often yields longer-lasting results for anxiety disorders.","translation":"尽管药物治疗很常见，但认知行为疗法通常对焦虑症产生更持久的效果。"},{"sentence":"Because physical therapy requires consistent effort, patients who adhere to the regimen recover more quickly.","translation":"由于物理治疗需要持续努力，坚持治疗计划的患者恢复得更快。"},{"sentence":"While gene therapy offers hope for rare diseases, its high cost limits accessibility for many patients.","translation":"虽然基因疗法为罕见病带来希望，但其高昂的费用限制了许多患者的可及性。"},{"sentence":"Art therapy, which uses creative expression, can help trauma victims process emotions that are difficult to verbalize.","translation":"艺术疗法利用创造性表达，可以帮助创伤受害者处理难以用语言表达的情感。"},{"sentence":"To ensure holistic recovery, the rehabilitation program combines occupational therapy with psychological counseling.","translation":"为确保全面康复，该康复计划将作业疗法与心理咨询相结合。"}]},"neat":{"examples":[{"sentence":"Although the laboratory was small, the researchers maintained a neat arrangement of equipment, which minimized contamination risks.","translation":"尽管实验室很小，但研究人员保持了设备的整洁排列，从而将污染风险降至最低。"},{"sentence":"The engineer proposed a neat algorithm that reduced computational time by half, thereby increasing the system's overall efficiency.","translation":"工程师提出了一种巧妙的算法，将计算时间缩短了一半，从而提高了系统的整体效率。"},{"sentence":"Because her notes were exceptionally neat, she was able to review the entire semester's material in just one evening.","translation":"因为她的笔记异常整洁，所以她能够在一个晚上内复习整个学期的材料。"},{"sentence":"The architect's neat integration of green spaces into the urban design not only improved aesthetics but also enhanced air quality.","translation":"建筑师将绿色空间巧妙地融入城市设计，不仅提升了美感，还改善了空气质量。"},{"sentence":"When presenting complex data, a neat visualization can help the audience grasp key trends without extensive explanation.","translation":"在展示复杂数据时，简洁的可视化可以帮助观众无需大量解释就能掌握关键趋势。"}]},"differentiate":{"examples":[{"sentence":"To differentiate between correlation and causation, researchers must design controlled experiments that isolate variables.","translation":"为了区分相关性和因果关系，研究人员必须设计能够隔离变量的对照实验。"},{"sentence":"Although the twins looked identical, their teachers could differentiate them by their distinct learning styles.","translation":"尽管这对双胞胎看起来一模一样，但他们的老师可以通过他们不同的学习风格来区分他们。"},{"sentence":"The new diagnostic tool can differentiate malignant tumors from benign ones with high accuracy, which reduces unnecessary surgeries.","translation":"这种新的诊断工具能够高精度地区分恶性肿瘤和良性肿瘤，从而减少了不必要的手术。"},{"sentence":"Because the two species share a common ancestor, it is often difficult to differentiate them based solely on morphological traits.","translation":"因为这两个物种有共同的祖先，所以通常很难仅凭形态特征来区分它们。"},{"sentence":"Effective branding helps a company differentiate its products in a crowded market, thereby attracting loyal customers.","translation":"有效的品牌塑造有助于公司在拥挤的市场中区分其产品，从而吸引忠实的客户。"}]},"statute":{"examples":[{"sentence":"Although the statute was enacted to protect consumer rights, its enforcement has been inconsistent across different regions.","translation":"尽管该法规旨在保护消费者权益，但其在不同地区的执行情况并不一致。"},{"sentence":"Because the statute imposes strict liability on manufacturers, companies must ensure their products meet all safety standards.","translation":"由于该法规对制造商施加严格责任，公司必须确保其产品符合所有安全标准。"},{"sentence":"The statute, which was passed unanimously by the legislature, represents a significant shift in environmental policy.","translation":"该法规由立法机构一致通过，代表了环境政策的重大转变。"},{"sentence":"While the statute provides clear guidelines for data protection, many small businesses struggle to comply with its requirements.","translation":"虽然该法规为数据保护提供了明确的指导方针，但许多小企业难以遵守其要求。"},{"sentence":"The statute not only defines the penalties for corporate fraud but also establishes a framework for whistleblower protection.","translation":"该法规不仅定义了公司欺诈的处罚，还建立了举报人保护框架。"}]},"bridge":{"examples":[{"sentence":"Because the bridge connects two major economic zones, its closure for repairs caused significant disruption to local businesses.","translation":"由于这座桥连接着两个主要经济区，其关闭维修给当地企业造成了严重干扰。"},{"sentence":"The bridge, which was designed by a renowned architect, has become an iconic landmark that attracts tourists from around the world.","translation":"这座由著名建筑师设计的桥已成为一个标志性地标，吸引着来自世界各地的游客。"},{"sentence":"While the bridge was built to withstand severe weather, the unprecedented storm still caused structural damage that required immediate attention.","translation":"虽然这座桥是为抵御恶劣天气而建造的，但这场史无前例的风暴仍然造成了需要立即关注的结构损坏。"},{"sentence":"The bridge not only facilitates the daily commute of thousands of residents but also serves as a critical route for emergency services.","translation":"这座桥不仅方便了数千居民的日常通勤，也是紧急服务的关键路线。"},{"sentence":"Engineers used advanced materials to construct the bridge, thereby extending its expected lifespan by several decades.","translation":"工程师使用先进材料建造了这座桥，从而将其预期寿命延长了几十年。"}]},"underestimate":{"examples":[{"sentence":"An underestimate of the project's complexity often leads to unrealistic timelines, which can compromise the quality of the final deliverable.","translation":"对项目复杂性的低估常常导致不切实际的时间表，这可能会损害最终交付成果的质量。"},{"sentence":"Because the initial underestimate of the market demand was not revised, the company faced severe shortages during the product launch.","translation":"由于最初对市场需求的低估没有修正，公司在产品发布期间面临严重短缺。"},{"sentence":"The underestimate of the opponent's strength, which was based on outdated intelligence, resulted in a strategic miscalculation that cost the team the championship.","translation":"基于过时情报对对手实力的低估导致了战略误判，使团队失去了冠军。"},{"sentence":"While an underestimate of the risks may accelerate decision-making, it can also expose the organization to unforeseen liabilities.","translation":"虽然低估风险可能会加速决策，但也可能使组织面临不可预见的责任。"},{"sentence":"The financial underestimate of the long-term maintenance costs made the infrastructure project appear viable, whereas a thorough analysis would have revealed its true expense.","translation":"对长期维护成本的财务低估使该基础设施项目看起来可行，而彻底的分析会揭示其真实费用。"}]},"apart":{"examples":[{"sentence":"Although the two communities live apart, they maintain a strong cultural connection through annual festivals.","translation":"尽管这两个社区分开居住，他们通过年度节日保持着紧密的文化联系。"},{"sentence":"When a society is torn apart by inequality, social cohesion becomes difficult to restore without deliberate policy interventions.","translation":"当一个社会因不平等而四分五裂时，如果没有刻意的政策干预，社会凝聚力就难以恢复。"},{"sentence":"Apart from providing financial support, the scholarship program offers mentorship that helps students navigate academic challenges.","translation":"除了提供经济支持，该奖学金项目还提供指导，帮助学生应对学业挑战。"},{"sentence":"Because the two studies were conducted years apart, their findings must be compared with caution to account for contextual changes.","translation":"由于这两项研究相隔多年进行，在比较其发现时必须谨慎，以考虑背景变化。"},{"sentence":"Setting apart time for reflection each day is a habit that many successful leaders credit for their clarity of thought.","translation":"每天留出时间进行反思是许多成功领导者认为有助于思维清晰的习惯。"}]},"customary":{"examples":[{"sentence":"In many East Asian societies, it is customary to bow when greeting elders, a practice that reflects deep-rooted Confucian values.","translation":"在许多东亚社会，问候长辈时鞠躬是习惯性的做法，这反映了根深蒂固的儒家价值观。"},{"sentence":"Although digital communication has become prevalent, it is still customary in formal business settings to send a handwritten thank-you note after an interview.","translation":"尽管数字通信已变得普遍，但在正式的商务场合，面试后寄送手写感谢信仍然是习惯性的做法。"},{"sentence":"In academic conferences, it is customary for the presenter to provide a brief overview before delving into the details, ensuring that the audience can follow the argument.","translation":"在学术会议上，演讲者在深入细节之前先提供一个简要概述是习惯性的做法，这确保听众能够跟上论述。"},{"sentence":"While remote work offers flexibility, it is customary for teams to hold a weekly video call to maintain cohesion and align on priorities.","translation":"虽然远程工作提供了灵活性，但团队每周举行一次视频电话以保持凝聚力并对齐优先事项是习惯性的做法。"},{"sentence":"In many cultures, it is customary to bring a small gift when invited to someone's home, as a token of appreciation for the host's hospitality.","translation":"在许多文化中，当受邀到别人家时带一份小礼物是习惯性的做法，作为对主人款待的感谢。"}]},"evaluate":{"examples":[{"sentence":"Before adopting the new curriculum, the education board must evaluate its effectiveness through pilot studies, which provide empirical evidence.","translation":"在采用新课程之前，教育委员会必须通过试点研究评估其有效性，这些研究提供实证证据。"},{"sentence":"To ensure a fair selection process, the committee will evaluate all candidates based on standardized criteria, rather than subjective impressions.","translation":"为了确保选拔过程公平，委员会将根据标准化标准而非主观印象来评估所有候选人。"},{"sentence":"Investors should carefully evaluate the potential risks of emerging markets, because these markets often exhibit high volatility and regulatory uncertainty.","translation":"投资者应仔细评估新兴市场的潜在风险，因为这些市场往往表现出高波动性和监管不确定性。"},{"sentence":"The study aims to evaluate whether mindfulness training can significantly reduce stress among healthcare workers, thereby improving patient care.","translation":"该研究旨在评估正念训练是否能显著减轻医护人员的压力，从而改善患者护理。"},{"sentence":"Although the initial results were promising, the researchers could not fully evaluate the long-term effects due to insufficient data, which limited their conclusions.","translation":"尽管初步结果令人鼓舞，但由于数据不足，研究人员无法全面评估长期效果，这限制了他们的结论。"}]},"whirl":{"examples":[{"sentence":"The whirl of technological change, which shows no sign of slowing, demands continuous learning from professionals.","translation":"技术变革的旋风毫无减缓迹象，要求专业人士不断学习。"},{"sentence":"Although she was caught in a whirl of social engagements, she managed to complete her thesis on time.","translation":"尽管她陷入了社交活动的旋风中，但她还是按时完成了论文。"},{"sentence":"The whirl of rumors surrounding the merger created uncertainty, thereby affecting the company's stock price.","translation":"围绕合并的谣言旋风造成了不确定性，从而影响了公司股价。"},{"sentence":"Because the whirl of daily tasks can be overwhelming, effective time management is essential for maintaining productivity.","translation":"由于日常任务的旋风可能令人难以招架，有效的时间管理对于保持生产力至关重要。"},{"sentence":"The whirl of activity during the festival, while exciting, often leads to logistical challenges for city planners.","translation":"节日期间的活动旋风虽然令人兴奋，但常常给城市规划者带来后勤挑战。"}]},"grass":{"examples":[{"sentence":"Although grass is often overlooked, it serves as a vital carbon sink that mitigates climate change.","translation":"尽管草常被忽视，但它作为重要的碳汇，能缓解气候变化。"},{"sentence":"The introduction of native grass species, which require less water, has transformed the park into a sustainable landscape.","translation":"引入需水量较少的本地草种，已将公园转变为可持续的景观。"},{"sentence":"Because overgrazing depletes grass cover, it accelerates soil erosion and desertification in fragile ecosystems.","translation":"由于过度放牧耗尽了草被，它加速了脆弱生态系统中的水土流失和荒漠化。"},{"sentence":"When grass is used as a biofuel feedstock, it offers a renewable alternative to fossil fuels without competing with food crops.","translation":"当草被用作生物燃料原料时，它提供了一种可再生的化石燃料替代品，且不与粮食作物竞争。"},{"sentence":"The study found that grass buffers along waterways effectively filter pollutants, thereby improving water quality.","translation":"研究发现，水道旁的草缓冲带能有效过滤污染物，从而改善水质。"}]},"wind":{"examples":[{"sentence":"Although the wind was strong enough to uproot trees, the old lighthouse stood firm against the gale.","translation":"尽管风力强大到足以将树连根拔起，但这座古老的灯塔在狂风中依然屹立不倒。"},{"sentence":"Because the wind carried the scent of rain, the farmers hurried to bring in the harvest before the storm arrived.","translation":"因为风带来了雨的气息，农民们急忙在暴风雨来临前收割庄稼。"},{"sentence":"The architect designed the skyscraper with a tapered shape, which reduces wind resistance and prevents structural sway.","translation":"建筑师将摩天大楼设计成锥形，从而减少风阻并防止结构摇摆。"},{"sentence":"When the wind turbines rotate at full capacity, they generate enough electricity to power thousands of homes.","translation":"当风力涡轮机全速旋转时，它们产生的电力足以供应数千户家庭。"},{"sentence":"Without wind to disperse pollutants, the city's air quality would deteriorate rapidly, posing serious health risks.","translation":"如果没有风来吹散污染物，城市的空气质量将迅速恶化，构成严重的健康风险。"}]},"vision":{"examples":[{"sentence":"Because prolonged screen time can strain your vision, experts recommend taking regular breaks to focus on distant objects.","translation":"因为长时间看屏幕会使视力疲劳，专家建议定期休息，眺望远处物体。"},{"sentence":"The company's vision, which emphasizes sustainable innovation, has guided its research and development strategy for decades.","translation":"该公司强调可持续创新的愿景，几十年来一直指导着其研发战略。"},{"sentence":"Although he lost his vision in childhood, he developed remarkable auditory skills that allowed him to excel as a musician.","translation":"尽管他在童年时失去了视力，但他培养了非凡的听觉技能，这使他成为一名杰出的音乐家。"},{"sentence":"A leader with a clear vision can inspire a team to overcome obstacles and achieve ambitious goals that initially seem unattainable.","translation":"一位有清晰愿景的领导者能够激励团队克服障碍，实现最初看似无法达成的宏伟目标。"},{"sentence":"The government's vision for urban development includes creating green spaces that enhance both environmental quality and public health.","translation":"政府的城市发展愿景包括创建既能改善环境质量又能促进公共健康的绿色空间。"}]},"fur":{"examples":[{"sentence":"Many Arctic animals have thick fur that insulates them against temperatures far below freezing.","translation":"许多北极动物拥有厚实的毛皮，能够使它们抵御远低于冰点的温度。"},{"sentence":"The conservation group argued that banning fur farming would reduce animal suffering without harming the economy.","translation":"该保护组织认为，禁止毛皮养殖将减少动物痛苦，同时不会损害经济。"},{"sentence":"When the cat's fur began to mat, the veterinarian recommended a special diet to improve its condition.","translation":"当猫的毛开始打结时，兽医推荐了一种特殊饮食来改善其状况。"},{"sentence":"Although synthetic alternatives now mimic real fur closely, some designers still prefer natural materials for their durability.","translation":"尽管合成替代品现在能逼真地模仿真毛皮，但一些设计师仍因其耐用性而偏爱天然材料。"},{"sentence":"The biologist examined the fur samples under a microscope to determine which species had been present in the area.","translation":"生物学家在显微镜下检查毛皮样本，以确定该地区曾出现过哪些物种。"}]},"integrity":{"examples":[{"sentence":"Although the pressure to succeed was immense, she maintained her integrity by refusing to cheat on the exam.","translation":"尽管成功的压力巨大，她仍通过拒绝在考试中作弊来保持自己的正直。"},{"sentence":"The structural integrity of the bridge was compromised because the engineers overlooked a critical flaw in the design.","translation":"桥梁的结构完整性受到了损害，因为工程师们忽视了设计中的一个关键缺陷。"},{"sentence":"When a journalist fabricates sources, the integrity of the entire news organization is called into question.","translation":"当一名记者捏造消息来源时，整个新闻机构的诚信都会受到质疑。"},{"sentence":"To ensure the integrity of the data, researchers must follow strict protocols that prevent unauthorized alterations.","translation":"为了确保数据的完整性，研究人员必须遵循严格的规程，以防止未经授权的更改。"},{"sentence":"A society that values integrity over personal gain is more likely to foster trust and cooperation among its citizens.","translation":"一个重视正直而非个人利益的社会更有可能在其公民之间培养信任与合作。"}]},"net":{"examples":[{"sentence":"Because the fisherman used a net with smaller mesh, he was able to catch shrimp that would otherwise have escaped.","translation":"因为渔夫使用了网眼更小的渔网，他捕到了原本会逃走的虾。"},{"sentence":"The company's net income rose significantly after it divested its unprofitable divisions, thereby focusing on core operations.","translation":"在剥离了不盈利的部门后，公司的净收入显著上升，从而专注于核心业务。"},{"sentence":"While the butterfly net was designed for delicate insects, it proved sturdy enough to withstand strong winds.","translation":"尽管捕蝶网是为脆弱的昆虫设计的，但它被证明足够坚固，能够抵御强风。"},{"sentence":"Installing a safety net beneath the trapeze artists not only protects them from falls but also boosts their confidence.","translation":"在秋千艺术家下方安装安全网不仅能保护他们免于坠落，还能增强他们的信心。"},{"sentence":"The government's social safety net, which includes unemployment benefits and food assistance, helps families during economic downturns.","translation":"政府的社会安全网，包括失业救济和食品援助，在经济衰退期间帮助了家庭。"}]},"marine":{"examples":[{"sentence":"Although marine ecosystems are resilient, they are increasingly threatened by pollution and overfishing.","translation":"尽管海洋生态系统具有恢复力，但它们正日益受到污染和过度捕捞的威胁。"},{"sentence":"Because marine transportation is vital for global trade, ports must operate efficiently around the clock.","translation":"因为海运对全球贸易至关重要，港口必须全天候高效运作。"},{"sentence":"The government established a marine sanctuary, which protects endangered species from human interference.","translation":"政府建立了一个海洋保护区，这保护了濒危物种免受人类干扰。"},{"sentence":"While marine biologists study deep-sea organisms, they often discover species that defy conventional classification.","translation":"当海洋生物学家研究深海生物时，他们经常发现挑战传统分类的物种。"},{"sentence":"To ensure sustainable fisheries, policymakers must consider the complex dynamics of marine food webs.","translation":"为了确保渔业的可持续性，政策制定者必须考虑海洋食物网的复杂动态。"}]},"obey":{"examples":[{"sentence":"Although the new regulation seemed burdensome, all employees had to obey it to ensure workplace safety.","translation":"尽管新规定看似繁琐，但所有员工都必须遵守，以确保工作场所安全。"},{"sentence":"Children who obey their parents' guidance often develop stronger self-discipline, which benefits their academic performance.","translation":"听从父母指导的孩子往往能培养更强的自律性，这有利于他们的学业表现。"},{"sentence":"Because the court's ruling is legally binding, all parties must obey it without delay.","translation":"因为法院的裁决具有法律约束力，所有当事方都必须立即遵守。"},{"sentence":"In a well-functioning society, citizens obey laws not only to avoid penalties but also to uphold social order.","translation":"在一个运转良好的社会中，公民遵守法律不仅是为了避免惩罚，也是为了维护社会秩序。"},{"sentence":"The experiment revealed that people tend to obey authority figures even when their instructions conflict with personal conscience.","translation":"实验表明，即使指令与个人良知相冲突，人们也倾向于服从权威人物。"}]},"lottery":{"examples":[{"sentence":"Although winning the lottery seems like a quick path to wealth, the probability of success is extremely low.","translation":"虽然中彩票看似是快速致富的途径，但成功的概率极低。"},{"sentence":"The government allocates lottery proceeds to public welfare programs, thereby improving community services.","translation":"政府将彩票收益分配给公共福利项目，从而改善社区服务。"},{"sentence":"Because lottery addiction can lead to financial ruin, many experts advocate for stricter regulations on advertising.","translation":"由于彩票成瘾可能导致财务破产，许多专家主张对广告进行更严格的监管。"},{"sentence":"The school admission lottery, which ensures equal opportunity for all applicants, has been widely debated.","translation":"学校招生抽签制度确保所有申请者机会均等，这一制度引发了广泛争议。"},{"sentence":"Rather than relying on a lottery windfall, individuals should focus on long-term financial planning to secure their future.","translation":"与其依赖彩票意外之财，个人应专注于长期财务规划以保障未来。"}]},"harden":{"examples":[{"sentence":"Although the clay was initially soft, the sculptor allowed it to harden gradually in the sun to achieve the desired firmness.","translation":"尽管黏土最初是软的，但雕塑家让它逐渐在阳光下变硬，以达到所需的硬度。"},{"sentence":"Because the steel must withstand extreme pressure, the engineers harden it through a specialized heat treatment process.","translation":"因为钢材必须承受极端压力，工程师通过专门的热处理工艺使其变硬。"},{"sentence":"When individuals face repeated failures without support, their attitudes may harden into cynicism, which hinders future collaboration.","translation":"当个人在没有支持的情况下反复面对失败时，他们的态度可能会变得愤世嫉俗，这会阻碍未来的合作。"},{"sentence":"The government's austerity measures, rather than alleviating the crisis, served to harden public resentment toward the administration.","translation":"政府的紧缩措施非但没有缓解危机，反而加剧了公众对政府的怨恨。"},{"sentence":"To ensure the chocolate coating sets properly, the confectioner must harden it at a controlled temperature before packaging.","translation":"为了确保巧克力涂层正确凝固，糖果师必须在包装前在受控温度下使其变硬。"}]},"fasten":{"examples":[{"sentence":"Before the aircraft departs, passengers must fasten their seat belts securely, which is a mandatory safety requirement.","translation":"飞机起飞前，乘客必须系好安全带，这是一项强制性的安全要求。"},{"sentence":"Although the lock was rusty, the janitor managed to fasten the gate with a sturdy chain to prevent unauthorized entry.","translation":"尽管锁生锈了，看门人还是设法用一条结实的链子把大门拴紧，以防止未经授权的进入。"},{"sentence":"Because the documents were confidential, she used a paper clip to fasten them together before placing them in the envelope.","translation":"因为文件是机密的，她在放入信封前用回形针把它们别在一起。"},{"sentence":"The new regulation seeks to fasten accountability onto corporate executives, thereby ensuring greater transparency in financial reporting.","translation":"新规定旨在让企业高管承担责任，从而确保财务报告更加透明。"},{"sentence":"When the toddler struggled to fasten his shoes, his older sister knelt down to assist him with the laces.","translation":"当幼儿费力系鞋带时，他的姐姐蹲下来帮他系好。"}]},"own":{"examples":[{"sentence":"Although she valued her colleagues' input, she ultimately trusted her own judgment to make the final decision.","translation":"尽管她重视同事的意见，但她最终相信自己的判断来做出最终决定。"},{"sentence":"Because the entrepreneur used her own capital to launch the startup, she retained complete ownership of the company.","translation":"因为这位企业家用自己的资金创办了初创公司，所以她保留了公司的全部所有权。"},{"sentence":"The artist developed her own unique style, which distinguished her work from that of her contemporaries.","translation":"这位艺术家发展了自己独特的风格，这使她的作品与同时代人的作品区分开来。"},{"sentence":"By cultivating their own food, communities can enhance food security while reducing environmental impact.","translation":"通过自己种植食物，社区可以增强粮食安全，同时减少对环境的影响。"},{"sentence":"He chose to write his own software rather than relying on commercial solutions, thereby gaining greater flexibility.","translation":"他选择编写自己的软件，而不是依赖商业解决方案，从而获得了更大的灵活性。"}]},"flaw":{"examples":[{"sentence":"Although the proposal seemed comprehensive, a critical flaw in its financial projections undermined its credibility.","translation":"尽管该提案看似全面，但其财务预测中的一个关键缺陷削弱了其可信度。"},{"sentence":"Because the bridge had a structural flaw that was overlooked during inspection, it required immediate reinforcement to ensure safety.","translation":"由于桥梁存在一个在检查中被忽视的结构缺陷，它需要立即加固以确保安全。"},{"sentence":"The researcher identified a methodological flaw in the study, which, if addressed, could significantly alter the conclusions.","translation":"研究人员发现了该研究中的一个方法论缺陷，如果加以解决，可能会显著改变结论。"},{"sentence":"While the software update fixed many bugs, a persistent security flaw left user data vulnerable to potential breaches.","translation":"尽管软件更新修复了许多错误，但一个持续存在的安全漏洞使用户数据容易受到潜在泄露的威胁。"},{"sentence":"A subtle flaw in the legal argument became evident when the opposing counsel presented a contradictory precedent.","translation":"当对方律师提出一个矛盾的先例时，法律论证中的一个细微缺陷变得明显起来。"}]},"swarm":{"examples":[{"sentence":"Although the beekeeper wore protective gear, a swarm of bees still managed to sting him several times.","translation":"尽管养蜂人穿着防护装备，一群蜜蜂还是设法蜇了他好几次。"},{"sentence":"When the earthquake struck, a swarm of people rushed out of the building, causing chaos in the streets.","translation":"当地震发生时，一大群人冲出大楼，导致街道上一片混乱。"},{"sentence":"Because the picnic was left uncovered, a swarm of ants quickly invaded the food, ruining the afternoon.","translation":"因为野餐没有遮盖，一群蚂蚁迅速侵入了食物，毁了整个下午。"},{"sentence":"The drone captured footage of a swarm of locusts that darkened the sky as they approached the village.","translation":"无人机拍摄到了一群蝗虫的镜头，它们接近村庄时遮天蔽日。"},{"sentence":"Despite the lifeguard's warnings, a swarm of jellyfish appeared near the shore, forcing the beach to close.","translation":"尽管救生员发出了警告，一群水母还是出现在海岸附近，迫使海滩关闭。"}]},"advocate":{"examples":[{"sentence":"As an advocate for sustainable agriculture, she promotes organic farming methods that protect soil health.","translation":"作为可持续农业的倡导者，她推广保护土壤健康的有机耕作方法。"},{"sentence":"The lawyer is a passionate advocate for criminal justice reform, arguing that the current system disproportionately affects minorities.","translation":"这位律师是刑事司法改革的热情倡导者，认为现行制度对少数群体影响过大。"},{"sentence":"A well-known advocate of digital privacy, he warns that unchecked data collection threatens individual freedoms.","translation":"作为数字隐私的知名倡导者，他警告说无限制的数据收集威胁个人自由。"},{"sentence":"The foundation acts as an advocate for endangered species, funding projects that preserve natural habitats.","translation":"该基金会充当濒危物种的倡导者，资助保护自然栖息地的项目。"},{"sentence":"Although she is an advocate of free speech, she acknowledges that hate speech must be regulated to prevent harm.","translation":"尽管她是言论自由的倡导者，但她承认必须监管仇恨言论以防止伤害。"}]},"accurate":{"examples":[{"sentence":"To ensure that the financial report is accurate, the accountant must verify every transaction against the original receipts.","translation":"为确保财务报告准确无误，会计师必须根据原始收据核对每一笔交易。"},{"sentence":"Although the weather forecast was not perfectly accurate, it still provided a useful guide for planning outdoor activities.","translation":"尽管天气预报并非完全准确，但它仍为规划户外活动提供了有用的指导。"},{"sentence":"An accurate translation of legal documents is crucial, because even a minor error can lead to serious misunderstandings.","translation":"法律文件的准确翻译至关重要，因为即使是一个小错误也可能导致严重的误解。"},{"sentence":"The historian argued that an accurate understanding of the past requires not only factual data but also an appreciation of cultural context.","translation":"这位历史学家认为，准确理解过去不仅需要事实数据，还需要对文化背景的领会。"},{"sentence":"In scientific research, accurate measurements are essential, which is why laboratories invest heavily in calibration and quality control.","translation":"在科学研究中，精确的测量至关重要，这就是实验室在校准和质量控制方面投入巨资的原因。"}]},"spite":{"examples":[{"sentence":"Although the initial data seemed discouraging, the researchers persisted in spite of the setbacks and eventually achieved a breakthrough.","translation":"尽管最初的数据令人沮丧，研究人员不顾挫折坚持下来，最终取得了突破。"},{"sentence":"In spite of the fact that the policy was widely criticized, it led to a significant reduction in carbon emissions because it incentivized green technology.","translation":"尽管该政策受到广泛批评，但由于它激励了绿色技术，碳排放量显著减少。"},{"sentence":"The team completed the project ahead of schedule in spite of the unexpected departure of two key members, which could have derailed the entire effort.","translation":"尽管两名关键成员意外离开，团队还是提前完成了项目，这本来可能使整个努力脱轨。"},{"sentence":"In spite of the cultural barriers that often hinder cross-border collaboration, the multinational team developed a unified strategy through regular communication.","translation":"尽管文化障碍常常阻碍跨境合作，跨国团队通过定期沟通制定出了统一战略。"},{"sentence":"The artist gained international recognition in spite of the initial rejection from major galleries, thereby proving that perseverance can overcome institutional bias.","translation":"尽管最初遭到各大画廊的拒绝，这位艺术家还是获得了国际认可，从而证明坚持不懈可以克服体制偏见。"}]},"orderly":{"examples":[{"sentence":"An orderly evacuation procedure, which is practiced regularly, can save many lives during an emergency because it minimizes panic and confusion.","translation":"定期演练的有序疏散程序可以在紧急情况下挽救许多生命，因为它能最大限度地减少恐慌和混乱。"},{"sentence":"The laboratory maintains an orderly environment to ensure that experiments are conducted safely and efficiently, thereby reducing the risk of contamination.","translation":"实验室保持有序的环境，以确保实验安全高效地进行，从而降低污染风险。"},{"sentence":"Effective urban planning promotes orderly development, which helps to reduce traffic congestion and environmental degradation while improving quality of life.","translation":"有效的城市规划促进有序发展，这有助于减少交通拥堵和环境退化，同时提高生活质量。"},{"sentence":"Although the transition of power was orderly, the new administration faced numerous challenges that required immediate attention.","translation":"尽管权力过渡有序，新政府仍面临许多需要立即关注的挑战。"},{"sentence":"The orderly arrangement of data in the database allows researchers to retrieve information quickly and accurately, which is essential for time-sensitive studies.","translation":"数据库中数据的有序排列使研究人员能够快速准确地检索信息，这对时间敏感的研究至关重要。"}]},"signal":{"examples":[{"sentence":"Although the initial signal was weak, the engineers managed to amplify it sufficiently for clear communication.","translation":"尽管初始信号很弱，工程师们设法将其放大到足以进行清晰通信的程度。"},{"sentence":"The central bank's decision to lower interest rates sent a strong signal to the market, thereby boosting investor confidence.","translation":"中央银行降低利率的决定向市场发出了强烈信号，从而提振了投资者信心。"},{"sentence":"Because the distress signal was detected by multiple satellites, the rescue operation could be launched without delay.","translation":"由于遇险信号被多颗卫星探测到，救援行动得以立即展开。"},{"sentence":"A sudden spike in online searches for flu symptoms often serves as an early signal of an impending outbreak, which allows health authorities to prepare.","translation":"流感症状在线搜索量的突然激增通常是疫情即将爆发的早期信号，这使得卫生部门能够提前准备。"},{"sentence":"When the traffic signal malfunctioned, the police officer stepped in to direct vehicles, ensuring that the intersection remained safe.","translation":"当交通信号灯发生故障时，警察介入指挥车辆，以确保十字路口保持安全。"}]},"ours":{"examples":[{"sentence":"While their marketing strategy relies heavily on social media influencers, ours focuses on building long-term customer relationships through personalized service.","translation":"他们的营销策略严重依赖社交媒体影响者，而我们的策略则侧重于通过个性化服务建立长期的客户关系。"},{"sentence":"Because the neighboring community invested in renewable energy early, their carbon footprint is much smaller than ours.","translation":"由于邻近社区早期投资了可再生能源，他们的碳足迹比我们的小得多。"},{"sentence":"The research team from the rival university published their findings first, but ours conducted a more comprehensive analysis, which led to a breakthrough.","translation":"竞争对手大学的研究团队率先发表了他们的发现，但我们团队进行了更全面的分析，从而取得了突破。"},{"sentence":"When comparing the two proposals, the committee noted that theirs lacked a clear implementation plan, whereas ours included a detailed timeline and budget.","translation":"在比较这两份提案时，委员会注意到他们的缺乏明确的实施计划，而我们的则包含了详细的时间表和预算。"},{"sentence":"Although their product has a sleek design, ours offers superior durability, which is crucial for industrial applications.","translation":"尽管他们的产品设计时尚，但我们的产品具有卓越的耐用性，这对于工业应用至关重要。"}]},"branch":{"examples":[{"sentence":"The legislative branch, which is responsible for enacting laws, must operate independently to ensure a balance of power.","translation":"负责制定法律的立法部门必须独立运作，以确保权力平衡。"},{"sentence":"Because the bank opened a new branch in the commercial district, it attracted more small-business clients seeking convenient financial services.","translation":"因为银行在商业区开设了新分行，它吸引了更多寻求便捷金融服务的小企业客户。"},{"sentence":"Cognitive neuroscience, a branch of psychology that examines brain mechanisms underlying mental processes, has advanced rapidly due to imaging technologies.","translation":"认知神经科学是心理学的一个分支，研究心理过程背后的脑机制，由于成像技术而迅速发展。"},{"sentence":"When a tree branch breaks under heavy snow, it can damage power lines, thereby causing widespread outages.","translation":"当树枝在厚雪下折断时，可能损坏电线，从而导致大面积停电。"},{"sentence":"Ethics, as a branch of philosophy, provides frameworks for evaluating moral dilemmas, which are increasingly complex in the age of artificial intelligence.","translation":"伦理学作为哲学的一个分支，为评估道德困境提供了框架，这些困境在人工智能时代日益复杂。"}]},"cease":{"examples":[{"sentence":"If the company does not address its financial losses, it will cease operations within six months, which would affect hundreds of employees.","translation":"如果公司不解决财务亏损，它将在六个月内停止运营，这将影响数百名员工。"},{"sentence":"Although the ceasefire was signed, hostilities did not cease immediately because deep-seated mistrust persisted between the factions.","translation":"尽管签署了停火协议，但敌对行动并未立即停止，因为派系之间根深蒂固的不信任持续存在。"},{"sentence":"The government ordered the factory to cease production until it could demonstrate compliance with environmental regulations, thereby protecting the local river.","translation":"政府命令工厂停止生产，直到它能证明遵守环境法规，从而保护当地河流。"},{"sentence":"When funding for the arts program was cut, the community theater had to cease its outreach activities, which had benefited underprivileged youth.","translation":"当艺术项目的资金被削减时，社区剧院不得不停止其外展活动，这些活动曾使贫困青年受益。"},{"sentence":"Because the medication caused severe side effects, the clinical trial was forced to cease, despite its promising early results.","translation":"因为药物引起严重副作用，临床试验被迫停止，尽管早期结果很有希望。"}]},"reading":{"examples":[{"sentence":"Although reading extensively can broaden one's perspective, it is the critical analysis of texts that truly deepens understanding.","translation":"尽管广泛阅读可以拓宽视野，但对文本的批判性分析才能真正加深理解。"},{"sentence":"Because regular reading of scholarly articles keeps researchers informed of the latest developments, it is indispensable for academic success.","translation":"由于定期阅读学术文章能让研究人员了解最新进展，因此它对学术成功不可或缺。"},{"sentence":"While reading fiction enhances empathy by allowing readers to experience diverse lives, non-fiction provides factual knowledge that informs decision-making.","translation":"虽然阅读小说通过让读者体验多样人生来增强同理心，但非小说类作品提供的事实知识能为决策提供依据。"},{"sentence":"A well-structured reading habit, which includes both intensive and extensive approaches, can significantly improve language proficiency over time.","translation":"一个结构良好的阅读习惯，包括精读和泛读，可以随着时间的推移显著提高语言能力。"},{"sentence":"When students engage in active reading by annotating and questioning the text, they retain information more effectively than through passive perusal.","translation":"当学生通过注释和质疑文本进行主动阅读时，他们比被动浏览更有效地记住信息。"}]},"lace":{"examples":[{"sentence":"Because the intricate lace pattern was handcrafted by skilled artisans, the wedding dress commanded a price far beyond that of machine-made alternatives.","translation":"由于复杂的蕾丝图案是由熟练工匠手工制作的，这件婚纱的价格远远超过机器制造的替代品。"},{"sentence":"Although lace is often associated with femininity and romance, its historical use in men's cravats and cuffs reveals a more complex gender narrative.","translation":"尽管蕾丝常与女性气质和浪漫联系在一起，但它在男性领巾和袖口上的历史用途揭示了一种更复杂的性别叙事。"},{"sentence":"The museum curator explained that the lace collar, which dates back to the 17th century, exemplifies the era's meticulous needlework and social status symbolism.","translation":"博物馆馆长解释说，这个可追溯到17世纪的蕾丝领子体现了那个时代精细的针线活和社会地位象征。"},{"sentence":"When hiking in rough terrain, it is crucial to lace your boots tightly to prevent ankle injuries and ensure stability.","translation":"在崎岖地形徒步时，系紧鞋带以防止脚踝受伤并确保稳定性至关重要。"},{"sentence":"Rather than discarding the torn lace curtain, she creatively repurposed it into decorative pillow covers, thereby reducing waste.","translation":"她没有丢弃撕破的蕾丝窗帘，而是创造性地将其改造成装饰性枕套，从而减少了浪费。"}]},"prospective":{"examples":[{"sentence":"Prospective graduate students should thoroughly research potential supervisors, because a supportive mentor can greatly influence their academic trajectory.","translation":"未来的研究生应该彻底研究潜在的导师，因为一位支持性的导师可以极大地影响他们的学术轨迹。"},{"sentence":"Although the company offered a competitive salary, the prospective employee hesitated due to concerns about work-life balance and corporate culture.","translation":"尽管公司提供了有竞争力的薪水，但这位潜在员工因担心工作与生活的平衡以及企业文化而犹豫不决。"},{"sentence":"A detailed market analysis enables prospective entrepreneurs to identify gaps in the industry, which can lead to innovative business opportunities.","translation":"详细的市场分析使潜在企业家能够发现行业中的空白，从而带来创新的商业机会。"},{"sentence":"When evaluating prospective investments, it is essential to consider not only the potential returns but also the associated risks and ethical implications.","translation":"在评估潜在投资时，不仅要考虑潜在回报，还要考虑相关风险和道德影响，这一点至关重要。"},{"sentence":"Universities often organize campus tours for prospective students, thereby allowing them to experience the academic environment and facilities firsthand.","translation":"大学经常为未来的学生组织校园参观，从而使他们能够亲身体验学术环境和设施。"}]},"apparent":{"examples":[{"sentence":"The apparent simplicity of the design conceals a sophisticated underlying algorithm that optimizes energy use.","translation":"该设计表面上的简洁掩盖了一个优化能源使用的复杂底层算法。"},{"sentence":"When the data were plotted on a graph, a clear upward trend became immediately apparent to all researchers.","translation":"当数据用图表绘制出来时，一个明显的上升趋势立即对所有研究人员变得显而易见。"},{"sentence":"Despite his apparent confidence during the presentation, he later admitted to feeling considerable anxiety.","translation":"尽管他在演讲时显得很自信，后来他承认感到相当焦虑。"},{"sentence":"The apparent contradiction between the two theories can be resolved if we consider the different time scales involved.","translation":"如果我们考虑所涉及的不同时间尺度，这两个理论之间明显的矛盾就可以得到解决。"},{"sentence":"It became apparent that the policy had unintended consequences, as small businesses struggled to meet the new requirements.","translation":"很明显，该政策产生了意想不到的后果，因为小企业难以满足新要求。"}]},"robust":{"examples":[{"sentence":"Although the economy faces headwinds, a robust labor market continues to support consumer spending.","translation":"尽管经济面临逆风，但强劲的劳动力市场继续支撑着消费者支出。"},{"sentence":"The company implemented a robust cybersecurity protocol, which protects sensitive data from increasingly sophisticated attacks.","translation":"该公司实施了一套强大的网络安全协议，保护敏感数据免受日益复杂的攻击。"},{"sentence":"Because the experimental results were replicated across multiple laboratories, the findings are considered highly robust.","translation":"由于实验结果在多个实验室得到重复，这些发现被认为非常可靠。"},{"sentence":"A robust legal framework is essential to ensure that intellectual property rights are enforced effectively.","translation":"一个健全的法律框架对于确保知识产权得到有效执行至关重要。"},{"sentence":"While the initial prototype was fragile, the final product featured a robust design that withstood extreme conditions.","translation":"虽然最初的原型很脆弱，但最终产品采用了坚固的设计，能够承受极端条件。"}]},"abound":{"examples":[{"sentence":"In the digital era, examples of misinformation abound, which makes media literacy an essential skill.","translation":"在数字时代，错误信息的例子比比皆是，这使得媒体素养成为一项基本技能。"},{"sentence":"Although challenges abound in the transition to renewable energy, the long-term benefits justify the investment.","translation":"尽管向可再生能源转型存在诸多挑战，但长期收益证明了投资的合理性。"},{"sentence":"The ancient city's ruins abound with artifacts that offer insights into early trade networks.","translation":"这座古城的废墟中充满了文物，为早期贸易网络提供了见解。"},{"sentence":"Because opportunities for advancement abound in this growing industry, employee turnover remains low.","translation":"由于这个成长型行业中晋升机会很多，员工流动率保持较低。"},{"sentence":"While rumors abound regarding the merger, the company has yet to release an official statement.","translation":"尽管关于合并的谣言四起，该公司尚未发布官方声明。"}]},"often":{"examples":[{"sentence":"Although many people rely on digital calendars, they often forget to check them before scheduling appointments.","translation":"尽管许多人依赖数字日历，但他们经常在安排约会前忘记查看。"},{"sentence":"Because consistent practice is key to language acquisition, learners who study daily often progress faster than those who study sporadically.","translation":"由于持续练习是语言习得的关键，每天学习的学习者通常比偶尔学习的人进步更快。"},{"sentence":"When companies prioritize short-term profits over long-term sustainability, they often face reputational damage and regulatory scrutiny.","translation":"当公司将短期利润置于长期可持续性之上时，它们常常面临声誉损害和监管审查。"},{"sentence":"Students who participate in extracurricular activities often develop teamwork and leadership skills that enhance their employability.","translation":"参加课外活动的学生通常会培养团队合作和领导能力，从而提高他们的就业能力。"},{"sentence":"While technology has streamlined many tasks, it often creates new complexities that require continuous adaptation.","translation":"虽然技术简化了许多任务，但它常常产生新的复杂性，需要不断适应。"}]},"flock":{"examples":[{"sentence":"Although a flock of birds may appear to move randomly, their coordinated flight patterns actually follow simple rules that ensure group cohesion.","translation":"尽管一群鸟看似随机移动，但它们协调的飞行模式实际上遵循简单的规则，以确保群体凝聚力。"},{"sentence":"When a new technology emerges, investors often flock to the sector, which can lead to rapid innovation but also speculative bubbles.","translation":"当新技术出现时，投资者往往涌入该领域，这可能导致快速创新，但也可能引发投机泡沫。"},{"sentence":"Tourists flock to the ancient city every autumn because the mild weather and cultural festivals create an irresistible attraction.","translation":"每年秋天游客们涌向这座古城，因为温和的天气和文化节庆营造出不可抗拒的吸引力。"},{"sentence":"A shepherd must guide the flock carefully through the mountain pass, thereby avoiding predators and ensuring access to fresh pasture.","translation":"牧羊人必须小心地引导羊群穿过山口，从而避开捕食者并确保获得新鲜牧草。"},{"sentence":"While a flock of sheep may seem docile, their collective behavior can be unpredictable when they sense danger, which requires constant vigilance.","translation":"尽管一群羊看似温顺，但当它们感知到危险时，其集体行为可能难以预测，这需要时刻保持警惕。"}]},"enforce":{"examples":[{"sentence":"If governments fail to enforce environmental laws, industrial pollution will continue to degrade air quality, which poses serious health risks.","translation":"如果政府未能执行环境法律，工业污染将继续恶化空气质量，这构成严重的健康风险。"},{"sentence":"The new regulation seeks to enforce stricter data privacy standards, thereby protecting consumers from unauthorized use of their personal information.","translation":"新法规旨在执行更严格的数据隐私标准，从而保护消费者免受个人信息未经授权的使用。"},{"sentence":"Because the school decided to enforce a zero-tolerance policy on bullying, students now feel safer and more focused on their academic pursuits.","translation":"由于学校决定对欺凌行为执行零容忍政策，学生们现在感到更安全，更专注于学业追求。"},{"sentence":"International agreements are often difficult to enforce when participating nations lack the necessary legal frameworks to implement them.","translation":"当参与国缺乏必要的法律框架来实施时，国际协议往往难以执行。"},{"sentence":"To maintain public safety, local authorities must enforce traffic regulations consistently, which reduces accidents and improves traffic flow.","translation":"为了维护公共安全，地方当局必须持续执行交通法规，这减少事故并改善交通流量。"}]},"downtown":{"examples":[{"sentence":"The revitalization of downtown districts often attracts new businesses, which in turn creates a vibrant economic ecosystem that benefits the entire city.","translation":"市中心区域的复兴往往吸引新企业，这反过来创造了一个充满活力的经济生态系统，惠及整个城市。"},{"sentence":"Although downtown living offers unparalleled convenience, the high cost of housing can deter many young professionals from settling there permanently.","translation":"尽管市中心生活提供了无与伦比的便利，但高昂的住房成本可能使许多年轻专业人士望而却步，不愿长期定居。"},{"sentence":"City planners are redesigning downtown streets to prioritize pedestrians and cyclists, thereby reducing traffic congestion and improving air quality.","translation":"城市规划者正在重新设计市中心的街道，以优先考虑行人和骑行者，从而减少交通拥堵并改善空气质量。"},{"sentence":"Because the downtown campus is easily accessible by public transit, students from various districts can attend classes without enduring long commutes.","translation":"由于市中心的校园乘坐公共交通很方便，来自不同地区的学生可以无需忍受长途通勤就能上课。"},{"sentence":"Investing in downtown cultural institutions, such as museums and theaters, can significantly enhance a city's appeal to tourists, which boosts the local economy.","translation":"投资于市中心的博物馆和剧院等文化机构，可以显著提升城市对游客的吸引力，从而促进当地经济。"}]},"wedge":{"examples":[{"sentence":"The new tax policy served as a wedge that drove a deep division between the two economic classes.","translation":"新的税收政策起到了楔子的作用，在两个经济阶层之间造成了深刻的分裂。"},{"sentence":"To keep the door from closing, she inserted a wooden wedge under it, which proved very effective.","translation":"为了防止门关上，她在门下塞了一个木楔，这被证明非常有效。"},{"sentence":"Although the crack was narrow, the geologist used a wedge to split the rock for further examination.","translation":"尽管裂缝很窄，地质学家还是用楔子劈开岩石以便进一步检查。"},{"sentence":"A minor disagreement can become a wedge that eventually destroys a long-standing friendship.","translation":"一个小小的分歧可能成为最终破坏长期友谊的楔子。"},{"sentence":"Because the gap was too small, they had to wedge the heavy sofa through the doorway with great effort.","translation":"因为空隙太小，他们不得不费很大力气把沉重的沙发挤进门道。"}]},"anything":{"examples":[{"sentence":"Without solid proof, we should not believe anything that contradicts established scientific theories.","translation":"没有确凿的证据，我们不应该相信任何与既定科学理论相矛盾的事情。"},{"sentence":"A comprehensive plan must consider anything that could potentially affect the project's outcome.","translation":"一个全面的计划必须考虑任何可能影响项目结果的事情。"},{"sentence":"Although she was exhausted, she did not forget anything important for the final exam preparation.","translation":"尽管她很疲惫，但她没有忘记期末考试准备的任何重要事项。"},{"sentence":"In a negotiation, you should not concede anything unless you receive a comparable benefit in return.","translation":"在谈判中，你不应该让步任何事情，除非你得到相应的回报。"},{"sentence":"Because the new regulation was so detailed, it covered almost anything related to workplace safety.","translation":"因为新规定非常详细，它几乎涵盖了与工作场所安全相关的任何事情。"}]},"rice":{"examples":[{"sentence":"Although rice is a staple food for billions, its cultivation contributes significantly to methane emissions, which exacerbates global warming.","translation":"尽管稻米是数十亿人的主食，但其种植会显著增加甲烷排放，从而加剧全球变暖。"},{"sentence":"Because rice paddies require standing water, farmers in drought-prone regions are adopting new irrigation techniques to ensure sustainable production.","translation":"由于稻田需要积水，干旱易发地区的农民正在采用新的灌溉技术，以确保可持续生产。"},{"sentence":"Governments often subsidize rice production to stabilize prices, thereby protecting both consumers and producers from market volatility.","translation":"政府经常补贴稻米生产以稳定价格，从而保护消费者和生产者免受市场波动的影响。"},{"sentence":"Scientists have engineered rice varieties that are resistant to pests, which reduces the need for chemical pesticides and benefits the environment.","translation":"科学家们已经培育出抗虫害的水稻品种，这减少了对化学农药的需求，有利于环境。"},{"sentence":"While rice is traditionally associated with Asian cuisine, its versatility has led to its incorporation into diverse dishes worldwide.","translation":"虽然稻米传统上与亚洲美食相关，但其多功能性使其被纳入世界各地的各种菜肴中。"}]},"regarding":{"examples":[{"sentence":"Although the committee discussed the proposal at length, no final decision was reached regarding the budget allocation.","translation":"尽管委员会详细讨论了该提案，但关于预算分配仍未做出最终决定。"},{"sentence":"The professor provided detailed feedback regarding the thesis, which helped the student improve the argument significantly.","translation":"教授就论文提供了详细反馈，这帮助学生显著改进了论证。"},{"sentence":"Because the policy lacked clarity regarding remote work, many employees expressed confusion about the new rules.","translation":"由于该政策在远程工作方面缺乏明确性，许多员工对新规定表示困惑。"},{"sentence":"The survey gathered essential data regarding consumer preferences, thereby enabling the company to tailor its marketing strategy.","translation":"该调查收集了关于消费者偏好的重要数据，从而使公司能够调整其营销策略。"},{"sentence":"When drafting the report, the team consulted multiple experts regarding the environmental impact of the project.","translation":"在起草报告时，团队就项目的环境影响咨询了多位专家。"}]},"laser":{"examples":[{"sentence":"Although laser technology was initially developed for scientific research, it now plays a crucial role in consumer electronics.","translation":"尽管激光技术最初是为科学研究而开发的，但它现在在消费电子产品中发挥着至关重要的作用。"},{"sentence":"Because laser cutting offers unparalleled precision, it has become the preferred method for manufacturing intricate components.","translation":"由于激光切割提供了无与伦比的精度，它已成为制造复杂部件的首选方法。"},{"sentence":"The surgeon used a laser to remove the tumor, thereby minimizing damage to surrounding healthy tissue.","translation":"外科医生使用激光切除肿瘤，从而最大限度地减少了对周围健康组织的损伤。"},{"sentence":"While laser printers are more expensive initially, their lower operating costs make them economical over time.","translation":"虽然激光打印机最初更贵，但其较低的运行成本使其长期来看更经济。"},{"sentence":"The laser communication system, which relies on light rather than radio waves, can transmit data at higher speeds.","translation":"激光通信系统依赖光而非无线电波，能够以更高的速度传输数据。"}]},"accept":{"examples":[{"sentence":"To foster innovation, organizations must accept that failure is an inherent part of the creative process.","translation":"为了促进创新，组织必须接受失败是创造过程中固有的一部分。"},{"sentence":"Although the evidence was inconclusive, the committee decided to accept the proposal in order to advance the discussion.","translation":"尽管证据尚无定论，委员会决定接受该提案以推进讨论。"},{"sentence":"Scholars generally accept that early exposure to multiple languages enhances cognitive flexibility in children.","translation":"学者们普遍认为，早期接触多种语言能增强儿童的认知灵活性。"},{"sentence":"If we accept the premise that education is a public good, then equitable funding becomes a moral imperative.","translation":"如果我们接受教育是公共产品这一前提，那么公平资助就成为一种道德责任。"},{"sentence":"The company was reluctant to accept liability for the environmental damage, despite mounting public pressure.","translation":"尽管公众压力越来越大，该公司仍不愿承担环境损害的责任。"}]},"blow":{"examples":[{"sentence":"Although the company survived the crisis, the loss of its key investor was a blow that forced a major restructuring.","translation":"尽管公司挺过了危机，但关键投资者的流失是一个打击，迫使公司进行了重大重组。"},{"sentence":"The sudden resignation of the CEO came as a blow to the board, which had not anticipated such a move.","translation":"首席执行官的突然辞职对董事会是一个打击，董事会没有预料到这一举动。"},{"sentence":"When the court ruled against them, it was a blow to their legal strategy, yet they immediately filed an appeal.","translation":"当法院做出不利于他们的裁决时，这对他们的法律策略是一个打击，但他们立即提起了上诉。"},{"sentence":"The cancellation of the international conference dealt a blow to academic exchange, because it had been a vital platform for collaboration.","translation":"国际会议的取消对学术交流是一个打击，因为它一直是合作的重要平台。"},{"sentence":"Losing the grant was a severe blow to the research team, which had relied on that funding for years.","translation":"失去资助对研究团队是一个沉重打击，该团队多年来一直依赖那笔资金。"}]},"premise":{"examples":[{"sentence":"The entire argument rests on the premise that economic growth automatically reduces poverty.","translation":"整个论点建立在经济增长会自动减少贫困这一前提之上。"},{"sentence":"If the underlying premise is flawed, even the most rigorous methodology cannot yield valid conclusions.","translation":"如果基本前提有缺陷，即使最严谨的方法也无法得出有效的结论。"},{"sentence":"The new policy was introduced on the premise that flexible working hours would boost employee productivity.","translation":"新政策的推出基于弹性工作时间能提高员工生产力这一前提。"},{"sentence":"Critics challenged the premise that standardized tests accurately measure a student's academic potential.","translation":"批评者质疑标准化考试能准确衡量学生学术潜力这一前提。"},{"sentence":"The company's expansion strategy was built on the premise that demand for electric vehicles would surge within five years.","translation":"公司的扩张战略建立在五年内电动汽车需求将激增这一前提之上。"}]},"sticky":{"examples":[{"sentence":"Although the label was designed to be removable, it left a sticky residue that required alcohol to clean.","translation":"尽管标签被设计为可移除，但它留下了粘性残留物，需要用酒精清洁。"},{"sentence":"Because the dough was too sticky, the baker added more flour to achieve the right consistency.","translation":"因为面团太粘，面包师添加了更多面粉以达到合适的稠度。"},{"sentence":"When the negotiations entered a sticky phase, the mediator proposed a temporary break to reduce tension.","translation":"当谈判进入棘手阶段时，调解员提议暂时休会以缓和紧张气氛。"},{"sentence":"Despite the central bank's efforts, inflation proved sticky, which forced a revision of economic forecasts.","translation":"尽管央行做出了努力，通货膨胀仍居高不下，这迫使经济预测进行修订。"},{"sentence":"The sticky weather made the outdoor event uncomfortable, thereby reducing attendance significantly.","translation":"湿热的天气使户外活动令人不适，从而显著减少了出席人数。"}]},"obstacle":{"examples":[{"sentence":"Although funding was a major obstacle, the research team secured a grant through persistent applications.","translation":"尽管资金是一个主要障碍，研究团队通过持续申请获得了资助。"},{"sentence":"Because language barriers can be a significant obstacle, multinational companies often provide translation services.","translation":"因为语言障碍可能是一个重大障碍，跨国公司通常提供翻译服务。"},{"sentence":"When an unexpected obstacle arose, the project manager quickly devised a contingency plan to stay on track.","translation":"当出现意外障碍时，项目经理迅速制定了应急计划以保持进度。"},{"sentence":"The lack of infrastructure remains the primary obstacle to economic development in rural areas, which requires immediate attention.","translation":"基础设施的缺乏仍然是农村地区经济发展的主要障碍，这需要立即关注。"},{"sentence":"She viewed every obstacle as a learning opportunity rather than a setback, thereby enhancing her resilience.","translation":"她把每一个障碍都视为学习机会而不是挫折，从而增强了她的韧性。"}]},"aircraft":{"examples":[{"sentence":"Although modern aircraft are equipped with advanced navigation systems, pilots must still undergo rigorous training to handle emergencies.","translation":"尽管现代飞机配备了先进的导航系统，飞行员仍必须接受严格训练以处理紧急情况。"},{"sentence":"The airline decided to retrofit its aging aircraft with fuel-efficient engines, thereby reducing both operating costs and carbon emissions.","translation":"该航空公司决定为其老化的飞机改装节能发动机，从而降低运营成本和碳排放。"},{"sentence":"Because aircraft noise can severely affect communities near airports, engineers are developing quieter engine designs.","translation":"由于飞机噪音会严重影响机场附近的社区，工程师们正在开发更安静的发动机设计。"},{"sentence":"Unmanned aircraft, which are increasingly used for surveillance, raise complex ethical and legal questions about privacy.","translation":"越来越多用于监视的无人驾驶飞机引发了关于隐私的复杂伦理和法律问题。"},{"sentence":"When an aircraft encounters severe turbulence, passengers are advised to remain seated with their seatbelts fastened to ensure safety.","translation":"当飞机遇到严重颠簸时，建议乘客系好安全带留在座位上以确保安全。"}]},"mend":{"examples":[{"sentence":"To mend the fractured relationship, both parties agreed to engage in mediated dialogue rather than resorting to litigation.","translation":"为了修复破裂的关系，双方同意进行调解对话，而不是诉诸诉讼。"},{"sentence":"Although the broken vase seemed beyond repair, a skilled artisan was able to mend it using traditional techniques.","translation":"尽管破碎的花瓶看似无法修复，一位技艺精湛的工匠却能用传统技术将其修补好。"},{"sentence":"The government launched a comprehensive plan to mend the healthcare system, which had been strained by years of underfunding.","translation":"政府启动了一项全面计划来修复因多年资金不足而紧张的医疗系统。"},{"sentence":"Because the patient followed the doctor's advice strictly, the bone began to mend much faster than expected.","translation":"由于患者严格遵循医嘱，骨头开始愈合的速度比预期快得多。"},{"sentence":"Community leaders organized workshops to mend social divisions, thereby fostering a more inclusive environment.","translation":"社区领袖组织研讨会来弥合社会分歧，从而营造一个更包容的环境。"}]},"coil":{"examples":[{"sentence":"The technician replaced the damaged coil, which had caused the transformer to overheat.","translation":"技术员更换了损坏的线圈，该线圈曾导致变压器过热。"},{"sentence":"When threatened, the python will coil tightly around its prey, thereby cutting off circulation.","translation":"当受到威胁时，蟒蛇会紧紧盘绕猎物，从而阻断其血液循环。"},{"sentence":"She carefully wound the garden hose into a neat coil, because a tangled hose is difficult to store.","translation":"她小心地将花园水管盘成整齐的一卷，因为缠绕的水管难以存放。"},{"sentence":"The sculptor shaped a coil of clay into an elegant vase, which was then fired in a kiln.","translation":"雕塑家将一卷黏土塑造成优雅的花瓶，随后放入窑中烧制。"},{"sentence":"A single coil of barbed wire, if improperly installed, can pose a serious hazard to wildlife.","translation":"单卷带刺铁丝网如果安装不当，会对野生动物构成严重危害。"}]},"irritate":{"examples":[{"sentence":"Although the new policy was well-intentioned, its complex procedures began to irritate the staff.","translation":"尽管新政策出于好意，但其复杂的程序开始激怒员工。"},{"sentence":"Certain synthetic fabrics can irritate sensitive skin, because they trap moisture and heat.","translation":"某些合成纤维会刺激敏感皮肤，因为它们会积聚湿气和热量。"},{"sentence":"The manager's habit of micromanaging tends to irritate his team, which ultimately reduces productivity.","translation":"经理事无巨细的管理习惯往往会激怒他的团队，最终降低生产力。"},{"sentence":"While the medication is effective, it may irritate the stomach lining unless taken with food.","translation":"虽然这种药物有效，但除非与食物同服，否则可能刺激胃黏膜。"},{"sentence":"The constant noise from the construction site can irritate residents, thereby affecting their quality of life.","translation":"建筑工地持续不断的噪音会激怒居民，从而影响他们的生活质量。"}]},"voltage":{"examples":[{"sentence":"Although the voltage was initially stable, a sudden surge caused the circuit breaker to trip.","translation":"尽管电压最初是稳定的，但突然的浪涌导致断路器跳闸。"},{"sentence":"The device will not function properly unless the input voltage remains within the specified range.","translation":"除非输入电压保持在指定范围内，否则设备将无法正常工作。"},{"sentence":"Because high voltage can be dangerous, technicians must follow strict safety protocols when working on power lines.","translation":"由于高压可能很危险，技术人员在电力线上工作时必须遵守严格的安全规程。"},{"sentence":"The voltage across the capacitor decreases exponentially over time, which is a fundamental principle in electronics.","translation":"电容器两端的电压随时间呈指数下降，这是电子学中的一个基本原理。"},{"sentence":"When the voltage drops below a critical threshold, the system automatically switches to backup power to prevent data loss.","translation":"当电压降至临界阈值以下时，系统会自动切换到备用电源，以防止数据丢失。"}]},"doubt":{"examples":[{"sentence":"There is no doubt that regular exercise, rather than diet alone, is essential for maintaining good health.","translation":"毫无疑问，定期锻炼而非仅仅节食，对于保持健康至关重要。"},{"sentence":"The researcher cast doubt on the study's conclusions, because the methodology failed to control for confounding variables.","translation":"研究人员对研究的结论提出了质疑，因为该方法未能控制混杂变量。"},{"sentence":"Despite lingering doubt about the project's feasibility, the board voted to proceed with the investment.","translation":"尽管对项目的可行性仍有疑虑，董事会还是投票决定继续投资。"},{"sentence":"When new evidence emerged, the jury began to doubt the reliability of the witness's testimony.","translation":"当新证据出现时，陪审团开始怀疑证人证词的可靠性。"},{"sentence":"The principle of reasonable doubt ensures that a defendant is not convicted unless the evidence is overwhelmingly convincing.","translation":"合理怀疑原则确保除非证据极具说服力，否则被告不会被定罪。"}]},"legacy":{"examples":[{"sentence":"Although the legacy of colonialism is complex, it undeniably shaped the political boundaries of many modern nations.","translation":"虽然殖民主义的遗产很复杂，但它无疑塑造了许多现代国家的政治边界。"},{"sentence":"The generous legacy from the philanthropist enabled the hospital to build a new wing, which will serve thousands of patients annually.","translation":"这位慈善家的慷慨遗赠使医院得以建造一座新翼楼，每年将服务数千名患者。"},{"sentence":"Because the industrial legacy includes contaminated soil, the redevelopment project must prioritize environmental remediation.","translation":"由于工业遗产包括受污染的土壤，重建项目必须优先考虑环境修复。"},{"sentence":"The artist's legacy continues to inspire new generations, despite the controversies that surrounded her personal life.","translation":"尽管她的个人生活充满争议，这位艺术家的遗产继续激励着新一代。"},{"sentence":"To address the legacy of inequality, the government implemented policies that invest in education and infrastructure in marginalized communities.","translation":"为了解决不平等的遗留问题，政府实施了投资于边缘化社区教育和基础设施的政策。"}]},"height":{"examples":[{"sentence":"The height of the mountain, which exceeds 8,000 meters, makes it one of the most challenging peaks to climb.","translation":"这座山的高度超过8000米，使其成为最具挑战性的攀登高峰之一。"},{"sentence":"Because the ceiling height in the laboratory is insufficient, the installation of advanced equipment has been postponed.","translation":"由于实验室的天花板高度不足，先进设备的安装已被推迟。"},{"sentence":"Although the height of the building was restricted by zoning laws, the architects managed to create an impressive design.","translation":"尽管建筑的高度受到分区法规的限制，建筑师们还是设法创造出了令人印象深刻的设计。"},{"sentence":"The height of the floodwaters, which rose rapidly overnight, forced residents to evacuate their homes.","translation":"洪水的高度在一夜之间迅速上涨，迫使居民撤离家园。"},{"sentence":"At the height of his career, the scientist published a groundbreaking paper that reshaped the field.","translation":"在他事业的顶点，这位科学家发表了一篇重塑该领域的开创性论文。"}]},"crew":{"examples":[{"sentence":"The film crew, which consisted of over a hundred members, worked tirelessly to capture the perfect scene.","translation":"电影摄制组由一百多名成员组成，他们不知疲倦地工作以捕捉完美的场景。"},{"sentence":"Because the crew lacked proper training, the expedition faced numerous challenges that could have been avoided.","translation":"由于全体船员缺乏适当的训练，探险队面临了许多本可避免的挑战。"},{"sentence":"Although the crew was exhausted after the long voyage, they still managed to unload the cargo efficiently.","translation":"尽管船员们在长途航行后筋疲力尽，他们仍然设法高效地卸下了货物。"},{"sentence":"The maintenance crew, which inspects the aircraft before every flight, plays a crucial role in ensuring passenger safety.","translation":"维修人员在每次飞行前检查飞机，在确保乘客安全方面发挥着至关重要的作用。"},{"sentence":"A diverse crew brings a range of perspectives that can enhance problem-solving and innovation in the workplace.","translation":"一个多元化的团队带来了广泛的视角，可以增强工作场所的问题解决和创新能力。"}]},"playground":{"examples":[{"sentence":"Although the playground was designed for young children, it also includes fitness equipment that attracts teenagers and adults.","translation":"尽管这个操场是为幼儿设计的，但它也包括吸引青少年和成人的健身器材。"},{"sentence":"Because the playground surface is made of recycled rubber, it provides a safer environment that reduces the risk of injury.","translation":"由于操场地面由再生橡胶制成，它提供了一个更安全的环境，降低了受伤的风险。"},{"sentence":"The playground, which was built through community fundraising, has become a vibrant hub where families gather on weekends.","translation":"这个通过社区筹款建造的操场已成为一个充满活力的中心，家庭在周末聚集于此。"},{"sentence":"While the playground serves as a recreational space for children, it also functions as an outdoor classroom for environmental education.","translation":"虽然这个操场是儿童的娱乐空间，但它也作为环境教育的户外教室。"},{"sentence":"The coastal resort, often called a playground for the rich, features luxury amenities that attract visitors from around the world.","translation":"这个海滨度假胜地常被称为富人的游乐场，拥有吸引世界各地游客的豪华设施。"}]},"x-ray":{"examples":[{"sentence":"Although the x-ray showed no obvious fracture, the physician ordered a CT scan to rule out a subtle injury.","translation":"尽管X光片没有显示明显骨折，医生还是安排了CT扫描以排除细微损伤。"},{"sentence":"Because the x-ray revealed a suspicious shadow, the patient was referred for a biopsy to ensure an accurate diagnosis.","translation":"由于X光片显示可疑阴影，患者被转诊进行活检以确保准确诊断。"},{"sentence":"While traditional x-ray machines use film, modern digital systems allow instant image review and lower radiation doses.","translation":"传统X光机使用胶片，而现代数字系统允许即时查看图像且辐射剂量更低。"},{"sentence":"The dentist took an x-ray of the patient's jaw, which helped identify an impacted wisdom tooth that required extraction.","translation":"牙医给患者的下颌拍了X光片，这有助于发现一颗需要拔除的阻生智齿。"},{"sentence":"When the x-ray was inconclusive, the radiologist recommended an MRI to obtain more detailed soft-tissue images.","translation":"当X光片无法确诊时，放射科医生建议做核磁共振以获得更详细的软组织图像。"}]},"ham":{"examples":[{"sentence":"The chef prepared a glazed ham with a honey-mustard crust, which became the centerpiece of the holiday banquet.","translation":"厨师准备了一道带有蜂蜜芥末脆皮的蜜汁火腿，这成为了节日宴会的主菜。"},{"sentence":"Because the cured ham had been aged for eighteen months, it developed a rich, complex flavor that delighted the guests.","translation":"由于腌制火腿经过了十八个月的风干，它形成了浓郁而复杂的风味，令宾客们赞不绝口。"},{"sentence":"Although ham is often high in sodium, moderate consumption can be part of a balanced diet if paired with fresh vegetables.","translation":"尽管火腿通常钠含量较高，但如果搭配新鲜蔬菜，适量食用可以成为均衡饮食的一部分。"},{"sentence":"The food scientist explained that the characteristic pink color of ham results from the curing process, which involves nitrites.","translation":"食品科学家解释说，火腿特有的粉红色是由腌制过程产生的，该过程涉及亚硝酸盐。"},{"sentence":"In many cultures, serving a baked ham symbolizes celebration and hospitality, thereby strengthening social bonds during festive gatherings.","translation":"在许多文化中，端上烤火腿象征着庆祝和好客，从而在节日聚会中加强社会联系。"}]},"item":{"examples":[{"sentence":"The most controversial item on the agenda was the proposal to reduce funding for public libraries, which sparked a heated debate among council members.","translation":"议程上最具争议的项目是削减公共图书馆经费的提案，这在委员会成员中引发了激烈辩论。"},{"sentence":"When designing a questionnaire, researchers must ensure that each item is phrased neutrally to avoid leading respondents toward a particular answer.","translation":"设计问卷时，研究人员必须确保每个条目措辞中立，以避免引导受访者给出特定答案。"},{"sentence":"Although the diamond necklace was the most expensive item in the auction, its provenance was questioned by several experts.","translation":"尽管这条钻石项链是拍卖中最昂贵的物品，但其来源受到了几位专家的质疑。"},{"sentence":"The new software update includes an item in the preferences menu that allows users to enable two-factor authentication for enhanced security.","translation":"新的软件更新在偏好设置菜单中包含一个项目，允许用户启用双因素认证以增强安全性。"},{"sentence":"Because the museum's latest acquisition was a rare item from the Han Dynasty, it attracted scholars from around the world to study its inscriptions.","translation":"由于博物馆的最新藏品是一件罕见的汉代物品，它吸引了世界各地的学者来研究其铭文。"}]},"reign":{"examples":[{"sentence":"During the reign of Emperor Wu of Han, the Silk Road was established, which facilitated trade and cultural exchange between East and West.","translation":"在汉武帝统治期间，丝绸之路得以建立，促进了东西方之间的贸易和文化交流。"},{"sentence":"Although the reign of Louis XIV is often associated with the splendor of Versailles, it also left France burdened by massive debt.","translation":"尽管路易十四的统治常与凡尔赛宫的辉煌联系在一起，但它也使法国背负了巨额债务。"},{"sentence":"Historians note that the reign of Elizabeth I was marked by a flourishing of English drama, with playwrights such as Shakespeare producing their greatest works.","translation":"历史学家指出，伊丽莎白一世的统治以英国戏剧的繁荣为标志，莎士比亚等剧作家创作了他们最伟大的作品。"},{"sentence":"The emperor's reign came to an end when a military coup forced him to flee the capital, thereby plunging the nation into chaos.","translation":"当一场军事政变迫使他逃离首都时，这位皇帝的统治结束了，从而使国家陷入混乱。"},{"sentence":"In many cultures, the reign of a just ruler is remembered not only for territorial expansion but also for the codification of laws that protect the weak.","translation":"在许多文化中，一位公正统治者的统治不仅因领土扩张而被铭记，还因编纂了保护弱者的法律而被纪念。"}]},"glue":{"examples":[{"sentence":"The glue that holds a diverse society together is a shared commitment to mutual respect and equal opportunity.","translation":"将一个多元社会凝聚在一起的粘合剂，是对相互尊重和平等机会的共同承诺。"},{"sentence":"Because the adhesive properties of this glue degrade under high humidity, manufacturers must store components in climate-controlled environments.","translation":"由于这种胶水的粘合性能在高湿度下会退化，制造商必须在温控环境中存放部件。"},{"sentence":"Although modern joinery techniques have reduced the reliance on glue, it remains indispensable for laminating curved wooden structures.","translation":"尽管现代接合技术减少了对胶水的依赖，但在层压弯曲木结构时它仍然是不可或缺的。"},{"sentence":"Researchers developed a biodegradable glue derived from plant proteins, which could replace synthetic adhesives in packaging and reduce plastic waste.","translation":"研究人员开发出一种源自植物蛋白的可生物降解胶水，它可以在包装中替代合成粘合剂并减少塑料垃圾。"},{"sentence":"Trust functions as the social glue that enables communities to cooperate effectively during crises, as evidenced by rapid volunteer mobilization after natural disasters.","translation":"信任起着社会粘合剂的作用，使社区在危机期间能够有效合作，自然灾害后迅速的志愿者动员就证明了这一点。"}]},"outfit":{"examples":[{"sentence":"The expedition team was equipped with a specialized outfit, which included GPS devices and thermal clothing.","translation":"探险队配备了一套专门的装备，其中包括GPS设备和保暖衣物。"},{"sentence":"Although she wore a simple outfit, her confidence made her stand out at the networking event.","translation":"尽管她穿着简单的服装，但她的自信使她在社交活动中脱颖而出。"},{"sentence":"The marketing outfit was hired to revamp the brand image, thereby attracting a younger demographic.","translation":"这家营销机构被聘请来重塑品牌形象，从而吸引更年轻的人群。"},{"sentence":"Because the hiking outfit was lightweight and waterproof, it was ideal for the unpredictable mountain weather.","translation":"因为这套徒步装备轻便且防水，所以非常适合山区多变的天气。"},{"sentence":"The film production required a historical outfit, which the costume department meticulously recreated from archival photos.","translation":"电影制作需要一套历史服装，服装部门根据档案照片精心重现了它。"}]},"admit":{"examples":[{"sentence":"Although the company was reluctant to admit its mistake, issuing a recall was necessary to ensure customer safety.","translation":"尽管公司不愿承认错误，但为了确保客户安全，发布召回是必要的。"},{"sentence":"The university will admit students based on a holistic review, which considers extracurricular achievements alongside grades.","translation":"这所大学将基于全面评估招收学生，该评估在考虑成绩的同时也考虑课外成就。"},{"sentence":"Because the evidence was overwhelming, the defendant had to admit guilt in order to receive a reduced sentence.","translation":"因为证据确凿，被告不得不认罪以获得减刑。"},{"sentence":"The new policy will admit more international professionals, thereby enriching the country's cultural diversity.","translation":"新政策将接纳更多的国际专业人士，从而丰富该国的文化多样性。"},{"sentence":"While it is hard to admit failure, doing so allows individuals to learn from their experiences and grow stronger.","translation":"虽然承认失败很难，但这样做可以让个人从经历中学习并变得更强大。"}]},"linen":{"examples":[{"sentence":"Although linen is more expensive than cotton, its durability and breathability make it a worthwhile investment for bedding.","translation":"尽管亚麻布比棉布更贵，但其耐用性和透气性使其成为值得投资的床上用品。"},{"sentence":"Because linen absorbs moisture without feeling damp, it is often used for towels in high-end spas.","translation":"由于亚麻布吸湿而不感潮湿，它常被用于高端水疗中心的毛巾。"},{"sentence":"The designer chose pure white linen for the tablecloths, which created an elegant atmosphere at the wedding reception.","translation":"设计师为桌布选择了纯白色亚麻布，这在婚宴上营造了优雅的氛围。"},{"sentence":"When properly cared for, linen garments can last for decades, thereby reducing the need for frequent replacements.","translation":"如果保养得当，亚麻服装可以使用数十年，从而减少频繁更换的需要。"},{"sentence":"To ensure a crisp appearance, the hotel staff iron the linen napkins while they are still slightly damp.","translation":"为确保挺括的外观，酒店员工在亚麻餐巾还微湿时熨烫它们。"}]},"fortunate":{"examples":[{"sentence":"Although many people struggle to find employment, she was fortunate to secure a position that aligned with her career goals.","translation":"尽管许多人找工作困难，她却幸运地获得了一个符合她职业目标的职位。"},{"sentence":"Because he was born into a supportive family, he considers himself fortunate to have had a stable upbringing.","translation":"由于出生在一个支持他的家庭，他认为自己幸运地拥有了稳定的成长环境。"},{"sentence":"The survivors of the natural disaster felt fortunate to receive international aid, which helped them rebuild their lives.","translation":"自然灾害的幸存者感到幸运，因为他们得到了国际援助，这帮助他们重建了生活。"},{"sentence":"While many species face extinction, we are fortunate that conservation efforts have saved the giant panda from that fate.","translation":"虽然许多物种面临灭绝，我们很幸运保护工作使大熊猫免于那种命运。"},{"sentence":"To be fortunate enough to have access to clean water is a privilege that billions of people still lack.","translation":"有幸获得清洁用水是一种特权，而数十亿人仍然缺乏。"}]},"public":{"examples":[{"sentence":"Although the new policy was controversial, the government held public hearings to gather feedback from citizens.","translation":"尽管新政策有争议，政府举行了公众听证会以收集公民的反馈。"},{"sentence":"Because public health depends on collective action, vaccination campaigns require widespread community participation.","translation":"由于公共卫生依赖于集体行动，疫苗接种运动需要广泛的社区参与。"},{"sentence":"The museum offers free admission to the public on weekends, which encourages more people to engage with art and history.","translation":"博物馆在周末向公众免费开放，这鼓励了更多人接触艺术和历史。"},{"sentence":"When public officials are held accountable for their actions, trust in government institutions tends to increase.","translation":"当公职人员对其行为负责时，对政府机构的信任往往会增加。"},{"sentence":"To ensure public safety, the city installed surveillance cameras in high-traffic areas, thereby deterring potential crime.","translation":"为确保公共安全，该市在人流量大的区域安装了监控摄像头，从而威慑了潜在的犯罪。"}]},"currency":{"examples":[{"sentence":"Because the country's currency was unstable, many citizens preferred to hold foreign reserves.","translation":"由于该国货币不稳定，许多公民更愿意持有外汇储备。"},{"sentence":"Digital currency, which operates independently of central banks, has challenged traditional financial systems.","translation":"数字货币独立于中央银行运作，对传统金融体系构成了挑战。"},{"sentence":"When traveling abroad, it is wise to exchange currency at authorized institutions to avoid excessive fees.","translation":"出国旅行时，明智的做法是在授权机构兑换货币，以避免过高的费用。"},{"sentence":"The concept of a single global currency, while appealing in theory, faces significant practical obstacles.","translation":"单一全球货币的概念虽然在理论上很有吸引力，但面临着巨大的实际障碍。"},{"sentence":"In times of hyperinflation, the local currency can lose value so rapidly that people resort to bartering.","translation":"在恶性通货膨胀时期，当地货币可能迅速贬值，以至于人们转而以物易物。"}]},"address":{"examples":[{"sentence":"Although the company relocated its headquarters, the mailing address remained unchanged to ensure continuity.","translation":"尽管公司搬迁了总部，但邮寄地址保持不变以确保连续性。"},{"sentence":"Because the application form lacked a valid address, the admissions office could not process it.","translation":"由于申请表缺少有效地址，招生办公室无法处理它。"},{"sentence":"The policy requires that every employee update their residential address within ten days of moving, which helps maintain accurate records.","translation":"该政策要求每位员工在搬家后十天内更新其居住地址，这有助于保持准确的记录。"},{"sentence":"While digital communication has reduced the need for physical mail, a permanent address is still essential for legal documents.","translation":"虽然数字通信减少了对实体邮件的需求，但永久地址对于法律文件仍然至关重要。"},{"sentence":"The university sent the acceptance letter to the address provided on the application, thereby confirming the student's enrollment.","translation":"大学将录取通知书寄到了申请中提供的地址，从而确认了学生的入学资格。"}]},"pencil":{"examples":[{"sentence":"Although digital note-taking is efficient, many artists still prefer a pencil because it offers unmatched tactile control over line weight and texture.","translation":"尽管数字笔记很高效，许多艺术家仍然更喜欢铅笔，因为它提供了对线条粗细和质感无与伦比的触觉控制。"},{"sentence":"The architect used a pencil to sketch the initial concept, which allowed her to quickly iterate on the design before moving to digital modeling.","translation":"建筑师用铅笔勾画了最初的概念，这使她能够在转向数字建模之前快速迭代设计。"},{"sentence":"When the standardized test required a number two pencil, the proctor distributed sharpened pencils to ensure that all students could mark their answers clearly.","translation":"当标准化考试要求使用2号铅笔时，监考人员分发了削好的铅笔，以确保所有学生都能清晰地标记答案。"},{"sentence":"Because the pencil marks are easily erasable, engineers often use them to annotate blueprints during the review process without permanently altering the documents.","translation":"由于铅笔痕迹容易擦除，工程师经常在审查过程中用铅笔在蓝图上做注释，而不会永久性地改变文件。"},{"sentence":"To foster creativity in the workshop, the instructor provided each participant with a pencil and a blank notebook, rather than relying on pre-printed templates.","translation":"为了在研讨会上培养创造力，讲师为每位参与者提供了一支铅笔和一本空白笔记本，而不是依赖预先打印的模板。"}]},"limp":{"examples":[{"sentence":"After the accident, the patient walked with a pronounced limp, which prompted the physiotherapist to design a customized rehabilitation program.","translation":"事故发生后，病人走路时明显跛行，这促使物理治疗师设计了一套定制的康复计划。"},{"sentence":"Although the veteran's limp was a constant reminder of his injury, he refused to let it hinder his participation in community sports events.","translation":"尽管这位老兵的跛行不断提醒着他的伤势，但他拒绝让它阻碍他参加社区体育活动。"},{"sentence":"The doctor observed the child's limp carefully, because an asymmetrical gait can sometimes indicate an underlying neurological condition.","translation":"医生仔细观察了孩子的跛行，因为不对称的步态有时可能表明潜在的神经系统疾病。"},{"sentence":"When the athlete developed a sudden limp during the match, the coach immediately substituted her to prevent further damage to the muscle.","translation":"当运动员在比赛中突然出现跛行时，教练立即将她换下，以防止肌肉进一步受损。"},{"sentence":"Despite the limp that resulted from the surgery, the dancer gradually regained her strength through a rigorous yet carefully monitored exercise regimen.","translation":"尽管手术导致了跛行，这位舞者通过严格但精心监控的锻炼方案逐渐恢复了力量。"}]},"grand":{"examples":[{"sentence":"Although the grand palace was built centuries ago, its intricate design still inspires modern architects.","translation":"尽管这座宏伟的宫殿建于几个世纪前，但其复杂的设计仍然启发着现代建筑师。"},{"sentence":"The research team proposed a grand unified theory, which attempts to explain all fundamental forces in physics.","translation":"研究团队提出了一个宏大的统一理论，试图解释物理学中的所有基本力。"},{"sentence":"Because the project required a grand investment, the committee carefully evaluated its long-term economic benefits.","translation":"由于该项目需要巨额投资，委员会仔细评估了其长期经济效益。"},{"sentence":"The grand ceremony, which was attended by diplomats from over fifty countries, celebrated the signing of the peace treaty.","translation":"这场隆重的典礼有来自五十多个国家的外交官出席，庆祝和平条约的签署。"},{"sentence":"While the scientist's grand vision seemed ambitious, it ultimately led to breakthroughs in renewable energy technology.","translation":"尽管这位科学家的宏伟愿景看似雄心勃勃，但最终促成了可再生能源技术的突破。"}]},"repression":{"examples":[{"sentence":"Political repression often leads to widespread dissent, which can destabilize a regime over time.","translation":"政治压制常常导致广泛的异议，这可能会随着时间的推移破坏政权的稳定。"},{"sentence":"Although emotional repression may provide short-term relief, it frequently results in long-term psychological harm.","translation":"尽管情感压抑可能提供短期的缓解，但它经常导致长期的心理伤害。"},{"sentence":"The repression of free speech, unless challenged by civil society, can become deeply entrenched in a nation's laws.","translation":"对言论自由的压制，除非受到公民社会的挑战，否则可能在一个国家的法律中根深蒂固。"},{"sentence":"Because the government intensified its repression of activists, international organizations imposed economic sanctions.","translation":"由于政府加强了对活动人士的压制，国际组织实施了经济制裁。"},{"sentence":"Historians note that cultural repression during that period stifled artistic expression, thereby delaying social progress.","translation":"历史学家指出，那个时期的文化压制扼杀了艺术表达，从而延缓了社会进步。"}]},"east":{"examples":[{"sentence":"The cultural exchange program between universities in the east and the west has fostered deeper mutual understanding, which benefits all participants.","translation":"东西方大学之间的文化交流项目促进了更深层次的相互理解，使所有参与者受益。"},{"sentence":"Rapid industrialization in the east of the country has created economic opportunities, whereas the west remains largely agricultural.","translation":"该国东部地区的快速工业化创造了经济机遇，而西部地区仍以农业为主。"},{"sentence":"Historical records indicate that trade routes connecting the east and the west facilitated the spread of knowledge, thereby advancing civilizations.","translation":"历史记录表明，连接东西方的贸易路线促进了知识的传播，从而推动了文明进步。"},{"sentence":"Because the prevailing winds from the east bring moist air, the region's agricultural productivity is well supported.","translation":"因为来自东方的盛行风带来湿润空气，该地区的农业生产力得到了良好支撑。"},{"sentence":"Many ancient philosophies that originated in the east emphasize harmony between humanity and nature, which remains relevant today.","translation":"许多起源于东方的古代哲学强调人与自然的和谐，这在今天仍然具有现实意义。"}]},"precise":{"examples":[{"sentence":"Establishing precise criteria for evaluating research proposals ensures that funding is allocated to the most promising projects.","translation":"制定精确的评估研究提案标准，确保资金分配给最有前景的项目。"},{"sentence":"Although the theory was groundbreaking, its practical application required precise measurements that were difficult to obtain at the time.","translation":"尽管该理论具有开创性，但其实际应用需要当时难以获得的精确测量。"},{"sentence":"The engineer provided a precise explanation of the mechanism, which helped the team identify the source of the malfunction.","translation":"工程师对该机制提供了精确的解释，帮助团队确定了故障源。"},{"sentence":"In legal documents, the use of precise language is essential to avoid ambiguity, thereby preventing potential disputes.","translation":"在法律文件中，使用精确的语言对于避免歧义至关重要，从而防止潜在争议。"},{"sentence":"Modern climate models require precise data on ocean temperatures, because accurate predictions depend on such details.","translation":"现代气候模型需要精确的海洋温度数据，因为准确的预测依赖于这些细节。"}]},"weather":{"examples":[{"sentence":"Although the weather forecast predicted rain, the outdoor ceremony proceeded as planned because the organizers had prepared a contingency tent.","translation":"尽管天气预报预测有雨，户外仪式仍按计划进行，因为组织者准备了应急帐篷。"},{"sentence":"The construction project was delayed by severe weather, which forced the team to revise the timeline and allocate additional resources.","translation":"建设项目因恶劣天气而延误，这迫使团队修改时间表并分配额外资源。"},{"sentence":"While farmers in arid regions struggle with unpredictable weather, those in temperate zones often enjoy more stable growing conditions.","translation":"干旱地区的农民与不可预测的天气作斗争，而温带地区的农民通常享有更稳定的生长条件。"},{"sentence":"By monitoring weather patterns through satellite imagery, meteorologists can issue early warnings that save countless lives during natural disasters.","translation":"通过卫星图像监测天气模式，气象学家可以发布早期预警，在自然灾害期间拯救无数生命。"},{"sentence":"The success of the harvest depends heavily on favorable weather, thereby making agriculture one of the sectors most vulnerable to climate change.","translation":"丰收在很大程度上取决于有利的天气，从而使农业成为最易受气候变化影响的部门之一。"}]},"aboard":{"examples":[{"sentence":"Because the ship was about to depart, the late passengers rushed aboard, hoping to find their cabins before the safety drill began.","translation":"由于船即将启航，迟到的乘客匆忙上船，希望在安全演习开始前找到自己的舱房。"},{"sentence":"The astronauts aboard the space station conducted experiments that could lead to breakthroughs in medicine and materials science.","translation":"空间站上的宇航员进行了可能带来医学和材料科学突破的实验。"},{"sentence":"Although the flight was turbulent, the passengers aboard remained calm because the crew had provided clear safety instructions.","translation":"尽管飞行颠簸，机上乘客仍保持冷静，因为机组人员提供了清晰的安全指示。"},{"sentence":"When the train arrived, the conductor welcomed everyone aboard and reminded them to keep their tickets handy for inspection.","translation":"火车到站时，列车员欢迎所有人上车，并提醒他们随时准备好车票以备查验。"},{"sentence":"The research team brought specialized equipment aboard the vessel, which allowed them to collect deep-sea samples without contamination.","translation":"研究团队将专业设备带上船，这使他们能够无污染地收集深海样本。"}]},"themselves":{"examples":[{"sentence":"Although the instructions were clear, the students found themselves struggling to apply the concepts in practice.","translation":"尽管说明很清楚，学生们却发现自己难以在实践中应用这些概念。"},{"sentence":"When individuals push themselves beyond their comfort zones, they often discover hidden talents and resilience.","translation":"当个人强迫自己走出舒适区时，他们常常会发现隐藏的才能和韧性。"},{"sentence":"The volunteers devoted themselves to the project, which ultimately benefited the entire community.","translation":"志愿者们全身心投入该项目，最终使整个社区受益。"},{"sentence":"Because the team members held themselves accountable for the outcome, they worked diligently to meet the deadline.","translation":"因为团队成员对结果负责，他们勤奋工作以赶上截止日期。"},{"sentence":"The children amused themselves with simple toys, whereas the adults preferred more sophisticated entertainment.","translation":"孩子们用简单的玩具自娱自乐，而成年人则更喜欢复杂的娱乐方式。"}]},"discharge":{"examples":[{"sentence":"The hospital decided to discharge the patient after confirming that his vital signs had remained stable for two consecutive days.","translation":"医院在确认病人生命体征连续两天保持稳定后，决定让他出院。"},{"sentence":"Companies that discharge untreated industrial waste into rivers face severe penalties under the newly revised environmental protection law.","translation":"根据新修订的环境保护法，将未经处理的工业废水排入河流的企业将面临严厉处罚。"},{"sentence":"Although he had served the organization faithfully for over a decade, the board voted to discharge him due to repeated violations of the code of conduct.","translation":"尽管他已为组织忠诚服务了十多年，董事会仍因他屡次违反行为准则而投票决定解雇他。"},{"sentence":"To discharge her responsibility as a mentor, she regularly held workshops that helped junior researchers refine their academic writing skills.","translation":"为履行作为导师的职责，她定期举办研讨会，帮助初级研究人员提升学术写作能力。"},{"sentence":"The battery can discharge its stored energy within minutes when connected to a high-power device, which makes it suitable for emergency backup systems.","translation":"当连接到高功率设备时，电池能在几分钟内释放其储存的能量，这使其适用于应急备用系统。"}]},"literacy":{"examples":[{"sentence":"Because digital literacy is now essential for accessing government services, many community centers offer free training to bridge the gap.","translation":"由于数字素养如今对于获取政府服务至关重要，许多社区中心提供免费培训以弥合差距。"},{"sentence":"Although the country's literacy rate has improved significantly, functional illiteracy remains a barrier to economic advancement for many adults.","translation":"尽管该国的识字率已显著提高，但功能性文盲仍然是许多成年人经济进步的障碍。"},{"sentence":"Media literacy education, which teaches students to critically analyze news sources, is vital in an era of widespread misinformation.","translation":"媒介素养教育教导学生批判性地分析新闻来源，在错误信息泛滥的时代至关重要。"},{"sentence":"Financial literacy programs that focus on budgeting and investing can empower individuals to make informed decisions about their long-term savings.","translation":"专注于预算和投资的金融素养项目可以使个人能够就其长期储蓄做出明智的决定。"},{"sentence":"The government's campaign to improve adult literacy not only enhances employability but also fosters greater civic participation among marginalized groups.","translation":"政府提高成人识字率的运动不仅提高了就业能力，还促进了边缘群体更多的公民参与。"}]},"visual":{"examples":[{"sentence":"Although the lecture was informative, the visual presentation made the concepts much easier to remember.","translation":"尽管讲座内容翔实，但视觉演示使概念更容易记住。"},{"sentence":"Because visual learners process information best through images, teachers should incorporate diagrams into their lessons.","translation":"由于视觉型学习者通过图像处理信息效果最佳，教师应在课程中加入图表。"},{"sentence":"The software provides a visual representation of data, which helps analysts identify trends that might otherwise go unnoticed.","translation":"该软件提供数据的视觉表示，这有助于分析师识别可能被忽视的趋势。"},{"sentence":"While textual instructions can be ambiguous, a visual guide ensures that users complete the assembly without errors.","translation":"虽然文字说明可能含糊不清，但视觉指南确保用户无误地完成组装。"},{"sentence":"To enhance the museum's appeal, the curators designed interactive visual exhibits that engage visitors of all ages.","translation":"为了增强博物馆的吸引力，策展人设计了互动视觉展品，吸引各年龄段的参观者。"}]},"famine":{"examples":[{"sentence":"Although the region had experienced famine before, the severity of the current crisis shocked even veteran aid workers.","translation":"尽管该地区以前经历过饥荒，但当前危机的严重性甚至震惊了经验丰富的援助工作者。"},{"sentence":"Because climate change intensifies droughts, many scientists warn that famine will become more frequent in vulnerable areas.","translation":"由于气候变化加剧了干旱，许多科学家警告说，饥荒在脆弱地区将变得更加频繁。"},{"sentence":"The government's failure to distribute food fairly, rather than an absolute shortage, was the primary cause of the famine.","translation":"政府未能公平分配粮食，而非绝对短缺，是饥荒的主要原因。"},{"sentence":"To mitigate the risk of famine, international organizations have established early warning systems that monitor crop yields and food prices.","translation":"为了减轻饥荒风险，国际组织建立了监测作物产量和粮食价格的早期预警系统。"},{"sentence":"While emergency food aid can save lives during a famine, long-term solutions require investment in agricultural infrastructure.","translation":"虽然紧急粮食援助可以在饥荒期间拯救生命，但长期解决方案需要对农业基础设施进行投资。"}]},"certainly":{"examples":[{"sentence":"Although the task is challenging, consistent effort will certainly lead to improvement.","translation":"尽管任务具有挑战性，但持续的努力必将带来进步。"},{"sentence":"Because the evidence is overwhelming, the theory is certainly valid.","translation":"因为证据确凿，该理论无疑是成立的。"},{"sentence":"While some may doubt the plan, it will certainly succeed if executed properly.","translation":"虽然有些人可能怀疑这个计划，但如果执行得当，它肯定会成功。"},{"sentence":"Investing in education certainly benefits society, which is why governments prioritize it.","translation":"投资教育无疑有益于社会，这就是政府优先考虑它的原因。"},{"sentence":"Without adequate preparation, one cannot certainly expect to pass the exam.","translation":"没有充分的准备，就不能肯定地期望通过考试。"}]},"stop":{"examples":[{"sentence":"The bus stop was relocated to a safer area, thereby reducing accidents.","translation":"公交车站被迁移到更安全的区域，从而减少了事故。"},{"sentence":"A sudden stop in funding can derail a project, which is why contingency plans are essential.","translation":"资金的突然中断可能使项目脱轨，这就是应急计划至关重要的原因。"},{"sentence":"Because the train made an unscheduled stop, many passengers missed their connections.","translation":"因为火车临时停车，许多乘客错过了换乘。"},{"sentence":"The new policy acts as a stop to deforestation, although enforcement remains a challenge.","translation":"新政策起到了阻止森林砍伐的作用，尽管执行仍然是一个挑战。"},{"sentence":"When the machine detects a fault, it comes to a complete stop to prevent damage.","translation":"当机器检测到故障时，它会完全停止以防止损坏。"}]},"onion":{"examples":[{"sentence":"Because onion contains antioxidants, it is often recommended for a healthy diet.","translation":"因为洋葱含有抗氧化剂，所以常被推荐用于健康饮食。"},{"sentence":"The price of onion rose sharply after the drought, which affected many households.","translation":"干旱后洋葱价格急剧上涨，这影响了许多家庭。"},{"sentence":"Although onion is a common ingredient, its cultivation requires specific soil conditions.","translation":"虽然洋葱是一种常见食材，但其种植需要特定的土壤条件。"},{"sentence":"Farmers use crop rotation to maintain onion yield, thereby ensuring soil fertility.","translation":"农民采用轮作来维持洋葱产量，从而确保土壤肥力。"},{"sentence":"When cutting onion, one can reduce tears by chilling it beforehand.","translation":"切洋葱时，事先冷藏可以减少流泪。"}]},"almost":{"examples":[{"sentence":"Although the experiment was almost successful, a minor error in calibration caused the results to be discarded.","translation":"尽管实验几乎成功了，但校准中的一个小错误导致结果被丢弃。"},{"sentence":"Because the deadline was almost upon us, we worked through the night to finalize the report.","translation":"由于截止日期几乎到了，我们通宵工作以完成报告。"},{"sentence":"The new policy, which was almost universally criticized, was eventually revised after public outcry.","translation":"这项几乎受到普遍批评的新政策，在公众强烈抗议后最终被修订。"},{"sentence":"When the patient's condition had almost deteriorated beyond recovery, a new treatment brought unexpected improvement.","translation":"当病人的状况几乎恶化到无法恢复时，一种新疗法带来了意想不到的好转。"},{"sentence":"In many urban areas, almost 80 percent of residents rely on public transportation, thereby reducing traffic congestion.","translation":"在许多城市地区，几乎80%的居民依赖公共交通，从而减少了交通拥堵。"}]},"telegraph":{"examples":[{"sentence":"The telegraph, which was invented in the early nineteenth century, transformed global communication by transmitting messages in minutes.","translation":"电报于19世纪初发明，通过几分钟内传递消息，改变了全球通信。"},{"sentence":"Although the telegraph is now obsolete, its development laid the groundwork for modern telecommunications.","translation":"尽管电报现已过时，但其发展为现代电信奠定了基础。"},{"sentence":"Because the telegraph enabled instant coordination, businesses could expand their operations across continents.","translation":"由于电报实现了即时协调，企业可以将业务扩展到各大洲。"},{"sentence":"When the first transatlantic telegraph cable was completed in 1866, it marked a new era of international diplomacy.","translation":"当第一条跨大西洋电报电缆于1866年建成时，它标志着国际外交的新纪元。"},{"sentence":"Historians note that the telegraph not only accelerated news dissemination but also influenced the outcome of wars.","translation":"历史学家指出，电报不仅加速了新闻传播，还影响了战争的结果。"}]},"lover":{"examples":[{"sentence":"Although she is a devoted lover of classical music, she also appreciates the complexity of modern jazz compositions.","translation":"尽管她是古典音乐的忠实爱好者，她也欣赏现代爵士乐作品的复杂性。"},{"sentence":"A true lover of literature often finds that reading classic novels provides deeper insights than watching film adaptations.","translation":"一个真正的文学爱好者常常发现，阅读经典小说比观看电影改编能提供更深刻的见解。"},{"sentence":"Because he is a passionate lover of nature, he spends every weekend hiking in the mountains to observe wildlife.","translation":"由于他是大自然的热情爱好者，他每个周末都在山中徒步旅行以观察野生动物。"},{"sentence":"As a lifelong lover of knowledge, she pursues interdisciplinary studies rather than limiting herself to a single field.","translation":"作为一个终生的知识爱好者，她追求跨学科研究，而不是将自己局限于单一领域。"},{"sentence":"While a lover of art may admire the beauty of a painting, a true connoisseur also understands its historical context.","translation":"虽然艺术爱好者可能欣赏画作的美，但真正的鉴赏家也理解其历史背景。"}]},"purchase":{"examples":[{"sentence":"Although the purchase price was high, the long-term savings on energy costs justified the investment.","translation":"尽管购买价格很高，但长期节省的能源成本证明了这项投资是合理的。"},{"sentence":"The company streamlined its procurement process to ensure that every purchase is approved by the finance department.","translation":"公司简化了采购流程，以确保每笔购买都经过财务部门批准。"},{"sentence":"Because the purchase of new software requires extensive training, the manager decided to delay the implementation.","translation":"由于购买新软件需要大量培训，经理决定推迟实施。"},{"sentence":"The purchase of carbon offsets, which allows companies to compensate for their emissions, has become increasingly common.","translation":"购买碳抵消，使公司能够补偿其排放，已变得越来越普遍。"},{"sentence":"When making a major purchase, consumers should compare prices across multiple retailers to ensure they get the best deal.","translation":"在进行大额购买时，消费者应比较多家零售商的价格，以确保获得最优惠的交易。"}]},"summon":{"examples":[{"sentence":"Although the evidence was weak, the prosecutor decided to summon the key witness to strengthen the case.","translation":"尽管证据薄弱，检察官还是决定传唤关键证人以加强案情。"},{"sentence":"The board of directors can summon an extraordinary general meeting if a majority of shareholders request it.","translation":"如果多数股东要求，董事会可以召集临时股东大会。"},{"sentence":"Because the situation required immediate action, the team leader had to summon all her resolve to make a difficult decision.","translation":"由于情况需要立即行动，团队领导不得不鼓起全部决心做出艰难的决定。"},{"sentence":"The ancient ritual was believed to summon ancestral spirits, which would then offer guidance to the community.","translation":"人们相信这个古老的仪式能召唤祖先的灵魂，然后为社区提供指引。"},{"sentence":"When the ambassador was declared persona non grata, the foreign ministry had to summon the envoy to convey the decision.","translation":"当大使被宣布为不受欢迎的人时，外交部不得不召见特使以传达这一决定。"}]},"potato":{"examples":[{"sentence":"The potato, which is a versatile crop, can be processed into starch, flour, and even biodegradable plastics.","translation":"马铃薯是一种多用途作物，可以加工成淀粉、面粉，甚至可生物降解的塑料。"},{"sentence":"Because the potato blight destroyed the harvest, thousands of families were forced to emigrate to survive.","translation":"由于马铃薯晚疫病摧毁了收成，成千上万的家庭被迫移民以求生存。"},{"sentence":"Although the potato is often associated with unhealthy fast food, it can be a nutritious part of a balanced diet when prepared properly.","translation":"尽管马铃薯常与不健康的快餐联系在一起，但如果烹饪得当，它可以成为均衡饮食中营养的一部分。"},{"sentence":"The development of frost-resistant potato varieties, which can thrive in colder climates, has expanded cultivation to northern regions.","translation":"耐霜冻马铃薯品种的开发，使其能在较冷的气候中茁壮成长，已将种植范围扩大到北部地区。"},{"sentence":"When the potato was first introduced to Europe, many people were skeptical about its safety and nutritional value.","translation":"当马铃薯首次引入欧洲时，许多人对它的安全性和营养价值持怀疑态度。"}]},"peach":{"examples":[{"sentence":"Although the peach is often enjoyed fresh, it can also be processed into jams and preserves that extend its shelf life.","translation":"尽管桃子常被鲜食，但它也可以加工成果酱和蜜饯，从而延长保质期。"},{"sentence":"The peach, which is rich in vitamins A and C, is a nutritious addition to a balanced diet.","translation":"桃子富含维生素A和C，是均衡饮食中的营养补充。"},{"sentence":"Because the peach tree requires a certain number of chill hours to produce fruit, it is not suitable for tropical climates.","translation":"由于桃树需要一定的低温时数才能结果，因此它不适合热带气候。"},{"sentence":"When the peach orchard is in full bloom, the pink blossoms attract numerous tourists and photographers.","translation":"当桃园盛开时，粉色的花朵吸引了众多游客和摄影师。"},{"sentence":"The farmer used organic methods to cultivate his peach crop, thereby reducing the environmental impact of pesticides.","translation":"这位农民采用有机方法种植桃子，从而减少了农药对环境的影响。"}]},"forgive":{"examples":[{"sentence":"Although it is difficult to forgive a betrayal, doing so can free a person from the burden of resentment.","translation":"尽管原谅背叛很难，但这样做可以使人摆脱怨恨的负担。"},{"sentence":"To forgive a debtor who cannot repay the loan is an act of compassion that may strengthen the relationship.","translation":"原谅无力偿还贷款的债务人是一种同情之举，可能会加强双方关系。"},{"sentence":"Because the leader chose to forgive the dissidents, the nation began a process of healing and unity.","translation":"由于领导人选择原谅持不同政见者，国家开始了愈合与团结的进程。"},{"sentence":"When we forgive others, we not only release them from guilt but also liberate ourselves from anger.","translation":"当我们原谅他人时，我们不仅使他们摆脱内疚，也使自己从愤怒中解脱。"},{"sentence":"The therapist explained that learning to forgive past traumas is essential for emotional recovery, which can lead to a more fulfilling life.","translation":"治疗师解释说，学会原谅过去的创伤对于情感恢复至关重要，这可以带来更充实的生活。"}]},"sniff":{"examples":[{"sentence":"Although a quick sniff of the milk revealed that it had already gone sour, he still hesitated to throw it away.","translation":"尽管快速闻了一下牛奶就发现它已经变酸了，但他还是犹豫着没有扔掉。"},{"sentence":"The detective gave a suspicious sniff when he entered the room, because he sensed something amiss.","translation":"侦探进入房间时怀疑地嗅了嗅，因为他感觉有些不对劲。"},{"sentence":"With a disdainful sniff, she dismissed the proposal as utterly impractical, thereby ending the discussion abruptly.","translation":"她轻蔑地哼了一声，认为这个提议完全不切实际，从而突然结束了讨论。"},{"sentence":"A single sniff of the fresh sea air was enough to lift his spirits after the long journey, which had been exhausting.","translation":"长途旅行后，闻一下清新的海风就足以让他精神振奋，这次旅行让他筋疲力尽。"},{"sentence":"The doctor recommended a gentle sniff of the inhaler to relieve nasal congestion, while also advising plenty of rest.","translation":"医生建议轻轻用鼻子吸一下吸入器以缓解鼻塞，同时还建议多休息。"}]},"network":{"examples":[{"sentence":"A robust transportation network is essential for the economic development of any region, because it facilitates the movement of goods and people.","translation":"健全的交通网络对任何地区的经济发展都至关重要，因为它促进了货物和人员的流动。"},{"sentence":"Building a professional network early in one's career can open doors to unexpected opportunities, which may prove invaluable later.","translation":"在职业生涯早期建立专业人脉网络，可以带来意想不到的机会，这些机会日后可能证明是无价的。"},{"sentence":"The university's alumni network provides valuable mentorship and job placement services for graduates, thereby enhancing their career prospects.","translation":"这所大学的校友网络为毕业生提供宝贵的指导和就业服务，从而提升了他们的职业前景。"},{"sentence":"Researchers are studying how social network structures influence the spread of information and behaviors, while also considering cultural factors.","translation":"研究人员正在研究社交网络结构如何影响信息和行为的传播，同时也考虑文化因素。"},{"sentence":"The company invested heavily in upgrading its computer network to enhance data security and efficiency, despite the high initial costs.","translation":"公司投入巨资升级其计算机网络，以提高数据安全性和效率，尽管初始成本很高。"}]},"copy":{"examples":[{"sentence":"Please submit a clean copy of your manuscript without any handwritten corrections, because the publisher requires a digital version.","translation":"请提交一份干净的手稿副本，不要有任何手写修改，因为出版社要求电子版。"},{"sentence":"The library holds a rare copy of the first edition, which scholars often request to examine, although access is restricted.","translation":"图书馆藏有一本珍稀的第一版副本，学者们经常请求查阅，尽管获取受限。"},{"sentence":"Before submitting the final report, the editor carefully reviewed the copy for any factual errors, thereby ensuring its accuracy.","translation":"在提交最终报告之前，编辑仔细审阅了文稿，查找任何事实错误，从而确保了其准确性。"},{"sentence":"The marketing team prepared compelling copy for the new product launch to attract potential customers, while also highlighting its unique features.","translation":"营销团队为新产品发布准备了引人注目的广告文案，以吸引潜在客户，同时也突出了其独特功能。"},{"sentence":"Although the painting is a copy, it faithfully reproduces the original's intricate details and vibrant colors, which makes it highly valued.","translation":"尽管这幅画是复制品，但它忠实地再现了原作的精细细节和鲜艳色彩，这使得它备受珍视。"}]}}};
